(function(){
  if (typeof LESSONS === "undefined") return;
  if (typeof STAGES !== "undefined") STAGES[21] = "Bản sạch — Tin 11";
  if (typeof QUESTION_BANK !== "undefined") QUESTION_BANK.push.apply(QUESTION_BANK, [{"id":"CB-mc-101","type":"mc","topic":"A","grade":11,"level":"easy","question":"Hệ điều hành là gì?","options":["Một phần mềm ứng dụng dùng để chỉnh sửa ảnh","Một thiết bị phần cứng giúp máy tính chạy nhanh hơn","Phần mềm hệ thống chạy đầu tiên và quản lí toàn bộ máy tính","Một loại tệp dùng để lưu trữ dữ liệu người dùng"],"answer":2,"explain":"Hệ điều hành là phần mềm hệ thống, chạy đầu tiên khi thiết bị khởi động, chịu trách nhiệm quản lí toàn bộ phần cứng và làm nền cho các phần mềm khác hoạt động. Đây không phải là phần cứng, cũng không phải một phần mềm ứng dụng hay một loại tệp."},{"id":"CB-mc-102","type":"mc","topic":"A","grade":11,"level":"easy","question":"Hệ điều hành nào phổ biến nhất trên điện thoại thông minh và máy tính bảng?","options":["Microsoft Word","Android","Google Chrome","Windows Media Player"],"answer":1,"explain":"Android (cùng với iOS) là hệ điều hành phổ biến trên điện thoại thông minh và máy tính bảng. Microsoft Word, Google Chrome, Windows Media Player đều là phần mềm ứng dụng chạy trên một hệ điều hành, không phải bản thân hệ điều hành."},{"id":"CB-mc-103","type":"mc","topic":"A","grade":11,"level":"medium","question":"Khi bạn mở cùng lúc trình duyệt web và phần mềm nghe nhạc trên một máy tính chỉ có một bộ xử lí, thành phần nào điều phối để cả hai phần mềm cùng hoạt động được?","options":["Hệ điều hành","Bàn phím","Màn hình","Bản thân từng phần mềm tự thoả thuận với nhau"],"answer":0,"explain":"Hệ điều hành chia nhỏ thời gian xử lí của bộ xử lí và luân phiên giao cho từng phần mềm, giúp nhiều phần mềm cùng hoạt động được dù máy chỉ có một bộ xử lí. Bàn phím và màn hình chỉ là thiết bị vào/ra, không có vai trò điều phối; các phần mềm cũng không tự thoả thuận với nhau."},{"id":"CB-mc-104","type":"mc","topic":"A","grade":11,"level":"medium","question":"Phát biểu nào sau đây mô tả đúng vai trò ‘làm cầu nối giữa người dùng và máy’ của hệ điều hành?","options":["Hệ điều hành biên dịch mã nguồn phần mềm sang ngôn ngữ máy","Hệ điều hành kết nối hai máy tính với nhau qua mạng Internet","Hệ điều hành tự động sửa lỗi chính tả trong văn bản người dùng gõ","Hệ điều hành cung cấp giao diện như cửa sổ, biểu tượng hoặc dòng lệnh để người dùng ra lệnh cho máy dễ dàng hơn"],"answer":3,"explain":"Hệ điều hành cung cấp giao diện — đồ hoạ hoặc dòng lệnh — để người dùng thao tác với máy mà không cần hiểu ngôn ngữ phần cứng; đó chính là vai trò cầu nối giữa người dùng và máy. Ba phương án còn lại mô tả những việc khác, không phải vai trò cầu nối này."},{"id":"CB-mc-105","type":"mc","topic":"A","grade":11,"level":"hard","question":"Một máy chủ `server` chạy Linux, phục vụ đồng thời hàng trăm người truy cập một trang web. Khi hệ điều hành phân chia bộ xử lí và bộ nhớ hợp lí cho từng yêu cầu, sao cho yêu cầu của người này không làm gián đoạn yêu cầu của người khác, đó là biểu hiện rõ nhất của vai trò nào?","options":["Làm cầu nối giữa người dùng và máy","Làm nền tảng cho phần mềm khác hoạt động","Quản lí phần cứng và bộ nhớ","Cài đặt thêm phần mềm ứng dụng mới"],"answer":2,"explain":"Phân chia bộ xử lí và bộ nhớ hợp lí cho nhiều yêu cầu cùng lúc, tránh xung đột giữa các tiến trình, chính là biểu hiện của vai trò quản lí phần cứng và bộ nhớ. Ở đây hệ điều hành không đóng vai trò giao diện người dùng trực tiếp (đây là máy chủ), cũng không phải đang cài phần mềm mới."},{"id":"CB-tf-101","type":"tf","topic":"A","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Hệ điều hành là phần mềm chạy đầu tiên khi thiết bị khởi động.","correct":true},{"text":"Nếu không có hệ điều hành, các phần mềm ứng dụng vẫn có thể tự chạy bình thường trên phần cứng.","correct":false},{"text":"Windows, Android, iOS và Linux đều là ví dụ về hệ điều hành.","correct":true},{"text":"Hệ điều hành chỉ có vai trò hiển thị hình ảnh lên màn hình, không liên quan đến quản lí bộ nhớ.","correct":false}],"explain":"(1) Đúng vì hệ điều hành được nạp và bắt đầu chạy ngay khi thiết bị khởi động, trước các phần mềm khác. (2) Sai vì không có hệ điều hành, phần mềm ứng dụng không có môi trường để chạy và cũng không thể truy cập phần cứng. (3) Đúng, đây đều là các hệ điều hành quen thuộc trên máy tính, điện thoại, máy chủ. (4) Sai vì hệ điều hành còn đảm nhận quản lí phần cứng, quản lí tệp và bộ nhớ, không chỉ hiển thị hình ảnh."},{"id":"CB-mc-201","type":"mc","topic":"A","grade":11,"level":"easy","question":"Phần mềm khác phần cứng ở điểm nào?","options":["Phần mềm là các bộ phận cầm nắm được như màn hình, bàn phím","Phần mềm là tập hợp câu lệnh chỉ dẫn cho máy làm việc, không cầm nắm được","Phần mềm chỉ tồn tại bên trong điện thoại, không tồn tại trong máy tính","Phần mềm và phần cứng thực chất là một, chỉ gọi tên khác nhau"],"answer":1,"explain":"Phần cứng là các bộ phận vật lí cầm nắm được (bộ xử lí, màn hình, bàn phím...). Phần mềm là tập hợp câu lệnh được viết sẵn, chỉ dẫn cho phần cứng phải làm gì; phần mềm không cầm nắm được, chỉ được lưu dưới dạng dữ liệu trên phần cứng."},{"id":"CB-mc-202","type":"mc","topic":"A","grade":11,"level":"easy","question":"Phần mềm nào dưới đây thuộc nhóm phần mềm hệ thống?","options":["Phần mềm soạn thảo văn bản","Trò chơi điện tử","Hệ điều hành","Phần mềm xem phim"],"answer":2,"explain":"Hệ điều hành quản lí toàn bộ phần cứng và làm nền cho các phần mềm khác chạy lên, nên thuộc nhóm phần mềm hệ thống. Soạn thảo văn bản, trò chơi điện tử, xem phim đều là phần mềm ứng dụng, phục vụ công việc hoặc giải trí cụ thể của người dùng."},{"id":"CB-mc-203","type":"mc","topic":"A","grade":11,"level":"medium","question":"Máy tính đã cài hệ điều hành, nhưng khi cắm một chiếc máy in mới vào thì máy in vẫn không in được. Nhiều khả năng nguyên nhân là do thiếu phần mềm nào?","options":["Thiếu hệ điều hành","Thiếu trình điều khiển thiết bị (driver) dành riêng cho mẫu máy in đó","Thiếu phần mềm bảng tính","Thiếu phần mềm diệt virus"],"answer":1,"explain":"Driver là phần mềm phiên dịch giữa hệ điều hành và một thiết bị phần cứng cụ thể. Máy đã có hệ điều hành nhưng thiếu đúng driver cho mẫu máy in đó thì hệ điều hành chưa biết cách gửi lệnh in, nên máy in không hoạt động được."},{"id":"CB-mc-204","type":"mc","topic":"A","grade":11,"level":"medium","question":"Điểm khác biệt cốt lõi giữa phần mềm nguồn mở và phần mềm thương mại là gì?","options":["Phần mềm nguồn mở không chạy được trên máy tính cá nhân","Phần mềm thương mại luôn miễn phí, còn phần mềm nguồn mở luôn mất phí","Phần mềm nguồn mở công khai mã nguồn cho phép xem, sửa; phần mềm thương mại giữ kín mã nguồn và yêu cầu trả tiền mua giấy phép","Phần mềm nguồn mở chỉ dùng được cho phần mềm hệ thống, không dùng được cho phần mềm ứng dụng"],"answer":2,"explain":"Phần mềm nguồn mở công bố mã nguồn công khai, cho phép người dùng xem, tìm hiểu, thậm chí chỉnh sửa, và phần lớn được cung cấp miễn phí. Phần mềm thương mại giữ kín mã nguồn, người dùng phải trả tiền mua giấy phép mới được dùng hợp pháp. Cả hai loại đều có thể là phần mềm hệ thống hoặc phần mềm ứng dụng."},{"id":"CB-mc-205","type":"mc","topic":"A","grade":11,"level":"hard","question":"Một người nói: “Tôi chỉ cần cài phần mềm bảng tính để tính toán là đủ, máy tính không cần thêm phần mềm nào khác.” Nhận định này có hợp lí không?","options":["Hợp lí, vì phần mềm bảng tính tự nó điều khiển được toàn bộ phần cứng","Không hợp lí, vì phần mềm ứng dụng như bảng tính luôn phải chạy trên nền một hệ điều hành (phần mềm hệ thống) đã được cài sẵn","Hợp lí, vì phần mềm hệ thống chỉ cần thiết cho trò chơi điện tử, không cần thiết cho bảng tính","Không hợp lí, vì phần mềm bảng tính là phần mềm hệ thống, không phải phần mềm ứng dụng"],"answer":1,"explain":"Phần mềm ứng dụng như phần mềm bảng tính không thể tự điều khiển phần cứng mà phải chạy dựa trên nền một hệ điều hành đã quản lí sẵn bộ xử lí, bộ nhớ, ổ đĩa... Vì vậy máy tính luôn cần có phần mềm hệ thống, dù người dùng chỉ có nhu cầu dùng một phần mềm ứng dụng duy nhất."},{"id":"CB-tf-201","type":"tf","topic":"A","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Hệ điều hành là phần mềm được nạp đầu tiên khi bật máy và quản lí toàn bộ phần cứng.","correct":true},{"text":"Trình điều khiển thiết bị (driver) là phần mềm dùng để xem phim và nghe nhạc giải trí.","correct":false},{"text":"Phần mềm nguồn mở cho phép người dùng xem và chỉnh sửa mã nguồn theo giấy phép đi kèm.","correct":true},{"text":"Sao chép phần mềm thương mại rồi đưa cho người khác dùng miễn phí là hợp pháp, không vi phạm bản quyền.","correct":false}],"explain":"(1) Đúng — hệ điều hành nạp đầu tiên khi bật máy, quản lí bộ xử lí, bộ nhớ, ổ đĩa, màn hình... (2) Sai — driver là phần mềm hệ thống, giúp hệ điều hành “nói chuyện” với một thiết bị phần cứng cụ thể, không phải phần mềm giải trí. (3) Đúng — đây chính là đặc điểm cốt lõi của phần mềm nguồn mở. (4) Sai — sao chép và phát tán phần mềm thương mại mà không trả tiền là vi phạm bản quyền, có thể bị xử lí theo pháp luật."},{"id":"CB-mc-301","type":"mc","topic":"A","grade":11,"level":"easy","question":"CPU trong máy tính thường được ví như bộ phận nào của cơ thể người, vì nó thực hiện các phép tính và điều khiển hoạt động của toàn hệ thống?","options":["Trái tim","Bộ não","Lá phổi","Đôi tay"],"answer":1,"explain":"CPU (bộ xử lí trung tâm) được ví như “bộ não” của máy tính vì đây là bộ phận thực hiện các phép tính và điều khiển hoạt động của những bộ phận còn lại."},{"id":"CB-mc-302","type":"mc","topic":"A","grade":11,"level":"easy","question":"Đặc điểm nào sau đây đúng với RAM (bộ nhớ trong)?","options":["Dữ liệu được lưu vĩnh viễn dù tắt máy","Chỉ dùng để kết nối máy in","Dữ liệu bị mất khi mất điện hoặc tắt máy đột ngột","Có dung lượng luôn lớn hơn ổ cứng"],"answer":2,"explain":"RAM là bộ nhớ trong, chỉ lưu dữ liệu tạm thời trong lúc máy có điện; khi mất điện hoặc tắt đột ngột, dữ liệu đang xử lí trong RAM sẽ mất - khác với ổ cứng vốn lưu lâu dài."},{"id":"CB-mc-303","type":"mc","topic":"A","grade":11,"level":"medium","question":"Vì sao khi soạn thảo văn bản, ta cần thường xuyên bấm lưu để ghi tệp xuống ổ cứng, thay vì chỉ giữ trong RAM?","options":["Vì ổ cứng luôn nhanh hơn RAM nên nên chuyển dữ liệu sang sớm","Vì CPU không thể đọc dữ liệu trực tiếp từ RAM","Vì RAM không đủ khả năng chứa văn bản, chỉ chứa được hình ảnh","Vì RAM chỉ lưu tạm, dữ liệu sẽ mất khi tắt máy hoặc mất điện, còn ổ cứng lưu lâu dài"],"answer":3,"explain":"RAM là nơi làm việc tạm thời; để giữ dữ liệu an toàn lâu dài, ta cần lưu (ghi) xuống bộ nhớ ngoài như ổ cứng - nơi dữ liệu vẫn còn nguyên dù máy đã tắt."},{"id":"CB-mc-304","type":"mc","topic":"A","grade":11,"level":"medium","question":"Tốc độ của CPU thường được đo bằng đơn vị GHz. Con số này cho biết điều gì?","options":["Kích thước vật lí của con chip CPU","Số phép tính, chu kì mà CPU có thể thực hiện trong một giây","Dung lượng lưu trữ tối đa của CPU","Số thiết bị vào - ra mà CPU có thể kết nối cùng lúc"],"answer":1,"explain":"GHz (gigahertz) thể hiện tần số xung nhịp, cho biết ước lượng số chu kì xử lí mà CPU thực hiện được trong một giây; chỉ số này càng lớn, CPU nói chung càng xử lí nhanh."},{"id":"CB-mc-305","type":"mc","topic":"A","grade":11,"level":"hard","question":"Một người dùng máy tính nhận thấy máy chạy chậm và giật khi mở cùng lúc nhiều phần mềm, dù ổ cứng vẫn còn rất nhiều dung lượng trống. Nguyên nhân có khả năng cao nhất là gì?","options":["Bàn phím và chuột bị lỏng cổng kết nối","Ổ cứng gần đầy dung lượng lưu trữ","RAM không đủ lớn để chứa dữ liệu của tất cả phần mềm đang chạy cùng lúc","CPU không có khả năng điều khiển thiết bị ra"],"answer":2,"explain":"Dung lượng ổ cứng còn trống không quyết định độ mượt khi chạy nhiều phần mềm cùng lúc - đó là vai trò của RAM. Khi RAM không đủ chứa dữ liệu của mọi phần mềm đang mở, máy phải xử lí bù trừ liên tục, gây chậm và giật dù ổ cứng vẫn còn dung lượng trống."},{"id":"CB-tf-301","type":"tf","topic":"A","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"CPU là bộ phận thực hiện các phép tính và điều khiển hoạt động của máy tính.","correct":true},{"text":"RAM là nơi lưu trữ dữ liệu lâu dài, không bị mất khi tắt máy.","correct":false},{"text":"Bàn phím và chuột là các thiết bị vào, dùng để đưa dữ liệu hoặc lệnh vào máy tính.","correct":true},{"text":"Ổ SSD hoạt động bằng đĩa từ quay cơ học, giống hệt nguyên lí của ổ HDD.","correct":false}],"explain":"(1) Đúng - CPU thực hiện phép tính và điều khiển các bộ phận khác của máy tính. (2) Sai - đó là vai trò của bộ nhớ ngoài (ổ cứng); RAM chỉ lưu tạm và mất dữ liệu khi mất điện. (3) Đúng - bàn phím, chuột đưa dữ liệu, lệnh từ người dùng vào máy tính nên là thiết bị vào. (4) Sai - SSD dùng chip nhớ điện tử, không có đĩa từ quay cơ học như HDD, nên thường nhanh và bền hơn."},{"id":"CB-mc-401","type":"mc","topic":"B","grade":11,"level":"easy","question":"Phần mở rộng (ví dụ `.docx`, `.jpg`) trong tên một tệp cho ta biết điều gì?","options":["Ngày giờ tệp được tạo ra","Kích thước của tệp đó, tính theo byte","Loại nội dung của tệp, giúp máy tính biết nên mở bằng phần mềm nào","Tên của người đã tạo ra tệp đó"],"answer":2,"explain":"Phần mở rộng là các kí tự đứng sau dấu chấm cuối cùng trong tên tệp (như `.docx`, `.jpg`, `.mp3`), cho máy tính biết tệp thuộc loại gì để mở bằng đúng phần mềm. Nó không thể hiện kích thước, ngày tạo hay người tạo ra tệp."},{"id":"CB-mc-402","type":"mc","topic":"B","grade":11,"level":"easy","question":"Trong bốn tên tệp sau, tệp nào là một tệp âm thanh?","options":["baocao.docx","dethi.pdf","anhbien.jpg","baihat.mp3"],"answer":3,"explain":"Phần mở rộng `.mp3` dùng cho tệp âm thanh, nên `baihat.mp3` là tệp âm thanh. `.docx` là văn bản Word, `.pdf` là văn bản PDF, `.jpg` là hình ảnh — đều không phải âm thanh."},{"id":"CB-mc-403","type":"mc","topic":"B","grade":11,"level":"medium","question":"Phát biểu nào sau đây mô tả đúng nhất quan hệ giữa thư mục và tệp?","options":["Thư mục và tệp thực chất là một, chỉ khác tên gọi","Một thư mục có thể chứa cả tệp lẫn thư mục con khác, tạo nên cấu trúc nhiều tầng","Một tệp có thể chứa nhiều thư mục con bên trong nó","Mỗi thư mục chỉ được phép chứa đúng một tệp duy nhất"],"answer":1,"explain":"Thư mục có thể chứa nhiều tệp và nhiều thư mục con; các thư mục con lại có thể chứa tiếp thư mục con khác, tạo thành cây thư mục nhiều tầng. Tệp thì không chứa được thư mục hay tệp nào khác bên trong nó."},{"id":"CB-mc-404","type":"mc","topic":"B","grade":11,"level":"medium","question":"Xét đường dẫn `D:\\HocTap\\Tin\\baitap.py`. Thư mục `Tin` có quan hệ thế nào với thư mục `HocTap`?","options":["`Tin` là thư mục con nằm bên trong `HocTap`","`Tin` là thư mục gốc, chứa `HocTap` bên trong","`Tin` và `HocTap` là tên của hai ổ đĩa khác nhau","`Tin` chính là tên của tệp `baitap.py`"],"answer":0,"explain":"Đọc đường dẫn từ trái sang phải: ổ đĩa `D:` chứa thư mục `HocTap`, bên trong `HocTap` có thư mục con `Tin`, và trong `Tin` có tệp `baitap.py`. Vậy `Tin` là thư mục con nằm bên trong `HocTap`, không phải ngược lại."},{"id":"CB-mc-405","type":"mc","topic":"B","grade":11,"level":"hard","question":"Trên cùng một ổ đĩa, có thể tồn tại hai tệp cùng tên `baitap.py` hay không?","options":["Không thể, vì tên tệp trên toàn bộ ổ đĩa phải là duy nhất","Không thể, vì phần mở rộng `.py` chỉ được dùng một lần trên mỗi ổ đĩa","Có thể, nhưng máy tính sẽ tự động đổi tên một trong hai tệp","Có thể, nếu hai tệp đó nằm trong hai thư mục khác nhau, vì khi đó đường dẫn của chúng khác nhau"],"answer":3,"explain":"Máy tính phân biệt tệp theo đường dẫn đầy đủ chứ không chỉ theo tên tệp; hai tệp cùng tên nhưng nằm ở hai thư mục khác nhau sẽ có đường dẫn khác nhau nên vẫn tồn tại song song bình thường. Chỉ trong CÙNG một thư mục thì hai tệp mới không được phép trùng tên."},{"id":"CB-tf-401","type":"tf","topic":"B","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Phần mở rộng của tệp thường là các kí tự đứng sau dấu chấm cuối cùng trong tên tệp.","correct":true},{"text":"Một thư mục chỉ được phép chứa tệp, tuyệt đối không được chứa thư mục con khác.","correct":false},{"text":"Đường dẫn cho biết chính xác vị trí của một tệp trong cây thư mục.","correct":true},{"text":"Sao lưu dữ liệu nghĩa là xóa bớt các tệp cũ đi để giải phóng dung lượng ổ đĩa.","correct":false}],"explain":"(1) đúng vì phần mở rộng chính là các kí tự sau dấu chấm cuối trong tên tệp, ví dụ `.jpg`, `.mp3`. (2) sai vì thư mục hoàn toàn có thể chứa thư mục con bên trong, đó chính là cách tạo nên cây thư mục nhiều tầng. (3) đúng vì đường dẫn ghi lại hành trình từ ổ đĩa, qua từng thư mục con, đến đúng tệp cần tìm. (4) sai vì sao lưu là tạo thêm một bản sao dữ liệu quan trọng ở nơi khác để phòng khi bản chính gặp sự cố, không phải là xóa bớt tệp."},{"id":"CB-mc-501","type":"mc","topic":"B","grade":11,"level":"easy","question":"Câu nào sau đây mô tả đúng vai trò của từ khoá khi tìm kiếm thông tin trên Internet?","options":["Từ khoá là câu hỏi đầy đủ, viết càng dài càng giúp công cụ tìm kiếm hiểu rõ ý người dùng","Từ khoá là những từ hoặc cụm từ cốt lõi, đúng trọng tâm, giúp công cụ tìm kiếm khoanh vùng đúng nội dung cần tìm","Từ khoá chỉ có tác dụng khi được viết in hoa toàn bộ","Từ khoá không ảnh hưởng gì đến kết quả tìm kiếm trả về"],"answer":1,"explain":"Công cụ tìm kiếm hoạt động bằng cách so khớp từ khoá — các từ, cụm từ cốt lõi, đúng trọng tâm — với nội dung có sẵn trên các trang web, nên chọn từ khoá ngắn gọn, đúng trọng tâm sẽ cho kết quả sát nhu cầu hơn là gõ nguyên một câu hỏi dài dòng."},{"id":"CB-mc-502","type":"mc","topic":"B","grade":11,"level":"easy","question":"Khi muốn tìm chính xác một cụm từ theo đúng thứ tự các từ, nên làm gì khi gõ vào ô tìm kiếm?","options":["Gõ cụm từ đó và đặt trong cặp dấu ngoặc kép","Viết cụm từ đó bằng chữ in hoa toàn bộ","Thêm dấu chấm hỏi vào cuối cụm từ","Tách rời từng từ trong cụm ra, mỗi từ tìm một lần riêng"],"answer":0,"explain":"Đặt một cụm từ trong cặp dấu ngoặc kép báo cho công cụ tìm kiếm biết cần trả về đúng các trang có nguyên văn cụm từ đó, theo đúng thứ tự, thay vì các trang chỉ chứa rời rạc từng từ trong cụm."},{"id":"CB-mc-503","type":"mc","topic":"B","grade":11,"level":"medium","question":"Một người gõ từ khoá `python` vào ô tìm kiếm nhưng nhận về đủ loại kết quả không liên quan đến lập trình, kể cả kết quả về loài trăn. Cách nào sau đây giúp thu hẹp đúng kết quả cần tìm?","options":["Thêm từ khoá phụ liên quan đến điều cần tìm, ví dụ gõ `python lập trình`","Gõ lại đúng từ `python` thêm một lần nữa","Xoá bớt một chữ cái trong từ khoá `python`","Đổi từ khoá `python` sang toàn chữ in hoa"],"answer":0,"explain":"Thêm từ khoá phụ đúng trọng tâm (như `lập trình`) giúp giới hạn phạm vi tìm kiếm vào đúng chủ đề cần tìm, loại bớt các kết quả không liên quan. Các cách còn lại không có tác dụng thu hẹp kết quả."},{"id":"CB-mc-504","type":"mc","topic":"B","grade":11,"level":"medium","question":"Đọc được một tin tức có tiêu đề rất giật gân trên một trang không rõ tác giả, và không có trang uy tín nào khác nhắc đến sự việc này. Nên hành động thế nào là hợp lý nhất?","options":["Tin ngay và chia sẻ tiếp cho nhiều người khác biết","Bỏ qua tiêu đề, chỉ đọc phần bình luận bên dưới bài viết để xác minh","Cảnh giác, đối chiếu thêm với các nguồn chính thống hoặc chuyên gia trước khi tin hoặc chia sẻ","Tin ngay vì tiêu đề càng giật gân thì độ tin cậy càng cao"],"answer":2,"explain":"Tiêu đề giật gân, nguồn không rõ tác giả và không có nguồn nào khác xác nhận là những dấu hiệu cần cảnh giác; nên đối chiếu thêm với nguồn chính thống hoặc chuyên gia trước khi tin theo hay chia sẻ tiếp, tránh vô tình lan truyền tin sai lệch."},{"id":"CB-mc-505","type":"mc","topic":"B","grade":11,"level":"hard","question":"Một học sinh đọc một đoạn phân tích trên một trang web, đổi một vài từ trong câu cho khác đi, rồi nộp bài mà không ghi nguồn nào. Hành động này có vi phạm bản quyền hay không?","options":["Không, vì đã đổi từ ngữ nên không còn giống nguyên văn nữa","Không, vì thông tin trên Internet là miễn phí cho tất cả mọi người sử dụng lại tuỳ ý","Có, vì chỉ đổi vài từ mà không tự viết lại theo cách hiểu của mình và không ghi rõ nguồn tham khảo vẫn coi là đạo văn","Có, nhưng chỉ vi phạm nếu đoạn văn đó dài hơn một trang giấy"],"answer":2,"explain":"Chỉ đổi vài từ mà vẫn giữ nguyên cấu trúc, ý tưởng của nguồn gốc, đồng thời không ghi rõ nguồn tham khảo, vẫn được coi là đạo văn — một hình thức vi phạm bản quyền. Cách làm đúng là đọc hiểu, viết lại theo cách diễn đạt của chính mình, và luôn ghi rõ nguồn đã tham khảo."},{"id":"CB-tf-501","type":"tf","topic":"B","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Có quyền truy cập Internet đồng nghĩa với việc tự động trở thành người hiểu biết, không cần thêm kỹ năng tìm kiếm hay đánh giá thông tin nào khác.","correct":false},{"text":"Đặt một cụm từ trong dấu ngoặc kép khi tìm kiếm giúp công cụ tìm kiếm trả về đúng các trang có nguyên văn cụm từ đó.","correct":true},{"text":"Nên ưu tiên tin theo thông tin từ nguồn chính thống hoặc chuyên gia, đồng thời đối chiếu thêm với nhiều nguồn khác trước khi tin hẳn.","correct":true},{"text":"Khi dùng lại số liệu hay ý tưởng từ một trang web khác cho bài viết của mình, không cần ghi nguồn miễn là đã hiểu rõ nội dung đó.","correct":false}],"explain":"(1) sai vì chỉ có quyền truy cập Internet chưa đủ, cần thêm kỹ năng tìm kiếm, đánh giá và trích dẫn thông tin mới khai thác được hiệu quả. (2) đúng vì đặt cụm từ trong dấu ngoặc kép báo cho công cụ tìm kiếm trả về đúng nguyên văn cụm từ đó, theo đúng thứ tự. (3) đúng vì đối chiếu nhiều nguồn, ưu tiên nguồn chính thống hoặc chuyên gia là cách đánh giá độ tin cậy hợp lý. (4) sai vì dù đã hiểu rõ nội dung, khi dùng lại số liệu hay ý tưởng của người khác vẫn cần ghi rõ nguồn tham khảo, nếu không sẽ bị coi là đạo văn."},{"id":"CB-mc-601","type":"mc","topic":"C","grade":11,"level":"easy","question":"Khi nào việc ghi chép dữ liệu bằng sổ tay hoặc bảng tính thông thường vẫn có thể đáp ứng tốt?","options":["Khi dữ liệu cần cập nhật liên tục bởi nhiều bộ phận khác nhau","Khi có hàng trăm người cùng truy cập một lúc","Khi dữ liệu ít và chỉ một người sử dụng","Khi dữ liệu có hàng triệu bản ghi"],"answer":2,"explain":"Với dữ liệu ít và chỉ một người dùng, sổ tay hay bảng tính là đủ; vấn đề chỉ thật sự nảy sinh khi dữ liệu lớn dần và có nhiều người cùng khai thác."},{"id":"CB-mc-602","type":"mc","topic":"C","grade":11,"level":"easy","question":"Cơ sở dữ liệu (`database`) được hiểu là gì?","options":["Một cuốn sổ tay ghi chép dữ liệu bằng tay","Một tập hợp dữ liệu có tổ chức, lưu trên máy tính để nhiều người/chương trình cùng khai thác","Một chiếc máy tính chuyên dùng để lưu trữ ảnh","Một loại phần mềm diệt virus"],"answer":1,"explain":"Cơ sở dữ liệu là tập dữ liệu có tổ chức, được lưu trên máy tính theo cấu trúc nhất quán, hỗ trợ nhiều người/chương trình cùng truy cập. Đây không phải một cuốn sổ tay, một loại máy tính chuyên dụng, hay một phần mềm diệt virus."},{"id":"CB-mc-603","type":"mc","topic":"C","grade":11,"level":"medium","question":"Một cửa hàng lưu danh sách khách hàng vừa ở sổ tay của quầy thu ngân, vừa ở file Excel của bộ phận kế toán; hai nơi thường xuyên lệch thông tin với nhau. Đây là biểu hiện rõ nhất của vấn đề gì?","options":["Thiếu dung lượng lưu trữ","Máy tính bị nhiễm virus","Tốc độ mạng internet chậm","Mâu thuẫn dữ liệu do lưu trùng lặp ở nhiều nơi"],"answer":3,"explain":"Khi cùng một thông tin được lưu ở nhiều nơi khác nhau nhưng không đồng bộ, các nơi đó dễ cho ra kết quả khác nhau — đây chính là mâu thuẫn dữ liệu phát sinh từ trùng lặp, không liên quan đến dung lượng lưu trữ, virus hay tốc độ mạng."},{"id":"CB-mc-604","type":"mc","topic":"C","grade":11,"level":"hard","question":"Bản chất của việc dùng cơ sở dữ liệu, so với việc chỉ đơn thuần có thật nhiều dữ liệu, nằm ở đâu?","options":["Ở cách dữ liệu được tổ chức và chia sẻ, không chỉ ở số lượng dữ liệu nhiều hay ít","Ở việc có càng nhiều dữ liệu thì tự nhiên sẽ có một cơ sở dữ liệu tốt","Ở việc không liên quan gì đến chuyện nhiều người cùng truy cập","Ở việc dữ liệu càng nhiều thì càng ít xảy ra trùng lặp"],"answer":0,"explain":"Giá trị của cơ sở dữ liệu nằm ở cách dữ liệu được tổ chức, chuẩn hoá và chia sẻ cho nhiều người/chương trình cùng dùng — không phải ở việc có nhiều dữ liệu. Thực tế, dữ liệu càng nhiều mà càng thiếu tổ chức thì trùng lặp, mâu thuẫn càng dễ xảy ra hơn, chứ không phải ít đi."},{"id":"CB-mc-605","type":"mc","topic":"C","grade":11,"level":"hard","question":"Một trường học chuyển toàn bộ sổ điểm giấy thành nhiều file Excel riêng lẻ, mỗi giáo viên giữ một file trên máy tính cá nhân, không chia sẻ với ai. Nhận định nào sau đây đúng nhất?","options":["Đây đã là một cơ sở dữ liệu hoàn chỉnh vì dữ liệu đã ở dạng file trên máy tính","Vấn đề trùng lặp dữ liệu sẽ tự động biến mất khi chuyển sang Excel","Vẫn còn nguy cơ trùng lặp, khó tổng hợp và mâu thuẫn dữ liệu như khi dùng sổ giấy, vì dữ liệu chưa thật sự được tổ chức để dùng chung","Không cần quan tâm đến việc chia sẻ dữ liệu vì Excel đã đủ an toàn"],"answer":2,"explain":"Chỉ chuyển dữ liệu sang file máy tính chưa đủ để gọi là cơ sở dữ liệu nếu dữ liệu vẫn rời rạc, không dùng chung được. Các vấn đề trùng lặp, khó tổng hợp, mâu thuẫn vẫn còn nguyên vì bản chất là do thiếu tổ chức và chia sẻ, chứ không phải do dùng giấy hay dùng máy tính."},{"id":"CB-tf-601","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Cơ sở dữ liệu giúp giảm tình trạng trùng lặp dữ liệu so với việc ghi chép rời rạc trên nhiều sổ sách.","correct":true},{"text":"Cơ sở dữ liệu chỉ phù hợp khi dữ liệu ít và chỉ một người truy cập, không phù hợp khi có nhiều người cùng dùng chung.","correct":false},{"text":"Dữ liệu có cấu trúc trong cơ sở dữ liệu giúp việc tìm kiếm thông tin nhanh hơn nhiều so với lật tìm trong sổ giấy.","correct":true},{"text":"Hễ dữ liệu đã được lưu trên máy tính dưới dạng file thì chắc chắn không còn xảy ra mâu thuẫn dữ liệu.","correct":false}],"explain":"(1) Đúng — trong cơ sở dữ liệu, mỗi thông tin lí tưởng chỉ lưu một lần nên giảm hẳn trùng lặp. (2) Sai — cơ sở dữ liệu đặc biệt hữu ích khi nhiều người hoặc nhiều chương trình cùng cần truy cập chung một nguồn dữ liệu. (3) Đúng — dữ liệu có cấu trúc giúp máy tính lọc và tìm kiếm nhanh hơn hẳn so với lật sổ giấy thủ công. (4) Sai — nếu dữ liệu trên máy tính vẫn rời rạc, không tổ chức, không chia sẻ (ví dụ nhiều file Excel riêng lẻ không đồng bộ), mâu thuẫn dữ liệu vẫn có thể xảy ra."},{"id":"CB-mc-701","type":"mc","topic":"C","grade":11,"level":"easy","question":"Trong cơ sở dữ liệu quan hệ, dữ liệu được tổ chức chủ yếu dưới dạng gì?","options":["Các bảng gồm hàng và cột","Một chuỗi văn bản dài duy nhất","Các hình ảnh minh hoạ","Một danh sách tệp rời rạc, không liên quan tới nhau"],"answer":0,"explain":"Cơ sở dữ liệu quan hệ tổ chức dữ liệu thành các bảng; mỗi bảng có hàng (bản ghi) và cột (trường). Các phương án còn lại không phải cách tổ chức dữ liệu của mô hình quan hệ."},{"id":"CB-mc-702","type":"mc","topic":"C","grade":11,"level":"easy","question":"Trong một bảng dữ liệu, mỗi HÀNG được gọi là gì?","options":["Một trường (`field`)","Một khoá ngoại","Một bản ghi (`record`)","Một cơ sở dữ liệu"],"answer":2,"explain":"Mỗi hàng gộp đầy đủ thông tin của một đối tượng cụ thể nên được gọi là một bản ghi (`record`). Trường (`field`) là tên gọi của cột, không phải hàng."},{"id":"CB-mc-703","type":"mc","topic":"C","grade":11,"level":"medium","question":"Bảng `HOC_SINH` có hai học sinh cùng tên Nguyễn Văn A nhưng khác `Ma` (`HS01` và `HS03`). Điều này cho thấy trường nào phù hợp để làm khoá chính?","options":["`HoTen`, vì dễ nhớ","`Ma`, vì giá trị của nó không trùng nhau giữa các học sinh","`Lop`, vì học sinh nào cũng có lớp","Không trường nào phù hợp, phải thêm cột mới"],"answer":1,"explain":"Khoá chính phải có giá trị duy nhất cho từng bản ghi. `Ma` đảm bảo điều đó, trong khi `HoTen` có thể trùng như ví dụ trên cho thấy."},{"id":"CB-mc-704","type":"mc","topic":"C","grade":11,"level":"medium","question":"Trong bảng `DIEM` (`Ma`, `MonHoc`, `Diem`), cột `Ma` đóng vai trò gì đối với bảng `HOC_SINH`?","options":["Là một trường thừa, có thể xoá đi","Là tên gọi khác của bảng `HOC_SINH`","Là khoá ngoại, trỏ tới bản ghi tương ứng trong bảng `HOC_SINH`","Là khoá chính của bảng `DIEM` và không liên quan gì tới bảng `HOC_SINH`"],"answer":2,"explain":"Cột `Ma` trong bảng `DIEM` là khoá ngoại: nó tham chiếu tới khoá chính `Ma` của bảng `HOC_SINH` để biết dòng điểm đó thuộc về học sinh nào."},{"id":"CB-mc-705","type":"mc","topic":"C","grade":11,"level":"hard","question":"Nếu bảng `DIEM` không dùng khoá ngoại mà lưu trực tiếp đầy đủ họ tên, lớp cho mỗi dòng điểm, vấn đề dễ gặp nhất là gì?","options":["Bảng sẽ chạy nhanh hơn hẳn","Không thể tính điểm trung bình được nữa","Bảng `HOC_SINH` sẽ tự động bị xoá","Họ tên, lớp bị lặp lại nhiều lần và dễ sai lệch khi một học sinh thi nhiều môn"],"answer":3,"explain":"Không dùng khoá ngoại, mỗi dòng điểm phải lặp lại toàn bộ họ tên, lớp — vừa tốn chỗ lưu vừa dễ gõ sai lệch giữa các dòng của cùng một học sinh, chẳng hạn ghi nhầm lớp ở dòng này so với dòng khác."},{"id":"CB-tf-701","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong một bảng dữ liệu, mỗi cột được gọi là một bản ghi.","correct":false},{"text":"Khoá chính là trường có giá trị không được trùng giữa các bản ghi trong cùng một bảng.","correct":true},{"text":"Khoá ngoại trong một bảng dùng để tham chiếu tới khoá chính của một bảng khác, giúp liên kết dữ liệu giữa hai bảng.","correct":true},{"text":"Tách dữ liệu thành nhiều bảng có liên kết khiến dữ liệu bị lặp lại nhiều hơn so với gộp tất cả vào một bảng duy nhất.","correct":false}],"explain":"(1) Sai — cột được gọi là trường (`field`); bản ghi (`record`) mới là tên gọi của hàng. (2) Đúng — đây chính là định nghĩa của khoá chính. (3) Đúng — khoá ngoại chính là điều giúp nối hai bảng lại với nhau thông qua khoá chính. (4) Sai — tách bảng và liên kết bằng khoá ngoại giúp tránh lặp lại dữ liệu, không phải làm tăng thêm."},{"id":"CB-mc-801","type":"mc","topic":"C","grade":11,"level":"easy","question":"`DBMS` (hệ quản trị cơ sở dữ liệu) là gì?","options":["Một loại phần cứng dùng để lưu trữ dữ liệu","Phần mềm giúp tạo, lưu trữ, cập nhật, truy vấn và bảo vệ cơ sở dữ liệu","Tên gọi khác của tệp dữ liệu thô","Một ngôn ngữ lập trình dùng để viết ứng dụng web"],"answer":1,"explain":"`DBMS` là **phần mềm** đứng giữa người dùng và dữ liệu thực để thực hiện các thao tác tạo, lưu trữ, cập nhật, truy vấn, bảo vệ — không phải phần cứng, không phải bản thân tệp dữ liệu, cũng không phải ngôn ngữ lập trình."},{"id":"CB-mc-802","type":"mc","topic":"C","grade":11,"level":"easy","question":"Phần mềm nào sau đây là một hệ quản trị cơ sở dữ liệu (DBMS)?","options":["`MySQL`","Microsoft Word","Adobe Photoshop","Windows Media Player"],"answer":0,"explain":"`MySQL` là một DBMS phổ biến, dùng để lưu trữ và truy vấn dữ liệu. Word dùng để soạn thảo văn bản, Photoshop để xử lý ảnh, Windows Media Player để phát nhạc/video — đều không phải DBMS."},{"id":"CB-mc-803","type":"mc","topic":"C","grade":11,"level":"medium","question":"Chức năng nào sau đây KHÔNG phải do DBMS đảm nhiệm?","options":["Thêm, sửa, xoá dữ liệu","Phân quyền truy cập cho từng nhóm người dùng","Sao lưu và phục hồi dữ liệu khi có sự cố","Thiết kế giao diện đồ hoạ cho trò chơi điện tử"],"answer":3,"explain":"DBMS phụ trách các việc liên quan tới quản lý dữ liệu: thêm/sửa/xoá/tìm, giữ dữ liệu đúng và nhất quán, phân quyền, sao lưu và phục hồi. Thiết kế đồ hoạ trò chơi điện tử là việc của phần mềm đồ hoạ, không liên quan tới chức năng của DBMS."},{"id":"CB-mc-804","type":"mc","topic":"C","grade":11,"level":"medium","question":"Người quản trị cơ sở dữ liệu (`DBA`) có vai trò nào sau đây?","options":["Chỉ được xem dữ liệu, không có quyền thay đổi gì trong hệ thống","Viết các trang web hiển thị dữ liệu cho người dùng cuối","Thiết kế cấu trúc cơ sở dữ liệu, cấp quyền truy cập và bảo trì hệ thống","Thay thế hoàn toàn vai trò của DBMS trong việc lưu trữ dữ liệu"],"answer":2,"explain":"`DBA` là người thiết kế cấu trúc CSDL ngay từ đầu, quyết định ai được cấp quyền xem/sửa phần dữ liệu nào, và theo dõi, bảo trì hệ thống. DBA sử dụng DBMS như công cụ để làm những việc này chứ không thay thế nó."},{"id":"CB-mc-805","type":"mc","topic":"C","grade":11,"level":"hard","question":"Phát biểu nào sau đây phân biệt ĐÚNG NHẤT giữa ‘cơ sở dữ liệu’ và ‘hệ quản trị cơ sở dữ liệu (DBMS)’?","options":["Cơ sở dữ liệu là khối dữ liệu được tổ chức, lưu trữ; DBMS là phần mềm giúp tạo, truy vấn và bảo vệ khối dữ liệu đó","Cơ sở dữ liệu và DBMS là hai tên gọi khác nhau của cùng một phần mềm","DBMS là dữ liệu thô; cơ sở dữ liệu là phần mềm quản lý dữ liệu đó","Một máy tính chỉ có thể có cơ sở dữ liệu hoặc DBMS, không thể có cả hai cùng lúc"],"answer":0,"explain":"Cơ sở dữ liệu là bản thân khối dữ liệu (giống toàn bộ sách trong thư viện); DBMS là phần mềm quản lý khối dữ liệu đó (giống người thủ thư). Hai khái niệm khác nhau nhưng luôn đi cùng nhau: có DBMS thì mới khai thác, cập nhật và bảo vệ dữ liệu một cách an toàn, tiện lợi."},{"id":"CB-tf-801","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"DBMS là phần mềm, không phải là bản thân cơ sở dữ liệu.","correct":true},{"text":"Khi dùng DBMS, người dùng vẫn phải tự mở tệp dữ liệu thô để sửa từng dòng bằng tay.","correct":false},{"text":"Một trong các chức năng của DBMS là phân quyền, tức quyết định ai được xem hoặc sửa phần dữ liệu nào.","correct":true},{"text":"Người quản trị cơ sở dữ liệu (DBA) là một phần mềm được cài thêm vào DBMS.","correct":false}],"explain":"(1) Đúng — DBMS là phần mềm quản lý, còn cơ sở dữ liệu mới là khối dữ liệu được quản lý. (2) Sai — DBMS đứng giữa người dùng và dữ liệu, ta gửi yêu cầu cho DBMS chứ không tự sửa trực tiếp tệp dữ liệu thô. (3) Đúng — phân quyền là một trong bốn chức năng chính của DBMS. (4) Sai — DBA là con người (người quản trị hệ thống), không phải phần mềm; DBA sử dụng DBMS như công cụ để làm việc."},{"id":"CB-mc-901","type":"mc","topic":"C","grade":11,"level":"easy","question":"Trong câu lệnh SQL, từ khoá nào dùng để nêu rõ dữ liệu được lấy từ bảng nào?","options":["WHERE","ORDER BY","FROM","SELECT"],"answer":2,"explain":"`FROM` dùng để nêu tên bảng chứa dữ liệu cần lấy. `SELECT` nêu các cột cần lấy, `WHERE` nêu điều kiện lọc, còn `ORDER BY` dùng để sắp xếp kết quả — không phải để chỉ định bảng."},{"id":"CB-mc-902","type":"mc","topic":"C","grade":11,"level":"easy","question":"Muốn lấy TẤT CẢ các cột của một bảng mà không cần gõ tên từng cột, ta viết:","options":["SELECT *","SELECT FULL","SELECT ALL","SELECT %"],"answer":0,"explain":"Dấu `*` ngay sau `SELECT` nghĩa là ‘lấy tất cả các cột’ của bảng, không cần gõ tên từng cột. Các cách viết còn lại không mang ý nghĩa ‘lấy mọi cột’ như `SELECT *`."},{"id":"CB-mc-903","type":"mc","topic":"C","grade":11,"level":"medium","question":"Cho bảng `HOC_SINH(Ma, HoTen, Lop, Diem)`. Câu lệnh `SELECT HoTen FROM HOC_SINH WHERE Lop = '11A2';` trả về kết quả nào?","options":["Toàn bộ 4 cột của những học sinh lớp 11A2","Chỉ cột HoTen, của những học sinh thuộc lớp 11A2","Chỉ cột HoTen, của tất cả học sinh trong bảng","Chỉ cột Lop, của những học sinh có tên bắt đầu bằng 11A2"],"answer":1,"explain":"`SELECT HoTen` chỉ lấy cột họ tên (bỏ qua Ma, Lop, Diem); `WHERE Lop = '11A2'` lọc, chỉ giữ những dòng có cột Lop đúng bằng ‘11A2’. Kết quả là danh sách họ tên của riêng các học sinh lớp 11A2."},{"id":"CB-mc-904","type":"mc","topic":"C","grade":11,"level":"medium","question":"Muốn sắp xếp danh sách học sinh theo Điểm từ THẤP đến CAO, ta thêm vào cuối câu lệnh:","options":["ORDER BY Diem DESC","WHERE Diem ASC","GROUP BY Diem","ORDER BY Diem ASC"],"answer":3,"explain":"`ASC` (ascending) nghĩa là tăng dần — từ thấp đến cao — nên `ORDER BY Diem ASC` đúng yêu cầu. `DESC` là giảm dần (cao đến thấp); `WHERE` dùng để lọc dữ liệu chứ không dùng để sắp xếp; bài học này chưa đề cập đến `GROUP BY`."},{"id":"CB-mc-905","type":"mc","topic":"C","grade":11,"level":"hard","question":"Câu lệnh nào sau đây đúng cú pháp (đúng thứ tự các mệnh đề)?","options":["SELECT HoTen FROM HOC_SINH ORDER BY Diem WHERE Diem >= 8;","FROM HOC_SINH SELECT HoTen WHERE Diem >= 8;","SELECT HoTen FROM HOC_SINH WHERE Diem >= 8 ORDER BY Diem DESC;","SELECT HoTen WHERE Diem >= 8 FROM HOC_SINH;"],"answer":2,"explain":"Thứ tự chuẩn của một câu truy vấn là `SELECT ... FROM ... WHERE ... ORDER BY ...;`. Ba phương án còn lại đổi chỗ các mệnh đề (đưa ORDER BY trước WHERE, đưa FROM lên đầu, hoặc đưa WHERE trước FROM) nên sai cú pháp."},{"id":"CB-tf-901","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Mỗi câu lệnh SQL kết thúc bằng dấu chấm phẩy `;`.","correct":true},{"text":"`SELECT *` chỉ lấy cột đầu tiên của bảng, các cột còn lại bị bỏ qua.","correct":false},{"text":"Mệnh đề `WHERE` dùng để lọc, chỉ giữ lại những dòng thoả điều kiện đã nêu.","correct":true},{"text":"Khi kết hợp hai điều kiện bằng `AND` trong mệnh đề `WHERE`, chỉ cần MỘT trong hai điều kiện đúng là dòng đó được giữ lại.","correct":false}],"explain":"(1) Đúng — dấu `;` đánh dấu kết thúc một câu lệnh SQL. (2) Sai — `SELECT *` lấy TẤT CẢ các cột của bảng, không phải chỉ cột đầu tiên. (3) Đúng — `WHERE` là mệnh đề lọc, chỉ giữ lại các dòng thoả mãn điều kiện, các dòng còn lại bị loại khỏi kết quả. (4) Sai — `AND` yêu cầu CẢ HAI điều kiện phải đúng thì dòng đó mới được giữ; ‘chỉ cần một trong hai đúng’ là ý nghĩa của `OR`."},{"id":"CB-mc-1001","type":"mc","topic":"C","grade":11,"level":"easy","question":"Lệnh SQL nào dùng để thêm một dòng dữ liệu mới vào bảng?","options":["`SELECT`","`INSERT INTO`","`UPDATE`","`DELETE FROM`"],"answer":1,"explain":"`INSERT INTO` dùng để thêm một dòng mới vào bảng. `SELECT` dùng để truy vấn (xem dữ liệu), `UPDATE` dùng để sửa dữ liệu đã có, còn `DELETE FROM` dùng để xoá dữ liệu — không phải để thêm mới."},{"id":"CB-mc-1002","type":"mc","topic":"C","grade":11,"level":"easy","question":"Trong câu lệnh `UPDATE HOC_SINH SET Diem = 9.0 WHERE Ma = 'HS021';`, mệnh đề nào xác định chỉ dòng nào bị thay đổi?","options":["`SET`","`UPDATE`","`WHERE`","`HOC_SINH`"],"answer":2,"explain":"`WHERE` là mệnh đề điều kiện, chỉ những dòng thoả điều kiện đó (ở đây là `Ma = 'HS021'`) mới bị sửa. `SET` chỉ cho biết cột nào và giá trị mới là gì, không giới hạn phạm vi dòng bị ảnh hưởng."},{"id":"CB-mc-1003","type":"mc","topic":"C","grade":11,"level":"medium","question":"Cho bảng `HOC_SINH(Ma, HoTen, Lop, Diem)`. Câu lệnh nào sau đây thêm đúng một học sinh mới có Ma là HS030, HoTen là Trần Thị Cúc, Lop là 12A1, Diem là 7.5?","options":["`INSERT INTO HOC_SINH (Ma, HoTen, Lop, Diem) WHERE VALUES ('HS030', 'Trần Thị Cúc', '12A1', 7.5);`","`UPDATE HOC_SINH SET Ma='HS030', HoTen='Trần Thị Cúc', Lop='12A1', Diem=7.5;`","`INSERT INTO HOC_SINH (Ma, HoTen, Lop, Diem) VALUES ('HS030', 'Trần Thị Cúc', '12A1', 7.5);`","`INSERT HOC_SINH (Ma, HoTen, Lop, Diem) VALUES ('HS030', 'Trần Thị Cúc', '12A1', 7.5);`"],"answer":2,"explain":"Thêm dòng mới phải viết đầy đủ `INSERT INTO bảng (cột...) VALUES (giá_trị...);`, với thứ tự giá trị khớp đúng thứ tự cột. Phương án dùng `UPDATE` là sai vì đó là lệnh sửa dữ liệu đã có chứ không phải thêm mới, lại còn thiếu `WHERE` nên rất nguy hiểm nếu lỡ chạy. Hai phương án còn lại sai cú pháp: một đặt `WHERE` sai chỗ (INSERT không có mệnh đề này), một thiếu hẳn từ khoá `INTO`."},{"id":"CB-mc-1004","type":"mc","topic":"C","grade":11,"level":"medium","question":"Điều gì xảy ra khi chạy `DELETE FROM HOC_SINH;` (không kèm `WHERE`)?","options":["Toàn bộ các dòng trong bảng HOC_SINH bị xoá","Không có gì xảy ra vì thiếu điều kiện","Chỉ dòng đầu tiên trong bảng bị xoá","Bảng HOC_SINH bị xoá hẳn khỏi cơ sở dữ liệu, không còn cả cấu trúc bảng"],"answer":0,"explain":"Khi `DELETE FROM` không kèm `WHERE`, điều kiện coi như đúng với mọi dòng, nên toàn bộ dữ liệu trong bảng bị xoá. Câu lệnh vẫn chạy bình thường — không báo lỗi, không chỉ xoá một dòng — và bảng (tên bảng, các cột) vẫn còn tồn tại, chỉ là rỗng, chứ không biến mất khỏi cơ sở dữ liệu."},{"id":"CB-mc-1005","type":"mc","topic":"C","grade":11,"level":"hard","question":"Bảng HOC_SINH có 3 dòng với Lop lần lượt là 11A1, 11A2, 11A3. Sau khi chạy `UPDATE HOC_SINH SET Lop = '11A1';` (không kèm `WHERE`), điều gì xảy ra?","options":["Không có dòng nào thay đổi vì thiếu WHERE","Chỉ dòng đang có Lop là 11A1 được giữ nguyên, hai dòng còn lại giữ nguyên giá trị cũ của chúng","Câu lệnh báo lỗi và không chạy được vì UPDATE bắt buộc phải có WHERE","Cả 3 dòng đều có Lop thành 11A1, tức là mất luôn thông tin lớp thật của hai học sinh kia"],"answer":3,"explain":"Không có `WHERE` nghĩa là điều kiện áp dụng cho mọi dòng, nên cả ba dòng đều bị `SET Lop = '11A1'`, kể cả hai dòng vốn thuộc lớp 11A2 và 11A3 — thông tin lớp thật của họ bị ghi đè và mất hẳn. Câu lệnh không hề báo lỗi hay bị chặn lại; SQL vẫn chạy bình thường, chỉ là phạm vi tác động là toàn bộ bảng thay vì đúng một dòng."},{"id":"CB-tf-1001","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Lệnh SELECT cũng làm thay đổi dữ liệu trong bảng, giống như UPDATE.","correct":false},{"text":"Trong câu lệnh INSERT INTO, thứ tự giá trị liệt kê sau VALUES phải khớp với thứ tự cột đã liệt kê trước đó.","correct":true},{"text":"Nếu quên mệnh đề WHERE trong lệnh DELETE FROM, chỉ dòng đầu tiên của bảng bị xoá.","correct":false},{"text":"Mệnh đề WHERE trong UPDATE và DELETE dùng để giới hạn (những) dòng bị câu lệnh tác động tới.","correct":true}],"explain":"(1) Sai — SELECT chỉ dùng để truy vấn, xem dữ liệu, hoàn toàn không làm thay đổi bất kỳ giá trị nào trong bảng. (2) Đúng — giá trị trong VALUES phải khớp đúng thứ tự với danh sách cột đã nêu trong INSERT INTO. (3) Sai — DELETE FROM thiếu WHERE sẽ xoá TOÀN BỘ các dòng trong bảng, không chỉ riêng dòng đầu tiên. (4) Đúng — WHERE chính là điều kiện giới hạn phạm vi những dòng bị UPDATE hoặc DELETE tác động tới; thiếu nó, câu lệnh áp dụng cho cả bảng."},{"id":"CB-mc-1101","type":"mc","topic":"C","grade":11,"level":"easy","question":"Trong cơ sở dữ liệu, việc đảm bảo chỉ những người được cấp phép mới có thể xem, sửa hoặc lấy dữ liệu đi được gọi là gì?","options":["Toàn vẹn dữ liệu","An toàn dữ liệu","Truy vấn dữ liệu","Chuẩn hoá dữ liệu"],"answer":1,"explain":"An toàn dữ liệu tập trung vào việc chống truy cập, sửa đổi hoặc lấy dữ liệu trái phép. Toàn vẹn dữ liệu là một khái niệm khác — nói về việc bản thân nội dung dữ liệu có hợp lý, nhất quán hay không."},{"id":"CB-mc-1102","type":"mc","topic":"C","grade":11,"level":"easy","question":"Trong một trường học, giáo viên được phép nhập và sửa điểm của lớp mình dạy, còn học sinh chỉ được xem điểm của chính mình mà không được sửa. Đây là ví dụ của biện pháp nào?","options":["Sao lưu dữ liệu","Mã hoá dữ liệu","Phân quyền truy cập","Ràng buộc miền giá trị"],"answer":2,"explain":"Mỗi tài khoản (giáo viên, học sinh) được cấp một mức quyền khác nhau, phù hợp với công việc của mình — đây chính là biểu hiện của phân quyền truy cập."},{"id":"CB-mc-1103","type":"mc","topic":"C","grade":11,"level":"medium","question":"Một cơ sở dữ liệu quan trọng cần được sao lưu (backup) định kỳ. Để bản sao lưu thực sự phát huy tác dụng khi dữ liệu gốc gặp sự cố (cháy, hỏng ổ đĩa, bị mã độc phá hoại...), bản sao lưu nên được:","options":["Lưu trên cùng ổ đĩa với dữ liệu gốc để dễ đối chiếu","Lưu ở một nơi hoặc thiết bị khác với dữ liệu gốc","Chỉ cần tạo đúng một lần khi cơ sở dữ liệu mới được xây dựng","Xoá ngay bản cũ mỗi khi có bản sao lưu mới để tiết kiệm dung lượng"],"answer":1,"explain":"Nếu bản sao lưu nằm chung một chỗ với dữ liệu gốc, một sự cố duy nhất có thể phá huỷ cả hai cùng lúc, khiến việc sao lưu trở nên vô nghĩa. Bản sao lưu cần đặt ở nơi khác, và cần được cập nhật định kỳ chứ không chỉ một lần."},{"id":"CB-mc-1104","type":"mc","topic":"C","grade":11,"level":"hard","question":"Một cơ sở dữ liệu quy định: Mã học sinh của mỗi người phải là duy nhất, không trùng với ai khác; đồng thời cột Điểm chỉ được nhận giá trị từ 0 đến 10. Một người nhập dữ liệu cố thêm một học sinh mới với Điểm = 8.5 (hợp lệ) nhưng Mã học sinh lại trùng với một học sinh đã có sẵn trong bảng. Ràng buộc nào khiến hệ quản trị CSDL từ chối thao tác này?","options":["Ràng buộc miền giá trị, vì điểm 8.5 không hợp lệ","Ràng buộc khoá, vì mã học sinh bị trùng","Ràng buộc tham chiếu, vì thiếu bảng liên kết","Không ràng buộc nào bị vi phạm nên thao tác vẫn được chấp nhận"],"answer":1,"explain":"Điểm 8.5 nằm trong khoảng 0–10 nên không vi phạm ràng buộc miền giá trị. Vấn đề nằm ở Mã học sinh: vì mã này đóng vai trò khoá, phải là duy nhất, nên việc trùng mã với một dòng đã có sẵn sẽ vi phạm ràng buộc khoá và bị từ chối."},{"id":"CB-mc-1105","type":"mc","topic":"C","grade":11,"level":"hard","question":"Xét hai bảng: HOC_SINH (Mã học sinh là khoá chính) và DIEM_THI (mỗi dòng lưu điểm một học sinh, có cột Mã học sinh tham chiếu đến bảng HOC_SINH). Nếu hệ quản trị CSDL đang áp dụng ràng buộc tham chiếu giữa hai bảng này, điều gì sẽ xảy ra khi ai đó cố thêm vào DIEM_THI một dòng với Mã học sinh chưa từng xuất hiện trong bảng HOC_SINH?","options":["Hệ quản trị CSDL tự động tạo thêm một học sinh mới trong bảng HOC_SINH với mã đó","Dòng dữ liệu vẫn được thêm bình thường vào DIEM_THI","Hệ quản trị CSDL từ chối thêm dòng dữ liệu đó vào DIEM_THI","Toàn bộ bảng DIEM_THI sẽ bị xoá để đồng bộ dữ liệu"],"answer":2,"explain":"Ràng buộc tham chiếu yêu cầu Mã học sinh ở bảng DIEM_THI phải khớp với một mã đã tồn tại ở bảng HOC_SINH. Nếu không, hệ quản trị CSDL sẽ từ chối thao tác thêm dữ liệu, tránh tình trạng ‘điểm thi của một học sinh không tồn tại’ — một dạng mâu thuẫn giữa hai bảng."},{"id":"CB-tf-1101","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Chỉ cần đặt mật khẩu mạnh cho hệ thống là đủ để đảm bảo an toàn dữ liệu, không cần phân quyền truy cập nữa.","correct":false},{"text":"Ràng buộc toàn vẹn giúp hệ quản trị CSDL tự động từ chối những dữ liệu không hợp lệ, chẳng hạn một điểm số âm.","correct":true},{"text":"Bản sao lưu dữ liệu chỉ cần thực hiện đúng một lần, ngay khi cơ sở dữ liệu mới được tạo ra.","correct":false},{"text":"Mã hoá dữ liệu giúp dữ liệu khó bị đọc hoặc khai thác, ngay cả khi tệp dữ liệu bị đánh cắp.","correct":true}],"explain":"(1) Sai — mật khẩu chỉ là một lớp bảo vệ; vẫn cần phân quyền để giới hạn phạm vi mỗi tài khoản được làm gì sau khi đã đăng nhập. (2) Đúng — đây chính là vai trò của ràng buộc miền giá trị. (3) Sai — dữ liệu luôn thay đổi theo thời gian nên cần sao lưu định kỳ, không chỉ một lần duy nhất. (4) Đúng — mã hoá biến dữ liệu gốc thành dạng khó đọc nếu không có khoá giải mã, kể cả khi tệp bị lấy đi."},{"id":"CB-mc-1201","type":"mc","topic":"F","grade":11,"level":"easy","question":"Trong Python, kiểu dữ liệu nào thường được dùng để lưu một dãy nhiều giá trị cùng loại theo đúng thứ tự, đóng vai trò một mảng một chiều?","options":["int","list","str","bool"],"answer":1,"explain":"`list` lưu được nhiều giá trị theo đúng thứ tự và cho phép truy cập từng phần tử qua chỉ số nên đóng vai trò mảng một chiều; `int` và `bool` chỉ lưu đúng một giá trị, còn `str` dùng để lưu một chuỗi kí tự chứ không phải một dãy các giá trị độc lập như điểm số."},{"id":"CB-mc-1202","type":"mc","topic":"F","grade":11,"level":"easy","question":"Danh sách diem có 5 phần tử. Chỉ số nào dùng để truy cập phần tử đầu tiên của diem?","options":["diem[1]","diem[0]","diem(0)","diem.dau"],"answer":1,"explain":"Chỉ số trong Python bắt đầu từ 0 chứ không phải từ 1, nên phần tử đầu tiên là `diem[0]`; `diem(0)` và `diem.dau` không phải cú pháp truy cập phần tử của `list` trong Python."},{"id":"CB-mc-1203","type":"mc","topic":"F","grade":11,"level":"medium","question":"Cho diem = [6, 7, 8, 9] và đoạn code sau:\ntong = 0\nfor d in diem:\n    tong = tong + d\nSau khi đoạn code chạy xong, biến tong có giá trị bằng bao nhiêu?","options":["4","9","30","6"],"answer":2,"explain":"Biến tong được cộng dồn giá trị từng phần tử của diem qua mỗi vòng lặp: 0+6=6, 6+7=13, 13+8=21, 21+9=30; kết quả cuối cùng là 30, không phải số lượng phần tử (4) hay một phần tử đơn lẻ nào trong dãy."},{"id":"CB-mc-1204","type":"mc","topic":"F","grade":11,"level":"medium","question":"Muốn đếm xem trong danh sách diem có bao nhiêu phần tử nhỏ hơn 5, cách làm nào sau đây là hợp lí?","options":["Khởi tạo dem = 0; trong vòng lặp for, mỗi khi phần tử d thoả d < 5 thì thực hiện dem = dem + 1","Khởi tạo dem = 0; trong vòng lặp for, mỗi lần lặp đều thực hiện dem = dem + 1, bất kể giá trị d","Không cần biến dem, chỉ cần tính tong rồi chia cho len(diem)","Khởi tạo dem = 1; trong vòng lặp for, mỗi khi phần tử d thoả d < 5 thì thực hiện dem = dem - 1"],"answer":0,"explain":"Đếm theo điều kiện cần một biến đếm bắt đầu từ 0, và chỉ tăng thêm 1 khi phần tử đang xét thoả điều kiện (ở đây là d < 5); phương án cộng dồn ở mọi vòng lặp sẽ đếm luôn cả những phần tử không thoả điều kiện, còn hai phương án còn lại không phản ánh đúng việc đếm theo điều kiện."},{"id":"CB-mc-1205","type":"mc","topic":"F","grade":11,"level":"hard","question":"Cho diem = [5, 9, 3, 7] và đoạn code sau để tìm giá trị lớn nhất (còn thiếu một dòng):\nlon_nhat = diem[0]\nfor d in diem:\n    ___\n        lon_nhat = d\nDòng còn thiếu nên là gì để đoạn code chạy đúng?","options":["if d > lon_nhat:","if d < lon_nhat:","if d == lon_nhat:","while d > lon_nhat:"],"answer":0,"explain":"Để cập nhật giá trị lớn nhất, ta so sánh phần tử hiện tại d với lon_nhat đang giữ, và chỉ khi d lớn hơn lon_nhat thì mới gán lại lon_nhat = d. Dùng d < lon_nhat sẽ khiến lon_nhat bị cập nhật thành giá trị nhỏ hơn, cho ra kết quả nhỏ nhất chứ không phải lớn nhất; d == lon_nhat gần như không bao giờ đúng nên không cập nhật được gì; while không phù hợp vì việc duyệt qua từng phần tử đã do for đảm nhiệm, ở đây chỉ cần một phép rẽ nhánh if."},{"id":"CB-tf-1201","type":"tf","topic":"F","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong Python, chỉ số của phần tử đầu tiên trong một danh sách luôn là 0.","correct":true},{"text":"Muốn duyệt qua toàn bộ phần tử của một danh sách, bắt buộc phải dùng vòng lặp while; vòng lặp for không dùng được.","correct":false},{"text":"Điểm trung bình của một dãy số bằng tổng các phần tử chia cho số lượng phần tử, tức là chia cho len() của danh sách.","correct":true},{"text":"Hàm max() có sẵn là cách duy nhất để tìm giá trị lớn nhất trong một danh sách; hoàn toàn không thể tự viết thuật toán tìm giá trị lớn nhất bằng vòng lặp.","correct":false}],"explain":"(1) Đúng vì Python đánh chỉ số bắt đầu từ 0. (2) Sai vì vòng lặp for (dạng for phần_tử in danh_sách hoặc for i in range(len(danh_sách))) là cách rất thông dụng và thuận tiện để duyệt danh sách. (3) Đúng, đây chính là công thức tính trung bình: tổng chia cho số lượng phần tử. (4) Sai vì như bài học đã trình bày, hoàn toàn có thể tự viết thuật toán tìm giá trị lớn nhất bằng vòng lặp so sánh dần từng phần tử, không phụ thuộc vào hàm max() có sẵn."},{"id":"CB-mc-1301","type":"mc","topic":"F","grade":11,"level":"easy","question":"Thuật toán tìm kiếm tuần tự hoạt động theo cách nào dưới đây?","options":["Chia đôi phạm vi tìm kiếm sau mỗi lần so sánh","Duyệt lần lượt từng phần tử của dãy theo đúng thứ tự, so sánh với giá trị cần tìm","Sắp xếp lại dãy theo thứ tự tăng dần rồi mới bắt đầu tìm","Chỉ so sánh với phần tử đứng giữa dãy"],"answer":1,"explain":"Tìm kiếm tuần tự (tìm kiếm tuyến tính) xét lần lượt từng phần tử theo đúng thứ tự xuất hiện trong dãy, so sánh với giá trị cần tìm cho đến khi gặp hoặc hết dãy — không chia đôi phạm vi và cũng không yêu cầu sắp xếp trước."},{"id":"CB-mc-1302","type":"mc","topic":"F","grade":11,"level":"easy","question":"Ngay khi tìm kiếm tuần tự gặp một phần tử bằng đúng giá trị cần tìm, thuật toán sẽ làm gì tiếp theo?","options":["Xoá phần tử đó khỏi dãy rồi tìm tiếp","Tiếp tục so sánh hết các phần tử còn lại để chắc chắn","Trả về vị trí của phần tử đó và dừng lại ngay","Bắt đầu lại việc so sánh từ phần tử đầu tiên"],"answer":2,"explain":"Khi gặp phần tử trùng khớp, thuật toán dừng ngay và trả về vị trí (chỉ số) của phần tử đó; không cần so sánh tiếp các phần tử còn lại vì đã có câu trả lời."},{"id":"CB-mc-1303","type":"mc","topic":"F","grade":11,"level":"medium","question":"Cho dãy có chỉ số từ 0 đến 4 với các giá trị lần lượt là 4, 8, 2, 9, 5. Nếu tìm kiếm tuần tự giá trị 9, thuật toán sẽ trả về chỉ số nào?","options":["3","1","2","Không tìm thấy"],"answer":0,"explain":"Duyệt lần lượt từ chỉ số 0: các giá trị 4, 8, 2 đều chưa khớp; đến chỉ số 3 gặp đúng giá trị 9 nên thuật toán dừng lại và trả về chỉ số 3."},{"id":"CB-mc-1304","type":"mc","topic":"F","grade":11,"level":"medium","question":"Một dãy có 200 phần tử. Nếu giá trị cần tìm không xuất hiện trong dãy, tìm kiếm tuần tự cần thực hiện tối đa bao nhiêu phép so sánh trước khi kết luận ‘không có’?","options":["1","100","199","200"],"answer":3,"explain":"Khi giá trị cần tìm không có trong dãy, không có lần so sánh nào khớp để dừng sớm, nên thuật toán phải so sánh lần lượt với toàn bộ 200 phần tử rồi mới kết luận ‘không có’."},{"id":"CB-mc-1305","type":"mc","topic":"F","grade":11,"level":"hard","question":"Vì sao tìm kiếm tuần tự vẫn cho kết quả đúng ngay cả khi dãy dữ liệu chưa được sắp xếp?","options":["Vì máy tính tự động sắp xếp dãy ngầm trước khi tìm","Vì thuật toán chỉ so sánh từng phần tử với giá trị cần tìm theo đúng thứ tự xuất hiện, không dựa vào quan hệ lớn nhỏ giữa các phần tử xung quanh","Vì tìm kiếm tuần tự chỉ áp dụng được cho dãy số, không áp dụng cho dãy chữ nên không cần sắp xếp","Vì tìm kiếm tuần tự luôn nhanh hơn tìm kiếm nhị phân nên không cần quan tâm đến thứ tự"],"answer":1,"explain":"Tìm kiếm tuần tự không dựa vào việc phần tử đứng trước có nhỏ hơn hay lớn hơn phần tử đứng sau; nó chỉ đơn thuần so sánh từng phần tử với giá trị cần tìm, nên dãy có được sắp xếp hay không cũng không ảnh hưởng đến tính đúng đắn của thuật toán."},{"id":"CB-tf-1301","type":"tf","topic":"F","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Tìm kiếm tuần tự luôn bắt đầu so sánh từ phần tử đầu tiên của dãy trước khi xét đến các phần tử khác.","correct":true},{"text":"Tìm kiếm tuần tự chỉ cho kết quả đúng khi dãy dữ liệu đã được sắp xếp tăng dần từ trước.","correct":false},{"text":"Trong trường hợp xấu nhất — giá trị cần tìm nằm ở cuối dãy hoặc không có trong dãy — tìm kiếm tuần tự phải so sánh với tất cả các phần tử.","correct":true},{"text":"Nếu phần tử đầu tiên của dãy đã khớp với giá trị cần tìm, tìm kiếm tuần tự vẫn phải tiếp tục so sánh với toàn bộ các phần tử còn lại.","correct":false}],"explain":"(1) Đúng — thuật toán luôn xuất phát từ chỉ số 0, tức phần tử đầu tiên. (2) Sai — tìm kiếm tuần tự vẫn cho kết quả đúng cả khi dãy chưa được sắp xếp, vì nó chỉ so sánh trực tiếp từng phần tử với giá trị cần tìm. (3) Đúng — khi không tìm thấy hoặc giá trị ở cuối dãy, thuật toán phải duyệt qua toàn bộ phần tử. (4) Sai — thuật toán dừng ngay khi gặp phần tử khớp đầu tiên, không cần so sánh tiếp."},{"id":"CB-mc-1401","type":"mc","topic":"F","grade":11,"level":"easy","question":"Tìm kiếm nhị phân chỉ có thể áp dụng đúng khi dãy dữ liệu thỏa điều kiện gì?","options":["Dãy có ít hơn 10 phần tử","Dãy đã được sắp xếp theo thứ tự (tăng dần hoặc giảm dần)","Dãy chỉ chứa số nguyên dương","Dãy không được chứa phần tử trùng nhau"],"answer":1,"explain":"Tìm kiếm nhị phân dựa vào việc so sánh giá trị ở giữa để suy ra nên tìm tiếp ở nửa trái hay nửa phải; suy luận này chỉ đúng khi dãy đã được sắp xếp."},{"id":"CB-mc-1402","type":"mc","topic":"F","grade":11,"level":"easy","question":"Trên một dãy đã sắp xếp tăng dần, nếu giá trị tại vị trí giữa NHỎ HƠN giá trị x cần tìm, bước tiếp theo của tìm kiếm nhị phân là gì?","options":["Dừng lại ngay và kết luận không tìm thấy x","Chuyển phai xuống giua - 1 để tìm ở nửa bên trái","Chuyển trai lên giua + 1 để tìm ở nửa bên phải","Bắt đầu lại toàn bộ dãy từ đầu"],"answer":2,"explain":"Vì dãy tăng dần, khi giá trị giữa còn nhỏ hơn x thì x (nếu có) chỉ có thể nằm ở các phần tử lớn hơn, tức nửa bên phải, nên trai được dời đến giua + 1."},{"id":"CB-mc-1403","type":"mc","topic":"F","grade":11,"level":"medium","question":"Cho dãy đã sắp xếp: 2, 4, 7, 9, 12, 15, 20 (đánh chỉ số từ 0 đến 6). Tìm x = 15 bằng tìm kiếm nhị phân. Ở bước đầu tiên, giua có chỉ số bao nhiêu và giá trị tại đó là gì?","options":["Chỉ số 3, giá trị 9","Chỉ số 4, giá trị 12","Chỉ số 3, giá trị 12","Chỉ số 6, giá trị 20"],"answer":0,"explain":"trai = 0, phai = 6 nên giua = (0 + 6) // 2 = 3; giá trị của dãy tại chỉ số 3 là 9."},{"id":"CB-mc-1404","type":"mc","topic":"F","grade":11,"level":"medium","question":"Một dãy đã sắp xếp có 1.000.000 phần tử. So với tìm kiếm tuần tự, số bước so sánh tối đa của tìm kiếm nhị phân trong trường hợp xấu nhất khác biệt thế nào?","options":["Cả hai đều cần khoảng 1.000.000 lần so sánh","Tìm kiếm tuần tự cần tới khoảng 1.000.000 lần, còn tìm kiếm nhị phân chỉ cần khoảng 20 lần","Tìm kiếm nhị phân cần nhiều lần so sánh hơn vì phải tính lại giua ở mỗi bước","Không thể so sánh vì kết quả phụ thuộc hoàn toàn vào loại máy tính đang chạy"],"answer":1,"explain":"Tìm kiếm tuần tự trường hợp xấu nhất phải xét hết dãy; tìm kiếm nhị phân mỗi bước loại một nửa số phần tử nên chỉ cần khoảng 20 bước, vì số phần tử giảm đi một nửa liên tiếp khoảng 20 lần thì còn lại đúng 1."},{"id":"CB-mc-1405","type":"mc","topic":"F","grade":11,"level":"hard","question":"Cho dãy đã sắp xếp: 1, 3, 5, 7, 9, 11, 13, 15 (chỉ số từ 0 đến 7). Tìm x = 13 bằng tìm kiếm nhị phân. Sau đúng 2 bước so sánh, thuật toán đã tìm thấy x chưa, và giua ở bước 2 là chỉ số nào?","options":["Đã tìm thấy ngay ở bước 2, tại chỉ số 5","Chưa tìm thấy; giua ở bước 2 là chỉ số 5 (giá trị 11), do 11 nhỏ hơn 13 nên còn phải tìm tiếp ở nửa phải","Chưa tìm thấy; giua ở bước 2 là chỉ số 6 (giá trị 13)","Đã tìm thấy ngay ở bước 1, tại chỉ số 3"],"answer":1,"explain":"Bước 1: giua = (0 + 7) // 2 = 3, giá trị 7 nhỏ hơn 13 nên trai chuyển thành 4. Bước 2: giua = (4 + 7) // 2 = 5, giá trị 11 vẫn nhỏ hơn 13 nên chưa tìm thấy, trai chuyển thành 6. Phải sang bước 3 (giua = 6, giá trị 13) mới tìm thấy."},{"id":"CB-tf-1401","type":"tf","topic":"F","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Tìm kiếm nhị phân có thể áp dụng cho một dãy bất kỳ, kể cả khi dãy chưa được sắp xếp.","correct":false},{"text":"Ở mỗi bước, nếu giá trị tại vị trí giua bằng đúng giá trị x cần tìm, thuật toán dừng lại ngay và trả về vị trí đó.","correct":true},{"text":"Với dãy có kích thước rất lớn, tìm kiếm nhị phân thường cần ít bước so sánh hơn nhiều so với tìm kiếm tuần tự.","correct":true},{"text":"Biến giua luôn được tính bằng trai cộng phai, không cần chia đôi.","correct":false}],"explain":"(1) Sai — dãy bắt buộc phải được sắp xếp trước thì tìm kiếm nhị phân mới cho kết quả đúng. (2) Đúng — khi giá trị tại giua trùng với x, thuật toán tìm thấy ngay và dừng lại. (3) Đúng — mỗi bước loại bỏ một nửa số phần tử nên số bước cần thiết tăng rất chậm dù dãy lớn đến đâu. (4) Sai — phải chia đôi: giua = (trai + phai) // 2; nếu không chia đôi thì giua sẽ vượt ra ngoài phạm vi dãy."},{"id":"CB-mc-1501","type":"mc","topic":"F","grade":11,"level":"easy","question":"Một trong những lý do quan trọng để sắp xếp một dãy dữ liệu là gì?","options":["Để có thể áp dụng thuật toán tìm kiếm nhị phân, vốn chỉ cho kết quả đúng trên dãy đã sắp xếp","Để dãy dữ liệu chiếm ít dung lượng lưu trữ hơn","Để chương trình không còn cần dùng vòng lặp khi xử lí dữ liệu","Để dữ liệu tự động được sao lưu an toàn hơn"],"answer":0,"explain":"Nhiều thuật toán xử lí dữ liệu hiệu quả, tiêu biểu là tìm kiếm nhị phân, chỉ cho kết quả đúng khi dãy đầu vào đã được sắp xếp theo thứ tự tăng dần hoặc giảm dần. Sắp xếp không làm giảm dung lượng lưu trữ, không loại bỏ nhu cầu dùng vòng lặp, và cũng không liên quan đến việc sao lưu dữ liệu."},{"id":"CB-mc-1502","type":"mc","topic":"F","grade":11,"level":"easy","question":"Trong thuật toán sắp xếp nổi bọt, khi phát hiện hai phần tử liền kề sai thứ tự (yêu cầu tăng dần nhưng phần tử đứng trước lại lớn hơn phần tử đứng sau), ta làm gì?","options":["Xoá phần tử đứng sau khỏi dãy","Chèn thêm một phần tử mới vào giữa hai phần tử đó","Đổi chỗ hai phần tử đó cho nhau","Dừng thuật toán ngay lập tức vì dãy không thể sắp xếp được"],"answer":2,"explain":"Ý tưởng cốt lõi của sắp xếp nổi bọt là: hễ phát hiện một cặp phần tử liền kề sai thứ tự thì đổi chỗ ngay hai phần tử đó, rồi tiếp tục xét cặp kế tiếp. Không có việc xoá bớt, chèn thêm phần tử hay dừng giữa chừng."},{"id":"CB-mc-1503","type":"mc","topic":"F","grade":11,"level":"medium","question":"Trong ví dụ cài đặt sắp xếp nổi bọt của bài học, câu lệnh `a[j], a[j + 1] = a[j + 1], a[j]` có tác dụng gì?","options":["Tính tổng của hai phần tử `a[j]` và `a[j + 1]`","Đổi chỗ giá trị của hai phần tử liền kề `a[j]` và `a[j + 1]`","So sánh xem `a[j]` có bằng `a[j + 1]` hay không","Xoá phần tử `a[j]` ra khỏi danh sách `a`"],"answer":1,"explain":"Cú pháp `a[j], a[j + 1] = a[j + 1], a[j]` là cách Python gán giá trị chéo cho hai phần tử của danh sách cùng một lúc, tức đổi chỗ giá trị của `a[j]` và `a[j + 1]` mà không cần dùng biến trung gian. Đây không phải là phép tính tổng, phép so sánh hay thao tác xoá phần tử."},{"id":"CB-mc-1504","type":"mc","topic":"F","grade":11,"level":"medium","question":"Trong đoạn code sắp xếp nổi bọt của bài học, vòng lặp ngoài với biến `i` (`for i in range(n - 1)`) có vai trò gì?","options":["Duyệt qua từng phần tử để in giá trị của nó ra màn hình","Đếm số phần tử của danh sách `a`","Kiểm tra xem danh sách `a` có rỗng hay không","Đếm số lượt duyệt qua toàn bộ dãy để thực hiện việc so sánh — đổi chỗ"],"answer":3,"explain":"Vòng lặp ngoài với biến `i` chạy từ 0 đến `n - 2`, mỗi giá trị của `i` tương ứng với một lượt duyệt qua dãy; việc so sánh và đổi chỗ thật sự diễn ra ở vòng lặp trong (biến `j`). Vòng lặp ngoài không dùng để in giá trị, đếm phần tử hay kiểm tra dãy rỗng."},{"id":"CB-mc-1505","type":"mc","topic":"F","grade":11,"level":"hard","question":"Trong code của bài học, phạm vi của `j` ở vòng lặp trong được viết là `range(n - 1 - i)`, tức chạy ít dần khi `i` tăng lên, thay vì luôn chạy `range(n - 1)`. Vì sao lại làm như vậy?","options":["Vì Python không cho phép hai vòng lặp lồng nhau có cùng phạm vi chạy","Vì càng về sau, danh sách `a` càng bị xoá bớt phần tử nên phạm vi phải thu hẹp lại","Vì càng về sau, các phần tử lớn nhất đã lần lượt được đưa về đúng vị trí cuối dãy ở các lượt trước, nên không cần so sánh lại đoạn cuối đó nữa","Vì làm như vậy khiến chương trình chạy chậm hơn nhưng cho kết quả chính xác hơn"],"answer":2,"explain":"Sau lượt thứ nhất, phần tử lớn nhất đã về đúng vị trí cuối cùng của dãy; sau lượt thứ hai, phần tử lớn thứ nhì cũng vào đúng chỗ ngay trước đó, và cứ thế. Vì vậy ở mỗi lượt sau, ta không cần so sánh lại phần đuôi dãy đã chắc chắn đúng vị trí nữa, giúp thuật toán bớt những phép so sánh thừa. Danh sách không hề bị xoá bớt phần tử, và đây cũng không phải giới hạn của Python."},{"id":"CB-tf-1501","type":"tf","topic":"F","grade":11,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong sắp xếp nổi bọt, ở mỗi lượt duyệt, ta so sánh các cặp phần tử đứng liền kề nhau trong dãy.","correct":true},{"text":"Sắp xếp nổi bọt chỉ cần đúng một lượt duyệt qua dãy là chắc chắn sắp xếp xong với mọi dãy số.","correct":false},{"text":"Sau lượt duyệt đầu tiên của sắp xếp nổi bọt, phần tử lớn nhất của dãy sẽ được đưa về đúng vị trí cuối cùng.","correct":true},{"text":"Thuật toán sắp xếp nổi bọt chỉ áp dụng được cho dãy số, không thể dùng để sắp xếp một dãy các xâu kí tự.","correct":false}],"explain":"(1) Đúng — ở mỗi lượt, thuật toán duyệt qua dãy và so sánh từng cặp phần tử đứng cạnh nhau. (2) Sai — nói chung cần nhiều lượt duyệt (tối đa n - 1 lượt với dãy n phần tử) mới chắc chắn sắp xếp xong; một lượt duy nhất thường chưa đủ. (3) Đúng — đây chính là đặc điểm nổi bật của thuật toán: sau mỗi lượt, phần tử lớn nhất trong đoạn chưa sắp xếp sẽ về đúng vị trí cuối cùng của nó. (4) Sai — sắp xếp nổi bọt dựa trên việc so sánh hai phần tử để biết cái nào lớn hơn, và phép so sánh này áp dụng được cho nhiều kiểu dữ liệu, kể cả xâu kí tự (so sánh theo thứ tự từ điển), không riêng gì số."},{"id":"CB-mc-1601","type":"mc","topic":"F","grade":11,"level":"easy","question":"Vì sao khi so sánh hai thuật toán cùng giải một bài toán, người ta thường không đo hiệu quả bằng cách bấm giờ đồng hồ khi chạy chương trình?","options":["Vì đồng hồ chỉ đo được thời gian tính bằng phút, không đo được giây","Vì thời gian chạy còn phụ thuộc vào tốc độ máy tính, không phản ánh đúng bản chất thuật toán","Vì các ngôn ngữ lập trình không cho phép đo thời gian chạy chương trình","Vì bấm giờ chỉ áp dụng được cho những chương trình có vòng lặp"],"answer":1,"explain":"Cùng một thuật toán có thể chạy nhanh hơn hoặc chậm hơn tuỳ vào máy tính đang sử dụng, nên thời gian chạy thực tế không phản ánh đúng bản chất của thuật toán. Vì vậy người ta đếm số phép tính cơ bản thay vì đo bằng đồng hồ."},{"id":"CB-mc-1602","type":"mc","topic":"F","grade":11,"level":"easy","question":"Trong khái niệm độ phức tạp thuật toán, kí hiệu `n` thường dùng để chỉ điều gì?","options":["Số lượng thuật toán có thể dùng để giải một bài toán","Kích thước (số lượng phần tử) của dữ liệu đầu vào","Số lần chương trình bị lỗi khi chạy thử","Tốc độ xử lí của bộ vi xử lí (CPU)"],"answer":1,"explain":"`n` biểu diễn kích thước của dữ liệu đầu vào — ví dụ số phần tử trong một danh sách cần tìm kiếm hoặc cần sắp xếp. Độ phức tạp thuật toán mô tả số phép tính cần thực hiện thay đổi thế nào khi `n` thay đổi."},{"id":"CB-mc-1603","type":"mc","topic":"F","grade":11,"level":"medium","question":"Thuật toán tìm kiếm tuần tự (xét lần lượt từng phần tử trong danh sách cho tới khi tìm thấy) có độ phức tạp nào?","options":["O(1)","O(log n)","O(n)","O(n^2)"],"answer":2,"explain":"Ở trường hợp xấu nhất, tìm kiếm tuần tự phải xét qua tất cả n phần tử của danh sách mới biết được kết quả (tìm thấy ở cuối, hoặc không có trong danh sách), nên số phép so sánh tỉ lệ thuận với n — tương ứng độ phức tạp O(n)."},{"id":"CB-mc-1604","type":"mc","topic":"F","grade":11,"level":"medium","question":"Một thuật toán có độ phức tạp O(n^2). Khi kích thước dữ liệu n tăng từ 100 lên 1000 (gấp 10 lần), số phép tính của thuật toán này tăng lên khoảng bao nhiêu lần?","options":["10 lần","100 lần","1000 lần","Không tăng, vẫn giữ nguyên"],"answer":1,"explain":"Với độ phức tạp O(n^2), số phép tính tỉ lệ với bình phương của n. Khi n tăng gấp 10 lần, bình phương của nó tăng gấp 10 x 10 = 100 lần. Cụ thể: n = 100 cần khoảng 100^2 = 10 000 phép tính, còn n = 1000 cần khoảng 1000^2 = 1 000 000 phép tính — đúng bằng 100 lần."},{"id":"CB-mc-1605","type":"mc","topic":"F","grade":11,"level":"hard","question":"Một danh sách đã được sắp xếp theo thứ tự tăng dần, gồm 1 000 000 phần tử. So với tìm kiếm tuần tự (độ phức tạp O(n)), tìm kiếm nhị phân (độ phức tạp O(log n)) trên danh sách này khác biệt ra sao về số phép so sánh cần thiết ở trường hợp xấu nhất?","options":["Tìm kiếm nhị phân chỉ cần khoảng 20 phép so sánh, còn tìm kiếm tuần tự có thể cần tới 1 000 000 phép so sánh","Cả hai đều cần đúng 1 000 000 phép so sánh vì phải xét hết danh sách","Tìm kiếm tuần tự luôn nhanh hơn vì cách làm đơn giản hơn","Tìm kiếm nhị phân cần nhiều phép so sánh hơn vì phải tính vị trí giữa danh sách nhiều lần"],"answer":0,"explain":"Vì mỗi bước tìm kiếm nhị phân loại bỏ được một nửa dữ liệu còn lại, số bước cần thiết xấp xỉ bằng log của n theo cơ số 2; với n = 1 000 000, số đó chỉ khoảng 20 (vì 2^20 xấp xỉ 1 000 000). Trong khi đó, tìm kiếm tuần tự ở trường hợp xấu nhất (giá trị ở cuối danh sách hoặc không tồn tại) phải xét qua tất cả 1 000 000 phần tử. Đây là ví dụ rõ ràng cho thấy vì sao độ phức tạp thấp hơn lại quan trọng khi dữ liệu lớn."},{"id":"CB-tf-1601","type":"tf","topic":"F","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Độ phức tạp O(1) nghĩa là số phép tính của thuật toán luôn không đổi, không phụ thuộc vào kích thước dữ liệu n.","correct":true},{"text":"Thuật toán có độ phức tạp O(n^2) luôn chạy chậm hơn thuật toán có độ phức tạp O(n), trong mọi trường hợp, với mọi kích thước dữ liệu.","correct":false},{"text":"Kí hiệu O trong độ phức tạp thuật toán mô tả xu hướng tăng của số phép tính khi kích thước dữ liệu tăng lên, không phải là số giây chính xác mà chương trình chạy.","correct":true},{"text":"Tìm kiếm nhị phân có thể áp dụng cho bất kỳ danh sách nào, kể cả danh sách chưa được sắp xếp, mà vẫn cho kết quả đúng.","correct":false}],"explain":"(1) Đúng — đây chính là định nghĩa của O(1): số phép tính cố định, không phụ thuộc n. (2) Sai — độ phức tạp mô tả xu hướng khi n rất lớn; với dữ liệu nhỏ, một thuật toán O(n^2) đơn giản vẫn có thể chạy tốt, thậm chí nhanh hơn một thuật toán khác về mặt thực tế. (3) Đúng — kí hiệu O mô tả tốc độ tăng của số phép tính theo n, không phải số giây cụ thể, vì thời gian thực tế còn phụ thuộc vào tốc độ máy tính. (4) Sai — tìm kiếm nhị phân chỉ cho kết quả đúng khi danh sách đã được sắp xếp trước; nếu danh sách chưa sắp xếp, việc thu hẹp một nửa phạm vi tìm kiếm không còn ý nghĩa và có thể bỏ sót giá trị cần tìm."},{"id":"CB-mc-1701","type":"mc","topic":"F","grade":11,"level":"easy","question":"Vì sao nên chia một bài toán lớn thành nhiều hàm nhỏ thay vì viết dồn thành một khối lệnh dài?","options":["Để chương trình chạy nhanh hơn về tốc độ xử lý của máy tính","Để mỗi hàm chỉ đảm nhận đúng một việc rõ ràng, giúp chương trình dễ viết, dễ đọc và dễ kiểm thử hơn","Vì Python bắt buộc một chương trình phải có ít nhất bốn hàm mới chạy được","Để chương trình chiếm ít dung lượng lưu trữ hơn trên ổ đĩa"],"answer":1,"explain":"Chia bài toán thành nhiều hàm nhỏ, mỗi hàm một việc rõ ràng, giúp chương trình dễ viết, dễ đọc, dễ kiểm thử từng phần và dễ tái sử dụng — đây là lí do chính được nêu trong bài, không liên quan đến tốc độ xử lý hay dung lượng lưu trữ. Python cũng không hề bắt buộc số lượng hàm tối thiểu nào."},{"id":"CB-mc-1702","type":"mc","topic":"F","grade":11,"level":"easy","question":"Cách làm mịn dần (thiết kế từ trên xuống) khi giải quyết một bài toán lớn nghĩa là gì?","options":["Viết ngay chi tiết từng dòng lệnh của cả bài toán ngay từ đầu, không cần phác thảo trước","Phác ra các bước lớn của bài toán trước, giống một dàn ý, rồi lần lượt viết chi tiết từng bước thành một hàm hoàn chỉnh","Chỉ viết đúng một hàm duy nhất cho toàn bộ bài toán để chương trình gọn nhất có thể","Xoá bỏ hết các hàm đã viết trước đó rồi viết lại từ đầu cho đến khi chương trình chạy đúng"],"answer":1,"explain":"Làm mịn dần là phác ra những bước lớn trước — như một dàn ý — rồi mới quay lại làm chi tiết (làm mịn) từng bước thành một hàm hoàn chỉnh. Viết ngay chi tiết từ đầu, gộp tất cả vào một hàm duy nhất, hay xoá đi viết lại đều không phải là cách làm mịn dần được nêu trong bài."},{"id":"CB-mc-1703","type":"mc","topic":"F","grade":11,"level":"medium","question":"Trong chương trình quản lí điểm ở bài học, hàm nào chỉ nhận vào một danh sách điểm có sẵn, tính rồi trả về điểm trung bình, không cần quan tâm những điểm đó được nhập vào bằng cách nào?","options":["nhap_diem","tinh_trung_binh","xep_loai","in_ket_qua"],"answer":1,"explain":"tinh_trung_binh chỉ nhận vào một danh sách điểm qua tham số danh_sach, tính tổng rồi chia cho số lượng phần tử để ra điểm trung bình; hàm này không quan tâm dữ liệu đầu vào lấy từ đâu. nhap_diem lo việc nhận điểm từ người dùng, xep_loai lo việc xếp loại từ điểm trung bình, còn in_ket_qua lo việc hiển thị kết quả ra màn hình."},{"id":"CB-mc-1704","type":"mc","topic":"F","grade":11,"level":"medium","question":"Sau khi viết xong bốn hàm nhap_diem, tinh_trung_binh, xep_loai, in_ket_qua, người viết muốn thử ngay xem hàm xep_loai có xếp loại đúng hay chưa, bằng vài giá trị mẫu, mà chưa cần chạy toàn bộ chương trình. Điều này thể hiện lợi ích nào của việc chia bài toán thành hàm?","options":["Dễ viết hơn, vì không cần suy nghĩ nhiều khi viết chương trình","Dễ kiểm thử từng phần, vì có thể thử riêng một hàm với vài giá trị mẫu trước khi ráp vào chương trình hoàn chỉnh","Dùng lại được hàm đó ở một chương trình hoàn toàn khác","Chương trình chạy nhanh hơn về mặt tốc độ xử lý của máy tính"],"answer":1,"explain":"Việc thử riêng một hàm (ở đây là xep_loai) với vài giá trị mẫu, trước khi ráp vào chương trình hoàn chỉnh, chính là lợi ích ‘dễ kiểm thử từng phần’ đã nêu trong bài. Đây không phải là ví dụ cho việc viết dễ hơn nói chung, cho việc tái sử dụng ở một chương trình khác, hay cho tốc độ xử lý của máy."},{"id":"CB-mc-1705","type":"mc","topic":"F","grade":11,"level":"hard","question":"Xét lại chương trình quản lí điểm ở bài học. Nếu người dùng lần lượt nhập ba điểm là 9, 8 rồi 10 khi chương trình chạy, hai dòng cuối cùng mà chương trình in ra sẽ là gì?","options":["Điểm trung bình: 9.0, rồi Xếp loại: Giỏi","Điểm trung bình: 9, rồi Xếp loại: Giỏi","Điểm trung bình: 9.0, rồi Xếp loại: Khá","Chương trình báo lỗi vì hàm tinh_trung_binh không nhận đủ tham số"],"answer":0,"explain":"d1, d2, d3 lần lượt nhận 9.0, 8.0, 10.0 (đã ép kiểu float); tổng ba điểm là 27.0, chia cho 3 phần tử được 9.0 — phép chia bằng dấu / trong Python luôn trả về số thực nên in ra 9.0 chứ không phải 9. Với diem_tb bằng 9.0, điều kiện diem_tb >= 8 đúng ngay ở nhánh đầu tiên nên xep_loai trả về Giỏi, không xét tới các nhánh elif phía sau. Chương trình cũng không thiếu tham số nào nên không hề báo lỗi."},{"id":"CB-tf-1701","type":"tf","topic":"F","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Khi mỗi hàm chỉ lo đúng một việc rõ ràng, chương trình thường dễ đọc và dễ kiểm thử hơn so với một hàm ôm đồm nhiều việc cùng lúc.","correct":true},{"text":"Làm mịn dần nghĩa là phải viết xong toàn bộ chi tiết của cả bài toán trước, sau đó mới được nghĩ đến các bước lớn.","correct":false},{"text":"Trong một chương trình được chia hàm hợp lý, phần chính thường chỉ còn vài dòng gọi hàm theo đúng thứ tự, không chứa nhiều phép tính chi tiết.","correct":true},{"text":"Một hàm đã viết xong và kiểm tra đúng thì không thể dùng lại ở bất kỳ chỗ nào khác, mỗi hàm chỉ được gọi đúng một lần duy nhất trong chương trình.","correct":false}],"explain":"(1) Đúng — mỗi hàm một việc rõ ràng giúp chương trình dễ đọc, dễ kiểm thử hơn, đây chính là lợi ích chính của việc chia hàm được nêu trong bài. (2) Sai — làm mịn dần đi theo thứ tự ngược lại: phác các bước lớn (dàn ý) trước, rồi mới quay lại làm chi tiết (làm mịn) từng bước sau. (3) Đúng — phần chính của một chương trình chia hàm hợp lý thường chỉ là vài dòng gọi hàm theo đúng thứ tự, giống như đọc lại dàn ý các bước lớn. (4) Sai — một hàm hoàn toàn có thể được gọi lại nhiều lần, ở nhiều chỗ khác nhau, thậm chí ở một chương trình khác có nhu cầu tương tự; đây chính là lợi ích ‘dùng lại được’ đã nêu trong bài."},{"id":"CB-mc-1801","type":"mc","topic":"F","grade":11,"level":"easy","question":"Vì sao một chương trình chạy đúng với một bộ dữ liệu duy nhất vẫn chưa đủ để khẳng định chương trình hoàn toàn đúng?","options":["Vì mỗi lần chạy, Python sẽ cho ra một kết quả ngẫu nhiên khác nhau","Vì lỗi logic có thể chỉ lộ ra ở một số bộ dữ liệu nhất định, còn những bộ khác vẫn cho kết quả đúng bình thường","Vì chương trình luôn báo lỗi cú pháp nếu có chỗ nào đó sai","Vì một chương trình chỉ được phép chạy đúng một lần duy nhất"],"answer":1,"explain":"Lỗi logic là loại lỗi tinh vi: chương trình vẫn chạy và cho kết quả, nhưng có thể chỉ sai ở một số bộ dữ liệu cụ thể, còn những bộ khác vẫn tình cờ cho kết quả đúng. Vì vậy cần thử nhiều bộ dữ liệu khác nhau mới phát hiện được. Các phương án còn lại không đúng: chương trình không cho kết quả ngẫu nhiên nếu logic cố định, lỗi cú pháp là chuyện khác hẳn lỗi logic, và không có giới hạn số lần chạy một chương trình."},{"id":"CB-mc-1802","type":"mc","topic":"F","grade":11,"level":"easy","question":"Theo bài học, một bộ dữ liệu kiểm thử (test case) đầy đủ cần gồm những gì?","options":["Chỉ cần dữ liệu đầu vào, không cần biết trước kết quả","Dữ liệu đầu vào và kết quả mà chương trình in ra","Dữ liệu đầu vào và kết quả mong đợi, được xác định từ trước bằng cách tính tay hoặc suy luận","Chỉ cần kết quả mong đợi, không cần dữ liệu đầu vào"],"answer":2,"explain":"Một bộ dữ liệu kiểm thử gồm đúng hai phần: dữ liệu đầu vào và kết quả mong đợi đã biết trước, độc lập với chương trình đang kiểm tra. So kết quả chương trình chạy ra với kết quả mong đợi này mới cho biết chương trình đúng hay sai; thiếu một trong hai phần, việc kiểm thử sẽ mất hết ý nghĩa."},{"id":"CB-mc-1803","type":"mc","topic":"F","grade":11,"level":"medium","question":"Ở ví dụ hàm `tim_max` trong bài, phiên bản gốc khởi tạo `lon_nhat = 0` trước khi duyệt toàn bộ danh sách. Bộ dữ liệu kiểm thử nào đã phát hiện ra lỗi này?","options":["`[3, 7, 2, 9, 4]`, mong đợi `9`","`[5]`, mong đợi `5`","`[-3, -1, -8, -2]`, mong đợi `-1`","Không bộ nào phát hiện ra, vì hàm gốc luôn cho kết quả đúng"],"answer":2,"explain":"Với danh sách toàn số âm, mọi phần tử đều nhỏ hơn `0`, nên biến `lon_nhat` khởi tạo bằng `0` không bao giờ bị thay đổi trong vòng lặp — hàm trả về `0` thay vì `-1` như mong đợi. Hai bộ dữ liệu đầu đều chứa số dương lớn hơn `0` nên tình cờ vẫn cho kết quả đúng, không lộ ra lỗi."},{"id":"CB-mc-1804","type":"mc","topic":"F","grade":11,"level":"medium","question":"Trong các trường hợp dữ liệu sau, đâu KHÔNG phải là một trường hợp biên cần ưu tiên đưa vào bộ kiểm thử?","options":["Danh sách rỗng, không có phần tử nào","Danh sách có 20 số ngẫu nhiên, giá trị trải đều và không trùng nhau","Danh sách chỉ có đúng một phần tử","Danh sách mà toàn bộ phần tử đều là số âm"],"answer":1,"explain":"Một danh sách gồm nhiều số ngẫu nhiên, trải đều, không trùng nhau là một trường hợp dữ liệu bình thường, đại diện cho tình huống phổ biến — không phải trường hợp biên. Rỗng, chỉ một phần tử, hay toàn số âm mới là những trường hợp đặc biệt dễ khiến lỗi logic lộ diện, như bài học đã chỉ ra."},{"id":"CB-mc-1805","type":"mc","topic":"F","grade":11,"level":"hard","question":"Một người viết hàm tìm giá trị NHỎ NHẤT của một danh sách số, rồi thử với ba bộ kiểm thử: `[4, 8, 1, 9]` mong đợi `1`; `[7]` mong đợi `7`; `[2, 2, 2]` mong đợi `2` — cả ba đều cho kết quả `Đúng`. Người này kết luận hàm đã hoàn toàn chính xác trong mọi trường hợp. Nhận định đó có vấn đề gì?","options":["Không có vấn đề gì — ba bộ kiểm thử đều đúng thì hàm chắc chắn đúng trong mọi trường hợp","Có vấn đề, vì bộ kiểm thử trên chưa thử đủ các trường hợp biên như danh sách rỗng, giá trị 0 hay số âm, nên vẫn có thể còn lỗi logic chưa bị phát hiện","Có vấn đề, vì với dữ liệu `[2, 2, 2]`, Python chắc chắn sẽ báo lỗi cú pháp khi chạy","Không có vấn đề gì, vì bài toán tìm giá trị nhỏ nhất quá đơn giản nên không thể có lỗi logic"],"answer":1,"explain":"Bộ kiểm thử trên tuy đã thử qua trường hợp một phần tử (`[7]`), nhưng vẫn còn thiếu nhiều trường hợp biên quan trọng khác như danh sách rỗng, giá trị `0` hay số âm — những chỗ lỗi logic rất dễ ẩn náu. Kiểm thử càng nhiều bộ dữ liệu, đặc biệt các trường hợp biên, độ tin cậy càng cao, nhưng không có bộ kiểm thử nào — dù toàn bộ đều `Đúng` — có thể khẳng định tuyệt đối rằng chương trình không còn lỗi ở những trường hợp chưa từng thử qua. Phương án nhắc tới lỗi cú pháp không liên quan gì tới tình huống này, vì `[2, 2, 2]` là dữ liệu hợp lệ."},{"id":"CB-tf-1801","type":"tf","topic":"F","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Một chương trình chạy xong, không báo lỗi và có in ra kết quả, chắc chắn là chương trình không còn lỗi logic nào.","correct":false},{"text":"Trong một bộ dữ liệu kiểm thử, kết quả mong đợi cần được xác định từ trước khi chạy chương trình, chẳng hạn bằng cách tính tay hoặc suy luận từ đề bài.","correct":true},{"text":"Danh sách rỗng, danh sách chỉ có một phần tử, hay các giá trị bằng 0 hoặc số âm đều là những trường hợp biên nên được đưa vào bộ kiểm thử.","correct":true},{"text":"Khi một bộ kiểm thử báo sai, cách làm hiệu quả nhất là xoá toàn bộ chương trình và viết lại từ đầu, không cần tìm xem chỗ nào sai.","correct":false}],"explain":"(1) Sai — chạy xong và có kết quả không đồng nghĩa với không còn lỗi logic; đây chính là lí do phải kiểm thử với nhiều bộ dữ liệu, đặc biệt các trường hợp biên. (2) Đúng — kết quả mong đợi phải được biết trước, độc lập với chương trình đang kiểm tra, thì việc so sánh mới có ý nghĩa. (3) Đúng — đây đều là những trường hợp biên được nêu trong bài, nơi lỗi logic dễ ẩn náu nhất. (4) Sai — cách làm hiệu quả là in giá trị trung gian, thu hẹp dần vùng nghi ngờ để tìm đúng chỗ sai trước khi sửa, không phải xoá hết viết lại từ đầu."},{"id":"CB-mc-1901","type":"mc","topic":"F","grade":11,"level":"easy","question":"Đệ quy (recursion), trong lập trình, được hiểu là gì?","options":["Một hàm tự gọi lại CHÍNH NÓ để giải một bài toán nhỏ hơn, cùng dạng với bài toán ban đầu","Một hàm gọi một hàm KHÁC để thực hiện một công việc phụ trợ","Một vòng lặp `for` được viết lồng bên trong một vòng lặp `for` khác","Một biến được gán lại giá trị nhiều lần trong cùng một chương trình"],"answer":0,"explain":"Đệ quy xảy ra khi một hàm tự gọi lại chính nó — chứ không phải gọi một hàm khác — để giải bài toán nhỏ hơn nhưng cùng dạng với bài toán ban đầu. Vòng lặp lồng nhau và việc gán lại biến là những khái niệm khác, không phải bản chất của đệ quy."},{"id":"CB-mc-1902","type":"mc","topic":"F","grade":11,"level":"easy","question":"Trong một hàm đệ quy, điều kiện dừng (base case) giữ vai trò gì?","options":["Là dòng lệnh dùng để in kết quả cuối cùng ra màn hình","Là tham số đầu tiên được truyền vào hàm ở lượt gọi đầu tiên","Là trường hợp nhỏ nhất, được giải quyết ngay mà không cần gọi lại hàm thêm lần nào nữa","Là lượt gọi hàm được thực hiện nhiều lần nhất trong toàn bộ quá trình đệ quy"],"answer":2,"explain":"Điều kiện dừng là trường hợp đơn giản nhất, được trả lời ngay lập tức, không gọi thêm hàm nữa — nhờ đó chuỗi lời gọi đệ quy mới có điểm kết thúc, tránh gọi mãi không dừng. Đây không phải lệnh in kết quả, cũng không phải tham số đầu vào hay lượt gọi bất kì nào khác."},{"id":"CB-mc-1903","type":"mc","topic":"F","grade":11,"level":"medium","question":"Cho hàm sau:\ndef giai_thua(n):\n    if n == 0:\n        return 1\n    else:\n        return n * giai_thua(n - 1)\n\nKhi gọi giai_thua(4), hàm trả về giá trị nào?","options":["10","24","16","Chương trình báo lỗi vì hàm thiếu điều kiện dừng"],"answer":1,"explain":"giai_thua(4) = 4 * giai_thua(3) = 4 * (3 * giai_thua(2)) = 4 * 3 * (2 * giai_thua(1)) = 4 * 3 * 2 * (1 * giai_thua(0)). Vì giai_thua(0) chạm điều kiện dừng, trả về 1 ngay, nên kết quả cuối cùng là 4 * 3 * 2 * 1 * 1 = 24. Hàm có đầy đủ điều kiện dừng tại n = 0 nên không hề báo lỗi."},{"id":"CB-mc-1904","type":"mc","topic":"F","grade":11,"level":"medium","question":"Cho hàm sau:\ndef tong(n):\n    if n == 1:\n        return 1\n    else:\n        return n + tong(n - 1)\n\nKhi gọi tong(5), hàm trả về giá trị nào?","options":["Chương trình báo lỗi vì hàm thiếu điều kiện dừng","20","15","10"],"answer":2,"explain":"tong(5) = 5 + tong(4) = 5 + 4 + tong(3) = 5 + 4 + 3 + tong(2) = 5 + 4 + 3 + 2 + tong(1). Vì điều kiện dừng là n == 1, tong(1) trả về 1 ngay, nên tổng cuối cùng là 5 + 4 + 3 + 2 + 1 = 15."},{"id":"CB-mc-1905","type":"mc","topic":"F","grade":11,"level":"hard","question":"Một người viết lại hàm tính giai thừa như sau, nhưng gõ nhầm ở lượt gọi bên trong:\ndef giai_thua(n):\n    if n == 0:\n        return 1\n    else:\n        return n * giai_thua(n)\n\nKhi gọi giai_thua(3), điều gì sẽ xảy ra?","options":["Chương trình chạy bình thường và in ra kết quả 6","Hàm tự gọi lại chính nó mãi với cùng giá trị n = 3, không bao giờ chạm điều kiện dừng, dẫn đến lỗi tràn ngăn xếp","Hàm vẫn chạy đúng nhưng chậm hơn bình thường một chút vì gọi hàm nhiều lần","Python tự động phát hiện chỗ gõ nhầm và tự sửa thành giai_thua(n - 1)"],"answer":1,"explain":"Ở lượt gọi bên trong, đối số truyền vào vẫn nguyên là n, không giảm dần về 0 như n - 1, nên hàm không bao giờ chạm được điều kiện dừng n == 0. Hàm sẽ tự gọi lại chính nó với n = 3 vô số lần, gây lỗi tràn ngăn xếp (`RecursionError`) — Python không tự động phát hiện hay sửa lỗi logic kiểu này."},{"id":"CB-tf-1901","type":"tf","topic":"F","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Mọi hàm đệ quy đều bắt buộc phải có ít nhất một điều kiện dừng (base case).","correct":true},{"text":"Nếu một hàm đệ quy thiếu điều kiện dừng, hàm đó sẽ tự dừng lại một cách an toàn ngay sau lượt tự gọi đầu tiên.","correct":false},{"text":"Trong hàm tong tính tổng 1 + 2 + ... + n ở bài học, điều kiện dừng ứng với trường hợp n = 1.","correct":true},{"text":"Đệ quy là cách DUY NHẤT để giải các bài toán như tính tổng hay tính giai thừa; không thể dùng vòng lặp for hoặc while để thay thế.","correct":false}],"explain":"(1) Đúng — thiếu điều kiện dừng, hàm sẽ tự gọi lại chính nó mãi, không bao giờ kết thúc. (2) Sai — nếu thiếu điều kiện dừng, hàm KHÔNG tự dừng an toàn, mà tiếp tục tự gọi lại chính nó cho đến khi tràn ngăn xếp và chương trình báo lỗi. (3) Đúng — đúng như hàm tong trong bài học, điều kiện dừng được đặt tại trường hợp n = 1, trả về 1 ngay lập tức. (4) Sai — mọi bài toán giải được bằng đệ quy đều có thể viết lại bằng vòng lặp for hoặc while, và ngược lại; đệ quy chỉ là một cách diễn đạt khác, không phải cách duy nhất."},{"id":"CB-mc-2001","type":"mc","topic":"E","grade":11,"level":"easy","question":"Công việc nào sau đây thuộc nhóm nghề dịch vụ và quản trị trong lĩnh vực tin học, chứ không phải công việc viết ra một phần mềm mới?","options":["Thiết kế giao diện cho một ứng dụng di động chuẩn bị ra mắt","Viết mã nguồn cho một trò chơi điện tử mới","Quản trị mạng và hệ thống, giữ cho mạng máy tính của một công ty luôn hoạt động ổn định","Phát triển một phần mềm quản lí bán hàng từ đầu"],"answer":2,"explain":"Quản trị mạng và hệ thống thuộc nhóm nghề dịch vụ và quản trị, giữ cho hệ thống đã có hoạt động ổn định chứ không tạo ra phần mềm mới. Thiết kế giao diện, viết mã nguồn trò chơi hay phát triển phần mềm quản lí bán hàng đều là công việc tạo ra một sản phẩm phần mềm mới, thuộc nhóm phát triển phần mềm."},{"id":"CB-mc-2002","type":"mc","topic":"E","grade":11,"level":"easy","question":"Nghề nào chuyên dò tìm lỗi trong một phần mềm trước khi phần mềm đó được phát hành đến người dùng?","options":["Quản trị cơ sở dữ liệu","Hỗ trợ kĩ thuật (`IT support`)","Quản trị mạng và hệ thống","Kiểm thử phần mềm (`tester`)"],"answer":3,"explain":"Kiểm thử phần mềm (`tester`) là nghề chuyên thử phần mềm trong nhiều tình huống khác nhau để phát hiện lỗi trước khi phát hành. Quản trị cơ sở dữ liệu trông coi dữ liệu, hỗ trợ kĩ thuật xử lí sự cố cho người đang dùng phần mềm, còn quản trị mạng và hệ thống lo mạng máy tính và máy chủ — không phải công việc dò lỗi phần mềm."},{"id":"CB-mc-2003","type":"mc","topic":"E","grade":11,"level":"medium","question":"Một công ty phát hiện cơ sở dữ liệu khách hàng bị truy cập trái phép, có dấu hiệu rò rỉ thông tin. Nghề nào cần vào cuộc xử lí trước tiên?","options":["Chuyên viên an toàn thông tin","Hỗ trợ kĩ thuật","Kiểm thử phần mềm","Nhân viên kinh doanh"],"answer":0,"explain":"Chuyên viên an toàn thông tin chuyên bảo vệ hệ thống và dữ liệu trước các cuộc tấn công mạng, truy cập trái phép hay rò rỉ thông tin, nên đây đúng là người cần vào cuộc trước tiên. Hỗ trợ kĩ thuật xử lí sự cố hằng ngày của người dùng, kiểm thử phần mềm lo dò lỗi trước khi phát hành, còn nhân viên kinh doanh không thuộc lĩnh vực kĩ thuật."},{"id":"CB-mc-2004","type":"mc","topic":"E","grade":11,"level":"medium","question":"Vì sao nghề hỗ trợ kĩ thuật (`IT support`) đặc biệt cần kĩ năng giao tiếp tốt?","options":["Vì phải viết tài liệu kĩ thuật bằng nhiều ngôn ngữ lập trình khác nhau","Vì phải thường xuyên giải thích vấn đề kĩ thuật bằng ngôn ngữ dễ hiểu cho người không rành công nghệ, đồng thời giữ bình tĩnh khi họ đang gặp sự cố","Vì phải thuyết trình trước hội đồng quản trị công ty mỗi tuần","Vì phải phiên dịch tài liệu kĩ thuật sang nhiều thứ tiếng khác nhau"],"answer":1,"explain":"Người làm hỗ trợ kĩ thuật thường xuyên tiếp xúc trực tiếp với người dùng không rành công nghệ, cần giải thích rõ ràng, dễ hiểu và giữ bình tĩnh khi họ đang bực bội vì gặp sự cố — đó là lí do giao tiếp tốt đặc biệt quan trọng với nghề này. Viết tài liệu bằng ngôn ngữ lập trình, thuyết trình trước hội đồng quản trị hay phiên dịch tài liệu không phải là công việc thường ngày của hỗ trợ kĩ thuật."},{"id":"CB-mc-2005","type":"mc","topic":"E","grade":11,"level":"hard","question":"Một hệ thống bán hàng trực tuyến chạy rất chậm mỗi khi có đông khách truy cập cùng lúc, dù đội kiểm thử đã xác nhận mã nguồn không có lỗi logic. Nghề nào phù hợp nhất để kiểm tra và xử lí tình huống này?","options":["Chuyên viên an toàn thông tin, vì tốc độ chậm chắc chắn do một cuộc tấn công mạng gây ra","Kiểm thử phần mềm, vì mọi sự cố đều xuất phát từ lỗi trong mã nguồn","Hỗ trợ kĩ thuật, vì chỉ cần hướng dẫn từng khách hàng cách khắc phục tại nhà","Quản trị mạng và hệ thống, vì cần kiểm tra khả năng đáp ứng của máy chủ và hạ tầng mạng khi có nhiều người truy cập cùng lúc"],"answer":3,"explain":"Tình huống mô tả đúng dấu hiệu hệ thống quá tải khi có nhiều người truy cập cùng lúc — thuộc trách nhiệm của quản trị mạng và hệ thống, người theo dõi và đảm bảo hiệu năng máy chủ, hạ tầng mạng. Đề bài đã loại trừ khả năng lỗi mã nguồn, chưa có bằng chứng cho thấy đây là một cuộc tấn công mạng, và hướng dẫn từng khách hàng cũng không giải quyết được nguyên nhân gốc của vấn đề."},{"id":"CB-tf-2001","type":"tf","topic":"E","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong nhóm nghề dịch vụ và quản trị, chứng chỉ chuyên môn hầu như không có giá trị gì, chỉ bằng đại học mới được nhà tuyển dụng công nhận.","correct":false},{"text":"Quản trị cơ sở dữ liệu (`DBA`) chịu trách nhiệm đảm bảo dữ liệu của một tổ chức luôn chính xác, an toàn và không bị mất khi có sự cố.","correct":true},{"text":"Người làm nghề dịch vụ và quản trị trong lĩnh vực tin học hầu như không cần tự học thêm sau khi ra trường, vì công nghệ trong ngành này ít khi thay đổi.","correct":false},{"text":"Bên cạnh kiến thức kĩ thuật, khả năng giao tiếp và giải quyết sự cố cũng là những kĩ năng quan trọng đối với nhiều nghề trong nhóm này.","correct":true}],"explain":"(1) Sai vì chứng chỉ chuyên môn thường được nhiều nhà tuyển dụng trong nhóm nghề này coi trọng, đôi khi ngang bằng hoặc hơn cả bằng cấp. (2) Đúng, đây chính là trách nhiệm chính của quản trị cơ sở dữ liệu. (3) Sai vì công nghệ, phần mềm và các hình thức tấn công mạng thay đổi liên tục, đòi hỏi phải tự học và cập nhật thường xuyên. (4) Đúng, đây là những kĩ năng đã nêu bên cạnh kiến thức kĩ thuật nền tảng."},{"id":"CB-mc-2101","type":"mc","topic":"A","grade":11,"level":"easy","question":"Vì sao không nên dùng tài khoản quản trị (admin) cho mọi việc thường ngày trên máy tính?","options":["Vì tài khoản quản trị luôn chạy chậm hơn tài khoản thường do phải kiểm tra nhiều quyền hơn.","Vì mọi phần mềm chạy dưới tài khoản này, kể cả phần mềm độc hại, đều được thừa hưởng quyền thay đổi toàn bộ hệ thống.","Vì tài khoản quản trị không mở được các phần mềm ứng dụng thông thường như trình duyệt hay soạn thảo văn bản.","Vì mỗi máy tính chỉ được phép đăng nhập bằng tài khoản quản trị một số lần nhất định."],"answer":1,"explain":"Đáp án đúng là B: phần mềm luôn chạy với đúng quyền của tài khoản đang đăng nhập, nên nếu lỡ mở phải mã độc khi đang dùng tài khoản quản trị thì mã độc lập tức có quyền sửa cả hệ thống; dùng tài khoản thường sẽ giới hạn thiệt hại trong phạm vi thư mục cá nhân. A sai vì quyền hạn của tài khoản không ảnh hưởng đến tốc độ xử lí của máy. C sai vì tài khoản quản trị chạy được mọi ứng dụng, thậm chí còn chạy được nhiều thứ hơn tài khoản thường. D sai vì không có giới hạn số lần đăng nhập nào như vậy."},{"id":"CB-mc-2102","type":"mc","topic":"A","grade":11,"level":"easy","question":"Khi không dùng một phần mềm nữa, cách gỡ bỏ đúng là gì?","options":["Xoá thư mục cài đặt của phần mềm rồi dọn sạch thùng rác.","Đổi tên thư mục cài đặt để phần mềm không khởi động được nữa.","Dùng chức năng gỡ cài đặt của hệ điều hành để phần mềm được tháo ra trọn vẹn.","Xoá biểu tượng lối tắt của phần mềm trên màn hình nền."],"answer":2,"explain":"Đáp án đúng là C: khi cài, phần mềm không chỉ chép tệp vào một thư mục mà còn ghi thông tin vào cấu hình hệ thống, đăng kí dịch vụ chạy ngầm và mục tự khởi động; chỉ chức năng gỡ cài đặt của hệ điều hành mới dọn được đầy đủ những phần đó. A sai vì xoá thư mục chỉ bỏ được phần tệp nhìn thấy, phần ghi trong hệ thống vẫn còn và tiếp tục làm máy chậm hoặc sinh lỗi. B sai vì đổi tên chỉ làm phần mềm không chạy được chứ hoàn toàn không gỡ bỏ gì, lại còn dễ gây lỗi. D sai vì lối tắt chỉ là đường dẫn đến phần mềm, xoá nó không hề động đến phần mềm đã cài."},{"id":"CB-mc-2103","type":"mc","topic":"A","grade":11,"level":"medium","question":"Đang soạn bài trên máy thì một ứng dụng vẽ hình đứng im, bấm mãi không phản hồi, trong khi các ứng dụng khác vẫn dùng được. Việc nên làm đầu tiên là gì?","options":["Mở trình quản lí tác vụ, chọn đúng ứng dụng không phản hồi rồi bấm kết thúc tác vụ.","Nhấn giữ nút nguồn để tắt cứng toàn bộ máy rồi bật lại.","Rút dây nguồn ra cắm lại để máy tự khởi động lại từ đầu.","Cài lại hệ điều hành để mọi phần mềm được thiết lập lại từ đầu."],"answer":0,"explain":"Đáp án đúng là A: hệ điều hành quản lí từng phần mềm như một tiến trình riêng, nên có thể kết thúc riêng tiến trình bị treo mà các ứng dụng khác vẫn chạy bình thường, không mất dữ liệu đang mở ở nơi khác. B và C đều là tắt cứng cả máy — cách này làm mất hết dữ liệu chưa lưu của mọi ứng dụng đang mở và còn có nguy cơ hỏng tệp đang ghi dở, chỉ nên dùng khi máy treo hoàn toàn không còn thao tác được. D sai vì cài lại hệ điều hành là biện pháp cực đoan, tốn hàng giờ, trong khi sự cố ở đây chỉ nằm ở một ứng dụng."},{"id":"CB-mc-2104","type":"mc","topic":"A","grade":11,"level":"medium","question":"Máy của bạn Hùng mở nguồn xong phải chờ rất lâu mới dùng được, dù ổ đĩa vẫn còn nhiều chỗ trống và máy đã cập nhật đầy đủ. Kiểm tra thì thấy có hàng chục biểu tượng phần mềm tự hiện lên ngay sau khi đăng nhập. Cách xử lí hợp lí nhất là gì?","options":["Gỡ bỏ toàn bộ phần mềm ứng dụng đang có trên máy rồi cài lại từng cái khi cần.","Xoá bớt tệp trong thư mục tài liệu cá nhân để nhẹ máy hơn khi khởi động.","Nâng cấp trình duyệt web lên phiên bản mới nhất để giảm thời gian khởi động máy.","Vào mục quản lí chương trình khởi động cùng máy và tắt bớt những chương trình không cần bật ngay từ đầu."],"answer":3,"explain":"Đáp án đúng là D: nguyên nhân đã được chỉ rõ là quá nhiều chương trình được đặt tự chạy cùng hệ điều hành, mỗi chương trình lại giành một phần CPU và RAM ngay lúc máy vừa đăng nhập; tắt bớt các mục khởi động là cách xử lí đúng gốc và không mất phần mềm nào cả (khi cần vẫn mở tay được). A sai vì gỡ hết phần mềm là phản ứng thái quá, mất thời gian mà không cần thiết. B sai vì đề bài đã nói ổ đĩa còn nhiều chỗ trống, hơn nữa tệp tài liệu nằm im không tự chạy nên không ảnh hưởng đến tốc độ khởi động. C sai vì phiên bản trình duyệt không liên quan đến thời gian khởi động máy, trừ khi chính trình duyệt được đặt tự bật cùng máy."},{"id":"CB-mc-2105","type":"mc","topic":"A","grade":11,"level":"hard","question":"Hệ điều hành báo có một bản cập nhật vá lỗ hổng bảo mật, nhưng bạn Mai bấm ‘Để sau’ suốt ba tháng vì ngại máy khởi động lại. Nhận định nào sau đây đúng về tình huống này?","options":["Không đáng lo, vì lỗ hổng bảo mật chỉ gây hại cho máy chủ của các công ty chứ không ảnh hưởng đến máy tính cá nhân.","Không đáng lo, vì đã có phần mềm diệt vi-rút trên máy thì phần mềm này thay thế được hoàn toàn vai trò của bản vá.","Đáng lo, vì khi bản vá được phát hành thì nội dung lỗ hổng cũng thường được công bố, kẻ xấu biết đúng chỗ yếu để khai thác trong khi máy của Mai vẫn chưa được vá.","Đáng lo, nhưng chỉ trong ngày đầu tiên; sau đó lỗ hổng sẽ tự mất tác dụng vì nhà sản xuất đã ngừng hỗ trợ phiên bản cũ."],"answer":2,"explain":"Đáp án đúng là C: bản vá và thông tin về lỗ hổng thường được công bố cùng lúc, nên kể từ thời điểm đó những máy chưa cập nhật chính là những máy để lộ đúng sơ hở mà ai cũng đã biết — càng hoãn lâu, rủi ro càng tăng chứ không đứng yên. A sai vì lỗ hổng nằm trong chính hệ điều hành và phần mềm mà máy cá nhân đang chạy. B sai vì phần mềm diệt vi-rút chỉ phát hiện và chặn mã độc đã biết mặt, nó không thể bịt được chỗ sơ hở nằm trong mã nguồn hệ điều hành — hai việc này bổ sung cho nhau chứ không thay thế nhau. D sai vì lỗ hổng chưa vá thì vẫn còn nguyên đó theo thời gian; việc nhà sản xuất ngừng hỗ trợ một phiên bản còn khiến tình hình xấu hơn vì sẽ không còn bản vá nào nữa."},{"id":"CB-tf-2101","type":"tf","topic":"A","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Nên dùng tài khoản thường cho các công việc hằng ngày và chỉ chuyển sang quyền quản trị khi thật sự cần cài đặt phần mềm hoặc thay đổi thiết lập hệ thống.","correct":true},{"text":"Kéo thư mục cài đặt của một phần mềm vào thùng rác rồi dọn sạch thùng rác là cách gỡ bỏ phần mềm triệt để nhất.","correct":false},{"text":"Kết thúc một tiến trình bị treo trong trình quản lí tác vụ chỉ đóng riêng ứng dụng đó, các ứng dụng khác vẫn tiếp tục chạy bình thường.","correct":true},{"text":"Bản cập nhật hệ điều hành chỉ nhằm bổ sung tính năng mới, nên bỏ qua cũng không ảnh hưởng gì đến mức độ an toàn của máy.","correct":false}],"explain":"(1) Đúng — mọi phần mềm đều chạy với quyền của tài khoản đang đăng nhập, nên dùng tài khoản thường hằng ngày giúp giới hạn thiệt hại nếu chẳng may dính mã độc, chỉ nâng quyền quản trị đúng lúc cần. (2) Sai — phần mềm khi cài còn ghi thông tin vào cấu hình hệ thống, đăng kí dịch vụ chạy ngầm và mục tự khởi động; xoá tay thư mục chỉ dọn được phần tệp nhìn thấy, phần còn lại vẫn nằm trong máy, phải dùng chức năng gỡ cài đặt của hệ điều hành mới sạch. (3) Đúng — hệ điều hành quản lí mỗi phần mềm như một tiến trình độc lập nên kết thúc được riêng tiến trình bị treo mà không phải tắt cứng cả máy. (4) Sai — bên cạnh tính năng mới, phần lớn bản cập nhật còn vá lỗi và vá lỗ hổng bảo mật; khi lỗ hổng đã bị công bố, máy chưa cập nhật chính là máy đang phơi ra sơ hở cho kẻ xấu khai thác."},{"id":"CB-mc-2201","type":"mc","topic":"A","grade":11,"level":"easy","question":"Muốn đưa cả hình ảnh và âm thanh từ máy tính ra máy chiếu chỉ bằng một sợi dây duy nhất, ta dùng cổng nào?","options":["Jack 3.5mm","Cổng RJ45","Cổng HDMI","Cổng USB-A"],"answer":2,"explain":"Cổng HDMI được thiết kế để truyền đồng thời tín hiệu hình ảnh và âm thanh, nên chỉ cần một dây là đủ. Jack 3.5mm chỉ truyền âm thanh, không mang được hình. Cổng RJ45 là cổng cắm dây mạng, không dùng để xuất hình. Cổng USB-A chủ yếu dùng cho chuột, bàn phím, ổ nhớ, máy in — không phải cổng xuất hình ảnh chuẩn ra máy chiếu."},{"id":"CB-mc-2202","type":"mc","topic":"A","grade":11,"level":"easy","question":"Trình điều khiển thiết bị (driver) là gì?","options":["Một linh kiện phần cứng gắn thêm vào máy để tăng tốc độ xử lí","Phần mềm giúp hệ điều hành hiểu và điều khiển được một thiết bị cụ thể","Loại dây cáp chuyên dụng dùng để nối thiết bị vào cổng USB","Vùng nhớ tạm dùng để chứa dữ liệu đang truyền giữa máy và thiết bị"],"answer":1,"explain":"Driver là một phần mềm đóng vai trò phiên dịch, chuyển các lệnh chung của hệ điều hành thành tín hiệu mà riêng thiết bị đó hiểu được. Phương án về linh kiện phần cứng sai vì driver không phải vật thể, không cắm được vào máy. Phương án về dây cáp sai vì cáp chỉ là đường truyền vật lí, không chứa lệnh điều khiển. Phương án về vùng nhớ tạm mô tả bộ đệm (buffer), là một khái niệm khác hẳn."},{"id":"CB-mc-2203","type":"mc","topic":"A","grade":11,"level":"medium","question":"Lần đầu tiên dùng một chiếc tai nghe không dây với máy tính xách tay, bước bắt buộc phải làm là gì?","options":["Cài một driver riêng tải về từ một trang tổng hợp driver trên mạng","Nối tai nghe với máy bằng dây RJ45 một lần để máy ghi nhận","Đưa tai nghe vào chế độ ghép đôi rồi chọn tên nó trong danh sách Bluetooth của máy","Tắt Wi-Fi trên máy, vì Wi-Fi và Bluetooth không thể hoạt động cùng lúc"],"answer":2,"explain":"Bluetooth yêu cầu hai bên phải ghép đôi (pairing) trong lần dùng đầu tiên: thiết bị vào chế độ chờ, máy dò tìm rồi ghi nhận tên nó; từ lần sau bật lên là tự nhận. Phương án cài driver từ trang tổng hợp vừa không cần thiết (tai nghe Bluetooth phổ thông dùng driver có sẵn) vừa rất nguy hiểm về mã độc. Phương án dùng dây RJ45 sai vì đó là cổng dây mạng, hoàn toàn không liên quan đến tai nghe. Phương án tắt Wi-Fi sai vì Wi-Fi và Bluetooth vẫn chạy song song bình thường trên cùng một máy."},{"id":"CB-mc-2204","type":"mc","topic":"A","grade":11,"level":"medium","question":"Hùng cần chuyển khoảng 300 tấm ảnh (gần 2 GB) từ điện thoại sang máy tính đang đặt ngay trước mặt, trong lúc mạng Internet của trường rất yếu. Cách hợp lí nhất là gì?","options":["Gửi lần lượt từng tấm ảnh qua Bluetooth","Tải toàn bộ ảnh lên một dịch vụ lưu trữ trực tuyến rồi tải xuống lại ở máy tính","Đính kèm ảnh vào nhiều thư điện tử rồi tự gửi cho chính mình","Nối điện thoại với máy tính bằng cáp USB rồi chép thẳng thư mục ảnh sang"],"answer":3,"explain":"Nối cáp cho tốc độ cao nhất, không phụ thuộc Internet và cho phép kéo thả cả thư mục một lần — đúng với hoàn cảnh hai thiết bị đang ở cạnh nhau còn mạng thì yếu. Gửi qua Bluetooth sai vì tốc độ Bluetooth rất thấp, 2 GB sẽ mất rất lâu. Dùng dịch vụ trực tuyến sai vì phải tải lên rồi tải xuống qua đúng đường mạng đang yếu, tức là truyền hai lần trên kênh chậm nhất. Gửi qua thư điện tử còn tệ hơn: vẫn cần Internet, lại bị giới hạn dung lượng tệp đính kèm nên phải chia thành rất nhiều thư."},{"id":"CB-mc-2205","type":"mc","topic":"A","grade":11,"level":"hard","question":"Cắm một máy in mới vào cổng USB, máy tính báo có thiết bị được gắn vào nhưng không in được; mở mục quản lí thiết bị thì thấy dòng tên máy in có dấu chấm than màu vàng. Cách xử lí đúng đắn nhất là gì?","options":["Tải và cài trình điều khiển đúng model máy in từ trang web chính hãng của nhà sản xuất","Chuyển sang cắm vào một cổng USB khác, vì cổng đang dùng chắc chắn đã hỏng","Cài một phần mềm cập nhật driver tự động tìm được trên mạng để nó tự dò và sửa","Thay một sợi cáp USB khác, vì dấu chấm than báo hiệu dây truyền dữ liệu bị đứt"],"answer":0,"explain":"Dấu chấm than vàng cho biết hệ điều hành đã thấy thiết bị nhưng chưa có trình điều khiển phù hợp để làm việc với nó, nên giải pháp đúng là cài driver đúng model và đúng phiên bản hệ điều hành, lấy từ trang chính hãng. Đổi cổng USB không giải quyết được, vì nếu cổng hỏng thì máy đã không nhận ra thiết bị ngay từ đầu. Dùng phần mềm cập nhật driver tự động trôi nổi trên mạng là con đường lây mã độc rất phổ biến, do driver chạy với quyền rất cao trong hệ thống. Thay cáp cũng không đúng, vì cáp đứt sẽ khiến máy không phát hiện được thiết bị chứ không tạo ra dấu chấm than báo thiếu driver."},{"id":"CB-tf-2201","type":"tf","topic":"A","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Cổng USB-C cắm được theo cả hai chiều, ngoài truyền dữ liệu còn dùng để sạc pin cho thiết bị.","correct":true},{"text":"Muốn dùng tai nghe Bluetooth với máy tính, bắt buộc phải nối tai nghe với máy bằng dây ít nhất một lần để máy ghi nhận.","correct":false},{"text":"NFC có phạm vi hoạt động ngắn hơn Bluetooth rất nhiều, chỉ khoảng vài xăng-ti-mét.","correct":true},{"text":"Vừa chép xong tệp là có thể rút thẳng ổ nhớ USB ra khỏi máy, vì dữ liệu luôn được ghi xong ngay lập tức.","correct":false}],"explain":"(1) Đúng — USB-C được thiết kế đối xứng nên cắm chiều nào cũng được, và ngoài truyền dữ liệu tốc độ cao nó còn đảm nhận việc cấp điện sạc pin cho máy hoặc cho điện thoại. (2) Sai — Bluetooth là chuẩn không dây, việc ghép đôi được thực hiện hoàn toàn qua sóng: chỉ cần đưa tai nghe vào chế độ ghép đôi rồi chọn tên nó trong danh sách trên máy, không cần nối dây lần nào. (3) Đúng — NFC chỉ hoạt động khi hai thiết bị chạm hoặc gần như chạm nhau, phạm vi vài xăng-ti-mét, trong khi Bluetooth đi được tới cả mươi mét; chính phạm vi cực ngắn ấy làm NFC an toàn cho thẻ và thanh toán chạm. (4) Sai — hệ điều hành thường giữ tạm một phần dữ liệu trong bộ nhớ để ghi gộp cho nhanh, nên rút đột ngột có thể làm tệp ghi dở hoặc hỏng cấu trúc thư mục của ổ; phải chọn lệnh ngắt kết nối an toàn và chờ thông báo rồi mới rút."},{"id":"CB-mc-2301","type":"mc","topic":"B","grade":11,"level":"easy","question":"Trong địa chỉ thư điện tử `thuha.11a5@truongbinhminh.edu.vn`, phần đứng sau dấu `@` cho biết điều gì?","options":["Mật khẩu rút gọn của hộp thư","Họ tên đầy đủ của chủ hộp thư","Tên miền — cho biết máy chủ của tổ chức nào quản lí hộp thư đó","Dung lượng tối đa mà hộp thư được phép sử dụng"],"answer":2,"explain":"Địa chỉ thư luôn có dạng `tên_người_dùng@tên_miền`. Phần sau dấu `@` là tên miền, cho biết hộp thư do máy chủ của tổ chức nào quản lí (ở đây là một trường học). Phương án A sai vì mật khẩu không bao giờ nằm trong địa chỉ thư và không được chia sẻ cho ai. Phương án B sai vì họ tên (nếu có) nằm ở phần trước dấu `@`, tức phần tên người dùng. Phương án D sai vì dung lượng hộp thư do nhà cung cấp dịch vụ quy định, hoàn toàn không thể hiện trong địa chỉ."},{"id":"CB-mc-2302","type":"mc","topic":"B","grade":11,"level":"easy","question":"Điểm khác biệt cơ bản giữa ô Bcc và ô Cc khi soạn thư điện tử là gì?","options":["Thư gửi qua Bcc đến chậm hơn thư gửi qua Cc","Địa chỉ đặt trong ô Bcc bị giấu đi, những người nhận khác không thấy; còn địa chỉ trong ô Cc thì ai cũng thấy","Ô Bcc chỉ điền được đúng một địa chỉ, ô Cc điền được nhiều địa chỉ","Người nhận qua Bcc không đọc được phần đính kèm của thư"],"answer":1,"explain":"Bcc nghĩa là gửi kín: người trong ô Bcc vẫn nhận đầy đủ lá thư, nhưng địa chỉ của họ bị giấu nên các người nhận khác không biết họ có trong danh sách. Ngược lại, mọi địa chỉ trong ô To và Cc đều hiển thị công khai cho tất cả người nhận. Phương án A sai vì tốc độ gửi hoàn toàn như nhau. Phương án C sai vì ô Bcc điền được rất nhiều địa chỉ — đó chính là lí do nó hữu ích khi gửi hàng loạt. Phương án D sai vì người nhận qua Bcc nhận được lá thư nguyên vẹn, kể cả tệp đính kèm."},{"id":"CB-mc-2303","type":"mc","topic":"B","grade":11,"level":"medium","question":"Hằng cần gửi cho cô giáo một đoạn phim ghi lại buổi diễn văn nghệ, tệp nặng khoảng 850 MB, trong khi dịch vụ thư chỉ cho đính kèm tối đa 25 MB. Cách xử lí hợp lí nhất là gì?","options":["Nén tệp phim thành `.zip` rồi đính kèm như bình thường","Tải tệp lên kho lưu trữ trực tuyến, đặt quyền xem phù hợp rồi gửi liên kết tới tệp trong thư","Cắt tệp phim thành 40 phần nhỏ và gửi thành 40 lá thư liên tiếp","Gửi thư nhiều lần cho đến khi hệ thống chấp nhận phần đính kèm"],"answer":1,"explain":"Với tệp quá nặng, giải pháp chuẩn là đưa tệp lên kho lưu trữ trực tuyến rồi chỉ gửi liên kết: thư nhẹ, gửi được ngay, người nhận vẫn xem được đầy đủ. Phương án A sai vì tệp phim đã ở dạng nén sẵn nên nén lại gần như không giảm dung lượng, 850 MB vẫn vượt xa mức 25 MB. Phương án C tuy về lí thuyết có thể làm được nhưng gây phiền cho người nhận và rất dễ thất lạc, không phải cách làm hợp lí. Phương án D sai vì giới hạn dung lượng là quy định cố định, gửi lại bao nhiêu lần cũng vẫn bị từ chối."},{"id":"CB-mc-2304","type":"mc","topic":"B","grade":11,"level":"medium","question":"Nam muốn mọi thư gửi từ địa chỉ của ban chủ nhiệm câu lạc bộ Tin học tự động được gắn nhãn ‘CLB’ và chuyển khỏi hộp thư đến, mà không phải thao tác thủ công mỗi lần. Nam nên dùng chức năng nào?","options":["Tìm kiếm theo từ khoá ‘CLB’ mỗi khi cần xem thư","Đánh dấu các thư đó là thư rác để hệ thống tự chuyển đi","Bấm huỷ đăng kí ở cuối các thư của câu lạc bộ","Đặt một bộ lọc tự động với điều kiện theo người gửi"],"answer":3,"explain":"Bộ lọc tự động cho phép đặt quy tắc dạng ‘nếu thư đến từ địa chỉ X thì gắn nhãn Y và bỏ khỏi hộp thư đến’, đúng nhu cầu của Nam và chỉ cần thiết lập một lần. Phương án A sai vì tìm kiếm chỉ giúp tra lại thư khi cần chứ không tự sắp xếp thư mới đến. Phương án B sai và còn nguy hiểm: đánh dấu thư rác sẽ khiến hệ thống chặn dần các thư quan trọng của câu lạc bộ. Phương án C sai vì huỷ đăng kí sẽ làm Nam không còn nhận được thư của câu lạc bộ nữa, trong khi bạn ấy vẫn muốn nhận, chỉ là muốn chúng nằm gọn một chỗ."},{"id":"CB-mc-2305","type":"mc","topic":"B","grade":11,"level":"hard","question":"Trang đăng một tấm ảnh chụp chung cả lớp ở chế độ công khai, hôm sau thấy không ổn nên xoá bài và chỉnh lại quyền riêng tư về ‘chỉ bạn bè’. Nhận định nào sau đây là chính xác nhất?","options":["Sau khi xoá bài, tấm ảnh chắc chắn biến mất hoàn toàn khỏi Internet","Chỉnh quyền riêng tư về ‘chỉ bạn bè’ sẽ tự động thu hồi mọi bản sao mà người khác đã lưu","Việc xoá bài chỉ gỡ bài khỏi trang của Trang, còn bản chụp màn hình hay bản tải về của người khác vẫn tồn tại — nên cần cân nhắc trước khi đăng","Vì bài đã bị xoá nên về sau không ai có thể tìm lại được nội dung đó nữa"],"answer":2,"explain":"Nội dung đã đưa lên mạng để lại dấu vết số lâu dài: trong khoảng thời gian bài còn công khai, bất kỳ ai cũng có thể chụp màn hình hoặc tải ảnh về máy, và những bản sao đó nằm ngoài tầm kiểm soát của người đăng. Vì vậy cách bảo vệ chắc chắn nhất là cân nhắc trước khi đăng. Phương án A và D sai vì xoá bài chỉ tác động lên bản đăng trên trang cá nhân, không xoá được các bản sao đã phát tán. Phương án B sai vì thiết lập quyền riêng tư chỉ áp dụng cho việc hiển thị từ nay về sau, không có khả năng thu hồi những gì người khác đã lưu giữ."},{"id":"CB-tf-2301","type":"tf","topic":"B","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Khi gửi cùng một thông báo tới 60 phụ huynh không quen biết nhau, nên đặt các địa chỉ đó vào ô Bcc để không ai nhìn thấy địa chỉ của người khác.","correct":true},{"text":"Nén một tập tài liệu văn bản thành tệp `.zip` trước khi đính kèm giúp giảm dung lượng và gộp nhiều tệp thành một, thuận tiện cho người nhận.","correct":true},{"text":"Mọi địa chỉ đặt trong ô Cc đều được hệ thống giấu đi, người nhận khác không thể biết thư còn được gửi cho ai.","correct":false},{"text":"Với thư quảng cáo nhận đều đặn hằng ngày, cách xử lí triệt để nhất là xoá tay từng thư mỗi khi mở hộp thư.","correct":false}],"explain":"(1) Đúng — đây chính là công dụng quan trọng nhất của Bcc: gửi hàng loạt mà vẫn bảo vệ địa chỉ của từng người, đồng thời tránh cảnh cả danh sách bấm ‘trả lời tất cả’. (2) Đúng — nén rất hiệu quả với văn bản và bảng tính, lại gói nhiều tệp lẻ thành một tệp duy nhất để người nhận chỉ phải tải một lần. (3) Sai — Cc là đồng gửi công khai, mọi người trong ô To và Cc đều nhìn thấy đầy đủ danh sách nhau; chỉ có Bcc mới giấu địa chỉ. (4) Sai — xoá tay chỉ giải quyết phần ngọn vì mai thư lại đến; cách triệt để là bấm liên kết huỷ đăng kí ở cuối thư, hoặc đánh dấu thư rác để hệ thống tự chặn về sau."},{"id":"CB-mc-2401","type":"mc","topic":"C","grade":11,"level":"easy","question":"Em lỡ tay xoá nhầm tệp đề cương ôn tập trong kho lưu trữ trực tuyến của mình cách đây mười phút. Việc nên làm đầu tiên là gì?","options":["Soạn lại tệp mới từ đầu, vì tệp đã xoá thì không có cách nào lấy lại","Mở thùng rác của dịch vụ lưu trữ và chọn khôi phục tệp về vị trí cũ","Gỡ ứng dụng đồng bộ trên máy tính rồi cài đặt lại để hệ thống nạp lại dữ liệu","Đổi mật khẩu tài khoản để dịch vụ tự động phục hồi các tệp vừa mất"],"answer":1,"explain":"Đáp án đúng là B: tệp bị xoá thường chỉ được chuyển vào thùng rác và nằm đó một thời gian, nên chỉ cần vào thùng rác chọn khôi phục là tệp trở lại đúng thư mục cũ. A sai vì xoá chưa đồng nghĩa với mất vĩnh viễn — chỉ khi đã xoá khỏi thùng rác hoặc quá hạn lưu mới không lấy lại được. C sai vì cài lại ứng dụng đồng bộ không tạo ra dữ liệu mới; bản trên máy chủ đã bị xoá thì đồng bộ về vẫn không có tệp đó. D sai vì mật khẩu chỉ liên quan đến việc đăng nhập, hoàn toàn không tác động gì đến nội dung đã xoá."},{"id":"CB-mc-2402","type":"mc","topic":"C","grade":11,"level":"easy","question":"Cô giáo muốn đọc bản nháp bài thuyết trình của nhóm em và ghi ý kiến góp ý ngay bên lề tài liệu, nhưng không tự tay thay đổi nội dung học sinh đã viết. Mức quyền nào phù hợp nhất để chia sẻ cho cô?","options":["Được chỉnh sửa","Chỉ được xem","Được nhận xét","Chuyển hẳn quyền chủ sở hữu tài liệu cho cô"],"answer":2,"explain":"Đáp án đúng là C: mức được nhận xét cho phép người nhận đọc tài liệu và chèn ý kiến vào lề, nhưng nội dung gốc vẫn nguyên vẹn — đúng nhu cầu của cô. A cấp quá nhiều quyền: cô có thể sửa trực tiếp, trái với yêu cầu chỉ góp ý. B cấp quá ít: chỉ được xem thì cô đọc được nhưng không ghi được ý kiến vào tài liệu. D là sai lầm nghiêm trọng vì chuyển quyền chủ sở hữu tức là trao toàn bộ quyền quản lí tệp, kể cả quyền xoá và quyền chia sẻ lại cho người khác."},{"id":"CB-mc-2403","type":"mc","topic":"C","grade":11,"level":"medium","question":"Em đang sửa một tệp nằm trong thư mục được đồng bộ trên máy tính thì mạng nhà bị mất. Điều gì xảy ra với những thay đổi em vừa thực hiện?","options":["Thay đổi vẫn được lưu ngay trên máy và tự động tải lên đám mây khi có mạng trở lại","Máy tính không cho mở tệp nữa vì không liên lạc được với máy chủ lưu trữ","Thay đổi bị huỷ bỏ ngay khi em đóng tệp vì chưa kịp gửi lên máy chủ","Bản trên đám mây vẫn được cập nhật bình thường vì đồng bộ không cần Internet"],"answer":0,"explain":"Đáp án đúng là A: tệp trong thư mục đồng bộ nằm sẵn trên ổ đĩa nên vẫn mở và sửa được khi mất mạng; thay đổi được ghi lại và xếp vào hàng đợi ở trạng thái đang chờ đồng bộ, đến khi có mạng ứng dụng tự đẩy lên. B sai vì bản cục bộ luôn có sẵn, không cần mạng để mở. C sai vì thay đổi được lưu xuống ổ đĩa chứ không nằm tạm ở đâu để bị mất khi đóng tệp. D sai ngược lại: việc đẩy dữ liệu lên máy chủ bắt buộc phải có kết nối Internet, nên trong lúc mất mạng bản trên đám mây vẫn là nội dung cũ."},{"id":"CB-mc-2404","type":"mc","topic":"C","grade":11,"level":"medium","question":"Nhóm em đặt bảng danh sách thành viên câu lạc bộ (có kèm số điện thoại và địa chỉ nhà) ở chế độ chia sẻ 'Bất kì ai có liên kết đều chỉnh sửa được', rồi dán liên kết vào một hội nhóm mạng xã hội đông người. Nhận định nào đúng nhất?","options":["Không đáng lo, vì đường liên kết rất dài và khó đoán nên chỉ ai biết chính xác mới mở được tệp","Yên tâm được, vì dịch vụ lưu trữ sẽ tự động che các thông tin cá nhân có trong tệp được chia sẻ","Chỉ cần xoá bài đăng chứa liên kết là những người đã kịp lưu lại liên kết cũng mất quyền truy cập","Rất rủi ro: ai có liên kết cũng xem và sửa được dữ liệu cá nhân, nên phải chuyển về chia sẻ theo email"],"answer":3,"explain":"Đáp án đúng là D: ở chế độ công khai, hệ thống không kiểm tra người mở là ai, nên bất kì ai cầm được liên kết đều đọc và sửa được dữ liệu cá nhân của cả nhóm; cách xử lí đúng là chia sẻ đích danh theo email và cấp mức quyền thấp nhất đủ dùng. A sai vì liên kết đã bị dán công khai thì không còn bí mật, hơn nữa nó có thể được chép lại và lan tiếp vô hạn. B sai vì dịch vụ lưu trữ không đọc hiểu và cũng không che nội dung bên trong tệp của người dùng. C sai vì xoá bài đăng chỉ làm liên kết khó tìm hơn, còn quyền truy cập vẫn còn nguyên; muốn thu hồi thật sự phải đổi phạm vi liên kết về chế độ hạn chế trong phần thiết lập chia sẻ."},{"id":"CB-mc-2405","type":"mc","topic":"C","grade":11,"level":"hard","question":"Sáng thứ Hai, cả nhóm phát hiện phần 'Kết luận' trong bản báo cáo dùng chung đã biến mất, không ai nhớ mình đã xoá và tệp vẫn nằm nguyên trong thư mục. Cách xử lí đúng và ít thiệt hại nhất là gì?","options":["Tải bản đang có về máy rồi gõ lại phần kết luận theo trí nhớ của cả nhóm","Mở lịch sử phiên bản của tài liệu, xem lại bản ở thời điểm trước khi nội dung bị mất rồi khôi phục đúng bản đó","Xoá tệp đi rồi vào thùng rác khôi phục lại để lấy về nội dung trước khi bị sửa","Hạ quyền của mọi thành viên xuống mức chỉ được xem để phần bị xoá tự quay trở lại"],"answer":1,"explain":"Đáp án đúng là B: dịch vụ tự động ghi lại các mốc thay đổi của tài liệu, nên chỉ cần mở lịch sử phiên bản, chọn bản trước thời điểm mất nội dung và khôi phục là lấy lại được nguyên vẹn phần kết luận. A tốn công và chắc chắn không khớp bản gốc, trong khi dữ liệu vẫn còn cứu được. C là hiểu nhầm nguy hiểm: thùng rác chỉ khôi phục tệp đã bị xoá cả tệp, còn xoá rồi khôi phục sẽ trả về đúng bản mới nhất — tức là bản đã mất phần kết luận. D sai vì thay đổi mức quyền chỉ ngăn chuyện sửa tiếp về sau, hoàn toàn không phục hồi được nội dung đã bị xoá."},{"id":"CB-tf-2401","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Người được chia sẻ ở mức 'được nhận xét' có thể ghi ý kiến vào lề tài liệu nhưng không sửa được nội dung gốc.","correct":true},{"text":"Sau khi đã cấp quyền chỉnh sửa cho một người, chủ sở hữu không còn cách nào thu hồi quyền đó nữa.","correct":false},{"text":"Thư mục đồng bộ hoạt động hai chiều: đổi tên một tệp trên điện thoại thì sau khi đồng bộ xong, tên tệp trên máy tính cũng đổi theo.","correct":true},{"text":"Chia sẻ theo danh sách địa chỉ email và chia sẻ công khai cho bất kì ai có liên kết là hai cách hoàn toàn tương đương về mức độ an toàn.","correct":false}],"explain":"(1) Đúng — mức được nhận xét cho phép đọc và chèn nhận xét vào lề, còn nội dung gốc thì được giữ nguyên, đây chính là mức phù hợp cho người góp ý. (2) Sai — chủ sở hữu luôn vào lại phần thiết lập chia sẻ để gỡ tên người đó khỏi danh sách, hoặc hạ mức quyền xuống thấp hơn; với liên kết công khai thì chuyển phạm vi về chế độ hạn chế là thu hồi được ngay. (3) Đúng — đồng bộ là quá trình hai chiều, thay đổi ở bất kì thiết bị nào cũng được đẩy lên máy chủ rồi kéo về các thiết bị còn lại đang đăng nhập cùng tài khoản. (4) Sai — chia sẻ theo email chỉ cho đúng những tài khoản được mời truy cập, còn chế độ công khai thì không kiểm tra danh tính, ai cầm được liên kết cũng vào được nên rủi ro lộ dữ liệu cao hơn hẳn."},{"id":"CB-mc-2501","type":"mc","topic":"D","grade":11,"level":"easy","question":"Một người gọi điện, tự xưng là nhân viên ngân hàng, nói cần bạn đọc mã OTP vừa gửi về máy để mở khoá tài khoản. Cách xử lí đúng là gì?","options":["Đọc mã cho họ, vì nhân viên ngân hàng mới biết tài khoản đang bị khoá","Không đọc mã cho bất kì ai; tắt máy rồi tự gọi tổng đài chính thức của ngân hàng để kiểm tra lại","Chụp màn hình mã rồi gửi qua tin nhắn cho chắc chắn không đọc nhầm số","Chỉ đọc ba chữ số đầu của mã để họ xác minh, giữ lại phần còn lại"],"answer":1,"explain":"Mã OTP là mã dùng một lần chỉ dành riêng cho chủ tài khoản; không tổ chức hợp pháp nào có lí do hỏi mã này, nên ai hỏi thì chính người đó đang lừa. Cách đúng là từ chối rồi tự liên hệ lại qua kênh chính thức do mình tự tra, vì số gọi đến có thể bị giả mạo. Phương án A sai vì kẻ lừa hoàn toàn có thể biết trước tên và một phần thông tin của bạn để tạo lòng tin. Phương án C sai vì gửi mã qua tin nhắn cũng chính là để lộ mã, thậm chí còn để lại bản lưu. Phương án D sai vì mã OTP không có phần nào được phép tiết lộ: khi bạn đã chịu đọc dù chỉ ba chữ số, kẻ gian chỉ cần lấy cớ nghe chưa rõ để hỏi tiếp cho đủ cả mã."},{"id":"CB-mc-2502","type":"mc","topic":"D","grade":11,"level":"easy","question":"Biết trang chính thức của trường có tên miền là thpthonngoc.edu.vn, địa chỉ nào dưới đây thật sự thuộc về trường?","options":["https://thpthonngoc.edu.vn.hocbong.top/dang-ky","https://hocbong2026.xyz/thpthonngoc/tin-tuc","https://thpthonngoc-edu-vn.info/tin-tuc","https://thpthonngoc.edu.vn/tin-tuc/hoc-bong"],"answer":3,"explain":"Chủ sở hữu thật của trang nằm ở CUỐI đoạn đứng trước dấu gạch chéo đầu tiên; chỉ phương án D có đoạn đó kết thúc đúng bằng thpthonngoc.edu.vn. Phương án A tuy chứa đủ chữ thpthonngoc.edu.vn nhưng chuỗi ấy chỉ là tên miền phụ, chủ thật là hocbong.top. Phương án B đặt tên trường sau dấu gạch chéo — phần này do chủ trang tự viết nên không nói lên điều gì, trang thuộc về hocbong2026.xyz. Phương án C thay các dấu chấm bằng dấu gạch nối, tạo ra một tên miền hoàn toàn khác là thpthonngoc-edu-vn.info."},{"id":"CB-mc-2503","type":"mc","topic":"D","grade":11,"level":"medium","question":"Vì sao dùng chung một mật khẩu cho nhiều dịch vụ là nguy hiểm, ngay cả khi mật khẩu đó rất dài và phức tạp?","options":["Vì một mật khẩu dùng càng lâu thì càng tự yếu đi theo thời gian","Vì các dịch vụ khác nhau không cho phép người dùng đặt mật khẩu giống nhau","Vì chỉ cần một dịch vụ bị lộ dữ liệu, kẻ tấn công sẽ đem đúng cặp tên đăng nhập và mật khẩu đó thử tự động vào mọi dịch vụ khác của bạn","Vì trình duyệt không thể ghi nhớ một mật khẩu đã được dùng ở nhiều trang khác nhau"],"answer":2,"explain":"Nguy cơ nằm ở chỗ độ mạnh của mật khẩu không cứu được bạn khi chính dịch vụ lưu nó bị lộ dữ liệu: kẻ tấn công có sẵn cặp tên đăng nhập và mật khẩu đúng, chỉ việc thử hàng loạt sang các dịch vụ khác, nên một chỗ thủng kéo theo mất tất cả. Phương án A sai vì mật khẩu không tự yếu đi, nó chỉ mất an toàn khi bị lộ. Phương án B sai vì các dịch vụ hoàn toàn độc lập, không hề biết mật khẩu bạn dùng ở nơi khác. Phương án D sai vì trình duyệt vẫn ghi nhớ bình thường, đó không phải vấn đề an toàn ở đây."},{"id":"CB-mc-2504","type":"mc","topic":"D","grade":11,"level":"medium","question":"Khi thấy đầu địa chỉ trang web có chữ https kèm biểu tượng ổ khoá, kết luận nào sau đây là đúng?","options":["Dữ liệu trao đổi giữa máy của bạn và trang đó được mã hoá, nhưng điều đó không chứng minh trang thuộc về tổ chức thật","Trang đã được cơ quan chức năng kiểm duyệt nội dung nên đáng tin cậy","Đây chắc chắn là trang chính thức, có thể yên tâm nhập mật khẩu và mã OTP","Trang này không thể chứa liên kết dẫn tới phần mềm độc hại"],"answer":0,"explain":"Ổ khoá chỉ nói lên rằng kết nối được mã hoá, tức người ngoài không đọc lén được nội dung trên đường truyền; nó không nói gì về danh tính hay ý đồ của chủ trang. Phương án B sai vì chứng chỉ bảo mật do tổ chức cấp chứng chỉ cấp một cách tự động, hoàn toàn không có khâu kiểm duyệt nội dung. Phương án C sai và là hiểu lầm nguy hiểm nhất: kẻ lừa đảo xin chứng chỉ rất dễ và miễn phí, nên trang giả vẫn có ổ khoá xanh như thường. Phương án D sai vì mã hoá đường truyền không ngăn được việc trang đó chứa nội dung hay tệp độc hại."},{"id":"CB-mc-2505","type":"mc","topic":"D","grade":11,"level":"hard","question":"Trâm lỡ bấm một liên kết lạ trên điện thoại và đã gõ tên đăng nhập cùng mật khẩu hộp thư vào trang đó. Thứ tự xử lí hợp lí nhất là gì?","options":["Đăng nhập lại vào hộp thư ngay trên chính điện thoại đó để xem có gì bất thường, rồi mới tính chuyện đổi mật khẩu","Chờ vài ngày xem có chuyện gì xảy ra không, nếu mọi thứ vẫn bình thường thì coi như không sao","Ngắt mạng điện thoại, dùng máy khác đổi mật khẩu hộp thư, đăng xuất mọi phiên đang mở, chụp lại bằng chứng rồi báo người lớn và cảnh báo bạn bè","Xoá hết tin nhắn cùng lịch sử duyệt web để không ai biết, rồi lập một tài khoản hoàn toàn mới"],"answer":2,"explain":"Phương án C đúng vì nó đi theo trình tự chặn thiệt hại rồi mới khắc phục: cắt đường truyền dữ liệu, giành lại quyền kiểm soát từ một thiết bị đáng tin, đẩy kẻ gian ra khỏi các phiên đang mở, giữ bằng chứng và cuối cùng là báo tin để chặn thiệt hại lan sang người khác. Phương án A sai vì thiết bị vừa bấm nhầm đang bị nghi ngờ, gõ lại mật khẩu trên đó có thể tiếp tục để lộ thông tin. Phương án B sai vì kẻ chiếm tài khoản hành động trong vài phút chứ không chờ vài ngày, chậm trễ chỉ làm mất cơ hội cứu vãn. Phương án D sai vì xoá bằng chứng khiến việc trình báo mất căn cứ, còn tài khoản cũ vẫn nằm trong tay kẻ gian và tiếp tục được dùng để lừa bạn bè."},{"id":"CB-tf-2501","type":"tf","topic":"D","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Mã QR và liên kết rút gọn không cho biết trước đích đến, nên cần xem trước địa chỉ thật hoặc tự gõ địa chỉ chính thức thay vì bấm ngay.","correct":true},{"text":"Nếu tin nhắn mượn tiền được gửi đi từ đúng tài khoản của bạn thân thì chắc chắn chính bạn ấy là người nhắn.","correct":false},{"text":"Bật xác thực hai bước giúp tài khoản vẫn an toàn ngay cả khi mật khẩu bị lộ, với điều kiện ta không cung cấp mã xác thực cho người khác.","correct":true},{"text":"Khi đã lỡ nhập mật khẩu vào một trang giả, nên tiếp tục dùng chính thiết bị đó để đổi mật khẩu vì như vậy nhanh nhất.","correct":false}],"explain":"(1) Đúng — cả mã QR lẫn liên kết rút gọn đều che mất địa chỉ thật, người dùng chỉ biết mình đi đâu sau khi trang đã mở, nên phải xem trước hoặc tự gõ địa chỉ chính thức. (2) Sai — tài khoản của người quen hoàn toàn có thể đã bị chiếm, đây chính là chiêu mượn danh phổ biến nhất; cần gọi điện trực tiếp hoặc hỏi một chi tiết chỉ hai người mới biết để xác minh. (3) Đúng — xác thực hai bước dựng thêm một lớp khoá độc lập với mật khẩu, nhưng lớp khoá đó chỉ còn giá trị khi ta tuyệt đối không đọc mã cho ai. (4) Sai — thiết bị vừa bấm nhầm đang bị nghi ngờ, việc cần làm là ngắt mạng thiết bị đó rồi đổi mật khẩu từ một máy khác đã an toàn."},{"id":"CB-mc-2601","type":"mc","topic":"C","grade":11,"level":"easy","question":"Một trường quản lí việc mượn sách bằng duy nhất một bảng, mỗi lượt mượn là một dòng có đủ họ tên và lớp của người mượn. Hậu quả nghiêm trọng nhất của cách làm này là gì?","options":["Bảng có quá nhiều cột nên không in vừa một trang giấy A4.","Máy tính không thể sắp xếp bảng theo cột ngày mượn được nữa.","Dữ liệu bị dư thừa, và khi một độc giả đổi lớp mà sửa sót một dòng thì bảng tự mâu thuẫn với chính nó.","Không thể thêm dòng mới vào bảng một khi bảng đã có quá nhiều dòng."],"answer":2,"explain":"Đáp án đúng là C. Vì họ tên và lớp bị chép lại ở mọi lượt mượn nên dữ liệu vừa dư thừa (tốn chỗ, không mang thêm tin tức) vừa dễ mâu thuẫn: một lần đổi lớp phải sửa hàng chục ô, sót một ô là bảng ghi hai lớp khác nhau cho cùng một người. A sai vì số cột nhiều hay ít chỉ là chuyện trình bày, không phải lỗi thiết kế dữ liệu. B sai vì việc sắp xếp theo một cột bất kì vẫn thực hiện bình thường, dồn chung một bảng không cản trở thao tác này. D sai vì số dòng của bảng không bị giới hạn bởi kiểu thiết kế; thêm dòng mới vẫn luôn làm được, vấn đề chỉ là dòng mới lại tiếp tục lặp dữ liệu."},{"id":"CB-mc-2602","type":"mc","topic":"C","grade":11,"level":"easy","question":"Sau khi tách dữ liệu thư viện thành ba bảng ĐỘC GIẢ, SÁCH và LƯỢT MƯỢN, bảng LƯỢT MƯỢN cần chứa những trường nào để biết được ai đã mượn cuốn nào?","options":["Mã độc giả và mã sách, đóng vai trò khoá ngoại trỏ về khoá chính của hai bảng kia.","Họ tên độc giả và nhan đề sách, chép lại đầy đủ cho người xem dễ đọc.","Chỉ cần ngày mượn và hạn trả, vì thủ thư đã nhớ ai mượn cuốn nào.","Toàn bộ các trường của bảng ĐỘC GIẢ và toàn bộ các trường của bảng SÁCH."],"answer":0,"explain":"Đáp án đúng là A. Bảng LƯỢT MƯỢN chỉ giữ hai mã tham chiếu là mã độc giả và mã sách; đó chính là khoá ngoại, nhờ chúng mà từ một lượt mượn ta lần được sang bảng ĐỘC GIẢ và bảng SÁCH để lấy mọi chi tiết còn lại. B sai vì chép lại họ tên và nhan đề chính là quay về đúng lỗi dư thừa mà việc tách bảng muốn loại bỏ. C sai vì thiếu hẳn thông tin về người mượn và về cuốn sách thì lượt mượn trở nên vô nghĩa, không thể nhắc trả hay thống kê được. D sai vì chép toàn bộ các trường của hai bảng sang đây còn tệ hơn cả bảng gộp ban đầu, dữ liệu lặp lại ở mức tối đa."},{"id":"CB-mc-2603","type":"mc","topic":"C","grade":11,"level":"medium","question":"Vì sao khi thiết kế bảng ĐỘC GIẢ, người ta nên dùng trường mã độc giả làm khoá chính thay vì dùng trường họ tên?","options":["Vì trường họ tên chiếm nhiều bộ nhớ hơn nên làm chương trình chạy chậm hẳn đi.","Vì các hệ quản trị cơ sở dữ liệu không cho phép khoá chính có kiểu dữ liệu văn bản.","Vì họ tên của học sinh sẽ thay đổi theo từng năm học nên không dùng lâu dài được.","Vì hai độc giả có thể trùng họ tên, lại hay bị viết tắt hoặc gõ sai dấu, nên họ tên không phân biệt chắc chắn được từng người."],"answer":3,"explain":"Đáp án đúng là D. Khoá chính đòi hỏi giá trị duy nhất và ổn định; họ tên vi phạm cả hai vì cả trường có thể có nhiều bạn trùng tên, và cùng một người lại có thể được ghi thành nhiều dạng khác nhau (viết tắt, thiếu dấu). A sai vì tiết kiệm bộ nhớ chỉ là lợi ích phụ, lí do cốt lõi là tính duy nhất chứ không phải tốc độ. B sai vì khoá chính hoàn toàn có thể là kiểu văn bản — chính mã độc giả dạng DG007 cũng là văn bản. C sai vì họ tên của một người về nguyên tắc không đổi theo năm học; cái thay đổi là lớp, và đó là lí do lớp không bao giờ được chọn làm khoá."},{"id":"CB-mc-2604","type":"mc","topic":"C","grade":11,"level":"medium","question":"Trong bảng LƯỢT MƯỢN của thư viện, trường nào sau đây hợp lí khi được phép tạm để trống, và vì lí do gì?","options":["Trường mã sách, vì có thể bổ sung sau khi độc giả chọn xong cuốn cần mượn.","Trường ngày trả thực tế, vì lượt mượn đang diễn ra thì chưa thể có ngày trả.","Trường mã độc giả, vì đôi khi có bạn mượn hộ cho người khác.","Trường ngày mượn, vì cộng tác viên có thể ghi bổ sung vào cuối tuần."],"answer":1,"explain":"Đáp án đúng là B. Ngày trả thực tế chỉ có giá trị khi sách đã được mang trả; trong lúc sách còn trong tay độc giả thì ô này để trống, và chính cái trống đó mang ý nghĩa ‘chưa trả’, giúp lọc ra các lượt quá hạn. A sai vì mã sách là khoá ngoại bắt buộc — một lượt mượn không rõ mượn cuốn nào thì không thể ghi nhận. C sai vì mã độc giả cũng là khoá ngoại bắt buộc; nếu có người mượn hộ thì vẫn phải ghi mã của người chịu trách nhiệm trả sách. D sai vì thiếu ngày mượn thì không tính được hạn trả và không phát hiện được quá hạn, nên trường này bắt buộc phải có ngay khi tạo dòng."},{"id":"CB-mc-2605","type":"mc","topic":"C","grade":11,"level":"hard","question":"Với thiết kế ba bảng ĐỘC GIẢ, SÁCH, LƯỢT MƯỢN, thủ thư muốn thống kê mỗi lớp trong trường đã mượn tổng cộng bao nhiêu lượt sách trong học kì. Cần khai thác dữ liệu như thế nào?","options":["Đếm số dòng của bảng ĐỘC GIẢ theo từng lớp là ra ngay kết quả cần tìm.","Đếm số dòng của bảng LƯỢT MƯỢN theo từng lớp, vì mỗi dòng đã có sẵn tên lớp.","Ghép bảng LƯỢT MƯỢN với bảng ĐỘC GIẢ qua mã độc giả để biết mỗi lượt mượn thuộc lớp nào, rồi đếm số lượt theo từng lớp.","Bắt buộc phải bổ sung thêm cột tên lớp vào bảng LƯỢT MƯỢN thì mới trả lời được câu hỏi này."],"answer":2,"explain":"Đáp án đúng là C. Bảng LƯỢT MƯỢN chỉ có mã độc giả, còn lớp nằm ở bảng ĐỘC GIẢ; đi theo khoá ngoại mã độc giả để ghép hai bảng là ta biết mỗi lượt mượn thuộc lớp nào, sau đó đếm theo lớp. A sai vì đếm bảng ĐỘC GIẢ chỉ cho biết mỗi lớp có bao nhiêu bạn đăng kí thẻ, không phải số lượt mượn. B sai vì bảng LƯỢT MƯỢN cố tình không chứa cột lớp — đó là điểm mấu chốt của việc tách bảng. D sai vì thêm cột lớp vào LƯỢT MƯỢN là chép lại dữ liệu đã có ở bảng khác, làm sống lại đúng lỗi dư thừa và mâu thuẫn khi có bạn chuyển lớp."},{"id":"CB-tf-2601","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Nguyên tắc khi tách bảng là mỗi thông tin chỉ được lưu ở đúng một nơi, các bảng khác cần dùng thì tham chiếu tới bằng khoá chứ không chép lại.","correct":true},{"text":"Bảng LƯỢT MƯỢN đã có mã sách rồi, nhưng vẫn nên chép thêm nhan đề và tác giả vào bảng này để tra cứu cho nhanh.","correct":false},{"text":"Các trường ngày mượn và hạn trả nên đặt kiểu ngày tháng thay vì kiểu văn bản, để máy tính so sánh được ngày và tính được số ngày quá hạn.","correct":true},{"text":"Khi một độc giả chuyển lớp, với thiết kế ba bảng ta vẫn phải sửa lại lớp ở tất cả các dòng của bảng LƯỢT MƯỢN mà bạn đó xuất hiện.","correct":false}],"explain":"(1) Đúng — đây chính là nguyên tắc cốt lõi của việc tách bảng, giúp loại bỏ dư thừa và ngăn dữ liệu mâu thuẫn. (2) Sai — chép thêm nhan đề và tác giả là quay lại đúng lỗi của bảng gộp: mỗi lần đính chính tên tác giả lại phải sửa ở rất nhiều dòng, sót một dòng là dữ liệu vênh nhau; đã có mã sách thì lấy chi tiết từ bảng SÁCH là đủ. (3) Đúng — nếu lưu ngày dưới dạng xâu kí tự tuỳ ý thì máy không so sánh và không trừ hai ngày cho nhau được, nên không lọc ra được các lượt quá hạn. (4) Sai — bảng LƯỢT MƯỢN không hề chứa cột lớp; lớp chỉ nằm ở một ô duy nhất trong bảng ĐỘC GIẢ nên chỉ cần sửa đúng một chỗ là toàn hệ thống được cập nhật."},{"id":"CB-mc-2701","type":"mc","topic":"C","grade":11,"level":"easy","question":"Trong SQL, muốn tạo một bảng mới cùng danh sách các cột và kiểu dữ liệu của từng cột, ta dùng lệnh nào?","options":["INSERT INTO ... VALUES ...","SELECT ... FROM ...","CREATE TABLE ... ( ... )","UPDATE ... SET ..."],"answer":2,"explain":"Chỉ có CREATE TABLE làm nhiệm vụ dựng khung bảng: đặt tên bảng rồi khai báo từng cột kèm kiểu dữ liệu. INSERT INTO chỉ thêm một dòng dữ liệu vào bảng đã có sẵn; SELECT ... FROM chỉ truy vấn để xem dữ liệu chứ không tạo ra bảng; UPDATE ... SET chỉ sửa giá trị của các dòng đang có. Cả ba lệnh này đều đòi hỏi bảng phải tồn tại từ trước."},{"id":"CB-mc-2702","type":"mc","topic":"C","grade":11,"level":"easy","question":"Khai báo ràng buộc NOT NULL cho cột HoTen khi tạo bảng có tác dụng gì?","options":["Mọi dòng thêm vào đều bắt buộc phải có giá trị ở cột HoTen, không được để trống","Các giá trị trong cột HoTen không được trùng nhau giữa các dòng","Giá trị của cột HoTen phải tồn tại sẵn ở một bảng khác được tham chiếu","Hệ quản trị sẽ tự động điền họ tên nếu người dùng bỏ trống ô này"],"answer":0,"explain":"NOT NULL nghĩa là 'không được rỗng': hệ quản trị sẽ từ chối bất kì dòng nào bỏ trống cột đó. Ràng buộc chống trùng lặp là UNIQUE (hoặc PRIMARY KEY) chứ không phải NOT NULL. Ràng buộc buộc giá trị phải có sẵn ở bảng khác là FOREIGN KEY. Và không có ràng buộc nào tự nghĩ ra họ tên để điền hộ — hệ quản trị chỉ biết từ chối dữ liệu sai chứ không bịa dữ liệu."},{"id":"CB-mc-2703","type":"mc","topic":"C","grade":11,"level":"medium","question":"Hai lệnh DROP TABLE LuotMuon; và DELETE FROM LuotMuon; khác nhau ở điểm căn bản nào?","options":["Cả hai đều xoá toàn bộ dữ liệu và giữ lại bảng, chỉ khác nhau về tốc độ thực hiện","DROP TABLE chỉ xoá những dòng thoả điều kiện, còn DELETE xoá mọi dòng của bảng","DROP TABLE xoá dữ liệu nhưng giữ lại cấu trúc bảng, còn DELETE xoá luôn cả cấu trúc","DROP TABLE xoá cả cấu trúc bảng lẫn dữ liệu bên trong, còn DELETE chỉ xoá các dòng dữ liệu và bảng rỗng vẫn còn tồn tại"],"answer":3,"explain":"DROP TABLE huỷ hẳn bảng khỏi cơ sở dữ liệu: sau lệnh đó không còn tên bảng LuotMuon nữa, muốn dùng lại phải CREATE TABLE từ đầu. DELETE chỉ xoá nội dung các dòng, khung bảng và các cột vẫn nguyên vẹn nên hôm sau vẫn INSERT dữ liệu mới vào được. Phương án đầu sai vì DROP không giữ lại bảng. Phương án thứ hai đảo ngược vai trò và còn nhầm ở chỗ DELETE có thể kèm WHERE để chỉ xoá một số dòng. Phương án thứ ba mô tả đúng nhưng gán nhầm cho hai lệnh."},{"id":"CB-mc-2704","type":"mc","topic":"C","grade":11,"level":"medium","question":"Trong một câu truy vấn có GROUP BY, mệnh đề HAVING giữ vai trò gì?","options":["Lọc từng dòng dữ liệu ngay trước khi các dòng được gộp thành nhóm","Lọc giữ lại những nhóm thoả điều kiện, sau khi đã gộp nhóm và tính xong hàm tổng hợp","Sắp xếp các nhóm kết quả theo thứ tự tăng dần hoặc giảm dần","Chỉ định cột nào sẽ được dùng làm căn cứ để gộp nhóm"],"answer":1,"explain":"HAVING làm việc ở giai đoạn sau cùng: các dòng đã được gộp thành nhóm, hàm tổng hợp đã tính xong cho từng nhóm, khi đó HAVING mới chọn giữ lại những nhóm đạt điều kiện. Việc lọc từng dòng trước khi gộp là nhiệm vụ của WHERE — đây chính là chỗ dễ nhầm nhất. Việc sắp xếp kết quả thuộc về ORDER BY. Còn cột dùng làm căn cứ gộp nhóm đã được nêu ngay sau chính từ khoá GROUP BY rồi."},{"id":"CB-mc-2705","type":"mc","topic":"C","grade":11,"level":"hard","question":"Bảng LuotMuon có 7 dòng, mỗi dòng ứng với một cặp (MaDG, SoNgayMuon) như sau: (DG01, 7), (DG01, 5), (DG02, 10), (DG03, 6), (DG01, 3), (DG02, 14), (DG03, 4). Truy vấn SELECT MaDG, COUNT(*) FROM LuotMuon WHERE SoNgayMuon >= 5 GROUP BY MaDG HAVING COUNT(*) >= 2; cho kết quả nào?","options":["Ba dòng: DG01 với 3, DG02 với 2, DG03 với 2","Một dòng duy nhất: DG01 với 3","Hai dòng: DG01 với 2 và DG02 với 2","Hai dòng: DG01 với 3 và DG02 với 2"],"answer":2,"explain":"Phải thực hiện đúng thứ tự. Bước 1, WHERE SoNgayMuon >= 5 loại bỏ trước hai dòng (DG01, 3) và (DG03, 4), chỉ còn 5 dòng. Bước 2, GROUP BY MaDG gộp 5 dòng còn lại thành DG01 có 2, DG02 có 2, DG03 có 1. Bước 3, HAVING COUNT(*) >= 2 loại nhóm DG03, giữ lại DG01 với 2 và DG02 với 2. Phương án đầu là kết quả khi bỏ quên cả WHERE lẫn HAVING. Phương án thứ hai là kết quả nếu bỏ qua WHERE và dùng HAVING COUNT(*) >= 3. Phương án cuối sai vì DG01 chỉ còn 2 lượt sau khi WHERE đã loại dòng có SoNgayMuon bằng 3."},{"id":"CB-tf-2701","type":"tf","topic":"C","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Ràng buộc FOREIGN KEY buộc giá trị điền vào cột khoá ngoại phải là một giá trị đã tồn tại ở cột khoá chính của bảng được tham chiếu.","correct":true},{"text":"Hàm AVG(SoNgayMuon) trả về số lượng dòng đang có trong cột SoNgayMuon.","correct":false},{"text":"Mệnh đề GROUP BY Lop gộp các dòng có cùng giá trị ở cột Lop thành một nhóm, để hàm tổng hợp được tính riêng cho từng lớp.","correct":true},{"text":"Trong một truy vấn, WHERE và HAVING có thể thay thế cho nhau vì cả hai đều làm nhiệm vụ lọc dữ liệu.","correct":false}],"explain":"(1) Đúng — đó chính là tác dụng của khoá ngoại: không thể ghi một lượt mượn cho mã độc giả chưa hề có trong bảng DocGia. (2) Sai — AVG tính trung bình cộng các giá trị của cột; hàm đếm số dòng là COUNT. (3) Đúng — GROUP BY gom các dòng cùng giá trị thành nhóm rồi COUNT, SUM, AVG... được tính riêng rẽ trên từng nhóm. (4) Sai — hai mệnh đề làm việc ở hai thời điểm khác nhau: WHERE lọc từng dòng trước khi gộp nhóm, HAVING lọc từng nhóm sau khi đã gộp; điều kiện chứa hàm tổng hợp bắt buộc phải đặt ở HAVING."},{"id":"CB-mc-2801","type":"mc","topic":"F","grade":11,"level":"easy","question":"Với mảng hai chiều `a` trong Python, biểu thức `a[i][j]` được hiểu như thế nào?","options":["`i` là chỉ số cột, `j` là chỉ số hàng, cả hai bắt đầu từ 1","`i` là chỉ số cột, `j` là chỉ số hàng, cả hai bắt đầu từ 0","`i` là chỉ số hàng, `j` là chỉ số cột, cả hai bắt đầu từ 0","`i` là chỉ số hàng, `j` là chỉ số cột, cả hai bắt đầu từ 1"],"answer":2,"explain":"Đáp án đúng là ‘`i` là chỉ số hàng, `j` là chỉ số cột, cả hai bắt đầu từ 0’. Lí do nằm ngay ở cách đọc biểu thức từ trái sang phải: `a[i]` lấy ra cả hàng thứ `i` (vì mảng hai chiều là danh sách của các hàng), rồi `[j]` mới lấy phần tử thứ `j` bên trong hàng đó, tức là cột. Hai phương án đầu sai vì đảo ngược vai trò hàng - cột. Phương án cuối tuy nhớ đúng thứ tự hàng trước cột sau nhưng lại cho chỉ số bắt đầu từ 1, trong khi mọi chỉ số của danh sách trong Python đều đếm từ 0."},{"id":"CB-mc-2802","type":"mc","topic":"F","grade":11,"level":"easy","question":"Cho mảng hai chiều `a` có các hàng dài bằng nhau. Biểu thức nào cho biết SỐ CỘT của bảng?","options":["`len(a[0])`","`len(a)`","`len(a) * len(a[0])`","`a[0]`"],"answer":0,"explain":"Đáp án đúng là `len(a[0])`: `a[0]` chính là hàng đầu tiên của bảng, mà số phần tử của một hàng chính là số cột. Phương án `len(a)` sai vì đó là số phần tử của danh sách lớn, tức số HÀNG chứ không phải số cột. Phương án `len(a) * len(a[0])` cho tổng số ô của cả bảng chứ không phải số cột. Phương án `a[0]` sai vì nó trả về bản thân danh sách hàng đầu tiên (một danh sách), không phải một con số."},{"id":"CB-mc-2803","type":"mc","topic":"F","grade":11,"level":"medium","question":"Cho `b = [[3, 1, 4], [1, 5, 9], [2, 6, 5]]`. Giá trị của `b[2][1]` là bao nhiêu?","options":["9","1","2","6"],"answer":3,"explain":"Đáp án đúng là 6. Ta đọc lần lượt: `b[2]` là hàng có chỉ số 2, tức hàng thứ ba `[2, 6, 5]`; sau đó `[1]` lấy phần tử có chỉ số 1 của hàng ấy, tức số thứ hai, chính là 6. Phương án 9 là kết quả của việc nhầm hàng với cột, vì `b[1][2]` mới bằng 9. Phương án 1 là kết quả của việc đếm chỉ số từ 1 thay vì từ 0 (hàng 2, cột 1 theo cách đếm từ 1 sẽ là `b[1][0]`). Phương án 2 là `b[2][0]`, tức lấy nhầm phần tử đầu tiên của hàng."},{"id":"CB-mc-2804","type":"mc","topic":"F","grade":11,"level":"medium","question":"Muốn tính tổng của TỪNG CỘT trong bảng `a` gồm `n` hàng và `m` cột, cách tổ chức vòng lặp nào là đúng?","options":["Vòng ngoài chạy theo `i` (hàng), vòng trong chạy theo `j` (cột), biến tổng được đặt lại bằng 0 ở đầu mỗi lần lặp của vòng ngoài","Vòng ngoài chạy theo `j` (cột), vòng trong chạy theo `i` (hàng), biến tổng được đặt lại bằng 0 ở đầu mỗi lần lặp của vòng ngoài","Chỉ cần một vòng lặp duy nhất chạy theo cột, vì mỗi cột chỉ có một giá trị","Vòng ngoài chạy theo `j` (cột), vòng trong chạy theo `i` (hàng), nhưng biến tổng chỉ được đặt bằng 0 một lần duy nhất trước cả hai vòng lặp"],"answer":1,"explain":"Đáp án đúng là phương án thứ hai: vì mỗi lần lặp của vòng ngoài phải cho ra kết quả của MỘT cột, nên vòng ngoài phải chạy theo `j`, còn vòng trong chạy theo `i` để cộng dồn các ô của cột đó qua mọi hàng; biến tổng phải được đặt lại bằng 0 ở đầu mỗi cột. Phương án đầu tiên chính là khuôn mẫu tính tổng theo HÀNG chứ không phải theo cột. Phương án ba sai vì một cột có `n` giá trị nằm ở `n` hàng khác nhau nên bắt buộc phải duyệt qua các hàng. Phương án bốn tuy đặt đúng thứ tự vòng lặp nhưng do chỉ gán `tong = 0` một lần trước cả hai vòng nên cuối cùng chỉ thu được tổng cộng dồn của toàn bộ bảng, không tách được từng cột."},{"id":"CB-mc-2805","type":"mc","topic":"F","grade":11,"level":"hard","question":"Cho đoạn chương trình sau. Kết quả in ra màn hình là bao nhiêu?\n`t = [[2, 5, 7], [4, 5, 6], [9, 1, 3]]`\n`d = 0`\n`for i in range(3):`\n`    for j in range(3):`\n`        if t[i][j] > i + j:`\n`            d += 1`\n`print(d)`","options":["5","6","7","8"],"answer":2,"explain":"Đáp án đúng là 7. Ta xét lần lượt từng ô và so sánh giá trị của ô với tổng hai chỉ số `i + j`: hàng 0 có 2 > 0, 5 > 1, 7 > 2 nên cả ba ô đều thoả; hàng 1 có 4 > 1, 5 > 2, 6 > 3 nên cũng cả ba ô đều thoả; hàng 2 có 9 > 2 thoả, còn 1 > 3 sai và 3 > 4 cũng sai. Tổng cộng là 3 + 3 + 1 = 7. Đáp án 6 là kết quả nếu bỏ sót ô `t[2][0]` ở góc dưới bên trái. Đáp án 8 là kết quả nếu tính nhầm 3 > 4 thành thoả. Đáp án 5 xuất hiện khi cho vòng trong chạy `range(2)`, tức bỏ sót toàn bộ cột cuối cùng của bảng."},{"id":"CB-tf-2801","type":"tf","topic":"F","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong Python, mảng hai chiều thực chất là một danh sách mà mỗi phần tử của nó lại là một danh sách.","correct":true},{"text":"Với mảng hai chiều `a`, số hàng của bảng được tính bằng `len(a)`.","correct":true},{"text":"Với mọi mảng hai chiều `a`, hai biểu thức `a[i][j]` và `a[j][i]` luôn cho cùng một giá trị vì cùng chỉ tới ô ở hàng `i` cột `j`.","correct":false},{"text":"Python bắt buộc mọi hàng của một mảng hai chiều phải có số phần tử bằng nhau, nên không bao giờ xảy ra lỗi `IndexError` khi duyệt bảng bằng `range(len(a[0]))`.","correct":false}],"explain":"(1) Đúng — đây chính là cách Python biểu diễn bảng: mỗi hàng của bảng là một danh sách, và tất cả các hàng đó được xếp vào một danh sách lớn. (2) Đúng — `len(a)` đếm số phần tử của danh sách lớn, mà mỗi phần tử là một hàng, nên kết quả chính là số hàng; số cột mới là `len(a[0])`. (3) Sai — `a[i][j]` là ô ở hàng `i` cột `j`, còn `a[j][i]` là ô ở hàng `j` cột `i`, hai ô hoàn toàn khác nhau; chúng chỉ tình cờ bằng nhau trong một số bảng đặc biệt hoặc khi `i` bằng `j`. (4) Sai — Python cho phép các hàng dài ngắn khác nhau; nếu lấy số cột theo hàng đầu tiên bằng `len(a[0])` rồi áp dụng cho một hàng ngắn hơn thì chương trình sẽ báo lỗi `IndexError`, nên với bảng không đều phải dùng `range(len(a[i]))`."},{"id":"CB-mc-2901","type":"mc","topic":"F","grade":11,"level":"easy","question":"Trong thuật toán sắp xếp chọn (sắp xếp tăng dần), ở mỗi lượt thuật toán thực hiện công việc gì?","options":["So sánh và đổi chỗ hai phần tử đứng liền kề nhau mỗi khi chúng sai thứ tự.","Chia dãy thành hai nửa, sắp xếp riêng từng nửa rồi trộn hai nửa lại với nhau.","Lấy phần tử đầu tiên làm mốc rồi tách dãy thành nhóm nhỏ hơn mốc và nhóm lớn hơn mốc.","Tìm phần tử nhỏ nhất trong đoạn chưa sắp xếp rồi đổi chỗ nó về đầu đoạn chưa sắp xếp."],"answer":3,"explain":"Đáp án đúng là phương án cuối: bản chất của sắp xếp chọn là mỗi lượt \"chọn\" ra phần tử nhỏ nhất còn lại rồi đưa nó về đầu đoạn chưa sắp xếp, nhờ đó sau lượt thứ k thì k phần tử đầu đã đúng chỗ vĩnh viễn. Phương án đầu mô tả sắp xếp nổi bọt (đổi chỗ hai phần tử liền kề), không phải sắp xếp chọn. Phương án thứ hai mô tả ý tưởng chia đôi rồi trộn, còn phương án thứ ba mô tả ý tưởng chọn mốc để phân hoạch — cả hai đều là các thuật toán sắp xếp khác, không phải sắp xếp chọn."},{"id":"CB-mc-2902","type":"mc","topic":"F","grade":11,"level":"easy","question":"Cho `a = [5, 2, 8]`. Sau khi thực hiện lệnh `b = sorted(a)`, giá trị của `a` và `b` lần lượt là gì?","options":["a = [5, 2, 8] và b = [2, 5, 8]","a = [2, 5, 8] và b = [2, 5, 8]","a = [2, 5, 8] và b = None","a = [5, 2, 8] và b = None"],"answer":0,"explain":"Hàm `sorted(a)` không đụng đến danh sách gốc mà tạo ra và trả về một danh sách MỚI đã sắp xếp, nên `a` vẫn là [5, 2, 8] còn `b` là [2, 5, 8]. Phương án thứ hai sai vì nhầm `sorted()` với `a.sort()` — chỉ `a.sort()` mới sửa trực tiếp danh sách gốc. Hai phương án còn lại sai vì cho rằng `sorted()` trả về `None`; thực ra `None` là giá trị trả về của `a.sort()`, chứ không phải của `sorted(a)`."},{"id":"CB-mc-2903","type":"mc","topic":"F","grade":11,"level":"medium","question":"Áp dụng thuật toán sắp xếp chọn (tăng dần) cho dãy 9, 4, 7, 2, 6. Dãy sẽ có dạng như thế nào ngay sau khi kết thúc lượt thứ nhất?","options":["4, 9, 7, 2, 6","2, 4, 7, 9, 6","2, 9, 4, 7, 6","2, 4, 6, 7, 9"],"answer":1,"explain":"Lượt thứ nhất quét cả dãy và tìm được phần tử nhỏ nhất là 2 (ở vị trí chỉ số 3), sau đó ĐỔI CHỖ nó với phần tử đang đứng đầu là 9. Hai phần tử 2 và 9 hoán đổi vị trí cho nhau, các phần tử khác giữ nguyên, nên dãy thành 2, 4, 7, 9, 6. Phương án đầu là kết quả của một lần đổi chỗ hai phần tử liền kề trong sắp xếp nổi bọt. Phương án thứ ba sai vì đã DỊCH các phần tử sang phải để nhường chỗ cho số 2 thay vì đổi chỗ. Phương án cuối là kết quả cuối cùng của cả quá trình, không phải sau đúng một lượt."},{"id":"CB-mc-2904","type":"mc","topic":"F","grade":11,"level":"medium","question":"Vì sao sắp xếp chèn thường chạy rất nhanh khi dãy đầu vào đã gần như được sắp xếp sẵn?","options":["Vì trong trường hợp đó thuật toán tự động chuyển sang dùng tìm kiếm nhị phân để định vị chỗ chèn.","Vì khi đó độ phức tạp của nó giảm xuống còn O(log n) trong mọi trường hợp.","Vì hầu hết phần tử mới đã lớn hơn phần tử đứng ngay trước nó, nên vòng lặp lùi dừng gần như ngay lập tức và rất ít phần tử phải dịch sang phải.","Vì thuật toán nhận ra đoạn đầu đã có thứ tự nên bỏ qua hoàn toàn, không cần thực hiện phép so sánh nào."],"answer":2,"explain":"Điều kiện của vòng lặp lùi là `a[j] > x`; nếu dãy gần như đã sắp sẵn thì phần tử liền trước thường đã nhỏ hơn hoặc bằng `x`, vòng lặp thoát ngay sau một phép so sánh và hầu như không có phần tử nào phải dịch chuyển — đó chính là lí do thuật toán chạy rất nhanh. Phương án đầu sai vì thuật toán không hề tự đổi chiến lược, nó chỉ có một cách làm duy nhất. Phương án thứ hai sai vì độ phức tạp của sắp xếp chèn trong trường hợp xấu nhất vẫn là O(n²), không có chuyện thành O(log n). Phương án cuối sai vì thuật toán vẫn phải so sánh ít nhất một lần với mỗi phần tử mới thì mới biết được là không cần dịch chuyển."},{"id":"CB-mc-2905","type":"mc","topic":"F","grade":11,"level":"hard","question":"Sắp xếp tăng dần dãy 6, 2, 9, 4 bằng thuật toán sắp xếp chèn. Sau khi chèn xong phần tử thứ ba của dãy (giá trị 9), dãy có dạng thế nào và đã có bao nhiêu phần tử phải dịch sang phải trong riêng lượt đó?","options":["Dãy là 2, 6, 9, 4 và trong lượt đó không có phần tử nào phải dịch sang phải.","Dãy là 2, 6, 9, 4 và trong lượt đó có hai phần tử phải dịch sang phải.","Dãy là 2, 4, 6, 9 và trong lượt đó có ba phần tử phải dịch sang phải.","Dãy là 2, 6, 4, 9 và trong lượt đó có một phần tử phải dịch sang phải."],"answer":0,"explain":"Sau lượt chèn số 2, dãy đã là 2, 6, 9, 4. Đến lượt chèn số 9, ta lấy x = 9 và so với phần tử liền trước là 6; vì 6 không lớn hơn 9 nên điều kiện `a[j] > x` sai ngay lập tức, vòng lặp lùi không chạy lần nào, không phần tử nào phải dịch và số 9 nằm nguyên tại chỗ cũ — dãy vẫn là 2, 6, 9, 4. Phương án thứ hai có dãy đúng nhưng đếm sai số phép dịch, vì nó nhầm rằng lượt nào cũng phải dịch chuyển. Phương án thứ ba là kết quả cuối cùng của cả quá trình, chưa xảy ra ở lượt thứ ba. Phương án cuối cho dãy 2, 6, 4, 9 là sai vì thuật toán không hề chuyển số 4 lên trước khi tới lượt của nó."},{"id":"CB-tf-2901","type":"tf","topic":"F","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong sắp xếp chọn, sau khi kết thúc lượt thứ k thì k phần tử đầu dãy đã nằm đúng vị trí cuối cùng của chúng và không cần xét lại nữa.","correct":true},{"text":"Sắp xếp chèn có độ phức tạp O(n log n) nên nhanh hơn hẳn sắp xếp chọn và sắp xếp nổi bọt trong mọi trường hợp.","correct":false},{"text":"Lệnh `a.sort()` sắp xếp ngay trên danh sách `a` và trả về giá trị `None`, vì vậy viết `a = a.sort()` sẽ làm mất dữ liệu của `a`.","correct":true},{"text":"Muốn sắp xếp một danh sách theo thứ tự giảm dần trong Python, bắt buộc phải tự viết lại thuật toán vì `sort()` chỉ sắp được tăng dần.","correct":false}],"explain":"(1) Đúng — đây chính là đặc điểm cốt lõi của sắp xếp chọn: mỗi lượt đưa được đúng một phần tử về vị trí vĩnh viễn, nên đoạn cần xét ở lượt sau ngắn hơn lượt trước một phần tử. (2) Sai — sắp xếp chèn vẫn là thuật toán O(n²) như hai thuật toán đơn giản kia; nó chỉ nhanh vượt trội trong trường hợp riêng là dãy đã gần được sắp sẵn, chứ không phải trong mọi trường hợp. (3) Đúng — `sort()` là phương thức sắp xếp tại chỗ và trả về `None`, nên phép gán `a = a.sort()` sẽ ghi đè `None` lên danh sách vừa sắp xếp; muốn giữ dãy gốc phải dùng `b = sorted(a)`. (4) Sai — chỉ cần thêm tham số `reverse=True`, chẳng hạn `a.sort(reverse=True)` hoặc `sorted(a, reverse=True)`, là có ngay thứ tự giảm dần mà không phải viết thêm dòng thuật toán nào."},{"id":"CB-mc-3001","type":"mc","topic":"F","grade":11,"level":"easy","question":"Điểm khác nhau cơ bản giữa việc chia chương trình thành các hàm và chia chương trình thành các mô đun là gì?","options":["Chia thành hàm là chia công việc bên trong một tệp, còn chia thành mô đun là tách mã nguồn ra nhiều tệp .py khác nhau.","Chia thành hàm chỉ dùng cho chương trình ngắn, còn chia thành mô đun chỉ dùng cho chương trình dài trên 1000 dòng.","Chia thành hàm làm chương trình chạy nhanh hơn, còn chia thành mô đun làm chương trình chạy chậm đi.","Chia thành hàm phải dùng câu lệnh import, còn chia thành mô đun thì không cần dùng import."],"answer":0,"explain":"Đáp án đúng là A: cả hai đều là cách chia nhỏ công việc, nhưng chia hàm diễn ra bên trong một tệp duy nhất, còn chia mô đun là tách hẳn ra thành nhiều tệp .py riêng, mỗi tệp lo một mảng công việc. B sai vì độ dài chương trình không phải tiêu chí phân biệt hai khái niệm; một chương trình ngắn vẫn có thể được tách mô đun và một chương trình dài vẫn có thể chỉ gồm các hàm trong một tệp. C sai vì việc chia hàm hay chia mô đun là chuyện tổ chức mã nguồn cho con người dễ đọc, dễ bảo trì, chứ không phải kĩ thuật tăng giảm tốc độ chạy. D nói ngược: chính khi tách ra thành các mô đun ở những tệp khác nhau ta mới cần import để dùng lại hàm, còn các hàm nằm chung một tệp thì gọi thẳng."},{"id":"CB-mc-3002","type":"mc","topic":"F","grade":11,"level":"easy","question":"Phát biểu nào sau đây mô tả đúng một mô đun được chia tốt?","options":["Mô đun càng gom nhiều loại công việc khác nhau càng tiện, vì chỉ cần mở đúng một tệp là làm được mọi việc.","Mô đun chỉ đảm nhận một nhiệm vụ rõ ràng và ít phụ thuộc vào các mô đun khác.","Mô đun tốt là mô đun có nhiều dòng lệnh nhất trong chương trình, vì nó làm được nhiều việc nhất.","Mô đun tốt phải gọi được tới tất cả các mô đun còn lại của chương trình để không bỏ sót chức năng nào."],"answer":1,"explain":"Đáp án đúng là B, đúng hai trong ba nguyên tắc chia mô đun: một nhiệm vụ rõ ràng và ít phụ thuộc lẫn nhau. A sai vì gom nhiều loại việc vào một tệp chính là dấu hiệu chia mô đun kém — mô đun đó phình to, ai động vào việc gì cũng phải mở nó ra và dễ gây xung đột khi nhiều người cùng sửa. C sai vì số dòng lệnh không nói lên chất lượng; một mô đun quá dài thường là mô đun đang ôm quá nhiều nhiệm vụ. D sai hoàn toàn: mô đun gọi càng nhiều mô đun khác thì càng phụ thuộc chằng chịt, sửa một chỗ hỏng nhiều chỗ — đúng điều ta cần tránh."},{"id":"CB-mc-3003","type":"mc","topic":"F","grade":11,"level":"medium","question":"Nói “giao diện sử dụng của một mô đun phải gọn” nghĩa là gì?","options":["Mô đun phải có cửa sổ đồ hoạ với nút bấm đẹp mắt để người dùng dễ thao tác.","Mô đun phải được viết trong không quá 50 dòng lệnh để người khác đọc hết nhanh.","Người dùng mô đun chỉ cần biết tên hàm, tham số cần đưa vào và kết quả trả về là dùng được, không phải đọc mã bên trong.","Mô đun chỉ được phép chứa đúng một hàm duy nhất để khỏi gây nhầm lẫn khi gọi."],"answer":2,"explain":"Đáp án đúng là C. Trong ngữ cảnh này, “giao diện” của mô đun là phần thông tin tối thiểu cần biết để gọi được nó: tên hàm, tham số truyền vào và kết quả nhận về. Giao diện gọn nghĩa là ba thông tin đó đã đủ dùng. A sai vì đang hiểu “giao diện” theo nghĩa giao diện đồ hoạ cho người dùng cuối, khác hẳn nghĩa ở đây. B sai vì số dòng lệnh bên trong không liên quan — chính điều ta mong muốn là người dùng không cần đọc mã bên trong, dù nó dài hay ngắn. D sai vì một mô đun hoàn toàn có thể chứa nhiều hàm, miễn là các hàm đó cùng phục vụ một mảng công việc."},{"id":"CB-mc-3004","type":"mc","topic":"F","grade":11,"level":"medium","question":"Một chương trình quản lí điểm được tách thành ba mô đun: đọc dữ liệu, tính toán – thống kê và hiển thị kết quả. Khi đó tệp chương trình chính nên làm gì?","options":["Chứa toàn bộ phần tính toán thống kê, còn ba mô đun kia chỉ để cho chương trình trông có vẻ gọn gàng.","Lưu tất cả dữ liệu điểm dưới dạng biến toàn cục để cả ba mô đun cùng đọc và cùng sửa trực tiếp.","Kiểm tra lại từng dòng lệnh bên trong ba mô đun trước khi cho phép chúng chạy.","Gọi lần lượt các mô đun theo đúng trình tự công việc: lấy dữ liệu, đưa cho mô đun thống kê tính, rồi đưa kết quả cho mô đun hiển thị in ra."],"answer":3,"explain":"Đáp án đúng là D: khi đã tách mô đun tốt, chương trình chính thường rất ngắn và gần như không tự làm gì, nó chỉ điều phối — gọi các mô đun theo đúng thứ tự công việc, giống bảng phân công các tổ. A sai vì nếu phần tính toán vẫn nằm trong tệp chính thì mô đun thống kê chẳng còn nhiệm vụ gì, việc tách mô đun trở nên hình thức. B sai vì để mọi mô đun cùng sửa chung một khối dữ liệu toàn cục sẽ khiến chúng phụ thuộc chặt vào nhau, sửa một chỗ hỏng nhiều chỗ — trái với nguyên tắc ít phụ thuộc. C sai vì đọc soát mã bên trong mô đun là việc của người viết khi kiểm thử, không phải nhiệm vụ mà chương trình chính thực hiện lúc chạy; đúng tinh thần mô đun thì tệp chính còn không cần biết bên trong mô đun viết thế nào."},{"id":"CB-mc-3005","type":"mc","topic":"F","grade":11,"level":"hard","question":"Nhóm ba bạn viết chương trình xếp loại thi đua theo mô đun. Bạn phụ trách mô đun thống kê thấy cách đếm cũ chạy chậm nên viết lại hoàn toàn phần bên trong, nhưng vẫn giữ nguyên tên hàm `dem_dat`, vẫn nhận vào một danh sách điểm và vẫn trả về một số nguyên. Điều gì sẽ xảy ra với phần còn lại của chương trình?","options":["Phải sửa lại cả chương trình chính lẫn mô đun hiển thị cho khớp với cách viết mới.","Chương trình chính sẽ báo lỗi ngay khi chạy, vì phần mã bên trong mô đun đã khác trước.","Các mô đun còn lại vẫn chạy bình thường, vì giao diện của mô đun thống kê không hề thay đổi.","Phải gộp cả ba mô đun trở lại thành một tệp duy nhất thì chương trình mới chạy được."],"answer":2,"explain":"Đáp án đúng là C. Các mô đun khác chỉ phụ thuộc vào giao diện của mô đun thống kê, tức tên hàm, tham số truyền vào và kiểu kết quả trả về; cả ba thứ đó đều được giữ nguyên nên chúng gọi hàm y như cũ và nhận kết quả y như cũ. Đây chính là lợi ích “sửa an toàn” của cách tổ chức theo mô đun. A và B đều sai vì cùng hiểu nhầm rằng phần còn lại của chương trình phụ thuộc vào cách cài đặt bên trong mô đun — nếu quả thật như vậy thì việc chia mô đun đã thất bại ngay từ đầu. D sai vì gộp lại một tệp không những không cần thiết mà còn xoá bỏ toàn bộ lợi ích vừa nêu, đưa chương trình về đúng tình trạng khó bảo trì mà ta muốn tránh."},{"id":"CB-tf-3001","type":"tf","topic":"F","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Chia chương trình thành các mô đun nghĩa là tách mã nguồn ra nhiều tệp .py khác nhau, mỗi tệp phụ trách một mảng công việc.","correct":true},{"text":"Hai mô đun càng gọi chéo lẫn nhau nhiều thì chương trình càng dễ bảo trì.","correct":false},{"text":"Nhờ tách mô đun, nhiều thành viên trong nhóm có thể cùng lúc viết các mô đun khác nhau rồi ghép lại, miễn là đã thống nhất trước giao diện.","correct":true},{"text":"Muốn gọi một hàm của mô đun khác, bắt buộc phải đọc hiểu toàn bộ mã lệnh bên trong mô đun đó.","correct":false}],"explain":"(1) Đúng — đây chính là định nghĩa của việc chia mô đun: mỗi mô đun là một nhóm hàm cùng phục vụ một mảng công việc, nằm riêng trong một tệp .py. (2) Sai — gọi chéo chằng chịt là dấu hiệu chia mô đun kém; các mô đun phụ thuộc chặt vào nhau khiến sửa một chỗ lại hỏng nhiều chỗ khác, nguyên tắc đúng là các mô đun phải ít phụ thuộc lẫn nhau. (3) Đúng — làm song song là một lợi ích lớn của cách tổ chức theo mô đun; điều kiện là cả nhóm thống nhất trước tên hàm, tham số và kết quả trả về. (4) Sai — điều làm nên giá trị của mô đun là bạn chỉ cần biết giao diện, tức tên hàm, tham số cần đưa vào và kết quả trả về, là dùng được ngay mà không phải mở tệp ra đọc từng dòng bên trong."},{"id":"CB-mc-3101","type":"mc","topic":"F","grade":11,"level":"easy","question":"Sau khi viết `import math` ở đầu chương trình, muốn tính căn bậc hai của 81 thì phải gọi hàm như thế nào?","options":["sqrt(81)","math.sqrt(81)","import math.sqrt(81)","math(sqrt, 81)"],"answer":1,"explain":"Với cách nạp `import math`, cả thư viện được nạp vào nhưng tên các hàm bên trong vẫn phải gọi kèm tên thư viện, tức `math.sqrt(81)`. Phương án 'sqrt(81)' chỉ đúng nếu đã nạp bằng `from math import sqrt`, còn ở đây tên `sqrt` chưa hề được đưa thẳng vào chương trình nên sẽ báo lỗi chưa định nghĩa. 'import math.sqrt(81)' sai vì `import` là lệnh nạp thư viện, không phải cách gọi hàm. 'math(sqrt, 81)' sai vì `math` là tên thư viện chứ không phải một hàm để gọi kèm đối số."},{"id":"CB-mc-3102","type":"mc","topic":"F","grade":11,"level":"easy","question":"Điểm khác biệt cơ bản giữa thư viện và mô đun là gì?","options":["Thư viện chỉ chứa biến, còn mô đun chỉ chứa hàm","Thư viện bắt buộc phải do công ty phần mềm viết, học sinh không thể tự tạo được","Thư viện gồm các hàm đã kiểm thử, dùng lại được cho nhiều chương trình khác nhau; còn mô đun thường chỉ phục vụ một chương trình cụ thể","Thư viện luôn nằm ở thư mục khác với chương trình chính, còn mô đun thì nằm cùng thư mục"],"answer":2,"explain":"Khác biệt nằm ở phạm vi phục vụ: thư viện được viết với ý định dùng chung cho nhiều chương trình khác nhau, còn mô đun thường sinh ra để gánh một phần việc của đúng một chương trình. Phương án đầu sai vì cả hai đều có thể chứa hàm lẫn biến. Phương án thứ hai sai vì bất kì ai cũng có thể tự tạo thư viện riêng bằng một tệp `.py` chứa các hàm dùng chung. Phương án cuối sai vì thư viện tự viết bắt buộc phải đặt cùng thư mục với chương trình chính thì Python mới tìm thấy."},{"id":"CB-mc-3103","type":"mc","topic":"F","grade":11,"level":"medium","question":"Chương trình bắt đầu bằng dòng `from math import sqrt`. Cách gọi nào sau đây là ĐÚNG?","options":["sqrt(49)","math.sqrt(49)","from.sqrt(49)","math.from.sqrt(49)"],"answer":0,"explain":"Dạng `from ... import ...` lấy đúng hàm `sqrt` và đặt thẳng tên đó vào chương trình, nên gọi trực tiếp `sqrt(49)` mà không cần tiền tố. Phương án `math.sqrt(49)` sai vì với cách nạp này, bản thân tên `math` chưa được đưa vào chương trình, muốn dùng phải nạp thêm bằng `import math`. Hai phương án còn lại sai về cú pháp: `from` là từ khoá của lệnh nạp thư viện, không bao giờ xuất hiện trong lời gọi hàm."},{"id":"CB-mc-3104","type":"mc","topic":"F","grade":11,"level":"medium","question":"Bạn đã gom các hàm dùng chung vào tệp `tienich.py`, trong đó có hàm `xep_loai()`. Để chương trình chính `bangdiem.py` gọi được hàm này thì phải làm gì?","options":["Đổi đuôi tệp `tienich.py` thành `tienich.txt` rồi mở bằng `open()`","Chép nguyên toàn bộ nội dung của `tienich.py` vào đầu tệp `bangdiem.py`","Chỉ cần gõ `xep_loai()` là được, vì Python tự tìm hàm trong mọi tệp có trên máy","Đặt hai tệp cùng một thư mục, trong `bangdiem.py` viết `import tienich` rồi gọi `tienich.xep_loai()`"],"answer":3,"explain":"Đúng quy trình dùng thư viện tự viết: hai tệp phải cùng thư mục để Python tìm thấy, nạp bằng `import tienich` (không kèm đuôi `.py`) rồi gọi hàm theo mẫu `tienich.xep_loai()`. Phương án đổi đuôi tệp sai vì thư viện phải là tệp mã Python `.py`, không phải tệp văn bản để đọc bằng `open()`. Phương án chép nguyên nội dung sang tệp khác đúng là chạy được nhưng phá bỏ toàn bộ lợi ích của thư viện: sửa một lỗi lại phải sửa ở mọi bản chép. Phương án 'chỉ cần gõ `xep_loai()`' sai vì Python chỉ biết đến những hàm đã được định nghĩa ngay trong tệp hoặc đã được nạp vào bằng `import`, chứ không tự đi quét các tệp khác trên máy."},{"id":"CB-mc-3105","type":"mc","topic":"F","grade":11,"level":"hard","question":"Cuối tệp `tienich.py` có khối lệnh `if __name__ == '__main__':` với một câu lệnh in dòng chữ 'Chạy thử'. Khi tệp `bangdiem.py` thực hiện `import tienich`, điều gì xảy ra?","options":["Chương trình báo lỗi vì tệp thư viện không được phép chứa lệnh `if`","Dòng chữ 'Chạy thử' được in ra trước, rồi `bangdiem.py` mới chạy tiếp","Dòng chữ 'Chạy thử' không được in ra, nhưng các hàm trong `tienich.py` vẫn dùng được bình thường","Cả các hàm lẫn dòng chữ 'Chạy thử' đều bị bỏ qua, `bangdiem.py` không gọi được hàm nào"],"answer":2,"explain":"Khi tệp bị nạp vào chương trình khác, biến `__name__` của nó mang giá trị là tên mô đun ('tienich') chứ không phải '__main__', nên điều kiện sai và khối chạy thử bị bỏ qua; trong khi đó các lệnh `def` vẫn được thực hiện nên mọi hàm đều sẵn sàng để gọi. Phương án đầu sai vì tệp thư viện hoàn toàn được phép chứa lệnh `if`. Phương án thứ hai mô tả tình huống xảy ra khi thiếu khối `if __name__`, tức lệnh in đặt trần trụi ở cuối tệp. Phương án cuối sai vì chỉ riêng phần trong khối `if` bị bỏ qua, còn các định nghĩa hàm vẫn có hiệu lực — nếu không thì việc import đã trở nên vô nghĩa."},{"id":"CB-tf-3101","type":"tf","topic":"F","grade":11,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Khi tệp `tienich.py` được nạp vào chương trình khác bằng `import`, biến `__name__` trong tệp đó nhận giá trị là tên mô đun chứ không phải chuỗi '__main__'.","correct":true},{"text":"Câu lệnh `import numpy as np` tạo ra một tên gọi tắt, sau đó có thể viết `np` thay cho `numpy` mỗi khi gọi hàm của thư viện này.","correct":true},{"text":"Sau câu lệnh `from math import sqrt`, ta vẫn bắt buộc phải viết `math.sqrt(x)` thì mới gọi được hàm căn bậc hai.","correct":false},{"text":"Docstring của hàm chỉ có tác dụng làm mã nguồn đẹp mắt; người muốn dùng lại hàm vẫn bắt buộc phải đọc hết các lệnh bên trong mới biết hàm làm gì.","correct":false}],"explain":"(1) Đúng — chỉ khi tệp được cho chạy trực tiếp thì `__name__` mới bằng '__main__'; lúc bị import, nó mang tên mô đun nên khối chạy thử bị bỏ qua. (2) Đúng — dạng `import ... as ...` chính là cách đặt tên gọi tắt, rất tiện với những thư viện tên dài phải gõ nhiều lần. (3) Sai — `from math import sqrt` đã đưa thẳng tên `sqrt` vào chương trình nên gọi trực tiếp `sqrt(x)`; ngược lại, viết `math.sqrt(x)` mới là lỗi vì tên `math` chưa được nạp. (4) Sai — docstring tồn tại đúng để người dùng lại hàm biết hàm làm gì, cần tham số nào và trả về gì mà không phải đọc mã bên trong."}]);
  LESSONS.push(
    {"id":"C11-01","stage":21,"order":1,"topic":"A","grade":11,"minutes":10,"title":"Hệ điều hành và vai trò của nó","intro":"Bài học giới thiệu hệ điều hành — phần mềm quan trọng nhất bên trong mọi máy tính, điện thoại — và bốn vai trò chính mà nó đảm nhận.","sections":[{"t":"story","text":"Hãy tưởng tượng một toà nhà văn phòng lớn, có hàng chục phòng ban khác nhau: phòng kế toán, phòng kinh doanh, phòng kho, phòng họp... Tất cả cùng dùng chung một hệ thống điện, một hệ thống thang máy, một đội bảo vệ và một sảnh lễ tân. Nếu không có ai đứng ra sắp xếp, chuyện gì sẽ xảy ra? Phòng kinh doanh và phòng kế toán có thể tranh nhau cùng một phòng họp vào cùng một giờ; thang máy chạy lộn xộn vì ai cũng bấm nút cùng lúc; hệ thống điện quá tải vì không ai kiểm soát thiết bị nào được bật, thiết bị nào phải tắt bớt.\n\nMay mắn là toà nhà nào cũng có một bộ phận quản lí đứng ra điều phối: phân phòng họp theo lịch, quy định giờ dùng thang máy, kiểm soát an ninh ra vào, đảm bảo phòng ban nào cũng có điện, có mạng để làm việc. Nhờ vậy, hàng chục phòng ban có thể hoạt động trơn tru trên cùng một cơ sở vật chất mà không giẫm chân lên nhau.\n\nBên trong một chiếc máy tính hay điện thoại cũng có tình huống tương tự: rất nhiều phần mềm — trình duyệt, phần mềm nghe nhạc, phần mềm soạn thảo... — cùng muốn dùng chung một bộ xử lí, một vùng bộ nhớ, một màn hình, một kết nối mạng. Bộ phận đứng ra điều phối tất cả những thứ đó, để mọi phần mềm hoạt động ổn thoả, chính là **hệ điều hành**."},{"t":"h","text":"1) Hệ điều hành là gì"},{"t":"text","text":"**Hệ điều hành** (tiếng Anh: `operating system`, viết tắt `OS`) là phần mềm quan trọng nhất trong một chiếc máy tính, điện thoại hay máy tính bảng. Đây là phần mềm **chạy đầu tiên**, ngay khi bạn bấm nút nguồn, trước cả khi bạn mở bất kì phần mềm nào khác.\n\nNgay khi khởi động, hệ điều hành được nạp vào bộ nhớ và bắt đầu kiểm soát toàn bộ thiết bị. Mọi phần mềm khác — trình duyệt web, phần mềm học tập, trò chơi... — đều phải ‘xin phép’ hệ điều hành mỗi khi cần dùng đến phần cứng, chẳng hạn đọc một tệp trên ổ đĩa, hiển thị hình ảnh lên màn hình, hay kết nối mạng. Nói cách khác, phần mềm không thể trực tiếp ra lệnh cho phần cứng; mọi yêu cầu đều phải đi qua hệ điều hành trước."},{"t":"h","text":"2) Vai trò của hệ điều hành"},{"t":"list","text":"Từ vị trí trung tâm đó, hệ điều hành đảm nhận bốn vai trò chính:","items":["**Quản lí phần cứng**: kiểm soát bộ xử lí `CPU`, bộ nhớ, màn hình, bàn phím, ổ đĩa và các thiết bị vào/ra khác, phân chia cho từng phần mềm dùng đúng lúc, đúng phần.","**Quản lí tệp và bộ nhớ**: tổ chức dữ liệu thành tệp, thư mục để bạn dễ tìm, dễ lưu; đồng thời cấp phát vùng bộ nhớ cho từng phần mềm đang chạy, tránh để phần mềm này ghi đè lên dữ liệu của phần mềm khác.","**Làm nền tảng cho phần mềm khác hoạt động**: mọi phần mềm đều được viết ra để chạy trên một hệ điều hành cụ thể; hệ điều hành cung cấp môi trường và các dịch vụ chung để phần mềm không phải tự lo mọi thứ từ đầu.","**Làm cầu nối giữa người dùng và máy**: cung cấp giao diện — màn hình, biểu tượng, cửa sổ, hoặc dòng lệnh — để bạn ra lệnh cho máy một cách dễ hiểu, thay vì phải hiểu ngôn ngữ của phần cứng."]},{"t":"example","text":"Thử hình dung điều gì diễn ra khi bạn vừa mở một trình duyệt web, vừa mở một phần mềm nghe nhạc, trên cùng một chiếc máy tính chỉ có một bộ xử lí:","code":"① Trình duyệt xin CPU xử lí trong một khoảng thời gian rất ngắn\n② Hệ điều hành tạm dừng trình duyệt, chuyển CPU sang phần mềm nghe nhạc trong một khoảng ngắn khác\n③ Hệ điều hành lại chuyển CPU về cho trình duyệt, rồi lại chuyển đi\n④ Việc đổi qua đổi lại diễn ra hàng trăm, hàng nghìn lần mỗi giây","output":"Vì tốc độ chuyển đổi rất nhanh, bạn có cảm giác cả hai phần mềm đang chạy cùng một lúc, dù thực chất bộ xử lí vẫn đang phục vụ lần lượt từng phần mềm trong đa số trường hợp."},{"t":"h","text":"3) Những hệ điều hành quen thuộc"},{"t":"list","text":"Trong đời sống hằng ngày, bạn tiếp xúc với hệ điều hành nhiều hơn bạn nghĩ:","items":["**Windows**: phổ biến trên máy tính cá nhân, máy tính văn phòng.","**Android** và **iOS**: hai hệ điều hành phổ biến nhất trên điện thoại thông minh và máy tính bảng.","**Linux**: dùng nhiều trên máy chủ `server`, một số máy tính cá nhân, và cả trong nhiều thiết bị nhúng như tivi thông minh, bộ định tuyến mạng."]},{"t":"note","text":"Không có hệ điều hành, một chiếc máy tính chỉ là một khối phần cứng vô dụng: có bộ xử lí nhưng không biết chạy phần mềm nào, có màn hình nhưng không biết hiển thị gì, có ổ đĩa nhưng không biết cách đọc và ghi dữ liệu. Chính hệ điều hành khiến toàn bộ phần cứng đó phối hợp được với nhau, biến một đống linh kiện rời rạc thành một thiết bị mà bạn thật sự có thể sử dụng."}],"keypoints":["**Hệ điều hành** (`operating system`) là phần mềm quan trọng nhất, chạy đầu tiên khi thiết bị khởi động và quản lí toàn bộ máy.","Hệ điều hành đảm nhận bốn vai trò chính: quản lí phần cứng, quản lí tệp và bộ nhớ, làm nền tảng cho phần mềm khác hoạt động, và làm cầu nối giữa người dùng với máy.","Windows, Android, iOS, Linux là những hệ điều hành quen thuộc, mỗi loại phù hợp với một nhóm thiết bị khác nhau.","Không có hệ điều hành, máy tính chỉ là phần cứng vô dụng vì không phần mềm nào chạy được và người dùng cũng không thể ra lệnh cho máy."],"quiz":["CB-mc-101","CB-mc-102","CB-mc-103","CB-mc-104","CB-mc-105","CB-tf-101"]},
    {"id":"C11-02","stage":21,"order":2,"topic":"A","grade":11,"minutes":11,"title":"Phần mềm hệ thống và phần mềm ứng dụng","intro":"Bài trước đã tìm hiểu về hệ điều hành. Bài này mở rộng ra toàn bộ thế giới phần mềm bên trong máy tính: phân biệt nhóm phần mềm âm thầm làm nền (phần mềm hệ thống) với nhóm phần mềm phục vụ trực tiếp công việc, sở thích của bạn (phần mềm ứng dụng), đồng thời tìm hiểu vì sao có phần mềm dùng miễn phí, có phần mềm phải trả tiền mới được dùng hợp pháp.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn vừa nhận bàn giao một căn hộ mới xây xong phần thô, chuẩn bị dọn vào ở. Trước khi nghĩ đến chuyện kê bàn ghế hay chọn màu rèm cửa, ngôi nhà đã phải có sẵn nền móng vững chắc, dây điện đi ngầm trong tường, đường ống nước dẫn tới từng phòng, hệ thống công tắc hoạt động ổn định. Những thứ này bạn hiếm khi nhìn thấy tận mắt, lại càng không tự tay chỉnh sửa, nhưng thiếu bất kì thứ nào trong số đó, ngôi nhà cũng không thể ở được — bật công tắc mà không có điện, mở vòi mà không có nước.\n\nChỉ sau khi phần nền ấy đã sẵn sàng, bạn mới bắt đầu mang đồ đạc vào theo đúng nhu cầu riêng của mình: người thích nấu nướng sắm bếp xịn, người làm việc tại nhà kê thêm bàn làm việc, người mê điện ảnh lắp thêm màn hình lớn ở phòng khách. Mỗi nhà một kiểu, tuỳ chủ nhà cần gì.\n\nBên trong một chiếc máy tính hay điện thoại cũng được tổ chức theo đúng hai tầng như vậy. Có một nhóm phần mềm âm thầm làm nền, giúp máy “sống” được — ta ít khi để ý tới chúng. Và có một nhóm phần mềm khác mà chính bạn chủ động mở ra mỗi ngày để học tập, làm việc hay giải trí. Bài học này sẽ giúp bạn gọi tên rõ ràng hai nhóm phần mềm đó, và biết thêm vì sao có phần mềm dùng miễn phí, có phần mềm phải trả tiền mới được dùng hợp pháp."},{"t":"h","text":"1) Phần mềm là gì, và vì sao chia thành hai nhóm?"},{"t":"text","text":"Một chiếc máy tính khi vừa xuất xưởng, chưa cài đặt gì, thực chất chỉ là một khối vỏ máy cùng các linh kiện điện tử — bộ xử lí, bộ nhớ, ổ đĩa, màn hình... Những bộ phận cầm nắm được, nhìn thấy được đó gọi là **phần cứng** (`hardware`). Phần cứng dù hiện đại đến đâu cũng không tự biết làm việc gì, giống một dàn nhạc cụ tốt nhưng chưa có bản nhạc để chơi.\n\nThứ “ra lệnh” cho phần cứng hoạt động gọi là **phần mềm** (`software`) — hiểu đơn giản là một tập hợp các câu lệnh được viết sẵn, chỉ dẫn cho máy phải làm gì, làm theo thứ tự nào, xử lí ra sao khi gặp tình huống này hay tình huống khác. Phần mềm không cầm nắm được, chỉ là dữ liệu được lưu trên phần cứng (ổ đĩa, bộ nhớ...), nhưng chính nó mới quyết định máy tính “biết” làm việc gì.\n\nXét theo việc phục vụ ai, người ta chia toàn bộ phần mềm trong một máy tính thành hai nhóm lớn: **phần mềm hệ thống** — làm nền cho máy hoạt động, và **phần mềm ứng dụng** — phục vụ trực tiếp công việc của người dùng. Hai phần tiếp theo sẽ đi vào từng nhóm."},{"t":"h","text":"2) Phần mềm hệ thống — nền cho máy hoạt động"},{"t":"text","text":"**Phần mềm hệ thống** là nhóm phần mềm chạy nền, đảm nhận việc vận hành và quản lí chính chiếc máy, để mọi phần mềm khác có chỗ mà chạy lên. Nhóm này gồm ba loại chính.\n\nLoại quen thuộc nhất, bạn đã tìm hiểu kĩ ở bài trước, là **hệ điều hành** (`operating system`) — phần mềm nạp đầu tiên khi bật máy, quản lí toàn bộ phần cứng và làm nền cho mọi phần mềm khác hoạt động, ví dụ `Windows`, `macOS`, `Linux` trên máy tính hay `Android`, `iOS` trên điện thoại.\n\nLoại thứ hai là **trình điều khiển thiết bị** (`driver`) — phần mềm nhỏ, chuyên biệt cho từng thiết bị phần cứng cụ thể, đóng vai trò phiên dịch giữa hệ điều hành và thiết bị đó. Mỗi mẫu máy in, mỗi loại card màn hình lại cần một driver riêng, vì cách “nói chuyện” với từng thiết bị không giống nhau; hệ điều hành dù mạnh đến đâu cũng không thể tự biết cách điều khiển một thiết bị mới toanh nếu thiếu đúng driver của nó.\n\nLoại thứ ba là **tiện ích hệ thống** (`system utility`) — các công cụ hỗ trợ giúp máy chạy trơn tru và an toàn hơn, chẳng hạn phần mềm diệt `virus`, phần mềm dọn dẹp ổ đĩa, phần mềm sao lưu dữ liệu. Không có chúng máy vẫn hoạt động được, nhưng có chúng máy chạy an toàn và ổn định hơn hẳn."},{"t":"example","text":"Một tình huống quen thuộc cho thấy rõ vai trò của trình điều khiển thiết bị:","code":"Bước 1 — Cắm một chiếc máy in đời mới vào máy tính qua cổng USB.\nBước 2 — Hệ điều hành nhận ra có thiết bị lạ vừa cắm vào nhưng CHƯA có driver phù hợp: máy in không in được, dù đã bật nguồn và có sẵn giấy.\nBước 3 — Cài đặt đúng driver do hãng máy in cung cấp.\nBước 4 — Hệ điều hành giờ đã biết cách gửi lệnh cho đúng mẫu máy in này: bấm in thử, máy in hoạt động bình thường.","output":"Phần cứng (chiếc máy in) không hề thay đổi giữa bước 2 và bước 4 — thứ vừa được thêm vào chỉ là driver, một phần mềm hệ thống đóng vai trò phiên dịch giữa hệ điều hành và thiết bị."},{"t":"h","text":"3) Phần mềm ứng dụng — phục vụ công việc và sở thích riêng"},{"t":"text","text":"Nếu phần mềm hệ thống là thứ ai dùng máy tính cũng cần có như nhau, thì **phần mềm ứng dụng** (`application software`) lại được chọn tuỳ theo nhu cầu của từng người. Phần mềm ứng dụng luôn chạy dựa trên nền mà hệ điều hành đã dựng sẵn; mỗi phần mềm nhắm tới giải quyết một công việc cụ thể mà người dùng muốn làm.\n\nNgười cần soạn báo cáo dùng phần mềm soạn thảo văn bản; người cần tính toán, thống kê số liệu dùng phần mềm bảng tính; hầu như máy nào cũng cần có trình duyệt để truy cập Internet; ngoài giờ học, giờ làm, người ta còn cài thêm phần mềm xem phim, nghe nhạc hay trò chơi điện tử để giải trí. Cùng một chiếc máy tính, hai người dùng có thể cài hai bộ phần mềm ứng dụng hoàn toàn khác nhau — đúng như việc chọn đồ nội thất theo sở thích riêng ở câu chuyện đầu bài."},{"t":"list","text":"Một vài ví dụ về phần mềm ứng dụng, mỗi loại phục vụ một mục đích riêng:","items":["**Soạn thảo văn bản, bảng tính** (như `Word`, `Excel`, `Google Docs`) — viết tài liệu, trình bày, tính toán, lập bảng biểu.","**Trình duyệt** (như `Chrome`, `Firefox`, `Edge`) — truy cập và xem các trang web trên Internet.","**Phần mềm xem phim, nghe nhạc** — phục vụ nhu cầu giải trí sau giờ học, giờ làm.","**Trò chơi điện tử** — cũng là một dạng phần mềm ứng dụng, phục vụ nhu cầu giải trí của người chơi."]},{"t":"h","text":"4) Phần mềm nguồn mở và phần mềm thương mại"},{"t":"text","text":"Ngoài cách chia theo vai trò (hệ thống / ứng dụng), người ta còn phân loại phần mềm theo một tiêu chí khác: ai được phép xem và chỉnh sửa đoạn câu lệnh gốc bên trong nó, gọi là **mã nguồn** (`source code`).\n\n**Phần mềm thương mại** do một công ti tạo ra và giữ kín mã nguồn. Muốn dùng hợp pháp, người dùng phải trả tiền mua giấy phép sử dụng, và chỉ được dùng đúng theo điều khoản đi kèm — không được xem, càng không được sửa những gì diễn ra bên trong phần mềm.\n\n**Phần mềm nguồn mở** (`open source`) thì ngược lại: mã nguồn được công bố công khai, phần lớn được cung cấp miễn phí; ai cũng có thể tải về xem, tìm hiểu cách phần mềm được viết ra, thậm chí chỉnh sửa hoặc phát triển thêm, miễn tuân theo giấy phép nguồn mở đi kèm. Hệ điều hành `Linux` là một ví dụ tiêu biểu của phần mềm nguồn mở, khác với `Windows` là phần mềm thương mại."},{"t":"h","text":"5) Bản quyền phần mềm — vì sao không thể tuỳ ý sao chép"},{"t":"note","text":"Dù là phần mềm thương mại hay phần mềm nguồn mở, phần mềm nào cũng có **bản quyền** — quyền của người hoặc tổ chức đã tạo ra phần mềm đó, được pháp luật bảo vệ. Với phần mềm thương mại, bản quyền thể hiện rõ nhất ở việc phải trả tiền mua giấy phép mới được dùng hợp pháp; tải bản “bẻ khoá”, sao chép rồi đưa cho người khác dùng mà không trả tiền là vi phạm bản quyền, có thể bị xử lí theo pháp luật dù việc này rất dễ thực hiện về mặt kĩ thuật.\n\nNgay cả phần mềm nguồn mở, miễn phí cũng có giấy phép đi kèm, quy định rõ được phép dùng, sửa, chia sẻ lại theo cách nào — không phải cứ mã nguồn công khai là muốn làm gì cũng được. Tôn trọng bản quyền phần mềm, vì vậy, chính là tôn trọng công sức của người đã viết ra nó, bất kể phần mềm đó có tính phí hay không."}],"keypoints":["**Phần mềm** là tập hợp các câu lệnh được viết sẵn, chỉ dẫn cho phần cứng phải làm gì; phần cứng dù hiện đại đến đâu cũng cần có phần mềm mới hoạt động được.","**Phần mềm hệ thống** (hệ điều hành, trình điều khiển thiết bị/driver, tiện ích hệ thống) làm nền cho máy hoạt động, ai dùng máy tính cũng cần có.","**Phần mềm ứng dụng** (soạn thảo văn bản, bảng tính, trình duyệt, xem phim, trò chơi...) phục vụ trực tiếp công việc và sở thích riêng của từng người dùng.","Phần mềm còn được phân biệt theo mã nguồn và bản quyền: **phần mềm thương mại** giữ kín mã nguồn, phải trả tiền mua giấy phép; **phần mềm nguồn mở** công khai mã nguồn, phần lớn miễn phí; dù thuộc loại nào, phần mềm cũng có bản quyền cần được tôn trọng."],"quiz":["CB-mc-201","CB-mc-202","CB-mc-203","CB-mc-204","CB-mc-205","CB-tf-201"]},
    {"id":"C11-03","stage":21,"order":3,"topic":"A","grade":11,"minutes":12,"title":"Bên trong máy tính: CPU, bộ nhớ và thiết bị","intro":"Máy tính hoạt động được là nhờ nhiều bộ phận phối hợp nhịp nhàng với nhau. Bài học này giúp bạn hiểu vai trò của CPU, RAM, bộ nhớ ngoài và các thiết bị vào - ra bên trong một chiếc máy tính.","sections":[{"t":"story","text":"Hãy tưởng tượng một căn bếp đang chuẩn bị bữa tối. Người đầu bếp không thể nấu ăn nếu không có nguyên liệu, nhưng cũng không thể bày hết mọi thứ ra cùng lúc. Vì vậy, căn bếp thường chia thành ba khu vực rõ rệt: một tủ lạnh và tủ đựng thực phẩm để trữ nguyên liệu lâu dài, dù không dùng đến trong nhiều ngày; một mặt bàn thao tác, nơi chỉ bày sẵn những thứ đang cần dùng ngay cho món đang nấu; và chính người đầu bếp - người trực tiếp cắt, nấu, nêm nếm, ra quyết định cho từng bước.\n\nMột chiếc máy tính cũng tổ chức công việc theo cách khá giống vậy. Có một bộ phận đóng vai trò như người đầu bếp - trực tiếp tính toán và điều khiển. Có một khu vực giống mặt bàn thao tác - nơi chứa những dữ liệu đang cần dùng ngay, dùng xong là dọn đi. Và có một nơi giống tủ lạnh, tủ đựng thực phẩm - chứa mọi thứ lâu dài, kể cả khi máy đã tắt. Ta sẽ lần lượt tìm hiểu từng bộ phận này, cùng với những thiết bị giúp con người trao đổi thông tin với máy tính."},{"t":"h","text":"CPU – bộ xử lí trung tâm: “bộ não” của máy tính"},{"t":"text","text":"Trở lại hình ảnh căn bếp, **CPU** (viết tắt của Central Processing Unit - bộ xử lí trung tâm) chính là “người đầu bếp” của máy tính. Đây là bộ phận thực hiện các **phép tính** (cộng, trừ, so sánh...) và **điều khiển** hoạt động của mọi bộ phận còn lại: khi nào cần lấy dữ liệu, khi nào cần hiển thị kết quả, khi nào cần ghi tệp...\n\nTốc độ của CPU thường được đo bằng đơn vị `GHz` (đọc là gigahertz). Con số này cho biết ước lượng số chu kì xử lí mà CPU thực hiện được trong một giây - `GHz` càng lớn, CPU nói chung càng xử lí nhanh, dù tốc độ thực tế của cả máy còn phụ thuộc thêm nhiều yếu tố khác, không chỉ riêng CPU."},{"t":"h","text":"RAM – bộ nhớ trong: nơi làm việc tạm thời"},{"t":"text","text":"**RAM** (Random Access Memory - bộ nhớ trong) đóng vai trò như mặt bàn thao tác trong bếp. Khi máy tính chạy một phần mềm, dữ liệu và lệnh của phần mềm đó được nạp vào RAM để CPU lấy ra xử lí ngay, với tốc độ rất nhanh.\n\nĐiểm cần nhớ: RAM chỉ là nơi lưu **TẠM THỜI**. Giống như mặt bàn thao tác sẽ được dọn sạch khi bếp đóng cửa, dữ liệu trong RAM biến mất ngay khi máy tính mất điện hoặc tắt nguồn đột ngột. Ngoài ra, RAM càng lớn thì “mặt bàn” càng rộng - máy tính càng có thể mở nhiều phần mềm, xử lí nhiều việc cùng lúc mà không bị chậm, giật."},{"t":"h","text":"Bộ nhớ ngoài và các thiết bị vào – ra"},{"t":"text","text":"Nếu RAM giống mặt bàn thao tác thì **bộ nhớ ngoài** - chẳng hạn ổ `HDD` (ổ đĩa cứng cơ học) hay ổ `SSD` (ổ cứng thể rắn) - giống như tủ lạnh và tủ đựng thực phẩm của căn bếp: nơi lưu trữ **LÂU DÀI**, dữ liệu vẫn còn nguyên dù máy đã tắt nhiều ngày. Đây là lí do một tệp bạn lưu hôm nay vẫn mở lại được vào hôm sau.\n\nGiữa hai loại: ổ `HDD` dùng đĩa từ quay cơ học nên giá thường rẻ hơn cho cùng dung lượng, nhưng tốc độ đọc/ghi chậm hơn; ổ `SSD` dùng chip nhớ điện tử, không có bộ phận chuyển động nên đọc/ghi nhanh hơn nhiều và bền hơn, dù giá trên mỗi GB thường cao hơn."},{"t":"list","text":"Bên cạnh nơi xử lí và lưu trữ, máy tính còn cần thêm các thiết bị để trao đổi thông tin với con người:","items":["**Thiết bị vào** (input): bàn phím, chuột, micro, máy quét... - đưa dữ liệu hoặc lệnh từ người dùng vào máy tính.","**Thiết bị ra** (output): màn hình, loa, máy in... - đưa kết quả xử lí từ máy tính ra cho người dùng xem, nghe hoặc in ra giấy.","Một số thiết bị vừa vào vừa ra, ví dụ màn hình cảm ứng: vừa hiển thị hình ảnh (ra), vừa nhận thao tác chạm (vào)."]},{"t":"example","text":"Hãy hình dung đầy đủ các bộ phận phối hợp với nhau khi bạn mở một tệp văn bản đã lưu sẵn, gõ thêm vài câu rồi lưu lại:","code":"1) Tệp đang nằm trên ổ cứng (bộ nhớ ngoài) - dữ liệu lâu dài.\n2) Mở tệp: dữ liệu được nạp từ ổ cứng vào RAM (bộ nhớ trong) để xử lí nhanh.\n3) Gõ thêm chữ: CPU đọc dữ liệu từ RAM, tính toán và cập nhật nội dung.\n4) Kết quả được đưa ra màn hình (thiết bị ra) để bạn nhìn thấy ngay.\n5) Bấm Lưu: CPU ghi dữ liệu từ RAM trở lại ổ cứng để giữ lâu dài.","output":"Tệp trên ổ cứng được cập nhật nội dung mới nhất. Nếu chưa bấm Lưu mà mất điện, phần vừa gõ thêm - đang nằm trong RAM - sẽ bị mất."}],"keypoints":["CPU (bộ xử lí trung tâm) là bộ phận thực hiện phép tính và điều khiển hoạt động của toàn bộ máy tính; tốc độ thường đo bằng GHz.","RAM (bộ nhớ trong) là nơi lưu dữ liệu tạm thời trong lúc máy đang chạy; mất điện là mất dữ liệu trong RAM, còn RAM càng lớn thì máy càng chạy mượt khi làm nhiều việc cùng lúc.","Bộ nhớ ngoài (ổ cứng HDD, SSD...) lưu dữ liệu lâu dài, vẫn còn nguyên sau khi tắt máy.","Thiết bị vào (bàn phím, chuột...) đưa dữ liệu, lệnh vào máy tính; thiết bị ra (màn hình, loa, máy in...) đưa kết quả ra; dữ liệu thường được nạp từ ổ cứng vào RAM để CPU xử lí, rồi kết quả được xuất ra thiết bị ra hoặc lưu lại."],"quiz":["CB-mc-301","CB-mc-302","CB-mc-303","CB-mc-304","CB-mc-305","CB-tf-301"]},
    {"id":"C11-04","stage":21,"order":4,"topic":"B","grade":11,"minutes":10,"title":"Tổ chức và quản lí dữ liệu bằng tệp và thư mục","intro":"Bài học giúp bạn hiểu tệp và phần mở rộng là gì, cách nhiều thư mục lồng nhau tạo thành cây thư mục, và cách đọc đường dẫn để tìm đúng một tệp. Bạn cũng sẽ biết cách tổ chức và sao lưu dữ liệu sao cho gọn gàng, an toàn.","sections":[{"t":"story","text":"Hãy tưởng tượng một tủ hồ sơ lớn trong một văn phòng, có nhiều ngăn kéo. Nếu người quản lí ném hết giấy tờ vào chung một ngăn — hóa đơn lẫn với hợp đồng, hồ sơ năm nay lẫn với hồ sơ năm ngoái — thì mỗi lần cần tìm một tờ giấy, phải lục tung cả ngăn kéo mới thấy, rất mất thời gian.\n\nNgược lại, nếu chia tủ thành nhiều ngăn, mỗi ngăn lại có các cặp hồ sơ dán nhãn rõ ràng theo từng chủ đề (hợp đồng, hóa đơn, hồ sơ nhân sự...), việc tìm một tờ giấy chỉ mất vài giây: nhìn nhãn ngăn kéo, nhìn nhãn cặp hồ sơ, rút đúng tờ cần tìm.\n\nMáy tính lưu dữ liệu theo đúng nguyên tắc đó. Mỗi bài làm, tấm ảnh, bài hát... được lưu thành một **tệp**; nhiều tệp liên quan được gom vào một **thư mục**, và các thư mục lại lồng vào nhau như những ngăn kéo trong ngăn kéo. Bài học này giúp bạn hiểu cách máy tính tổ chức dữ liệu theo kiểu đó, và học cách sắp xếp “tủ hồ sơ số” của chính mình sao cho gọn gàng, dễ tìm, ít rủi ro mất mát."},{"t":"h","text":"1) Tệp — đơn vị lưu trữ dữ liệu"},{"t":"text","text":"Mỗi khi bạn gõ xong một bài văn rồi bấm lưu, chụp một tấm ảnh, hay tải về một bài hát, máy tính đều cất nội dung đó thành một **tệp** (tiếng Anh gọi là `file`). Có thể hình dung tệp là một gói dữ liệu mang một cái tên riêng, được lưu thành một khối độc lập trên ổ đĩa hay thẻ nhớ — giống như một tờ giấy hay một tập tài liệu trong tủ hồ sơ.\n\nTệp có thể chứa nhiều loại nội dung: văn bản, hình ảnh, âm thanh, video, hoặc cả một chương trình máy tính. Dù nội dung bên trong khác nhau đến đâu, máy tính vẫn coi mỗi tệp là một đơn vị lưu trữ riêng biệt, có tên để phân biệt với các tệp khác.\n\nTên một tệp thường có hai phần, ngăn cách nhau bởi dấu chấm: **phần tên** (do người dùng tự đặt) và **phần mở rộng** (thường gồm vài kí tự sau dấu chấm cuối cùng). Phần mở rộng cho máy tính — và cho cả bạn — biết tệp đó thuộc loại gì, nên mở bằng phần mềm nào."},{"t":"example","text":"Bốn tệp sau có nội dung hoàn toàn khác nhau — hãy để ý phần mở rộng đứng sau dấu chấm cuối cùng trong mỗi tên:","code":"baocao.docx    → văn bản Word\nanhbien.jpg    → hình ảnh\nbaihat.mp3     → âm thanh\nbaitap.py      → chương trình Python","output":"Chỉ cần nhìn phần mở rộng (`.docx`, `.jpg`, `.mp3`, `.py`), máy tính đã biết nên mở tệp bằng phần mềm nào, và bạn cũng đoán được nội dung bên trong mà chưa cần mở tệp lên."},{"t":"h","text":"2) Thư mục và cây thư mục"},{"t":"text","text":"Nếu chỉ có tệp mà không có gì gom chúng lại, hàng nghìn tệp trên máy tính sẽ nằm lẫn lộn, rất khó tìm. Vì vậy máy tính có thêm một loại đối tượng khác gọi là **thư mục** (tiếng Anh: `folder`, có tài liệu gọi là `directory`). Thư mục giống một ngăn kéo hay một cặp đựng hồ sơ: bản thân nó không phải là dữ liệu, mà là nơi chứa các tệp — và quan trọng hơn, thư mục còn có thể chứa cả **thư mục con** bên trong nó.\n\nVì một thư mục có thể chứa thư mục con, thư mục con lại chứa thư mục con nhỏ hơn nữa, toàn bộ hệ thống thư mục trên một ổ đĩa tạo thành một cấu trúc nhiều tầng, gọi là **cây thư mục**. Thư mục ngoài cùng của cả ổ đĩa gọi là thư mục gốc; từ đó rẽ dần xuống các thư mục con, giống một cái cây có gốc, có cành, rồi cành lại chia thành cành nhỏ hơn."},{"t":"example","text":"Hình dung một cây thư mục nhỏ, phục vụ việc học, nằm trên ổ đĩa D:","code":"D:\\HocTap\n├── Tin\n│   ├── baitap.py\n│   └── baocao.docx\n├── Toan\n│   └── dethi.pdf\n└── AnhChup\n    └── anhbien.jpg","output":"Thư mục `HocTap` chứa ba thư mục con: `Tin`, `Toan`, `AnhChup`. Riêng thư mục `Tin` lại chứa hai tệp bên trong. Cứ như vậy, cây thư mục có thể rẽ thành bao nhiêu tầng cũng được, tùy vào cách người dùng tổ chức."},{"t":"example","text":"Cây thư mục càng lớn, càng cần một cách chỉ ra chính xác một tệp nằm ở đâu. Cách đó gọi là **đường dẫn** (tiếng Anh: `path`) — một chuỗi ghi lại hành trình đi từ ổ đĩa, qua từng thư mục con, đến đúng tệp cần tìm, các phần ngăn cách nhau bởi dấu `\\`. Xét đường dẫn ứng với cây thư mục ở trên, dẫn tới tệp bài tập Python:","code":"D:\\HocTap\\Tin\\baitap.py","output":"Đọc từ trái sang phải: vào ổ đĩa `D:`, mở thư mục `HocTap`, mở tiếp thư mục con `Tin`, và tệp cần tìm là `baitap.py`. Chỉ cần chuyển tệp này sang một thư mục khác, đường dẫn của nó cũng đổi theo vị trí mới."},{"t":"list","text":"Cây thư mục càng lớn càng dễ rối. Khi tự tổ chức dữ liệu của mình, ta nên theo một số nguyên tắc đơn giản sau:","items":["**Đặt tên gợi nhớ**: nhìn tên tệp hay tên thư mục là đoán được nội dung bên trong, ví dụ `BaoCao_HoaHoc_HocKi1` rõ ràng hơn hẳn so với `tailieu1`.","**Gom theo chủ đề**: mỗi môn học hay mỗi dự án nên có một thư mục riêng, tránh để mọi tệp cùng nằm chung một chỗ.","**Không lồng quá nhiều tầng thư mục con**: cây thư mục sâu quá bốn, năm tầng sẽ khiến việc mở đến đúng tệp mất khá nhiều thao tác.","**Dọn dẹp định kì**: chuyển hoặc xóa những tệp không còn dùng đến, tránh để thư mục làm việc chính ngày càng phình to, lẫn lộn."]},{"t":"note","text":"Tổ chức gọn gàng vẫn chưa đủ để bảo vệ dữ liệu. Ổ đĩa có thể hỏng, máy tính có thể nhiễm mã độc, hoặc chính ta có thể lỡ tay xóa nhầm một tệp quan trọng. Vì vậy, cần **sao lưu** (tiếng Anh: `backup`) dữ liệu quan trọng — nghĩa là tạo thêm một bản sao, lưu ở một nơi khác với bản chính (đĩa ngoài, USB, hoặc dịch vụ lưu trữ trực tuyến). Nếu bản chính gặp sự cố, ta vẫn còn bản sao lưu để khôi phục lại, không phải làm lại từ đầu."}],"keypoints":["**Tệp** (`file`) là đơn vị lưu trữ dữ liệu (văn bản, ảnh, nhạc, chương trình...); **phần mở rộng** sau dấu chấm cuối trong tên tệp (`.docx`, `.jpg`, `.mp3`...) cho biết đó là loại tệp gì.","**Thư mục** (`folder`) chứa tệp và có thể chứa cả thư mục con bên trong nó; nhiều thư mục lồng nhau tạo thành **cây thư mục** nhiều tầng.","**Đường dẫn** (`path`) là chuỗi ghi lại hành trình từ ổ đĩa, qua từng thư mục con, đến đúng một tệp, ví dụ `D:\\HocTap\\Tin\\baitap.py`.","Tổ chức khoa học (đặt tên gợi nhớ, gom theo chủ đề, không lồng quá nhiều tầng) và **sao lưu** (`backup`) định kì giúp dữ liệu vừa dễ tìm vừa an toàn."],"quiz":["CB-mc-401","CB-mc-402","CB-mc-403","CB-mc-404","CB-mc-405","CB-tf-401"]},
    {"id":"C11-05","stage":21,"order":5,"topic":"B","grade":11,"minutes":10,"title":"Khai thác thông tin số một cách hiệu quả","intro":"Bài học giúp bạn tìm kiếm thông tin trên Internet nhanh và đúng trọng tâm hơn nhờ chọn từ khoá hợp lý, biết đánh giá độ tin cậy của một nguồn tin, và tôn trọng bản quyền khi sử dụng lại thông tin của người khác.","sections":[{"t":"story","text":"Hãy hình dung một thư viện khổng lồ, xếp hàng triệu quyển sách trên hàng nghìn kệ, trải dài qua nhiều tầng lầu. Một người bước vào, cần tìm đúng một cuốn sách hướng dẫn cách trồng cà chua trong chậu trên sân thượng.\n\nNếu cứ đi dọc từng kệ, giở từng quyển ra xem, có khi mất trọn một buổi vẫn chưa tìm ra, thậm chí bỏ cuộc giữa chừng vì nản. Nhưng nếu biết tra cứu mục lục, gõ đúng vài từ như “trồng cà chua trong chậu”, hệ thống sẽ chỉ thẳng đến đúng kệ, đúng quyển sách cần tìm; hoặc chỉ cần hỏi đúng người phụ trách mảng cây trồng, câu trả lời có khi đến trong chưa đầy một phút.\n\nInternet cũng là một “thư viện” như vậy, chỉ khác là nó lớn hơn gấp hàng triệu lần, và không có ai sắp xếp gọn gàng từng ngăn từng kệ theo một trật tự cố định. Muốn tìm đúng thứ mình cần giữa kho thông tin khổng lồ ấy, ta cũng phải biết cách hỏi — hỏi đúng từ, đúng cách. Nhưng tìm ra rồi vẫn chưa xong: còn phải biết thông tin đó có đáng tin hay không, và dùng lại nó sao cho đàng hoàng. Đó chính là nội dung của bài học này."},{"t":"h","text":"1) Vì sao cần biết cách khai thác thông tin số?"},{"t":"text","text":"Lượng thông tin tồn tại trên Internet lớn đến mức không một ai, dù dành cả đời, có thể đọc hết. Mỗi ngày có thêm hàng triệu bài viết, hình ảnh, video mới được đăng tải, phủ kín mọi chủ đề từ khoa học, lịch sử, cho đến nấu ăn hay sửa xe. Nhưng có quyền truy cập vào một kho thông tin khổng lồ như vậy **không tự động** khiến một người trở nên hiểu biết hơn.\n\nCùng đứng trước một câu hỏi, người biết cách khai thác thông tin số có thể tìm ra câu trả lời đáng tin cậy chỉ trong vài giây; người không biết cách có thể lạc giữa hàng nghìn kết quả, tin nhầm thông tin sai lệch mà không hay, hoặc bỏ cuộc vì không lọc ra được điều thật sự cần. Ba kĩ năng tạo nên sự khác biệt đó là: **tìm kiếm** đúng cách, **đánh giá** được độ tin cậy của thông tin tìm được, và **sử dụng lại thông tin một cách đàng hoàng**, tôn trọng công sức của người khác — cũng là ba nội dung chính của bài học này."},{"t":"h","text":"2) Tìm kiếm tốt: chọn từ khoá, thu hẹp kết quả"},{"t":"text","text":"Công cụ tìm kiếm không hiểu câu hỏi theo cách một người sẽ hiểu; nó làm việc bằng cách so khớp **từ khoá** — những từ hoặc cụm từ cốt lõi — với nội dung có sẵn trên các trang web. Vì vậy, gõ nguyên một câu hỏi dài dòng thường không hiệu quả bằng việc rút ra vài từ khoá ngắn gọn, đúng trọng tâm điều cần tìm; nên bỏ bớt những từ nối không cần thiết như “là gì”, “như thế nào”, “hãy cho biết”, vì chúng hầu như không giúp công cụ tìm kiếm khoanh vùng kết quả.\n\nNếu từ khoá vẫn còn quá chung chung, kết quả trả về có thể lên đến hàng triệu trang không liên quan. Khi đó, cách đơn giản nhất là **thêm từ khoá phụ** để thu hẹp đúng phạm vi cần tìm — ví dụ từ khoá `python` một mình có thể cho ra đủ loại kết quả, từ ngôn ngữ lập trình đến tên loài trăn; gõ thêm thành `python lập trình` sẽ giới hạn đúng vào chủ đề cần tìm. Còn khi cần tìm chính xác một cụm từ theo đúng thứ tự các từ, hãy **đặt cụm từ đó trong dấu ngoặc kép** — công cụ tìm kiếm khi đó sẽ chỉ trả về những trang có đúng nguyên văn cụm từ, thay vì các trang chỉ chứa rời rạc từng từ trong cụm."},{"t":"example","text":"Xét một tình huống cụ thể: cần tìm chính xác nguyên văn câu nói “học, học nữa, học mãi” để trích dẫn cho đúng, tránh nhầm với những cách diễn đạt tương tự.","code":"Không đặt trong ngoặc kép: học học nữa học mãi\nCó đặt trong ngoặc kép: \"học, học nữa, học mãi\"","output":"Không đặt trong ngoặc kép, kết quả trả về gồm mọi trang có chứa rời rạc các từ “học”, “nữa”, “mãi”, kể cả những trang không liên quan gì đến câu nói gốc. Đặt trong ngoặc kép, kết quả chỉ còn lại những trang có đúng nguyên văn cụm từ này, giúp xác minh chính xác nguồn gốc câu nói."},{"t":"h","text":"3) Đánh giá độ tin cậy của thông tin"},{"t":"list","text":"Không phải trang nào hiện lên trong kết quả tìm kiếm cũng đáng tin — Internet cho phép gần như bất kỳ ai cũng đăng được nội dung lên mạng, không qua khâu kiểm duyệt nào. Trước khi tin và dùng lại một thông tin, nên kiểm tra qua bốn điều sau:","items":["**Xem nguồn đăng tải**: thông tin từ cơ quan nhà nước, trường đại học, tổ chức chuyên môn hoặc chuyên gia có uy tín trong lĩnh vực đó thường đáng tin hơn một bài đăng không rõ tác giả trên mạng xã hội.","**Đối chiếu nhiều nguồn khác nhau**: nếu chỉ một trang duy nhất đưa tin, còn các nguồn uy tín khác không hề nhắc đến, khả năng cao thông tin đó chưa chính xác hoặc chưa được kiểm chứng đầy đủ.","**Xem thời gian cập nhật**: một bài viết về giá cả, quy định hay số liệu thống kê đăng từ nhiều năm trước có thể đã lỗi thời, không còn đúng với hiện tại.","**Cảnh giác với tin giật gân, tin có tiêu đề gây sốc**: những tiêu đề cố tình phóng đại, kích động cảm xúc mạnh thường nhằm câu lượt xem hơn là phản ánh đúng sự thật; gặp loại tin này, càng cần đối chiếu kỹ trước khi tin hoặc chia sẻ tiếp, tránh vô tình tiếp tay lan truyền tin sai lệch."]},{"t":"h","text":"4) Tôn trọng bản quyền khi sử dụng lại thông tin"},{"t":"text","text":"Thông tin trên Internet — dù là bài viết, hình ảnh, số liệu hay video — đều là công sức của một ai đó bỏ ra để tạo nên, và thường thuộc quyền sở hữu của người hoặc tổ chức đã tạo ra nó, gọi là **bản quyền**. Được tự do đọc, xem những nội dung ấy không có nghĩa là được phép lấy lại rồi trình bày như thể đó là sản phẩm của chính mình.\n\nKhi cần dùng lại một thông tin, số liệu hay hình ảnh lấy từ nguồn khác cho bài viết, bài làm của bản thân, hãy **trích dẫn nguồn**: nêu rõ thông tin đó lấy từ đâu — tên tác giả, tên trang web hoặc tài liệu gốc. Chẳng hạn, thay vì chỉ viết “dân số Việt Nam hơn 100 triệu người”, nên viết rõ hơn: “theo số liệu công bố trên trang Tổng cục Thống kê (2024), dân số Việt Nam đạt hơn 100 triệu người” — vừa đúng nội dung, vừa cho người đọc biết thông tin đến từ đâu để kiểm chứng lại nếu cần.\n\nChép nguyên văn một đoạn dài từ nguồn khác rồi nộp như thể tự mình viết ra — dù có đổi vài từ cho khác đi — vẫn là hành vi vi phạm bản quyền, gọi là **đạo văn**. Cách làm đúng là đọc hiểu nội dung gốc, viết lại theo cách hiểu và diễn đạt của chính mình, và luôn ghi rõ nguồn đã tham khảo."}],"keypoints":["**Internet** chứa lượng thông tin khổng lồ; có quyền truy cập chưa đủ để trở nên hiểu biết — phải biết **tìm kiếm**, **đánh giá** và **sử dụng** thông tin đúng cách mới thật sự khai thác được nó.","Tìm kiếm tốt: chọn **từ khoá** ngắn gọn, đúng trọng tâm; thu hẹp kết quả bằng cách thêm từ khoá phụ hoặc đặt cụm từ cần tìm chính xác trong **dấu ngoặc kép**.","Đánh giá độ tin cậy: ưu tiên nguồn chính thống hoặc chuyên gia, **đối chiếu nhiều nguồn**, xem thời gian cập nhật, cảnh giác tin giật gân hay tin giả.","Tôn trọng **bản quyền**: luôn **trích dẫn nguồn** khi dùng lại thông tin của người khác; chép nguyên văn rồi nhận là của mình là **đạo văn**."],"quiz":["CB-mc-501","CB-mc-502","CB-mc-503","CB-mc-504","CB-mc-505","CB-tf-501"]},
    {"id":"C11-06","stage":21,"order":6,"topic":"C","grade":11,"minutes":10,"title":"Cơ sở dữ liệu là gì và vì sao cần đến nó?","intro":"Bài học lí giải vì sao khi dữ liệu lớn dần và có nhiều người cùng dùng chung, cách ghi chép thủ công không còn đủ, và cơ sở dữ liệu ra đời để giải quyết vấn đề đó như thế nào.","sections":[{"t":"story","text":"Hãy tưởng tượng một trường học vẫn quản lí điểm bằng sổ điểm giấy. Mỗi giáo viên chủ nhiệm giữ một cuốn sổ riêng, tự tay ghi điểm của học sinh lớp mình. Cuối học kì, văn phòng cần tổng hợp điểm của cả trường để xét thi đua — nhân viên phải lật từng cuốn sổ, chép lại vào một bảng tổng hợp chung. Chữ viết tay đôi khi khó đọc, có chỗ bị tẩy xoá, có học sinh bị ghi thiếu một cột điểm, có trường hợp lại bị chép nhầm tên giữa sổ này với sổ khác. Muốn tìm điểm của một học sinh cụ thể, đôi khi phải lật giở mất vài phút mới ra.\n\nGiờ hãy so sánh với một trường đã dùng phần mềm quản lí học sinh: giáo viên nhập điểm một lần duy nhất trên máy, và bất kì ai được cấp quyền — hiệu trưởng, văn phòng, thậm chí phụ huynh — đều tra cứu ra kết quả chỉ trong vài giây, dữ liệu ở mọi nơi đều khớp nhau tuyệt đối. Sự khác biệt đó không đơn thuần nằm ở việc “có dùng máy tính” hay không, mà nằm ở cách dữ liệu được tổ chức. Đó chính là chủ đề của bài này: cơ sở dữ liệu."},{"t":"h","text":"1) Khi nào ghi chép thủ công không còn đủ"},{"t":"text","text":"Nếu bạn chỉ cần lưu vài chục số điện thoại của bạn bè, hoặc ghi lại chi tiêu cá nhân trong một tháng, một cuốn sổ tay hoặc một file bảng tính (`spreadsheet`) là quá đủ. Dữ liệu ít, chỉ một người dùng, không ai khác cần truy cập cùng lúc — chưa có gì phức tạp cần giải quyết.\n\nVấn đề chỉ thật sự xuất hiện khi hai điều kiện cùng xảy ra: dữ liệu tăng lên rất nhiều (hàng nghìn, hàng triệu bản ghi), và có nhiều người hoặc nhiều bộ phận cùng cần đọc, cùng cần sửa dữ liệu đó — giống hệt tình huống sổ điểm ở trên."},{"t":"list","text":"**Khi dữ liệu lớn dần và nhiều người cùng dùng chung, các vấn đề sau sẽ dần xuất hiện:**","items":["**Trùng lặp dữ liệu**: cùng một thông tin (ví dụ họ tên, lớp của một học sinh) bị chép lại ở nhiều cuốn sổ, nhiều file khác nhau.","**Khó tìm kiếm**: muốn biết một thông tin, phải lật giở hoặc mở lần lượt nhiều nơi mới tìm ra được.","**Dễ sai sót khi cập nhật**: sửa dữ liệu ở chỗ này nhưng quên sửa ở chỗ khác đang lưu cùng thông tin đó.","**Mâu thuẫn dữ liệu**: hai nơi cùng lưu một thông tin nhưng lại cho ra hai kết quả khác nhau, không biết nên tin theo bản nào."]},{"t":"h","text":"2) Cơ sở dữ liệu là gì"},{"t":"text","text":"**Cơ sở dữ liệu** (`database`) là một tập hợp dữ liệu có **tổ chức**, được lưu trữ trên máy tính theo một cấu trúc nhất quán, sao cho nhiều người và nhiều chương trình có thể **cùng truy cập, cùng khai thác** mà không giẫm chân lên nhau.\n\nĐiểm mấu chốt nằm ở chữ “có tổ chức”: dữ liệu được sắp xếp theo một cấu trúc rõ ràng — chẳng hạn theo dạng bảng, mỗi hàng là một đối tượng, mỗi cột là một thông tin — để phần mềm có thể tìm kiếm, lọc, cập nhật một cách nhanh chóng, chính xác. Nhờ vậy, mỗi thông tin lí tưởng chỉ cần lưu **một lần duy nhất** ở một nơi, giảm hẳn trùng lặp và mâu thuẫn đã nói ở trên.\n\nCần lưu ý: một file bảng tính lớn cũng có thể trông giống một bảng dữ liệu, nhưng cơ sở dữ liệu đúng nghĩa còn cần một **hệ quản trị cơ sở dữ liệu** — phần mềm đứng ra tổ chức, kiểm soát ai được xem, ai được sửa, và bảo vệ dữ liệu khi có nhiều người dùng cùng lúc. Nội dung này ta sẽ tìm hiểu kĩ hơn ở bài sau."},{"t":"example","text":"Thay vì rải điểm học sinh trên nhiều cuốn sổ của từng giáo viên, một cơ sở dữ liệu gom mọi thông tin cần thiết vào một bảng duy nhất, chẳng hạn bảng `HOC_SINH` gồm các cột Mã, Họ tên, Lớp, Điểm:","code":"Mã HS  | Họ tên           | Lớp   | Điểm\nHS001  | Nguyễn Văn A     | 11A1  | 8.5\nHS002  | Trần Thị B       | 11A2  | 7.0\nHS003  | Lê Văn C         | 11A1  | 9.0","output":"Mỗi học sinh chỉ xuất hiện đúng một dòng, mỗi thông tin (Họ tên, Lớp, Điểm) chỉ nằm ở một cột cố định. Ai cần tra điểm của “HS002” đều lấy từ đúng một dòng duy nhất này — không còn chuyện sổ này ghi khác, sổ kia ghi khác."},{"t":"h","text":"3) Cơ sở dữ liệu quanh ta và lợi ích của nó"},{"t":"list","text":"**Một khi để ý, bạn sẽ thấy cơ sở dữ liệu vận hành phía sau rất nhiều hoạt động quen thuộc:**","items":["**Thư viện**: lưu danh sách sách (tên sách, tác giả, số lượng) và danh sách người mượn — ai đang mượn cuốn nào, hạn trả khi nào.","**Trường học**: lưu hồ sơ học sinh, danh sách lớp học, điểm số, thời khoá biểu.","**Ngân hàng**: lưu thông tin tài khoản, số dư, lịch sử từng giao dịch — luôn đòi hỏi độ chính xác gần như tuyệt đối.","**Cửa hàng**: lưu danh mục hàng hoá, giá bán, số lượng tồn kho, hoá đơn đã bán ra."]},{"t":"list","text":"**So với việc rải dữ liệu trên nhiều sổ sách, nhiều file rời rạc, dùng cơ sở dữ liệu mang lại bốn lợi ích chính:**","items":["**Nhất quán**: mỗi thông tin chỉ lưu ở một nơi, nên không xảy ra tình trạng nơi này nói khác nơi kia.","**Chia sẻ được**: nhiều người, nhiều bộ phận, thậm chí nhiều phần mềm khác nhau có thể cùng khai thác một nguồn dữ liệu.","**Tìm kiếm nhanh**: nhờ dữ liệu có cấu trúc, máy tính lọc ra đúng thông tin cần trong tích tắc, dù dữ liệu lên tới hàng triệu bản ghi.","**An toàn hơn**: có thể phân quyền (ai được xem, ai được sửa) và sao lưu định kì, tránh mất mát hay bị chỉnh sửa tuỳ tiện."]}],"keypoints":["Khi dữ liệu còn ít, sổ sách hay bảng tính là đủ; vấn đề chỉ thật sự xuất hiện khi dữ liệu nhiều lên và có nhiều người cùng dùng chung, dẫn tới trùng lặp, khó tìm, sai sót, mâu thuẫn.","**Cơ sở dữ liệu** (`database`) là tập dữ liệu có tổ chức, lưu trên máy tính, cho phép nhiều người/chương trình cùng truy cập, giảm trùng lặp, dễ tìm kiếm và cập nhật.","Cơ sở dữ liệu có mặt trong nhiều hoạt động quen thuộc: quản lí thư viện, quản lí trường học, ngân hàng, cửa hàng.","Dùng cơ sở dữ liệu mang lại bốn lợi ích chính: nhất quán, chia sẻ được, tìm kiếm nhanh và an toàn hơn."],"quiz":["CB-mc-601","CB-mc-602","CB-mc-603","CB-mc-604","CB-mc-605","CB-tf-601"]},
    {"id":"C11-07","stage":21,"order":7,"topic":"C","grade":11,"minutes":12,"title":"Mô hình dữ liệu quan hệ: bảng, bản ghi, trường","intro":"Bài học này giới thiệu cách **cơ sở dữ liệu quan hệ** tổ chức dữ liệu thành các bảng, cùng bốn khái niệm nền tảng: bản ghi, trường, khoá chính và khoá ngoại — nền tảng để hiểu mọi hệ cơ sở dữ liệu và câu lệnh `SQL` sau này.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn đang giữ sổ theo dõi của một lớp học. Cuốn sổ được kẻ thành hàng và cột: mỗi hàng ghi thông tin của một học sinh, mỗi cột là một loại thông tin như họ tên hay lớp học. Một hôm, giáo viên gọi “Nguyễn Văn A” lên bảng — nhưng có đến hai người cùng đứng dậy, vì lớp có hai học sinh trùng tên. Muốn phân biệt chắc chắn, mỗi học sinh cần một mã số riêng, không ai giống ai.\n\nCách sắp xếp dữ liệu thành bảng gồm hàng và cột, cùng một mã số duy nhất để phân biệt từng người, chính là ý tưởng nền tảng của cách máy tính lưu trữ dữ liệu có tổ chức — gọi là **cơ sở dữ liệu quan hệ**."},{"t":"h","text":"Dữ liệu quan hệ: mọi thứ được xếp vào bảng"},{"t":"text","text":"Trong **cơ sở dữ liệu quan hệ** (`relational database`), dữ liệu không được ghi lộn xộn mà được sắp xếp thành các **bảng** (`table`) — giống như một bảng tính mà bạn vẫn thấy trong Excel hay Google Sheets.\n\nMỗi bảng thường lưu thông tin về một loại đối tượng. Chẳng hạn, một trường học có thể có một bảng lưu thông tin học sinh, một bảng khác lưu điểm số, một bảng khác nữa lưu thông tin giáo viên. Mỗi bảng có một cái tên, và bên trong được chia thành các hàng (dòng ngang) và các cột (dòng dọc)."},{"t":"example","text":"Đây là bảng `HOC_SINH`, dùng để lưu thông tin của từng học sinh trong lớp:","code":"Ma      HoTen           Lop\nHS01    Nguyễn Văn A    11A1\nHS02    Trần Thị B      11A2\nHS03    Nguyễn Văn A    11A3","output":"Bảng có 3 cột (`Ma`, `HoTen`, `Lop`) và 3 hàng dữ liệu; mỗi hàng là thông tin đầy đủ của một học sinh."},{"t":"text","text":"Trong bảng trên, mỗi HÀNG — ví dụ dòng `HS01, Nguyễn Văn A, 11A1` — được gọi là một **bản ghi** (`record`): nó gộp toàn bộ thông tin của một đối tượng cụ thể, ở đây là một học sinh. Còn mỗi CỘT — ví dụ cột `HoTen` — được gọi là một **trường** (`field`): một loại thông tin dùng chung cho mọi bản ghi trong bảng; trường `HoTen` luôn chứa họ tên, trường `Lop` luôn chứa tên lớp.\n\nNói ngắn gọn: một bảng gồm nhiều bản ghi xếp chồng lên nhau, còn mỗi bản ghi lại gồm nhiều trường xếp cạnh nhau."},{"t":"h","text":"Khoá chính: trường không bao giờ được trùng"},{"t":"text","text":"Nhìn lại bảng `HOC_SINH`, trường `HoTen` có thể trùng nhau — cả `HS01` và `HS03` đều tên **Nguyễn Văn A**. Nếu chỉ dựa vào họ tên, phần mềm không thể biết chắc đang nói đến bản ghi nào.\n\nVì vậy, mỗi bảng cần có một trường mà giá trị của nó không bao giờ trùng giữa hai bản ghi bất kì — trường đó gọi là **khoá chính** (`primary key`). Trong bảng `HOC_SINH`, trường `Ma` chính là khoá chính: mỗi học sinh có một mã số riêng, không ai trùng ai, nên chỉ cần biết `Ma` là xác định đúng một bản ghi duy nhất."},{"t":"note","text":"Khoá chính nên là một giá trị ổn định, không đổi theo thời gian. Mã học sinh (`Ma`) là lựa chọn tốt; còn `Lop` thì không phù hợp để làm khoá chính, vì một học sinh có thể chuyển sang lớp khác ở năm học sau, và bản thân `Lop` cũng không phải giá trị duy nhất — rất nhiều học sinh cùng học một lớp."},{"t":"h","text":"Khoá ngoại: sợi dây nối hai bảng với nhau"},{"t":"text","text":"Giả sử trường muốn lưu thêm điểm thi của từng môn học cho mỗi học sinh. Nếu tạo một bảng điểm mới và ghi lại đầy đủ họ tên, lớp cho từng dòng điểm, dữ liệu sẽ bị lặp đi lặp lại — một học sinh thi 5 môn thì họ tên, lớp của người đó phải gõ lại 5 lần.\n\nCách gọn hơn nhiều: bảng điểm chỉ cần lưu `Ma` (mã học sinh) thay vì lặp lại toàn bộ thông tin. Cột `Ma` trong bảng điểm lúc này đóng vai trò **khoá ngoại** (`foreign key`) — nó không tự mô tả điều gì, mà chỉ trỏ tới một bản ghi ở bảng khác, thông qua đúng giá trị khoá chính của bảng đó."},{"t":"example","text":"Bảng `DIEM` lưu điểm thi, liên kết với bảng `HOC_SINH` qua cột `Ma`:","code":"Ma      MonHoc     Diem\nHS01    Toán       8.5\nHS01    Văn        7.0\nHS02    Toán       9.0\nHS03    Toán       6.5","output":"Muốn biết dòng đầu tiên là điểm của ai, ta lấy `Ma = HS01`, đối chiếu sang bảng `HOC_SINH` và tìm được: Nguyễn Văn A, lớp 11A1. Bảng `DIEM` không cần lưu lại họ tên hay lớp — chỉ cần cột `Ma` để tham chiếu."},{"t":"list","text":"Nhờ tách dữ liệu thành nhiều bảng rồi liên kết bằng khoá ngoại, ta được lợi:","items":["Không phải gõ lại họ tên, lớp nhiều lần cho mỗi dòng điểm — tránh lặp dữ liệu, giảm sai sót khi nhập.","Khi một học sinh chuyển lớp, chỉ cần sửa đúng một dòng trong bảng `HOC_SINH`, không phải dò sửa khắp bảng điểm.","Có thể thêm bảng mới (ví dụ bảng khen thưởng) và liên kết với `HOC_SINH` qua cùng cột `Ma`, mà không đụng tới dữ liệu đã có.","Mỗi bảng chỉ tập trung lưu một loại thông tin, giúp dữ liệu rõ ràng và dễ tra cứu hơn."]}],"keypoints":["Cơ sở dữ liệu quan hệ tổ chức dữ liệu thành các **bảng** (`table`), mỗi bảng gồm nhiều hàng và cột.","Mỗi hàng là một **bản ghi** (`record`) — thông tin đầy đủ của một đối tượng; mỗi cột là một **trường** (`field`) — một loại thông tin dùng chung cho cả bảng.","**Khoá chính** (`primary key`) là trường có giá trị không bao giờ trùng nhau giữa các bản ghi, dùng để phân biệt chắc chắn từng bản ghi.","**Khoá ngoại** (`foreign key`) là trường ở một bảng dùng để tham chiếu tới khoá chính của bảng khác, nhờ đó các bảng liên kết được với nhau mà không phải lặp lại dữ liệu."],"quiz":["CB-mc-701","CB-mc-702","CB-mc-703","CB-mc-704","CB-mc-705","CB-tf-701"]},
    {"id":"C11-08","stage":21,"order":8,"topic":"C","grade":11,"minutes":10,"title":"Hệ quản trị cơ sở dữ liệu (DBMS)","intro":"Bài học này giới thiệu hệ quản trị cơ sở dữ liệu (DBMS) — phần mềm đóng vai trò trung gian giúp ta tạo, tìm kiếm, cập nhật và bảo vệ dữ liệu mà không phải tự tay can thiệp vào tệp dữ liệu thô, đồng thời tìm hiểu vai trò của người quản trị cơ sở dữ liệu trong việc vận hành hệ thống này.","sections":[{"t":"story","text":"Hãy tưởng tượng một thư viện có hàng chục nghìn cuốn sách. Nếu phải tự nhớ vị trí từng cuốn, tự ghi chép ai đang mượn sách nào, tự kiểm tra xem có cuốn nào bị mượn trùng hay chưa trả, công việc này gần như bất khả thi nếu chỉ làm một mình. Nhưng thư viện nào cũng có một người thủ thư giỏi: ta chỉ cần đến quầy và nói ‘cho tôi mượn cuốn này’ hoặc ‘tôi cần tìm sách về chủ đề kia’, còn việc tìm đúng cuốn, ghi sổ mượn, sắp xếp lại giá sách, từ chối nếu sách đã hết — người thủ thư lo hết, ta không cần biết cuốn sách đang nằm ở ngăn nào.\n\nDữ liệu trong máy tính cũng vậy. Một khối dữ liệu có hàng nghìn, hàng triệu dòng thông tin nếu để ta tự mở tệp, tự dò tìm và sửa từng dòng bằng tay thì vừa chậm vừa dễ gây sai sót. Vì vậy, dữ liệu cũng cần một ‘người thủ thư’ riêng cho mình — đó chính là hệ quản trị cơ sở dữ liệu, thường được gọi tắt là `DBMS`."},{"t":"h","text":"DBMS là gì?"},{"t":"text","text":"`DBMS` là viết tắt của Database Management System — **hệ quản trị cơ sở dữ liệu**. Đây là một **phần mềm** đứng giữa ta và khối dữ liệu thực sự được lưu trên máy tính. Dữ liệu gốc thường được tổ chức theo cấu trúc phức tạp, không tiện đọc hay sửa trực tiếp bằng tay. Thay vì tự mở những tệp đó, ta gửi yêu cầu cho DBMS — chẳng hạn ‘tìm những học sinh đạt điểm từ 8 trở lên’, ‘thêm một học sinh mới vào danh sách’ — và DBMS sẽ thực hiện đúng yêu cầu đó trên dữ liệu thực.\n\nCần phân biệt hai khái niệm dễ nhầm với nhau: **cơ sở dữ liệu** là bản thân khối dữ liệu được tổ chức và lưu trữ, giống như toàn bộ sách trong thư viện; còn **DBMS** là phần mềm quản lý khối dữ liệu đó, giống như người thủ thư. Không có DBMS, dữ liệu vẫn tồn tại, nhưng việc khai thác, cập nhật và bảo vệ nó sẽ rất khó khăn và dễ xảy ra sai sót."},{"t":"list","text":"Một số hệ quản trị cơ sở dữ liệu được dùng phổ biến hiện nay:","items":["`MySQL` — DBMS mã nguồn mở, thường dùng để lưu dữ liệu cho các trang web và ứng dụng.","`SQLite` — DBMS gọn nhẹ, toàn bộ dữ liệu nằm trong một tệp duy nhất, hay gặp trong điện thoại và các ứng dụng nhỏ.","`PostgreSQL` — DBMS mã nguồn mở, xử lý tốt dữ liệu lớn và phức tạp, dùng nhiều trong các hệ thống quy mô lớn.","`Microsoft Access` — DBMS có giao diện trực quan, dễ thao tác, phù hợp với người mới bắt đầu hoặc dữ liệu quy mô nhỏ."]},{"t":"h","text":"DBMS làm được những việc gì? Bốn nhóm chức năng chính"},{"t":"list","text":"Nói cụ thể, một DBMS đảm nhiệm bốn nhóm việc chính:","items":["Thêm, sửa, xoá, tìm dữ liệu — các thao tác cơ bản nhất mà người dùng cần trên dữ liệu.","Đảm bảo dữ liệu đúng và nhất quán — chẳng hạn không cho nhập điểm âm, không để hai học sinh trùng mã số.","Phân quyền truy cập — quyết định ai được xem, ai được sửa, ai không được động tới phần dữ liệu nào.","Sao lưu và phục hồi — giữ bản sao dữ liệu để khôi phục khi máy hỏng, mất điện hoặc thao tác nhầm."]},{"t":"example","text":"Giả sử một trường học có bảng dữ liệu `HOC_SINH` gồm các cột `Mã`, `Họ tên`, `Lớp`, `Điểm`. Khi giáo viên muốn xem danh sách học sinh đạt điểm từ 8 trở lên, giáo viên không tự mở tệp dữ liệu để dò từng dòng, mà gửi một yêu cầu cho DBMS dưới dạng câu lệnh sau:","code":"SELECT HoTen, Diem\nFROM HOC_SINH\nWHERE Diem >= 8;","output":"DBMS trả về đúng những dòng có Điểm từ 8 trở lên, chỉ gồm hai cột Họ tên và Điểm. Trong câu lệnh trên, SELECT nêu những cột muốn xem, FROM cho biết lấy dữ liệu từ bảng nào, còn WHERE là điều kiện lọc. Ta chỉ nêu yêu cầu, việc dò tìm chính xác trong toàn bộ dữ liệu là do DBMS thực hiện — đây chính là chức năng ‘tìm dữ liệu’ đã nhắc ở trên."},{"t":"h","text":"Người quản trị cơ sở dữ liệu (DBA)"},{"t":"text","text":"Nếu DBMS là ‘người thủ thư’ thực hiện các yêu cầu hằng ngày, thì đứng phía sau còn có một vai trò khác: **người quản trị cơ sở dữ liệu**, thường gọi tắt là `DBA` (Database Administrator). Đây là người thiết kế cấu trúc cơ sở dữ liệu ngay từ đầu (quyết định có những bảng nào, cột nào), cấp hoặc thu hồi quyền truy cập cho từng người dùng hoặc nhóm người dùng, đồng thời theo dõi và bảo trì hệ thống khi có sự cố xảy ra.\n\nDBA không phải là phần mềm, mà là con người sử dụng DBMS như công cụ để thực hiện những việc trên. Chẳng hạn trong một trường học, DBA có thể là người quyết định giáo viên chủ nhiệm chỉ được sửa điểm của lớp mình phụ trách, còn hiệu trưởng được xem điểm của toàn trường."}],"keypoints":["`DBMS` (hệ quản trị cơ sở dữ liệu) là **phần mềm** trung gian giúp tạo, lưu trữ, cập nhật, truy vấn và bảo vệ dữ liệu — ta thao tác qua DBMS chứ không tự sửa trực tiếp tệp dữ liệu thô.","Một số DBMS quen thuộc: `MySQL`, `SQLite`, `PostgreSQL`, `Microsoft Access`.","DBMS đảm nhiệm bốn nhóm việc chính: thêm/sửa/xoá/tìm dữ liệu; giữ dữ liệu đúng và nhất quán; phân quyền truy cập; sao lưu và phục hồi.","**Người quản trị cơ sở dữ liệu** (`DBA`) là người thiết kế cấu trúc, cấp quyền truy cập và bảo trì hệ thống — DBA là con người, không phải phần mềm."],"quiz":["CB-mc-801","CB-mc-802","CB-mc-803","CB-mc-804","CB-mc-805","CB-tf-801"]},
    {"id":"C11-09","stage":21,"order":9,"topic":"C","grade":11,"minutes":12,"title":"SQL: truy vấn dữ liệu với câu lệnh SELECT","intro":"Cơ sở dữ liệu có thể lưu hàng nghìn dòng thông tin, nhưng muốn lấy đúng phần mình cần thì phải biết cách ‘hỏi’ đúng ngôn ngữ của nó. Bài này giới thiệu câu lệnh `SELECT` — công cụ cơ bản nhất của SQL để truy vấn, lọc và sắp xếp dữ liệu.","sections":[{"t":"story","text":"Cuối học kỳ, sổ điểm của một trường có thể ghi đến hàng nghìn dòng — mỗi dòng là thông tin của một học sinh: lớp nào, điểm bao nhiêu. Giả sử có người đến văn phòng nhà trường và chỉ nói: ‘cho tôi xem điểm học sinh’. Người trực văn phòng chắc chắn sẽ hỏi ngược lại: điểm của ai, lớp nào, học kỳ nào? Câu hỏi mơ hồ như vậy không thể trả lời ngay được. Nhưng nếu hỏi thật rõ ràng: ‘cho tôi tên những bạn có điểm từ 8 trở lên, xếp từ cao xuống’, yêu cầu đã đủ cụ thể để tra cứu và trả lời chính xác, không cần hỏi lại thêm gì nữa.\n\nCơ sở dữ liệu hoạt động đúng theo tinh thần đó: máy tính không hiểu nổi một câu hỏi mơ hồ, nhưng hiểu rất chính xác một ngôn ngữ hỏi–đáp có cấu trúc, gọi là **SQL**. Bài này sẽ tập cho ta cách đặt câu hỏi kiểu trên sao cho máy hiểu đúng và trả lời đúng ý."},{"t":"h","text":"SQL là gì và cấu trúc câu lệnh SELECT"},{"t":"text","text":"**SQL** (Structured Query Language — ngôn ngữ truy vấn có cấu trúc) là ngôn ngữ dùng để giao tiếp với cơ sở dữ liệu quan hệ: xin lấy dữ liệu, thêm dữ liệu mới, hoặc sửa/xoá dữ liệu đã có. Bài này chỉ tập trung vào việc **xin lấy dữ liệu** — hành động này gọi là **truy vấn** (query), thực hiện bằng câu lệnh `SELECT`. Một câu lệnh SQL luôn kết thúc bằng dấu chấm phẩy `;`, giống như một câu nói cần dấu chấm để biết đã nói xong.\n\nCấu trúc truy vấn cơ bản nhất gồm ba phần, viết theo đúng thứ tự:\n\n`SELECT <các cột> FROM <bảng> WHERE <điều kiện>;`\n\nTrong đó, `SELECT` nêu những **cột nào cần lấy** (muốn xem thông tin gì), `FROM` nêu **lấy từ bảng nào** (dữ liệu nằm ở đâu), còn `WHERE` nêu **điều kiện lọc** (chỉ lấy những dòng thoả điều kiện đó). Có thể hình dung: FROM trả lời câu ‘tìm ở đâu’, WHERE trả lời câu ‘tìm cái gì’, còn SELECT trả lời câu ‘hiển thị phần nào’."},{"t":"list","text":"Để thực hành, bài học dùng một bảng tên `HOC_SINH` gồm 4 cột theo thứ tự `Ma` (mã học sinh), `HoTen` (họ tên), `Lop` (lớp), `Diem` (điểm trung bình). Giả sử bảng đang lưu 5 dòng dữ liệu sau (viết theo thứ tự Ma – HoTen – Lop – Diem):","items":["HS001 – Nguyễn Văn An – 11A1 – 7.5","HS002 – Trần Thị Bình – 11A1 – 9.0","HS003 – Lê Văn Cường – 11A2 – 6.0","HS004 – Phạm Thị Dung – 11A2 – 8.5","HS005 – Hoàng Văn Em – 11A1 – 8.0"]},{"t":"example","text":"Ở bài trước, khi cần xem những học sinh đạt điểm từ 8 trở lên, DBMS đã chạy đúng câu lệnh dưới đây — giờ ta sẽ hiểu vì sao nó hoạt động. Áp dụng cấu trúc SELECT–FROM–WHERE: `SELECT HoTen, Diem` chọn hai cột cần xem, `FROM HOC_SINH` lấy dữ liệu từ đúng bảng, `WHERE Diem >= 8` chỉ giữ lại những dòng thoả điều kiện.","code":"SELECT HoTen, Diem\nFROM HOC_SINH\nWHERE Diem >= 8;","output":"Trả về 3 dòng, chỉ gồm hai cột HoTen và Diem (đối chiếu với dữ liệu mẫu ở trên): Trần Thị Bình – 9.0, Phạm Thị Dung – 8.5, Hoàng Văn Em – 8.0. Hai học sinh có điểm dưới 8 là Nguyễn Văn An (7.5) và Lê Văn Cường (6.0) bị loại vì không thoả điều kiện WHERE."},{"t":"h","text":"Lấy tất cả các cột: SELECT *"},{"t":"text","text":"Nếu muốn xem **toàn bộ các cột** của bảng mà không cần gõ tên từng cột, dùng dấu `*` (đọc là ‘tất cả’) ngay sau SELECT. Cách viết này tiện khi ta chưa chắc cần cột nào, hoặc muốn xem toàn cảnh dữ liệu trước khi thu hẹp lại bằng WHERE."},{"t":"example","text":"Ví dụ: xem toàn bộ thông tin của những học sinh thuộc lớp 11A1.","code":"SELECT *\nFROM HOC_SINH\nWHERE Lop = '11A1';","output":"Trả về đủ cả 4 cột (Ma, HoTen, Lop, Diem), nhưng chỉ những dòng có Lop bằng ‘11A1’: HS001 (Nguyễn Văn An – 7.5), HS002 (Trần Thị Bình – 9.0), HS005 (Hoàng Văn Em – 8.0). Chú ý điều kiện so sánh **chữ** (văn bản) phải đặt trong cặp nháy đơn như `'11A1'`, khác với so sánh **số** như `Diem >= 8` thì không cần nháy."},{"t":"h","text":"Sắp xếp kết quả: ORDER BY"},{"t":"text","text":"Mặc định, thứ tự các dòng trả về không được đảm bảo theo ý ta muốn. Muốn **sắp xếp** kết quả theo một cột, thêm `ORDER BY <tên cột>` vào cuối câu lệnh (sau WHERE, nếu có). Viết thêm `ASC` (ascending) để sắp **tăng dần** — từ thấp đến cao (đây cũng là cách sắp xếp mặc định nếu không ghi gì); hoặc viết `DESC` (descending) để sắp **giảm dần** — từ cao đến thấp.\n\nTrong mệnh đề WHERE, ta còn có thể so sánh bằng các dấu quen thuộc `=`, `>`, `<`, `>=`, và kết hợp nhiều điều kiện cùng lúc bằng `AND` (bắt buộc CẢ HAI điều kiện cùng đúng) hoặc `OR` (chỉ cần MỘT trong hai điều kiện đúng). Việc này cũng giống như khi tìm một phòng trọ với yêu cầu ‘gần trường VÀ giá dưới hai triệu’ — cả hai điều kiện phải đúng cùng lúc mới chọn — so với yêu cầu ‘rảnh thứ Bảy HOẶC Chủ nhật’ — chỉ cần một trong hai ngày đúng là đủ."},{"t":"example","text":"Quay lại đúng câu hỏi mở đầu bài: ‘cho tôi tên những bạn có điểm từ 8 trở lên, xếp từ cao xuống’. Kết hợp WHERE để lọc và ORDER BY để sắp xếp, ta viết được câu hỏi đó bằng SQL:","code":"SELECT HoTen, Diem\nFROM HOC_SINH\nWHERE Diem >= 8\nORDER BY Diem DESC;","output":"Trả về 3 dòng — đúng những học sinh có Diem từ 8 trở lên — và đã được sắp theo Diem giảm dần: Trần Thị Bình – 9.0, Phạm Thị Dung – 8.5, Hoàng Văn Em – 8.0. So với ví dụ đầu bài, tập kết quả giống nhau nhưng nay đã có thứ tự rõ ràng nhờ ORDER BY."},{"t":"note","text":"Một vài lưu ý khi viết SQL: giá trị **chữ** (văn bản) trong điều kiện phải đặt trong cặp nháy đơn, ví dụ `Lop = '11A1'`; còn giá trị **số** thì viết trực tiếp, không cần nháy, ví dụ `Diem >= 8`. Nếu bỏ hẳn mệnh đề WHERE, câu lệnh sẽ trả về toàn bộ các dòng của bảng, không lọc gì cả."}],"keypoints":["SQL là ngôn ngữ dùng để ‘hỏi’ cơ sở dữ liệu; câu lệnh `SELECT` dùng để truy vấn (xin lấy) dữ liệu.","Cấu trúc cơ bản: `SELECT <cột> FROM <bảng> WHERE <điều kiện>;` — SELECT chọn cột cần lấy, FROM chỉ bảng, WHERE lọc theo điều kiện.","`SELECT *` lấy toàn bộ các cột của bảng; `ORDER BY <cột> ASC/DESC` sắp xếp kết quả tăng dần hoặc giảm dần.","Mệnh đề WHERE dùng các phép so sánh `=, >, <, >=` và có thể kết hợp nhiều điều kiện bằng `AND` (cả hai cùng đúng) hoặc `OR` (một trong hai đúng)."],"quiz":["CB-mc-901","CB-mc-902","CB-mc-903","CB-mc-904","CB-mc-905","CB-tf-901"]},
    {"id":"C11-10","stage":21,"order":10,"topic":"C","grade":11,"minutes":11,"title":"SQL: thêm, sửa và xoá dữ liệu","intro":"Bên cạnh việc truy vấn để xem dữ liệu, SQL còn cho phép thay đổi dữ liệu đã lưu bằng ba lệnh `INSERT`, `UPDATE` và `DELETE`. Bài học chỉ ra cách dùng từng lệnh, và vì sao mệnh đề `WHERE` lại quan trọng đến mức có thể quyết định cả một bảng dữ liệu còn nguyên vẹn hay biến mất chỉ trong một câu lệnh.","sections":[{"t":"story","text":"Hãy tưởng tượng một câu lạc bộ ở trường có một cuốn sổ ghi danh sách thành viên, mỗi dòng ghi mã số, họ tên, lớp và điểm rèn luyện của một người. Cuốn sổ này không thể đứng yên mãi: có người mới xin gia nhập, cần **thêm** hẳn một dòng mới; có người bị ghi nhầm lớp hoặc điểm, cần **sửa** lại đúng dòng đó cho khớp thực tế; có người đã rời câu lạc bộ, cần **gạch bỏ** dòng của người đó khỏi sổ.\n\nNgười phụ trách sổ luôn phải làm việc này rất cẩn thận: mỗi lần sửa hay gạch bỏ, phải chỉ ra đúng chính xác dòng nào, đúng người nào. Nếu chỉ định mơ hồ, hoặc tệ hơn là quên mất việc chỉ định, rất có thể cả cuốn sổ sẽ bị sửa hoặc xoá sạch chỉ trong một lần đặt bút — điều không ai muốn xảy ra.\n\nCơ sở dữ liệu vận hành y hệt như vậy. Công cụ để **thêm, sửa, xoá** dữ liệu trong một bảng chính là ba câu lệnh SQL: `INSERT`, `UPDATE` và `DELETE`."},{"t":"h","text":"1) Ba việc có thể làm với dữ liệu đã lưu"},{"t":"text","text":"Từ trước tới nay, `SELECT` được dùng để **truy vấn** — nghĩa là xem dữ liệu đang có mà không làm thay đổi gì trong bảng cả. Nhưng một bảng dữ liệu thật sự, chẳng hạn bảng `HOC_SINH` (gồm các cột `Ma`, `HoTen`, `Lop`, `Diem`) của một lớp học, không thể chỉ đứng yên để xem: mỗi năm có học sinh mới nhập học, có điểm bị nhập sai cần chỉnh lại, có học sinh chuyển trường cần gỡ khỏi danh sách.\n\nSQL cung cấp đúng ba lệnh để làm những việc đó: `INSERT` (thêm một dòng mới), `UPDATE` (sửa giá trị trong dòng đã có) và `DELETE` (xoá hẳn một dòng). Ba lệnh này thường được gọi chung là các lệnh **thao tác dữ liệu**, vì chúng làm thay đổi nội dung của bảng, thay vì chỉ đọc dữ liệu ra như `SELECT`."},{"t":"h","text":"2) Thêm dữ liệu mới với `INSERT INTO`"},{"t":"example","text":"Cú pháp tổng quát: `INSERT INTO bảng (cột1, cột2, ...) VALUES (giá_trị1, giá_trị2, ...);`. Ta liệt kê tên các cột muốn ghi dữ liệu vào trong cặp ngoặc đầu tiên, rồi liệt kê giá trị tương ứng trong cặp ngoặc sau `VALUES`, theo đúng thứ tự đó. Giả sử có một học sinh mới tên Nguyễn Văn Bình vừa chuyển vào lớp 11A3, cần thêm vào bảng `HOC_SINH`:","code":"INSERT INTO HOC_SINH (Ma, HoTen, Lop, Diem)\nVALUES ('HS021', 'Nguyễn Văn Bình', '11A3', 8.5);","output":"Bảng HOC_SINH có thêm đúng một dòng mới ở cuối bảng: Ma là HS021, HoTen là Nguyễn Văn Bình, Lop là 11A3, Diem là 8.5. Các dòng đang có sẵn trong bảng không hề bị ảnh hưởng."},{"t":"h","text":"3) Sửa dữ liệu đã có với `UPDATE`, `SET` và `WHERE`"},{"t":"example","text":"Cú pháp tổng quát: `UPDATE bảng SET cột = giá_trị_mới WHERE điều_kiện;`. Mệnh đề `SET` cho biết cột nào sẽ được ghi đè bằng giá trị gì; mệnh đề `WHERE` cho biết chỉ áp dụng cho (những) dòng nào — đây là phần bắt buộc phải suy nghĩ thật kỹ. Ít lâu sau, phát hiện điểm của học sinh mã HS021 bị nhập sai, đúng ra phải là 9.0:","code":"UPDATE HOC_SINH\nSET Diem = 9.0\nWHERE Ma = 'HS021';","output":"Chỉ riêng dòng có Ma bằng HS021 được đổi Diem thành 9.0; toàn bộ các dòng còn lại trong bảng vẫn giữ nguyên giá trị cũ, kể cả những học sinh khác cũng đang học lớp 11A3."},{"t":"h","text":"4) Xoá dữ liệu không cần nữa với `DELETE FROM` và `WHERE`"},{"t":"example","text":"Cú pháp tổng quát: `DELETE FROM bảng WHERE điều_kiện;`. Lệnh này xoá hẳn (những) dòng thoả điều kiện ra khỏi bảng — dữ liệu mất đi hoàn toàn, không phải chỉ ẩn đi. Đến cuối học kỳ, học sinh mã HS021 chuyển trường, không còn thuộc lớp 11A3 nữa, cần gỡ khỏi bảng:","code":"DELETE FROM HOC_SINH\nWHERE Ma = 'HS021';","output":"Dòng có Ma bằng HS021 biến mất hoàn toàn khỏi bảng HOC_SINH; số dòng của bảng giảm đi đúng một, các dòng khác vẫn nguyên vẹn."},{"t":"note","text":"Nhìn lại hai câu lệnh `UPDATE` và `DELETE` vừa rồi: cả hai đều có `WHERE Ma = 'HS021'`. Đây không phải là chi tiết tuỳ chọn — nó quyết định phạm vi ảnh hưởng của cả câu lệnh. Nếu chẳng may quên hẳn `WHERE`, ví dụ viết `UPDATE HOC_SINH SET Diem = 9.0;`, hệ quản trị sẽ hiểu là áp dụng cho **tất cả mọi dòng** đang có trong bảng — toàn bộ điểm của cả lớp sẽ bị ghi đè thành 9.0 chỉ trong một câu lệnh. Tương tự, `DELETE FROM HOC_SINH;` không kèm `WHERE` sẽ xoá sạch toàn bộ bảng, không sót lại một dòng nào. Đây là một trong những lỗi tai hại nhất khi làm việc với cơ sở dữ liệu, vì sau khi lệnh đã chạy xong, thường không còn cách nào lấy lại dữ liệu cũ nếu chưa sao lưu từ trước.\n\nMột thói quen an toàn: trước khi chạy `UPDATE` hoặc `DELETE` thật sự, hãy thử chạy một câu `SELECT` với đúng điều kiện `WHERE` đó trước, để chắc chắn nó chỉ trúng đúng (những) dòng mình muốn thay đổi."}],"keypoints":["Ba lệnh thao tác dữ liệu trong SQL là `INSERT` (thêm), `UPDATE` (sửa) và `DELETE` (xoá) — khác với `SELECT` chỉ dùng để xem dữ liệu.","`INSERT INTO bảng (cột...) VALUES (giá_trị...);` thêm một dòng mới, với các giá trị khớp đúng thứ tự các cột đã liệt kê.","`UPDATE bảng SET cột = giá_trị WHERE điều_kiện;` chỉ sửa (những) dòng thoả điều kiện; `DELETE FROM bảng WHERE điều_kiện;` chỉ xoá (những) dòng đó.","Quên mệnh đề `WHERE` trong `UPDATE` hoặc `DELETE` là lỗi rất nguy hiểm: lệnh sẽ áp dụng cho **TOÀN BỘ** các dòng đang có trong bảng, không chỉ riêng dòng bạn muốn thay đổi."],"quiz":["CB-mc-1001","CB-mc-1002","CB-mc-1003","CB-mc-1004","CB-mc-1005","CB-tf-1001"]},
    {"id":"C11-11","stage":21,"order":11,"topic":"C","grade":11,"minutes":11,"title":"An toàn và toàn vẹn dữ liệu trong cơ sở dữ liệu","intro":"Bài học này giới thiệu những biện pháp cơ bản giúp một cơ sở dữ liệu vừa an toàn (không bị truy cập, sửa hay lấy đi trái phép) vừa toàn vẹn (dữ liệu luôn hợp lý, nhất quán) — gồm phân quyền truy cập, sao lưu và phục hồi, ràng buộc toàn vẹn, cùng một số biện pháp bảo mật hệ thống khác mà ta thường gặp.","sections":[{"t":"story","text":"Hãy hình dung một cửa hàng tạp hoá nhỏ. Tiền mặt và sổ sách kế toán được cất trong một két sắt; chỉ chủ cửa hàng và người quản lý được giao chìa khoá, còn nhân viên bán hàng bình thường thì không được đụng tới. Mỗi tối, chủ cửa hàng chép lại toàn bộ sổ doanh thu trong ngày sang một cuốn sổ phụ, mang cất ở một nơi khác hẳn — để nếu cuốn sổ chính chẳng may bị cháy, bị ướt hay thất lạc thì vẫn còn dữ liệu để đối chiếu, khôi phục lại. Cửa hàng còn đặt ra những nguyên tắc ghi chép rất rõ ràng: số tiền không bao giờ được ghi âm, mỗi mã hàng chỉ được xuất hiện đúng một lần trong danh mục — hễ ai ghi nhầm, con số bất thường sẽ lộ ra ngay khi đối chiếu sổ sách.\n\nMột cơ sở dữ liệu mà ta xây dựng trên máy tính cũng cần được đối xử tương tự như vậy: vừa phải **an toàn** (không phải ai cũng được xem, sửa hay lấy dữ liệu đi), vừa phải **toàn vẹn** (số liệu luôn hợp lý, khớp nhau, không mâu thuẫn). Thiếu một trong hai điều đó, dữ liệu dù nhiều đến đâu cũng khó mà tin tưởng được."},{"t":"h","text":"Dữ liệu — tài sản cần được bảo vệ"},{"t":"text","text":"Trong một hệ thống thật — trường học, bệnh viện, ngân hàng, cửa hàng... — cơ sở dữ liệu lưu những thông tin gắn liền với hoạt động hằng ngày: điểm số, hồ sơ bệnh án, số dư tài khoản, đơn hàng. Nếu dữ liệu đó bị lộ ra ngoài, bị kẻ xấu sửa đổi, hoặc đơn giản là bị mất do sự cố kỹ thuật, hậu quả có thể rất nghiêm trọng — từ thiệt hại tiền bạc, lộ thông tin riêng tư, cho đến việc cả một tổ chức phải ra quyết định dựa trên số liệu sai.\n\nVì vậy, khi xây dựng và vận hành một cơ sở dữ liệu, ta luôn phải tính đến hai yêu cầu song song. **An toàn dữ liệu** nghĩa là chỉ những người, những chương trình được cấp phép mới được truy cập hoặc thay đổi dữ liệu; dữ liệu cũng phải được bảo vệ khỏi nguy cơ mất mát. **Toàn vẹn dữ liệu** nghĩa là bản thân nội dung dữ liệu luôn hợp lý, nhất quán — không có giá trị vô lý, không có mâu thuẫn giữa các bảng liên quan tới nhau. Các phần sau sẽ đi vào từng biện pháp cụ thể để đạt được hai điều này."},{"t":"h","text":"Phân quyền truy cập"},{"t":"text","text":"Biện pháp cơ bản nhất là **phân quyền truy cập**: mỗi tài khoản sử dụng hệ thống chỉ được cấp đúng những quyền cần thiết cho công việc của người đó, không hơn không kém. Hai quyền phổ biến nhất là quyền **xem** (đọc dữ liệu) và quyền **sửa** (thêm, sửa, xoá dữ liệu); phạm vi của mỗi quyền còn có thể giới hạn trong một số bảng, thậm chí một số cột nhất định.\n\nVí dụ trong cơ sở dữ liệu của một trường học: giáo viên bộ môn được cấp quyền nhập và sửa điểm cho lớp mình phụ trách, nhưng không được sửa điểm của lớp khác; học sinh chỉ được cấp quyền xem điểm của chính mình, không được sửa bất kỳ điểm nào, kể cả điểm của bản thân; còn quản trị viên hệ thống mới có quyền tạo, xoá tài khoản người dùng và cấp quyền cho từng người. Nhờ phân quyền như vậy, dù một tài khoản chẳng may bị lộ mật khẩu, thiệt hại gây ra cũng chỉ giới hạn trong phạm vi quyền mà tài khoản đó được cấp, không ảnh hưởng tới toàn bộ hệ thống."},{"t":"h","text":"Sao lưu, phục hồi và một số lớp bảo vệ khác"},{"t":"list","text":"Phân quyền chỉ giải quyết được việc ai được làm gì; hệ thống còn cần thêm những lớp bảo vệ khác để chống lại rủi ro mất dữ liệu hoặc bị xâm nhập từ bên ngoài:","items":["**Sao lưu định kỳ**: định kỳ (mỗi ngày, mỗi tuần...) chép toàn bộ hoặc một phần dữ liệu sang một nơi lưu trữ khác hẳn với dữ liệu gốc — nếu để chung một chỗ, một sự cố duy nhất (cháy, hỏng ổ đĩa, mã độc...) có thể phá huỷ cả hai cùng lúc.","**Phục hồi dữ liệu**: khi dữ liệu gốc bị hỏng, bị xoá nhầm hoặc bị phá hoại, dùng bản sao lưu gần nhất để khôi phục lại hệ thống, hạn chế tối đa phần dữ liệu bị mất.","**Đặt mật khẩu và xác thực người dùng**: chỉ những tài khoản có mật khẩu (hoặc phương thức xác thực khác) hợp lệ mới đăng nhập và sử dụng được hệ thống.","**Mã hoá dữ liệu nhạy cảm**: những dữ liệu quan trọng (mật khẩu, thông tin cá nhân...) được biến đổi sang dạng không thể đọc trực tiếp, để dù tệp dữ liệu có bị đánh cắp, kẻ xấu cũng khó khai thác được.","**Ghi nhật ký truy cập**: hệ thống tự động lưu lại ai đã truy cập, làm gì, vào lúc nào — giúp truy vết khi có sự cố hoặc dấu hiệu bất thường."]},{"t":"h","text":"Toàn vẹn dữ liệu: đặt ràng buộc để dữ liệu luôn hợp lý"},{"t":"text","text":"Bên cạnh việc kiểm soát ai được truy cập, hệ quản trị cơ sở dữ liệu (`DBMS`) còn có thể tự kiểm tra xem dữ liệu được nhập vào có hợp lý hay không, thông qua các **ràng buộc toàn vẹn**. Đây là những quy tắc được khai báo sẵn ngay khi tạo bảng; hễ có thao tác thêm hoặc sửa dữ liệu vi phạm quy tắc, `DBMS` sẽ tự động từ chối, không cần chờ con người phát hiện ra sai sót.\n\nBa loại ràng buộc thường gặp là: **ràng buộc miền giá trị** — giới hạn giá trị hợp lệ của một cột, ví dụ cột Điểm chỉ được nhận giá trị từ 0 đến 10; **ràng buộc khoá** — đảm bảo một cột (hoặc nhóm cột) đóng vai trò khoá chính không có hai dòng nào trùng giá trị, ví dụ Mã học sinh phải là duy nhất; và **ràng buộc tham chiếu** — đảm bảo giá trị ở một bảng phải khớp với một giá trị đã tồn tại ở bảng khác mà nó tham chiếu tới, nhờ đó tránh được tình trạng mâu thuẫn giữa các bảng có liên quan với nhau."},{"t":"example","text":"Xét bảng `HOC_SINH` với `MaHS` là khoá chính, cột `Diem` chỉ nhận giá trị hợp lệ từ 0 đến 10:","code":"CREATE TABLE HOC_SINH (\n    MaHS VARCHAR(10) PRIMARY KEY,\n    HoTen VARCHAR(50),\n    Lop VARCHAR(10),\n    Diem FLOAT CHECK (Diem >= 0 AND Diem <= 10)\n);\n\nINSERT INTO HOC_SINH VALUES ('HS01', 'Nguyen Van A', '11A1', 12);","output":"Câu lệnh `CREATE TABLE` khai báo hai ràng buộc: `MaHS` là `PRIMARY KEY` (ràng buộc khoá — không được trùng), còn `Diem` có thêm `CHECK (Diem >= 0 AND Diem <= 10)` (ràng buộc miền giá trị). Vì vậy, câu lệnh `INSERT` phía dưới sẽ bị `DBMS` từ chối và báo lỗi vi phạm ràng buộc `CHECK`, do 12 nằm ngoài khoảng 0–10. Nếu sửa lại giá trị Điểm thành một số hợp lệ, chẳng hạn 8.5, dòng dữ liệu sẽ được thêm thành công vào bảng."},{"t":"note","text":"An toàn và toàn vẹn là hai việc khác nhau, cần làm song song, không thể thay thế cho nhau. Một cơ sở dữ liệu có ràng buộc chặt chẽ nhưng không phân quyền, không mật khẩu thì dữ liệu tuy hợp lý nhưng ai cũng có thể xem hoặc sửa được. Ngược lại, một hệ thống canh gác truy cập rất kỹ nhưng không đặt ràng buộc nào thì dữ liệu tuy kín đáo nhưng vẫn có thể sai lệch, mâu thuẫn ngay từ bên trong. Một cơ sở dữ liệu đáng tin cậy cần cả hai."}],"keypoints":["Một cơ sở dữ liệu đáng tin cậy phải vừa **an toàn** (không bị truy cập, sửa đổi hay lấy đi trái phép) vừa **toàn vẹn** (dữ liệu luôn hợp lý, nhất quán).","**Phân quyền truy cập** giúp mỗi người dùng chỉ xem hoặc sửa đúng phần dữ liệu cần thiết cho công việc của họ — ví dụ giáo viên nhập điểm, còn học sinh chỉ được xem.","**Sao lưu định kỳ** (ở một nơi khác với dữ liệu gốc) giúp **phục hồi** dữ liệu khi gặp sự cố; kết hợp thêm mật khẩu, mã hoá và nhật ký truy cập để tăng cường bảo mật.","**Ràng buộc toàn vẹn** (miền giá trị, khoá, tham chiếu) giúp `DBMS` tự động từ chối dữ liệu sai hoặc mâu thuẫn giữa các bảng, không cần chờ con người phát hiện."],"quiz":["CB-mc-1101","CB-mc-1102","CB-mc-1103","CB-mc-1104","CB-mc-1105","CB-tf-1101"]},
    {"id":"C11-12","stage":21,"order":12,"topic":"F","grade":11,"minutes":12,"title":"Mảng một chiều và cách xử lí dãy số","intro":"Bài này giới thiệu cách Python lưu và xử lí một dãy nhiều giá trị cùng loại bằng `list` — mảng một chiều — cùng những thao tác cơ bản nhất trên một dãy số: duyệt, tính tổng, tính trung bình, đếm theo điều kiện, và tìm giá trị lớn nhất, nhỏ nhất.","sections":[{"t":"story","text":"Hãy tưởng tượng một dãy ngăn kéo dài, đặt sát nhau thành một hàng, phía trên mỗi ngăn có dán một con số thứ tự bắt đầu từ 0: ngăn số 0, ngăn số 1, ngăn số 2... Mỗi ngăn chỉ đựng đúng một giá trị, chẳng hạn một điểm số. Muốn biết giá trị ở ngăn thứ ba, bạn không cần mở lần lượt từng ngăn từ đầu — chỉ cần nhớ đúng số thứ tự rồi mở thẳng ngăn đó ra. Khi một lớp học có vài chục điểm số, hay một trạm đo ghi nhiệt độ của cả một tháng, việc gom tất cả giá trị vào một dãy ngăn kéo đánh số như vậy giúp xử lí gọn gàng hơn nhiều so với việc đặt cho mỗi giá trị một cái tên riêng. Trong lập trình, cấu trúc đóng vai trò dãy ngăn kéo ấy được gọi là **mảng một chiều**; trong Python, nó được cài đặt bằng kiểu dữ liệu `list`."},{"t":"h","text":"Danh sách: mảng một chiều trong Python"},{"t":"text","text":"Ở các bài trước, mỗi giá trị thường được gán cho một biến riêng, chẳng hạn diem1, diem2, diem3. Cách này chỉ ổn khi số lượng giá trị rất ít. Nếu một lớp có 40 học sinh, chắc bạn cũng không muốn viết 40 biến diem1 đến diem40 rồi lặp lại gần như cùng một đoạn code 40 lần.\n\nPython giải quyết vấn đề này bằng `list` — một kiểu dữ liệu cho phép gom nhiều giá trị cùng loại (ví dụ toàn bộ là số thực) vào một cái tên duy nhất, giữ đúng thứ tự đã nhập. Khai báo một `list` rất đơn giản: chỉ cần đặt các giá trị trong cặp ngoặc vuông, cách nhau bởi dấu phẩy, ví dụ `diem = [7.5, 8.0, 6.5, 9.0, 5.5]`.\n\nMỗi giá trị bên trong `list` gọi là một **phần tử**, và mỗi phần tử có một **chỉ số** (index) cho biết vị trí của nó trong dãy. Điều cần nhớ kĩ: Python đánh chỉ số bắt đầu từ 0, không phải từ 1. Vậy phần tử đầu tiên là `diem[0]`, phần tử thứ hai là `diem[1]`, còn phần tử cuối cùng của một danh sách có 5 phần tử là `diem[4]` chứ không phải `diem[5]`."},{"t":"h","text":"Duyệt danh sách bằng vòng lặp for"},{"t":"list","text":"Có hai cách quen thuộc để lần lượt xử lí từng phần tử của một danh sách:","items":["Duyệt trực tiếp từng phần tử: `for d in diem:` — biến d lần lượt nhận giá trị của từng phần tử; dùng khi chỉ cần giá trị, không cần biết vị trí.","Duyệt theo chỉ số: `for i in range(len(diem)):` — biến i chạy từ 0 đến (độ dài danh sách trừ 1); phần tử tương ứng khi đó là `diem[i]`. Dùng khi cần biết vị trí, hoặc cần dùng chỉ số để so sánh, cập nhật giá trị."]},{"t":"example","text":"Ví dụ sau khai báo một danh sách điểm rồi duyệt qua từng phần tử kèm theo chỉ số của nó. `range(len(diem))` sinh ra dãy số nguyên từ 0 đến (số phần tử của diem trừ 1) — đúng bằng toàn bộ chỉ số hợp lệ của danh sách; biến i lần lượt nhận từng số đó, và `diem[i]` cho ta giá trị điểm tại vị trí i:","code":"diem = [7.5, 8.0, 6.5, 9.0, 5.5]\n\nfor i in range(len(diem)):\n    print('Vị trí', i, '- điểm:', diem[i])","output":"Vị trí 0 - điểm: 7.5\nVị trí 1 - điểm: 8.0\nVị trí 2 - điểm: 6.5\nVị trí 3 - điểm: 9.0\nVị trí 4 - điểm: 5.5"},{"t":"example","text":"Tiếp theo là nhóm thao tác gặp thường xuyên nhất khi xử lí một dãy số: **tính tổng**, **tính trung bình** và **đếm theo điều kiện**. Muốn tính tổng của cả dãy điểm, ta dùng một biến trung gian (đặt tên tong) khởi tạo bằng 0, rồi mỗi lần vòng lặp đi qua một phần tử thì cộng dồn phần tử đó vào tong. Có tổng rồi, trung bình chỉ là tổng chia cho số phần tử — `len(diem)`. Muốn đếm xem có bao nhiêu điểm từ 8.0 trở lên, ta dùng thêm một biến đếm khởi tạo bằng 0, và chỉ cộng thêm 1 vào biến đó khi phần tử đang xét thoả điều kiện:","code":"diem = [7.5, 8.0, 6.5, 9.0, 5.5]\n\ntong = 0\ndem_gioi = 0\n\nfor d in diem:\n    tong = tong + d\n    if d >= 8.0:\n        dem_gioi = dem_gioi + 1\n\ntrung_binh = tong / len(diem)\n\nprint('Tổng điểm:', tong)\nprint('Điểm trung bình:', trung_binh)\nprint('Số bạn đạt từ 8.0 trở lên:', dem_gioi)","output":"Tổng điểm: 36.5\nĐiểm trung bình: 7.3\nSố bạn đạt từ 8.0 trở lên: 2"},{"t":"example","text":"Một thao tác quan trọng khác là **tìm giá trị lớn nhất, nhỏ nhất** trong dãy số. Python có sẵn hai hàm `max()` và `min()`, nhưng để hiểu rõ máy tính thực sự làm gì bên trong, ta thử tự viết thuật toán bằng vòng lặp. Ý tưởng: giả sử phần tử đầu tiên tạm thời là lớn nhất; sau đó lần lượt xét các phần tử còn lại, hễ gặp phần tử nào lớn hơn giá trị đang giữ thì cập nhật lại giá trị đó. Xét hết danh sách, giá trị đang giữ chính là phần tử lớn nhất. Tìm giá trị nhỏ nhất làm tương tự, chỉ đổi chiều so sánh:","code":"diem = [7.5, 8.0, 6.5, 9.0, 5.5]\n\nlon_nhat = diem[0]\nnho_nhat = diem[0]\n\nfor d in diem:\n    if d > lon_nhat:\n        lon_nhat = d\n    if d < nho_nhat:\n        nho_nhat = d\n\nprint('Điểm lớn nhất:', lon_nhat)\nprint('Điểm nhỏ nhất:', nho_nhat)","output":"Điểm lớn nhất: 9.0\nĐiểm nhỏ nhất: 5.5"},{"t":"note","text":"Trong các ví dụ trên, danh sách diem được gõ sẵn ngay trong code — đó cũng là một cách nhập dữ liệu hợp lệ khi số lượng giá trị ít và đã biết trước. Khi dữ liệu do người dùng nhập lúc chương trình đang chạy, cách phổ biến là tạo một danh sách rỗng bằng `diem = []`, rồi dùng vòng lặp for chạy đúng số lần cần nhập, mỗi lần đọc một giá trị bằng `input()` rồi gắn nó vào cuối danh sách bằng `diem.append(...)`. Dù dữ liệu đến từ đâu — gõ sẵn trong code hay nhập từ bàn phím — một khi đã nằm gọn trong một danh sách, mọi cách xử lí ở trên (duyệt, tính tổng, đếm, tìm lớn nhất, nhỏ nhất) đều áp dụng y hệt như nhau."}],"keypoints":["Khi cần lưu và xử lí nhiều giá trị cùng loại theo một thứ tự nhất định (điểm số cả lớp, nhiệt độ nhiều ngày...), Python dùng `list` làm mảng một chiều thay vì tạo nhiều biến rời rạc.","Chỉ số của `list` bắt đầu từ 0; phần tử ở vị trí i được truy cập bằng `ten_list[i]`, và toàn bộ danh sách có thể được duyệt qua bằng vòng lặp for.","Tính tổng, tính trung bình và đếm theo điều kiện trên một dãy số đều theo cùng một khuôn mẫu: khởi tạo một biến trung gian bằng 0 rồi cộng dồn (hoặc cộng thêm 1) qua từng vòng lặp.","Tìm giá trị lớn nhất, nhỏ nhất bằng vòng lặp là một thuật toán cụ thể: giữ tạm giá trị đầu tiên làm chuẩn, rồi so sánh và cập nhật dần khi duyệt qua các phần tử còn lại."],"quiz":["CB-mc-1201","CB-mc-1202","CB-mc-1203","CB-mc-1204","CB-mc-1205","CB-tf-1201"]},
    {"id":"C11-13","stage":21,"order":13,"topic":"F","grade":11,"minutes":11,"title":"Thuật toán tìm kiếm tuần tự","intro":"Bài học giới thiệu bài toán tìm kiếm trong một dãy dữ liệu, và thuật toán đơn giản nhất để giải quyết bài toán đó — tìm kiếm tuần tự — cùng cách cài đặt bằng Python.","sections":[{"t":"story","text":"Giả sử bạn được phân công đón tiếp khách tại một buổi hội thảo. Trên bàn có một tờ danh sách đăng ký, ghi tên hơn một trăm người theo đúng thứ tự họ đăng ký trực tuyến — hoàn toàn không được sắp xếp theo bảng chữ cái. Khi một người bước tới và đọc tên mình, bạn phải xác định xem tên đó có trong danh sách hay không, và nếu có thì ở dòng thứ mấy để đánh dấu.\n\nVì danh sách không hề được sắp xếp, cách duy nhất chắc chắn đúng là dò từng dòng một: đọc dòng 1, so tên; chưa khớp thì đọc dòng 2, so tên; cứ như vậy cho đến khi gặp đúng tên cần tìm (dừng lại, biết ngay vị trí), hoặc đọc hết toàn bộ danh sách mà vẫn không thấy (kết luận người này chưa đăng ký). Cách dò tuần tự từng dòng một như vậy — đơn giản nhưng có thể mất khá nhiều thời gian nếu danh sách dài và tên cần tìm nằm ở cuối — chính là ý tưởng của thuật toán mà ta sẽ tìm hiểu trong bài này."},{"t":"h","text":"Bài toán tìm kiếm"},{"t":"text","text":"Trong Tin học, bài toán tìm kiếm được phát biểu khá đơn giản: cho một dãy gồm n phần tử (có thể là dãy số, dãy tên, dãy điểm số...) và một giá trị cụ thể cần tìm. Yêu cầu đặt ra là trả lời hai câu hỏi: giá trị đó có xuất hiện trong dãy hay không, và nếu có thì nó nằm ở vị trí (chỉ số) nào trong dãy.\n\nBài toán này xuất hiện ở khắp nơi trong thực tế: tra một mã học sinh trong danh sách lớp, kiểm tra xem một số điện thoại đã được lưu trong danh bạ chưa, hay tìm một mặt hàng theo mã số trong kho. Có nhiều thuật toán khác nhau để giải bài toán này; bài học này giới thiệu thuật toán đơn giản và dễ hình dung nhất — **tìm kiếm tuần tự** (còn gọi là tìm kiếm tuyến tính)."},{"t":"h","text":"Ý tưởng của tìm kiếm tuần tự"},{"t":"text","text":"Ý tưởng của **tìm kiếm tuần tự** đúng như tên gọi: duyệt lần lượt các phần tử của dãy theo đúng thứ tự xuất hiện, bắt đầu từ phần tử đầu tiên.\n\nTại mỗi bước, ta so sánh phần tử đang xét với giá trị cần tìm. Nếu trùng nhau, coi như đã tìm thấy — trả về vị trí của phần tử đó và dừng thuật toán ngay lập tức, không cần xét tiếp các phần tử còn lại. Nếu không trùng, chuyển sang so sánh phần tử kế tiếp.\n\nNếu đã so sánh đến phần tử cuối cùng của dãy mà vẫn không gặp giá trị cần tìm, thuật toán kết luận: giá trị đó không có mặt trong dãy."},{"t":"list","text":"Tóm tắt các bước của thuật toán tìm kiếm tuần tự:","items":["Bắt đầu xét từ phần tử đầu tiên của dãy (chỉ số 0).","So sánh phần tử đang xét với giá trị cần tìm.","Nếu trùng khớp: trả về chỉ số hiện tại và dừng lại — đã có kết quả.","Nếu chưa trùng và vẫn còn phần tử phía sau: chuyển sang phần tử kế tiếp rồi quay lại bước so sánh.","Nếu đã xét hết toàn bộ dãy mà không trùng: kết luận không tìm thấy."]},{"t":"example","text":"Xét dãy điểm số của một nhóm học sinh, với chỉ số từ 0 đến 4 tương ứng các giá trị 7, 5, 9, 6, 8. Ta muốn biết có phần tử nào bằng 6 không, và nếu có thì ở chỉ số nào.\n\nThuật toán so sánh lần lượt: chỉ số 0 (giá trị 7) — chưa khớp; chỉ số 1 (giá trị 5) — chưa khớp; chỉ số 2 (giá trị 9) — chưa khớp; chỉ số 3 (giá trị 6) — khớp! Thuật toán dừng lại và trả về chỉ số 3.\n\nDưới đây là cách cài đặt bằng Python, thử với cả một giá trị có trong dãy (6) và một giá trị không có (10) để thấy rõ hai tình huống có thể xảy ra.","code":"def tim_kiem_tuan_tu(day, muc_tieu):\n    for i in range(len(day)):\n        if day[i] == muc_tieu:\n            return i\n    return -1\n\ndiem = [7, 5, 9, 6, 8]\n\nvt1 = tim_kiem_tuan_tu(diem, 6)\nprint('Tìm 6 ->', vt1)\n\nvt2 = tim_kiem_tuan_tu(diem, 10)\nprint('Tìm 10 ->', vt2)","output":"Tìm 6 -> 3\nTìm 10 -> -1"},{"t":"text","text":"Trong đoạn chương trình trên, dòng `def tim_kiem_tuan_tu(day, muc_tieu):` định nghĩa một hàm nhận vào hai tham số: `day` là dãy cần tìm, `muc_tieu` là giá trị cần tìm. Vòng lặp `for i in range(len(day))` cho `i` chạy lần lượt qua tất cả các chỉ số hợp lệ của dãy — đây chính là bước duyệt ‘tuần tự’, đúng theo thứ tự từ đầu đến cuối.\n\nBên trong vòng lặp, câu lệnh `if day[i] == muc_tieu` kiểm tra phần tử tại chỉ số `i` có bằng giá trị cần tìm không. Nếu đúng, `return i` lập tức trả về chỉ số đó và thoát khỏi hàm ngay, không chạy tiếp các lần lặp còn lại — giống hệt việc dừng lại ngay khi gặp đúng tên trong câu chuyện ở đầu bài. Nếu vòng lặp chạy hết mà không có lần nào `return`, dòng `return -1` ở cuối hàm sẽ được thực hiện, báo hiệu không tìm thấy."},{"t":"note","text":"Tìm kiếm tuần tự có ưu điểm lớn nhất là **đơn giản, dễ cài đặt**, và áp dụng được cho cả những dãy dữ liệu **chưa được sắp xếp** — điều mà nhiều thuật toán tìm kiếm khác (như tìm kiếm nhị phân) không làm được. Tuy nhiên, nhược điểm nằm ở tốc độ: nếu dãy có rất nhiều phần tử và giá trị cần tìm nằm ở gần cuối dãy (hoặc không có trong dãy), thuật toán phải thực hiện rất nhiều phép so sánh trước khi có kết quả, nên sẽ **chậm hơn hẳn** so với các thuật toán tìm kiếm chuyên biệt trên dãy đã sắp xếp."}],"keypoints":["**Tìm kiếm tuần tự** duyệt lần lượt từng phần tử của dãy từ đầu đến cuối, so sánh với giá trị cần tìm.","Nếu gặp phần tử khớp, thuật toán trả về ngay **vị trí (chỉ số)** của phần tử đó và dừng lại, không xét tiếp.","Nếu duyệt hết dãy mà không gặp, thuật toán kết luận ‘không có’ (trong Python thường trả về `-1`).","Ưu điểm là đơn giản và dùng được cả với dãy **chưa sắp xếp**; nhược điểm là **chậm** khi dãy dài mà giá trị cần tìm ở gần cuối hoặc không tồn tại."],"quiz":["CB-mc-1301","CB-mc-1302","CB-mc-1303","CB-mc-1304","CB-mc-1305","CB-tf-1301"]},
    {"id":"C11-14","stage":21,"order":14,"topic":"F","grade":11,"minutes":12,"title":"Thuật toán tìm kiếm nhị phân","intro":"Bài học giới thiệu tìm kiếm nhị phân — thuật toán tìm kiếm nhanh hơn tìm kiếm tuần tự rất nhiều khi áp dụng trên một dãy dữ liệu đã được sắp xếp — cùng cách cài đặt bằng Python.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn chơi một trò đoán số quen thuộc: một người nghĩ trong đầu một số bất kỳ từ 1 đến 100, còn bạn phải đoán ra số đó trong ít lần nhất có thể. Sau mỗi lần đoán, người kia chỉ cho bạn biết số cần tìm cao hơn hay thấp hơn số bạn vừa đoán, chứ không nói thẳng đáp án.\n\nNếu đoán bừa từ 1, 2, 3... bạn có thể phải đoán tới gần 100 lần mới ra. Nhưng nếu chọn cách thông minh hơn, bạn sẽ đoán ngay con số nằm ở giữa khoảng còn có thể đúng. Giả sử số bí mật là 73: bạn đoán 50, được báo “cao hơn”, nghĩa là số cần tìm chỉ có thể nằm trong khoảng từ 51 đến 100. Bạn đoán tiếp số ở giữa khoảng đó là 75, được báo “thấp hơn”, khoảng còn nghi ngờ thu hẹp về 51 đến 74. Cứ mỗi lần đoán vào giữa khoảng còn lại như vậy, khoảng đó lại co xuống còn một nửa, nên chỉ sau khoảng 6–7 lần, bạn chắc chắn tìm ra đúng số cần tìm trong cả trăm số.\n\nCách làm này gần giống việc bạn tra một từ trong cuốn từ điển giấy dày cả nghìn trang: thay vì lật từng trang từ đầu, bạn mở đại vào khoảng giữa cuốn sách, so sánh từ đang mở với từ cần tìm theo thứ tự bảng chữ cái, rồi quyết định lật tiếp về nửa trước hay nửa sau. Cách “luôn nhìn vào giữa rồi thu hẹp dần” đó chính là ý tưởng cốt lõi của thuật toán tìm kiếm nhị phân — cách máy tính tìm kiếm rất nhanh trong một dãy dữ liệu đã được sắp xếp."},{"t":"h","text":"Điều kiện tiên quyết: dãy phải được sắp xếp"},{"t":"text","text":"Trò chơi đoán số ở trên có một điểm mấu chốt: các số nguyên từ 1 đến 100 vốn đã được sắp xếp theo thứ tự tăng dần một cách tự nhiên. Nhờ vậy, khi biết số cần tìm cao hơn 50, bạn chắc chắn nó nằm ở nửa sau (51 đến 100), chứ không thể nằm rải rác ở nửa trước. Tương tự, từ điển sắp xếp các từ theo thứ tự bảng chữ cái, nên việc mở vào giữa rồi suy ra nên lật về phía nào mới có ý nghĩa.\n\nVới máy tính cũng vậy: **tìm kiếm nhị phân chỉ cho kết quả đúng khi dãy dữ liệu đã được sắp xếp** (tăng dần hoặc giảm dần). Nếu dãy chưa được sắp xếp, phần tử nhỏ hơn giá trị cần tìm có thể nằm ở bất cứ đâu — cả bên trái lẫn bên phải vị trí giữa — nên việc chỉ xét một nửa và bỏ qua nửa còn lại có thể làm bỏ sót mất giá trị cần tìm.\n\nVì vậy, nếu dãy ban đầu chưa được sắp xếp, ta phải sắp xếp nó trước bằng một thuật toán sắp xếp, rồi mới áp dụng tìm kiếm nhị phân. Đây cũng chính là điểm khác biệt lớn nhất so với tìm kiếm tuần tự — vốn áp dụng được cho cả dãy chưa sắp xếp, nhưng đổi lại chậm hơn nhiều."},{"t":"h","text":"Ý tưởng: nhìn vào giữa rồi thu hẹp dần"},{"t":"text","text":"Giả sử dãy đã được sắp xếp tăng dần, và ta cần tìm xem giá trị x có xuất hiện trong dãy hay không — nếu có thì ở vị trí nào. Ta dùng hai biến để đánh dấu đoạn đang xét: `trai` là chỉ số đầu đoạn, `phai` là chỉ số cuối đoạn. Ban đầu, đoạn đang xét là toàn bộ dãy.\n\nỞ mỗi bước, ta tính chỉ số ở giữa đoạn, gọi là `giua`, rồi so sánh giá trị tại vị trí đó với x:\n\n– Nếu giá trị ở `giua` bằng x: tìm thấy, dừng lại ngay.\n– Nếu giá trị ở `giua` nhỏ hơn x: vì dãy tăng dần nên x (nếu có) chỉ có thể nằm ở nửa bên phải; ta dời `trai` đến ngay sau vị trí giữa.\n– Nếu giá trị ở `giua` lớn hơn x: x chỉ có thể nằm ở nửa bên trái; ta dời `phai` đến ngay trước vị trí giữa.\n\nSau đó, ta lặp lại đúng cách so sánh này với đoạn đã thu hẹp, cho đến khi tìm thấy x, hoặc đến khi `trai` vượt qua `phai` — lúc đó đoạn đang xét đã rỗng, nghĩa là x không có trong dãy.\n\nĐiểm mấu chốt là: **mỗi bước đều loại bỏ hẳn một nửa số phần tử còn nghi ngờ**, nên đoạn cần xét co lại rất nhanh, dù dãy ban đầu dài đến đâu."},{"t":"example","text":"Sau đây là cách cài đặt tìm kiếm nhị phân bằng Python, dùng đúng ba biến `trai`, `phai`, `giua` bên trong một vòng `while`, đặt trong một hàm để có thể gọi lại nhiều lần. Danh sách điểm thi đã được sắp xếp tăng dần; ta thử với một giá trị có trong danh sách (8) và một giá trị không có (7) để thấy rõ cả hai tình huống.","code":"def tim_kiem_nhi_phan(day, x):\n    trai = 0\n    phai = len(day) - 1\n    while trai <= phai:\n        giua = (trai + phai) // 2\n        if day[giua] == x:\n            return giua\n        elif day[giua] < x:\n            trai = giua + 1\n        else:\n            phai = giua - 1\n    return -1\n\ndiem = [3, 5, 6, 8, 9, 10]\n\nvt1 = tim_kiem_nhi_phan(diem, 8)\nprint('Tìm 8 ->', vt1)\n\nvt2 = tim_kiem_nhi_phan(diem, 7)\nprint('Tìm 7 ->', vt2)","output":"Tìm 8 -> 3\nTìm 7 -> -1"},{"t":"text","text":"Ta đi qua từng bước của lần gọi `tim_kiem_nhi_phan(diem, 8)` để thấy `giua` thay đổi thế nào. Danh sách `diem` có 6 phần tử, đánh chỉ số từ 0 đến 5 với các giá trị 3, 5, 6, 8, 9, 10. Ban đầu `trai = 0`, `phai = 5`.\n\n– Bước 1: `giua = (0 + 5) // 2 = 2`. Giá trị tại vị trí 2 là 6, nhỏ hơn x = 8, nên chuyển sang tìm ở nửa phải: `trai` trở thành 3.\n\n– Bước 2: đoạn xét còn lại từ vị trí 3 đến 5, nên `giua = (3 + 5) // 2 = 4`. Giá trị tại vị trí 4 là 9, lớn hơn 8, nên chuyển sang tìm ở nửa trái: `phai` trở thành 3.\n\n– Bước 3: đoạn xét chỉ còn đúng một vị trí, `giua = (3 + 3) // 2 = 3`. Giá trị tại vị trí 3 là 8 — bằng đúng x, nên hàm trả về ngay giá trị 3, khớp với dòng in ra ‘Tìm 8 -> 3’.\n\nVới lần gọi `tim_kiem_nhi_phan(diem, 7)`, ba bước đầu diễn ra giống hệt (giua lần lượt là 2, 4, 3) vì `diem` và các phép so sánh đầu chưa phân biệt được 7 với 8; nhưng ở bước 3, giá trị 8 lại lớn hơn 7 nên `phai` chuyển thành 2. Lúc này `trai` (bằng 3) đã vượt qua `phai` (bằng 2), vòng lặp `while` dừng lại và hàm chạy đến dòng `return -1`, đúng như kết quả in ra."},{"t":"h","text":"Vì sao tìm kiếm nhị phân nhanh hơn tìm kiếm tuần tự rất nhiều"},{"t":"text","text":"Tìm kiếm tuần tự — dò từng phần tử từ đầu đến cuối — trong trường hợp xấu nhất phải xét qua toàn bộ dãy. Với một dãy có 1.000.000 (một triệu) phần tử, nếu giá trị cần tìm nằm ở cuối cùng, hoặc không hề có trong dãy, tìm kiếm tuần tự có thể phải thực hiện tới 1.000.000 lần so sánh.\n\nTrong khi đó, tìm kiếm nhị phân loại bỏ một nửa số phần tử đang nghi ngờ sau mỗi lần so sánh: từ 1.000.000 phần tử, sau bước 1 chỉ còn khoảng 500.000, sau bước 2 còn khoảng 250.000, sau bước 3 còn khoảng 125.000... Số phần tử còn nghi ngờ cứ giảm đi một nửa liên tiếp như vậy, nên chỉ sau khoảng 20 bước so sánh là đoạn xét đã co lại còn đúng 1 phần tử. Nói cách khác, dù dãy có tăng lên gấp đôi kích thước, tìm kiếm nhị phân cũng chỉ cần thêm đúng một bước so sánh nữa mà thôi.\n\nĐây là lý do khi làm việc với những dãy dữ liệu lớn đã được sắp xếp sẵn — chẳng hạn danh sách hàng triệu mã số hay tên đã sắp theo thứ tự — tìm kiếm nhị phân luôn được ưu tiên hơn hẳn so với tìm kiếm tuần tự."},{"t":"note","text":"Nếu dãy chưa được sắp xếp, tuyệt đối không áp dụng trực tiếp cách chia đôi này, vì kết quả có thể **sai hoặc bỏ sót** giá trị cần tìm — khi đó phải sắp xếp dãy trước. Ngoài ra, khi `trai` vượt qua `phai` mà chưa từng gặp giá trị nào bằng x, vòng lặp `while` sẽ tự kết thúc và hàm chạy đến dòng `return -1` ở cuối để báo hiệu không tìm thấy, đúng như trường hợp tìm giá trị 7 trong ví dụ trên."}],"keypoints":["**Tìm kiếm nhị phân** chỉ cho kết quả đúng khi dãy dữ liệu đã được **sắp xếp** (tăng dần hoặc giảm dần).","Ý tưởng: so sánh giá trị ở vị trí **giữa** đoạn đang xét với x; nếu chưa đúng thì thu hẹp về nửa trái hoặc nửa phải, lặp lại đến khi tìm thấy hoặc đoạn xét rỗng.","Cài đặt bằng vòng `while` với ba biến `trai`, `phai`, `giua`, trong đó `giua = (trai + phai) // 2` được tính lại sau mỗi bước.","Vì mỗi bước loại bỏ **một nửa** số phần tử đang xét, tìm kiếm nhị phân **nhanh hơn tìm kiếm tuần tự rất nhiều** khi dãy có kích thước lớn."],"quiz":["CB-mc-1401","CB-mc-1402","CB-mc-1403","CB-mc-1404","CB-mc-1405","CB-tf-1401"]},
    {"id":"C11-15","stage":21,"order":15,"topic":"F","grade":11,"minutes":12,"title":"Thuật toán sắp xếp","intro":"Bài học lí giải vì sao cần sắp xếp dữ liệu, rồi giới thiệu một thuật toán sắp xếp đơn giản, dễ hình dung: sắp xếp nổi bọt, cùng cách cài đặt cụ thể bằng Python.","sections":[{"t":"story","text":"Hãy tưởng tượng một hàng người đứng lộn xộn trước khi chụp ảnh tập thể, và có người muốn xếp lại cả hàng theo thứ tự chiều cao tăng dần, từ thấp đến cao. Người này không thể nhấc bổng tất cả mọi người lên rồi đặt đúng vị trí ngay lập tức; cách làm đơn giản nhất là đi dọc hàng, mỗi lần nhìn hai người đứng cạnh nhau. Nếu người đứng trước cao hơn người đứng sau, hai người đó đổi chỗ cho nhau. Đi hết một lượt từ đầu hàng đến cuối hàng như vậy, rồi quay lại đi thêm lượt nữa, cứ thế lặp lại nhiều lần, cho đến khi không còn cặp nào đứng sai thứ tự — lúc đó cả hàng đã được xếp đúng theo chiều cao.\n\nTrong Tin học, cách sắp xếp một dãy dữ liệu bằng việc so sánh và đổi chỗ từng cặp phần tử đứng liền kề nhau như vậy chính là ý tưởng của một trong những thuật toán sắp xếp cơ bản nhất: **sắp xếp nổi bọt**."},{"t":"h","text":"Vì sao cần sắp xếp dữ liệu?"},{"t":"text","text":"Dữ liệu khi mới thu thập hay nhập vào máy tính thường được lưu theo đúng thứ tự nhập vào, chưa chắc đã theo một trật tự có ý nghĩa nào. Nếu cần tìm nhanh một giá trị, so sánh xem giá trị nào lớn nhất hay nhỏ nhất, hoặc chỉ đơn giản là trình bày một danh sách sao cho dễ theo dõi, thì một dãy đã được sắp xếp luôn thuận tiện hơn hẳn một dãy lộn xộn.\n\nQuan trọng hơn, nhiều thuật toán xử lí dữ liệu hiệu quả chỉ hoạt động đúng khi dãy đầu vào đã được sắp xếp từ trước. Ví dụ tiêu biểu là thuật toán **tìm kiếm nhị phân**: thuật toán này liên tục thu hẹp phạm vi tìm kiếm dựa trên việc so sánh với phần tử ở giữa dãy, và điều đó chỉ có ý nghĩa khi dãy đã tăng dần (hoặc giảm dần) từ trước. Vì vậy, sắp xếp thường là bước chuẩn bị cần thiết trước khi làm nhiều việc khác với dữ liệu, chứ không chỉ để trình bày cho gọn gàng."},{"t":"h","text":"Ý tưởng của thuật toán sắp xếp nổi bọt"},{"t":"text","text":"Có khá nhiều thuật toán sắp xếp khác nhau; bài này ta tìm hiểu thuật toán đơn giản, dễ hình dung nhất: **sắp xếp nổi bọt** (bubble sort). Sở dĩ có tên gọi như vậy là vì sau mỗi lượt duyệt, phần tử lớn nhất trong đoạn dãy chưa chắc chắn đúng vị trí sẽ dần được đẩy về đúng chỗ của nó ở cuối dãy, tương tự hình ảnh một bọt khí nổi dần lên trên mặt nước.\n\nÝ tưởng cốt lõi khá đơn giản: ta duyệt qua dãy nhiều lượt; ở mỗi lượt, ta xét lần lượt từng cặp phần tử đứng liền kề nhau. Nếu phần tử đứng trước lớn hơn phần tử đứng sau — tức đang sai thứ tự so với yêu cầu tăng dần — ta đổi chỗ hai phần tử đó ngay lập tức. Làm hết một lượt từ đầu dãy đến cuối dãy, rồi lặp lại thêm lượt khác; cứ như vậy cho đến khi cả dãy đã đúng thứ tự."},{"t":"list","text":"Tóm tắt các bước của thuật toán sắp xếp nổi bọt:","items":["So sánh hai phần tử đứng liền kề nhau trong dãy.","Nếu phần tử đứng trước lớn hơn phần tử đứng sau thì đổi chỗ hai phần tử đó cho nhau.","Chuyển sang xét cặp liền kề tiếp theo, lặp lại việc so sánh — đổi chỗ cho đến hết một lượt duyệt.","Lặp lại nhiều lượt như vậy; sau mỗi lượt, phần tử lớn nhất còn lại sẽ về đúng vị trí cuối cùng, cho tới khi không còn cặp nào sai thứ tự nữa."]},{"t":"example","text":"Để cài đặt sắp xếp nổi bọt bằng Python, ta dùng **hai vòng lặp lồng nhau**: vòng lặp ngoài (biến `i`) đếm số lượt duyệt, vòng lặp trong (biến `j`) thực hiện việc so sánh và đổi chỗ từng cặp phần tử liền kề trong một lượt. Việc đổi chỗ hai phần tử được viết gọn bằng cú pháp quen thuộc `a[i], a[j] = a[j], a[i]`; ở đây hai phần tử cần đổi chỗ là hai phần tử liền kề `a[j]` và `a[j + 1]`, nên ta viết `a[j], a[j + 1] = a[j + 1], a[j]` — dòng này gán đồng thời giá trị của `a[j + 1]` cho `a[j]` và giá trị cũ của `a[j]` cho `a[j + 1]`, mà không cần dùng đến biến trung gian nào.\n\nXét dãy số `[5, 2, 4, 1, 3]`. Đoạn code dưới đây sắp xếp dãy này tăng dần, đồng thời in ra dãy sau mỗi lượt duyệt để ta quan sát sự thay đổi:","code":"a = [5, 2, 4, 1, 3]\nn = len(a)\n\nfor i in range(n - 1):\n    for j in range(n - 1 - i):\n        if a[j] > a[j + 1]:\n            a[j], a[j + 1] = a[j + 1], a[j]\n    print('Sau lượt', i + 1, ':', a)\n\nprint('Dãy sau khi sắp xếp:', a)","output":"Sau lượt 1 : [2, 4, 1, 3, 5]\nSau lượt 2 : [2, 1, 3, 4, 5]\nSau lượt 3 : [1, 2, 3, 4, 5]\nSau lượt 4 : [1, 2, 3, 4, 5]\nDãy sau khi sắp xếp: [1, 2, 3, 4, 5]"},{"t":"text","text":"Quan sát kết quả in ra ở trên, ta thấy rõ ý tưởng của thuật toán. Sau lượt 1, phần tử lớn nhất của dãy ban đầu (số 5) đã được đẩy dần về đúng vị trí cuối cùng. Sau lượt 2, phần tử lớn thứ nhì (số 4) cũng về đúng chỗ, ngay trước số 5. Đến lượt 3, dãy đã đúng thứ tự hoàn toàn (`[1, 2, 3, 4, 5]`); lượt 4 vẫn chạy đúng theo code nhưng không còn cặp nào phải đổi chỗ nữa.\n\nVới dãy gồm `n = 5` phần tử, vòng lặp ngoài thực hiện đúng `n - 1 = 4` lượt, khớp với 4 dòng ‘Sau lượt’ xuất hiện trong kết quả."},{"t":"note","text":"Trong cách cài đặt trên, vòng lặp trong luôn chạy đủ số bước quy định dù dãy có thể đã sắp xếp xong từ trước đó, như thấy ở lượt 3 và lượt 4 trong ví dụ. Một cách cải tiến thường gặp là: nếu trong một lượt duyệt mà không có bất kì lần đổi chỗ nào xảy ra, nghĩa là dãy đã sắp xếp xong, chương trình có thể dừng ngay mà không cần chạy hết các lượt còn lại."}],"keypoints":["Sắp xếp dữ liệu giúp tra cứu và so sánh dễ dàng hơn, đồng thời là điều kiện cần để nhiều thuật toán khác — như **tìm kiếm nhị phân** — hoạt động đúng.","**Sắp xếp nổi bọt** lặp lại việc so sánh và đổi chỗ hai phần tử liền kề khi chúng sai thứ tự, qua nhiều lượt duyệt liên tiếp.","Cài đặt bằng Python cần **hai vòng lặp lồng nhau**: vòng ngoài đếm lượt duyệt, vòng trong so sánh — đổi chỗ từng cặp bằng cú pháp `a[j], a[j + 1] = a[j + 1], a[j]`.","Sau mỗi lượt duyệt, phần tử lớn nhất trong đoạn chưa chắc chắn đúng vị trí sẽ được đưa về đúng chỗ cuối cùng; với dãy có `n` phần tử, cần tối đa `n - 1` lượt để chắc chắn sắp xếp xong."],"quiz":["CB-mc-1501","CB-mc-1502","CB-mc-1503","CB-mc-1504","CB-mc-1505","CB-tf-1501"]},
    {"id":"C11-16","stage":21,"order":16,"topic":"F","grade":11,"minutes":12,"title":"Độ phức tạp của thuật toán","intro":"Bài học này giới thiệu vì sao cùng một bài toán có thể có nhiều thuật toán khác nhau, và làm thế nào để đo một cách khách quan xem thuật toán nào hiệu quả hơn — đặc biệt khi phải xử lí dữ liệu rất lớn — thông qua khái niệm độ phức tạp thuật toán và các kí hiệu quen thuộc như `O(1)`, `O(log n)`, `O(n)`, `O(n^2)`.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn cần tìm số điện thoại của một người trong một cuốn danh bạ giấy. Nếu cuốn danh bạ chỉ có 10 người, cách đơn giản nhất — lật lần lượt từng trang, đọc từng tên một cho tới khi gặp đúng tên cần tìm — vẫn hoàn toàn ổn: cùng lắm chỉ mất vài giây, dù tên đó nằm ở trang cuối cùng.\n\nNhưng nếu đó là danh bạ của cả một thành phố, với một triệu người, cách ‘đọc từng tên một’ đó sẽ trở thành một cơn ác mộng — trong tình huống xấu nhất, bạn phải lật qua gần hết một triệu cái tên mới tìm ra người cần tìm. Trong khi đó, nếu cuốn danh bạ đã được sắp xếp theo thứ tự bảng chữ cái (như hầu hết danh bạ thật), bạn có thể mở ngay vào khoảng giữa cuốn sách, so sánh tên ở đó với tên cần tìm để biết nên tìm tiếp ở nửa trước hay nửa sau, rồi lặp lại cách thu hẹp một nửa như vậy — chỉ khoảng 20 bước là tìm ra, dù danh bạ có cả triệu người.\n\nHai cách làm trên đều cho ra đúng kết quả. Nhưng rõ ràng có một cách ‘chịu đựng được’ dữ liệu lớn, còn cách kia thì không. Làm sao để so sánh các thuật toán một cách khách quan, thay vì chỉ nói chung chung rằng ‘thuật toán này có vẻ nhanh hơn’?"},{"t":"h","text":"Một bài toán, nhiều thuật toán khác nhau"},{"t":"text","text":"Với hầu hết các bài toán trong tin học, không chỉ có một cách giải duy nhất. Bài toán ‘tìm một giá trị trong một danh sách’ có thể giải bằng cách xét lần lượt từng phần tử (giống việc lật từng trang danh bạ), hoặc — nếu danh sách đã được sắp xếp — bằng cách liên tục thu hẹp phạm vi tìm kiếm còn một nửa (giống việc mở vào giữa cuốn sách). Bài toán ‘sắp xếp một danh sách theo thứ tự’ cũng vậy: có nhiều thuật toán sắp xếp khác nhau, mỗi thuật toán xử lí dữ liệu theo một cách riêng.\n\nNhiều thuật toán cùng giải một bài toán đều có thể cho ra kết quả đúng như nhau. Điều khác nhau nằm ở chỗ: thuật toán nào cần ít công sức hơn — ít phép tính, ít phép so sánh hơn — để ra được kết quả đó, đặc biệt là khi lượng dữ liệu đầu vào rất lớn. Đây chính là điều mà **độ phức tạp của thuật toán** giúp ta đo lường."},{"t":"h","text":"Đo hiệu quả bằng gì? Đếm phép tính, không bấm giờ"},{"t":"text","text":"Một cách nghĩ tự nhiên là đo thời gian chạy thực tế của mỗi thuật toán bằng đồng hồ. Nhưng cách đó không đáng tin cậy: cùng một thuật toán, chạy trên một máy tính đời mới sẽ nhanh hơn hẳn so với chạy trên một máy tính cũ, dù bản chất thuật toán không hề thay đổi. Vì vậy, thay vì đếm giây, người ta đếm **số phép tính cơ bản** (phép so sánh, phép cộng, phép gán giá trị...) mà thuật toán phải thực hiện — con số này không phụ thuộc vào việc thuật toán được chạy trên máy nào, bằng ngôn ngữ lập trình gì.\n\nSố phép tính đó thường không cố định, mà phụ thuộc vào **kích thước của dữ liệu đầu vào**, hay quy ước gọi là `n` (chẳng hạn: số phần tử trong danh sách cần tìm kiếm hoặc cần sắp xếp). Điều ta quan tâm là số phép tính đó tăng nhanh hay chậm khi `n` tăng lên, nhất là khi `n` rất lớn — vì trên thực tế, dữ liệu mà máy tính phải xử lí (danh sách khách hàng, hoá đơn, kết quả tìm kiếm...) có thể lên tới hàng trăm nghìn, hàng triệu phần tử."},{"t":"h","text":"Kí hiệu O — cách viết gọn độ phức tạp"},{"t":"list","text":"Để mô tả tốc độ tăng của số phép tính theo `n`, người ta dùng một cách viết gọn gọi là **độ phức tạp thời gian** của thuật toán, kí hiệu dưới dạng `O(...)` (đọc là ‘O lớn của...’). Bốn mức độ phức tạp đơn giản, thường gặp nhất là:","items":["`O(1)` — **không đổi**: số phép tính gần như luôn cố định, không phụ thuộc vào `n`. Ví dụ: lấy phần tử đầu tiên của một danh sách, hoặc tra cứu trực tiếp theo chỉ số — dù danh sách có 10 hay 1 triệu phần tử, thao tác đó vẫn chỉ mất đúng một bước.","`O(log n)` — **rất nhanh**: số phép tính tăng rất chậm khi `n` tăng, vì mỗi bước loại bỏ được một nửa phần dữ liệu còn phải xét. Đây là độ phức tạp của **tìm kiếm nhị phân** trên một danh sách đã được sắp xếp — đúng như cách ‘mở vào giữa cuốn danh bạ’ ở phần mở đầu.","`O(n)` — **tuyến tính**: số phép tính tỉ lệ thuận với `n` — dữ liệu tăng gấp đôi thì số phép tính cũng tăng gấp đôi. Đây là độ phức tạp của **tìm kiếm tuần tự**: xét lần lượt từng phần tử của danh sách cho tới khi tìm thấy, hoặc xét hết danh sách mà không thấy.","`O(n^2)` — **chậm**: số phép tính tỉ lệ với bình phương của `n`. Đây là độ phức tạp của một số thuật toán sắp xếp đơn giản như **sắp xếp nổi bọt** — với mỗi phần tử, thuật toán phải so sánh nó với gần như mọi phần tử còn lại, khiến tổng số phép so sánh tăng rất nhanh."]},{"t":"example","text":"Đoạn chương trình Python dưới đây minh hoạ độ phức tạp `O(n)` của tìm kiếm tuần tự, bằng cách đếm số lần so sánh thực hiện được cho tới khi tìm thấy giá trị cần tìm:","code":"def tim_tuan_tu(danh_sach, x):\n    so_sanh = 0\n    for gia_tri in danh_sach:\n        so_sanh = so_sanh + 1\n        if gia_tri == x:\n            return so_sanh\n    return so_sanh\n\ndanh_sach = [12, 7, 24, 5, 31, 18, 9]\nprint('Số phép so sánh để tìm 9:', tim_tuan_tu(danh_sach, 9))\nprint('Số phép so sánh để tìm 5:', tim_tuan_tu(danh_sach, 5))","output":"Số phép so sánh để tìm 9: 7\nSố phép so sánh để tìm 5: 4\n\nDanh sách có 7 phần tử. Giá trị 9 nằm ở cuối danh sách nên phải so sánh đủ cả 7 lần mới tìm thấy — gần với trường hợp xấu nhất của tìm kiếm tuần tự, đúng với độ phức tạp `O(n)`: với danh sách n phần tử, có thể phải so sánh tới n lần mới ra kết quả. Giá trị 5 nằm gần đầu danh sách hơn nên chỉ cần 4 lần so sánh — nhưng nói chung, ở trường hợp xấu nhất (giá trị cần tìm nằm cuối danh sách, hoặc không có trong danh sách), số phép so sánh luôn tỉ lệ với n."},{"t":"h","text":"So sánh trực quan: n tăng gấp 10 lần thì sao?"},{"t":"example","text":"Bảng dưới đây ước lượng số phép tính cần thực hiện theo từng độ phức tạp, khi kích thước dữ liệu `n` lần lượt là 10, 100 và 1000 (số ở cột `O(log n)` được làm tròn):","code":"n        O(1)    O(log n)    O(n)      O(n^2)\n10       1       ~3          10        100\n100      1       ~7          100       10 000\n1000     1       ~10         1000      1 000 000","output":"`O(1)` luôn là 1 phép tính, không phụ thuộc n. `O(log n)` tăng cực chậm: n tăng gấp 100 lần (từ 10 lên 1000) mà số phép tính chỉ tăng từ khoảng 3 lên khoảng 10. `O(n)` tăng đúng theo tỉ lệ của n — n gấp 10 thì số phép tính cũng gấp 10. Còn `O(n^2)` tăng theo bình phương của n: n gấp 10 lần thì số phép tính gấp tới 100 lần; từ n = 10 lên n = 1000 (gấp 100 lần), số phép tính vọt từ 100 lên 1 000 000 — tức gấp tới 10 000 lần! Đây chính là lí do những thuật toán `O(n^2)` như sắp xếp nổi bọt vẫn ổn với vài chục hay vài trăm phần tử, nhưng trở nên cực kỳ chậm, thậm chí không thể chờ nổi, khi dữ liệu lên tới hàng triệu phần tử."},{"t":"note","text":"Độ phức tạp thuật toán không cho biết chương trình chạy mất chính xác bao nhiêu giây, mà cho biết xu hướng: khi dữ liệu ngày càng lớn, khối lượng tính toán sẽ tăng nhanh cỡ nào. Với dữ liệu nhỏ — vài chục, vài trăm phần tử — một thuật toán `O(n^2)` viết đơn giản, dễ hiểu vẫn hoàn toàn dùng tốt, có khi còn dễ cài đặt hơn. Nhưng khi làm việc với dữ liệu lớn, chẳng hạn danh sách hàng triệu khách hàng hay hàng triệu giao dịch, việc chọn một thuật toán có độ phức tạp thấp hơn — gần với `O(n)` hay `O(log n)`, thay vì `O(n^2)` — có thể tạo ra khác biệt giữa một chương trình chạy xong trong vài giây và một chương trình phải chờ hàng giờ, thậm chí không bao giờ chạy xong."}],"keypoints":["Cùng một bài toán có thể giải bằng nhiều **thuật toán** khác nhau; để biết thuật toán nào **hiệu quả** hơn — nhất là khi dữ liệu lớn — cần một cách đo khách quan, không phụ thuộc vào máy tính đang chạy.","Cách đo đó là đếm **số phép tính cơ bản** (so sánh, phép gán...) mà thuật toán thực hiện, tính theo **kích thước dữ liệu `n`**, và quan tâm đến xu hướng tăng của nó khi `n` rất lớn.","Bốn mức **độ phức tạp** thường gặp, từ nhanh đến chậm: `O(1)` (không đổi), `O(log n)` (rất nhanh, như tìm kiếm nhị phân), `O(n)` (tuyến tính, như tìm kiếm tuần tự), `O(n^2)` (chậm, như sắp xếp nổi bọt).","Khi `n` tăng gấp 10 lần, `O(n)` tăng gấp 10 nhưng `O(n^2)` tăng gấp 100 — nên thuật toán `O(n^2)` vẫn ổn với dữ liệu nhỏ nhưng nhanh chóng trở nên rất chậm với dữ liệu lớn; chọn thuật toán phù hợp vì vậy rất quan trọng."],"quiz":["CB-mc-1601","CB-mc-1602","CB-mc-1603","CB-mc-1604","CB-mc-1605","CB-tf-1601"]},
    {"id":"C11-17","stage":21,"order":17,"topic":"F","grade":11,"minutes":11,"title":"Chia bài toán thành hàm và cách làm mịn dần","intro":"Một bài toán trong thực tế thường không đơn giản như những ví dụ luyện tập ban đầu. Bài học này giới thiệu cách **chia một bài toán lớn thành nhiều hàm nhỏ**, mỗi hàm đảm nhận đúng một việc, cùng cách **làm mịn dần** — phác thảo các bước lớn trước, rồi mới viết chi tiết từng bước — để việc viết chương trình trở nên gọn gàng và dễ kiểm soát hơn.","sections":[{"t":"story","text":"Hãy tưởng tượng một nhóm bạn cùng nhau tổ chức một bữa tiệc nhỏ. Nếu giao cho đúng một người phải lo liệu tất cả mọi việc — vừa đi chợ mua nguyên liệu, vừa nấu từng món, vừa kê bàn ghế, vừa dọn dẹp sau khi ăn xong — người đó chắc chắn sẽ rối tung, dễ quên việc, và khó biết nên bắt đầu từ đâu trước. Cách làm hợp lý hơn nhiều là chia bữa tiệc thành từng đầu việc riêng biệt: một nhóm lo đi chợ, một nhóm lo nấu nướng, một nhóm khác lo dọn bàn và sắp xếp chỗ ngồi. Mỗi nhóm chỉ cần tập trung hoàn thành đúng phần việc của mình; đến giờ, các phần việc được ráp lại với nhau, bữa tiệc coi như hoàn tất mà không ai phải ôm đồm quá nhiều thứ cùng lúc.\n\nViết một chương trình máy tính để giải quyết một bài toán lớn cũng nên đi theo tinh thần “chia để trị” như vậy: thay vì viết một khối lệnh dài giải quyết mọi thứ cùng lúc, ta chia bài toán thành từng phần việc nhỏ, mỗi phần việc giao cho một hàm đảm nhận."},{"t":"h","text":"Vì sao nên chia bài toán lớn thành nhiều hàm nhỏ?"},{"t":"text","text":"Những bài toán dùng để luyện tập ban đầu thường chỉ vài dòng lệnh, nên viết một mạch từ trên xuống dưới cũng không gây khó khăn gì. Nhưng một bài toán trong thực tế — chẳng hạn quản lí điểm của cả một lớp học, tính tiền hoá đơn cho một cửa hàng, xử lí danh sách khách hàng — thường đòi hỏi nhiều bước xử lí khác nhau. Nếu cố viết tất cả các bước đó thành một khối lệnh liền mạch, đoạn chương trình sẽ nhanh chóng trở nên dài dòng: rất nhiều biến cùng tồn tại một lúc, nhiều bước tính toán đan xen nhau, khiến người viết khó theo dõi, và về sau muốn sửa một chi tiết nhỏ cũng phải dò tìm giữa hàng chục dòng lệnh mới biết nên sửa ở đâu.\n\nCách xử lí hợp lý hơn là **chia bài toán lớn thành nhiều phần việc nhỏ**, mỗi phần việc giao cho đúng một hàm đảm nhận, và mỗi hàm chỉ nên làm **đúng một việc rõ ràng**. Hàm nào chỉ lo tính toán thì không cần kiêm luôn việc in kết quả ra màn hình; hàm nào chỉ lo nhận dữ liệu đầu vào thì không cần kiêm luôn việc xử lí dữ liệu ấy. Khi mỗi hàm gọn và rõ việc như vậy, một bài toán dù phức tạp đến đâu cũng có thể được giải quyết dần từng phần, không cần ôm đồm tất cả cùng một lúc trong đầu."},{"t":"h","text":"Làm mịn dần: từ dàn ý lớn đến từng hàm cụ thể"},{"t":"text","text":"Vậy nên bắt đầu chia bài toán như thế nào? Một cách làm hiệu quả gọi là **làm mịn dần** (còn gọi là thiết kế từ trên xuống): thay vì viết ngay từng dòng lệnh chi tiết, hãy bắt đầu bằng cách phác ra những bước lớn của bài toán, giống như viết một dàn ý ngắn gọn — mỗi bước lúc này chỉ cần nêu tên việc cần làm, chưa cần biết bên trong sẽ viết ra sao.\n\nChẳng hạn, bài toán “quản lí điểm của một học sinh” có thể phác thành một dàn ý bốn bước: nhập điểm các môn, tính điểm trung bình, xếp loại học lực, in kết quả ra màn hình. Ở bước phác thảo này, ta hoàn toàn chưa cần biết công thức xếp loại cụ thể ra sao, cũng chưa cần biết điểm trung bình sẽ được tính bằng công thức nào — chỉ cần biết bài toán gồm đúng bốn việc, theo đúng thứ tự đó. Sau khi có dàn ý, ta quay lại **làm mịn** từng bước một: biến mỗi bước lớn thành một hàm hoàn chỉnh, viết đầy đủ các dòng lệnh cần thiết bên trong hàm đó. Làm mịn xong một bước, bài toán coi như đã giải quyết trọn vẹn đúng phần việc của bước ấy, chưa cần vội lo đến các bước còn lại."},{"t":"list","text":"Chia bài toán thành nhiều hàm nhỏ, kết hợp với cách làm mịn dần, mang lại một số lợi ích rõ rệt:","items":["**Dễ viết hơn** — tại một thời điểm, người viết chỉ cần tập trung hoàn thành đúng một hàm, một việc cụ thể, thay vì phải nghĩ đến toàn bộ bài toán cùng lúc.","**Dễ đọc hơn** — phần chính của chương trình chỉ còn là vài dòng gọi hàm theo đúng thứ tự, đọc vào gần như hiểu ngay chương trình đang làm những việc gì, không cần dò từng dòng lệnh chi tiết bên trong.","**Dễ kiểm thử từng phần** — có thể thử riêng từng hàm với vài giá trị mẫu để chắc chắn hàm đó chạy đúng, trước khi ráp các hàm lại thành một chương trình hoàn chỉnh; nhờ vậy, nếu có lỗi cũng dễ khoanh vùng đúng hàm đang gây ra lỗi.","**Dùng lại được** — một hàm đã viết xong và kiểm tra đúng có thể được gọi lại ở nhiều chỗ khác nhau trong cùng chương trình, thậm chí mang sang dùng cho một chương trình khác có nhu cầu tương tự."]},{"t":"example","text":"Áp dụng đúng dàn ý bốn bước ở trên, chương trình quản lí điểm có thể được viết thành bốn hàm nhỏ, cộng thêm một phần chính đứng riêng chỉ để gọi lần lượt các hàm ấy theo đúng thứ tự:","code":"def nhap_diem():\n    d1 = float(input('Nhập điểm môn 1: '))\n    d2 = float(input('Nhập điểm môn 2: '))\n    d3 = float(input('Nhập điểm môn 3: '))\n    return [d1, d2, d3]\n\ndef tinh_trung_binh(danh_sach):\n    return sum(danh_sach) / len(danh_sach)\n\ndef xep_loai(diem_tb):\n    if diem_tb >= 8:\n        return 'Giỏi'\n    elif diem_tb >= 6.5:\n        return 'Khá'\n    elif diem_tb >= 5:\n        return 'Trung bình'\n    else:\n        return 'Yếu'\n\ndef in_ket_qua(diem_tb, loai):\n    print('Điểm trung bình:', diem_tb)\n    print('Xếp loại:', loai)\n\n# Phần chính: chỉ gọi lần lượt các hàm theo đúng thứ tự\ndiem = nhap_diem()\ntb = tinh_trung_binh(diem)\nloai = xep_loai(tb)\nin_ket_qua(tb, loai)","output":"Nhập điểm môn 1: 8\nNhập điểm môn 2: 7\nNhập điểm môn 3: 6\nĐiểm trung bình: 7.0\nXếp loại: Khá"},{"t":"text","text":"Chương trình trên được chia thành bốn hàm, mỗi hàm chỉ lo đúng một việc. Hàm `nhap_diem` chỉ lo phần nhận điểm từ người dùng và trả về một danh sách gồm ba điểm; hàm `tinh_trung_binh` chỉ lo mỗi việc tính trung bình từ một danh sách điểm cho trước, không cần quan tâm những điểm đó lấy từ đâu ra; hàm `xep_loai` chỉ lo mỗi việc so sánh một điểm trung bình rồi trả ra xếp loại tương ứng, cũng không cần quan tâm điểm trung bình đó được tính kiểu gì; còn hàm `in_ket_qua` chỉ lo mỗi việc hiển thị kết quả ra màn hình.\n\nPhần chính ở cuối chương trình — bốn dòng lệnh sau dòng chú thích “Phần chính” — không hề chứa phép tính hay điều kiện nào cả; nó chỉ gọi bốn hàm theo đúng thứ tự, gần như đọc lại y nguyên dàn ý bốn bước đã phác ra từ trước: nhập điểm, tính trung bình, xếp loại, in kết quả. Muốn biết chương trình làm những gì, chỉ cần đọc bốn dòng ở phần chính là đủ; muốn biết một bước cụ thể được xử lí ra sao, mới cần mở đúng hàm tương ứng ra xem chi tiết bên trong."},{"t":"note","text":"Một dấu hiệu cho thấy nên chia nhỏ hàm ra thêm: nếu một hàm đã dài tới vài chục dòng lệnh, hoặc phải dùng chữ “và” mới mô tả hết việc nó làm (chẳng hạn một hàm tên `tinh_diem_va_in_ket_qua`), đó thường là dấu hiệu hàm đang ôm đồm nhiều việc cùng lúc, nên tách thành hai hàm riêng biệt. Đặt tên hàm ngắn gọn nhưng mô tả đúng việc nó làm — như `tinh_trung_binh`, `xep_loai` ở trên — cũng giúp phần chính của chương trình dễ đọc hơn rất nhiều, vì chỉ cần đọc tên hàm là đoán được ngay hàm đó dùng để làm gì."}],"keypoints":["Một bài toán lớn nên được **chia thành nhiều hàm nhỏ**, mỗi hàm chỉ đảm nhận **đúng một việc rõ ràng**, thay vì viết dồn tất cả vào một khối lệnh dài.","**Làm mịn dần** (thiết kế từ trên xuống) là cách phác ra các bước lớn của bài toán trước — như một dàn ý — rồi mới quay lại viết chi tiết từng bước thành một hàm hoàn chỉnh.","Chia hàm và làm mịn dần giúp chương trình **dễ viết, dễ đọc, dễ kiểm thử từng phần và dễ tái sử dụng** hơn so với việc viết một mạch từ đầu đến cuối.","Trong một chương trình được chia tốt, **phần chính** thường chỉ gồm vài dòng gọi hàm theo đúng thứ tự, đọc vào giống như đọc lại dàn ý các bước lớn của bài toán."],"quiz":["CB-mc-1701","CB-mc-1702","CB-mc-1703","CB-mc-1704","CB-mc-1705","CB-tf-1701"]},
    {"id":"C11-18","stage":21,"order":18,"topic":"F","grade":11,"minutes":13,"title":"Kiểm thử và gỡ lỗi chương trình (nâng cao)","intro":"Ở mức cơ bản, ta đã biết ba loại lỗi thường gặp và vài cách dò lỗi đơn giản. Bài học này đi xa hơn: xây dựng một **bộ kiểm thử** thật sự có hệ thống — so kết quả chương trình với đáp án đã biết trước cho nhiều bộ dữ liệu, đặc biệt ở những trường hợp biên dễ bị bỏ sót — để không còn phải chạy thử một lần rồi vội yên tâm.","sections":[{"t":"story","text":"Giả sử bạn vừa học được một dạng bài tập mới và đem ra thử với một đề khá dễ trong sách — làm xong, so đáp số thì khớp ngay lập tức. Cảm giác đó rất dễ khiến ta tin rằng mình đã nắm chắc cách giải, và yên tâm dừng lại ở đó. Nhưng đến khi gặp một đề “khó nhằn” hơn — số liệu đặc biệt, hoặc rơi vào một tình huống mà đề dễ chưa từng có — cách giải tưởng như đã vững bỗng cho ra một kết quả vô lí. Hoá ra ta mới chỉ thử qua những trường hợp “đẹp”, còn những trường hợp ít gặp hơn thì chưa hề động tới.\n\nMột chương trình máy tính cũng vận hành y hệt như vậy: chạy đúng với một bộ dữ liệu duy nhất không có nghĩa là chương trình đúng trong MỌI tình huống. Muốn thật sự tin tưởng vào một chương trình, ta cần một cách kiểm tra có hệ thống hơn nhiều — chuẩn bị sẵn nhiều bộ dữ liệu khác nhau, đặc biệt những bộ “khó nhằn” nhất, rồi so kết quả với đáp án đã biết trước cho từng bộ, thay vì chỉ dừng lại ở một hai lần chạy thử suôn sẻ."},{"t":"h","text":"Vì sao chạy đúng một lần chưa chắc đã đúng"},{"t":"text","text":"Ở mức cơ bản, ta đã biết lỗi logic là loại lỗi khó chịu nhất: chương trình không hề báo lỗi gì cả, vẫn chạy trơn tru từ đầu đến cuối và in ra một kết quả — chỉ có điều kết quả đó sai so với điều mong muốn. Vấn đề còn tinh vi hơn nữa: một chương trình mắc lỗi logic vẫn hoàn toàn có thể cho kết quả ĐÚNG với một số bộ dữ liệu, và chỉ lộ sai ở những bộ dữ liệu khác. Nếu chỉ chạy thử đúng một lần rồi dừng lại, rất có thể ta vừa trúng ngay bộ dữ liệu “dễ tính” mà lỗi chưa kịp lộ diện.\n\nVì lẽ đó, kiểm thử một chương trình không thể chỉ là chạy thử vài lần theo cảm tính rồi yên tâm. Cần một cách làm có hệ thống hơn: chuẩn bị trước nhiều bộ dữ liệu khác nhau, biết trước đáp án đúng của từng bộ, rồi lần lượt so sánh — đó gọi là xây dựng một **bộ kiểm thử** cho chương trình."},{"t":"h","text":"Bộ kiểm thử: đầu vào và kết quả mong đợi"},{"t":"text","text":"Đơn vị nhỏ nhất trong một bộ kiểm thử gọi là một **bộ dữ liệu kiểm thử**, gồm đúng hai phần: **dữ liệu đầu vào** đưa vào chương trình, và **kết quả mong đợi** — đáp án đúng riêng của bộ dữ liệu đó. Điều quan trọng là kết quả mong đợi phải được xác định từ TRƯỚC, bằng cách tính tay hoặc suy luận trực tiếp từ đề bài, hoàn toàn độc lập với chương trình đang được kiểm tra — nếu để chương trình tự chạy ra rồi mới lấy luôn kết quả đó làm “đáp án”, việc so sánh sẽ mất hết ý nghĩa.\n\nKiểm thử, khi đó, đơn giản là: chạy chương trình với đầu vào của từng bộ, rồi so kết quả chương trình in ra với kết quả mong đợi đã chuẩn bị sẵn. Khớp nhau thì bộ đó `Đúng`; lệch nhau thì bộ đó `Sai` — và đây chính là dấu hiệu cho biết chương trình vẫn còn lỗi cần sửa. Lần lượt kiểm tra qua nhiều bộ dữ liệu như vậy, thay vì chỉ thử một lần rồi tin ngay, chính là **kiểm thử có hệ thống**."},{"t":"example","text":"Xét hàm `tim_max` dưới đây, dùng để tìm giá trị lớn nhất trong một danh sách số. Cùng với hàm, ta chuẩn bị sẵn một bộ kiểm thử gồm ba bộ dữ liệu — mỗi bộ được viết thành một cặp `(đầu vào, kết quả mong đợi)` đặt trong ngoặc đơn — trong đó có một bộ toàn số âm:","code":"def tim_max(day_so):\n    lon_nhat = 0\n    for x in day_so:\n        if x > lon_nhat:\n            lon_nhat = x\n    return lon_nhat\n\nbo_kiem_thu = [\n    ([3, 7, 2, 9, 4], 9),\n    ([5], 5),\n    ([-3, -1, -8, -2], -1),\n]\n\nfor dau_vao, mong_doi in bo_kiem_thu:\n    ket_qua = tim_max(dau_vao)\n    if ket_qua == mong_doi:\n        print(dau_vao, \"-> Đúng\")\n    else:\n        print(dau_vao, \"-> Sai. Mong đợi\", mong_doi, \"nhưng được\", ket_qua)","output":"[3, 7, 2, 9, 4] -> Đúng\n[5] -> Đúng\n[-3, -1, -8, -2] -> Sai. Mong đợi -1 nhưng được 0\n\nHai bộ đầu báo `Đúng` khiến ta dễ yên tâm — nhưng bộ thứ ba, một trường hợp biên toàn số âm, lại lộ ra chỗ sai."},{"t":"text","text":"Bộ kiểm thử thứ ba chính là một **trường hợp biên**: danh sách toàn số âm. Nhờ đưa nó vào bộ kiểm thử, lỗi logic ẩn trong hàm mới bị lộ ra — nếu chỉ thử với những dãy số dương “đẹp” như bộ đầu tiên, ta sẽ không bao giờ phát hiện ra vấn đề này.\n\nĐể tìm đúng chỗ sai, cách làm hiệu quả là chèn thêm `print()` ngay bên trong vòng lặp để in giá trị trung gian của `lon_nhat` sau mỗi bước — với đầu vào `[-3, -1, -8, -2]`, ta sẽ thấy `lon_nhat` đứng yên ở `0` suốt từ đầu đến cuối, không hề nhúc nhích. Nhờ vậy, vùng nghi ngờ được thu hẹp ngay về đúng một dòng: `lon_nhat = 0` — hàm đang ngầm giả định danh sách luôn có số dương, nên không phần tử âm nào vượt qua nổi điều kiện `x > lon_nhat`. Cách sửa là khởi tạo `lon_nhat` bằng chính phần tử đầu tiên của danh sách, thay vì một giá trị cố định:"},{"t":"example","text":"Sau khi sửa, cần chạy lại đúng bộ kiểm thử cũ để chắc chắn cả ba bộ đều `Đúng` — sửa xong không có nghĩa là xong việc, mà phải **thử lại toàn bộ bộ kiểm thử**, kể cả những bộ trước đó đã từng `Đúng`, để chắc chắn chỗ sửa không làm hỏng những gì đang chạy tốt:","code":"def tim_max(day_so):\n    lon_nhat = day_so[0]\n    for x in day_so[1:]:\n        if x > lon_nhat:\n            lon_nhat = x\n    return lon_nhat\n\nbo_kiem_thu = [\n    ([3, 7, 2, 9, 4], 9),\n    ([5], 5),\n    ([-3, -1, -8, -2], -1),\n]\n\nfor dau_vao, mong_doi in bo_kiem_thu:\n    ket_qua = tim_max(dau_vao)\n    if ket_qua == mong_doi:\n        print(dau_vao, \"-> Đúng\")\n    else:\n        print(dau_vao, \"-> Sai. Mong đợi\", mong_doi, \"nhưng được\", ket_qua)","output":"[3, 7, 2, 9, 4] -> Đúng\n[5] -> Đúng\n[-3, -1, -8, -2] -> Đúng\n\nCả ba bộ đều khớp với kết quả mong đợi, kể cả trường hợp biên toàn số âm."},{"t":"h","text":"Những trường hợp biên cần đặc biệt lưu ý"},{"t":"list","text":"Khi chuẩn bị bộ kiểm thử cho bất kì chương trình nào, hãy dành riêng một số bộ dữ liệu cho các trường hợp biên sau — đây là nơi lỗi logic thích “ẩn náu” nhất:","items":["**Dãy/danh sách rỗng** — không có phần tử nào cả; rất nhiều chương trình quên xử lí trường hợp này nên bị lỗi ngay khi chạy.","**Chỉ có một phần tử** — dễ lộ lỗi ở những chỗ chương trình ngầm giả định danh sách phải có từ hai phần tử trở lên.","**Giá trị bằng 0** — dễ gây lỗi khi chạy nếu chương trình có phép chia, hoặc dễ bị hiểu nhầm thành “chưa có gì” ở một số câu lệnh điều kiện.","**Số âm** — như ví dụ hàm `tim_max` ở trên, dễ lộ lỗi ở những chỗ ngầm giả định dữ liệu luôn mang giá trị dương.","**Giá trị lớn nhất/nhỏ nhất có thể có** — kiểm tra xem chương trình có xử lí đúng ở hai đầu mút của phạm vi dữ liệu hay không.","**Trường hợp “không tìm thấy”** — với chương trình tìm kiếm, cần thử cả khi giá trị cần tìm không hề có trong dữ liệu, xem chương trình phản hồi ra sao thay vì báo bừa một kết quả nào đó."]},{"t":"note","text":"Một điểm liên quan: nếu gọi hàm `tim_max` ở trên với một danh sách RỖNG, dòng `day_so[0]` sẽ gây lỗi ngay khi chạy, vì danh sách rỗng không có phần tử đầu tiên nào để lấy ra. Đây chính là lí do dãy rỗng luôn cần có mặt trong bộ kiểm thử: nó buộc người viết chương trình phải quyết định rõ ràng nên làm gì trong tình huống đó — báo lỗi có kiểm soát, trả về một giá trị đặc biệt, hay quy định trước rằng đầu vào luôn phải có ít nhất một phần tử — thay vì bỏ sót và để chương trình tự sụp đổ bất ngờ."}],"keypoints":["Chạy đúng với một bộ dữ liệu, hay chỉ một lần, không đủ để khẳng định chương trình đúng — lỗi logic có thể ẩn và chỉ lộ ra ở một số bộ dữ liệu nhất định, nên cần kiểm thử với NHIỀU bộ dữ liệu khác nhau.","Một bộ dữ liệu kiểm thử gồm hai phần: dữ liệu đầu vào và kết quả MONG ĐỢI đã biết trước (tính tay hoặc suy luận từ đề bài); kiểm thử là so kết quả chương trình chạy ra với kết quả mong đợi đó.","Cần đặc biệt chú ý các trường hợp biên khi chuẩn bị bộ kiểm thử: dãy rỗng, chỉ một phần tử, giá trị 0, số âm, giá trị lớn/nhỏ nhất có thể có, và trường hợp không tìm thấy — đây là nơi lỗi logic dễ ẩn náu nhất.","Khi một bộ kiểm thử báo sai, nên đọc kĩ thông báo lỗi (nếu có), in giá trị trung gian để xem chương trình đang tính đến đâu, thu hẹp dần vùng nghi ngờ, sửa lại rồi chạy thử lại TOÀN BỘ bộ kiểm thử, không chỉ riêng bộ vừa báo sai."],"quiz":["CB-mc-1801","CB-mc-1802","CB-mc-1803","CB-mc-1804","CB-mc-1805","CB-tf-1801"]},
    {"id":"C11-19","stage":21,"order":19,"topic":"F","grade":11,"minutes":12,"title":"Đệ quy (recursion)","intro":"Bài học này giới thiệu **đệ quy (recursion)** — kỹ thuật để một hàm tự gọi lại chính nó nhằm giải một bài toán nhỏ hơn, cùng dạng với bài toán ban đầu — cùng với phần không thể thiếu của mọi hàm đệ quy: điều kiện dừng (base case).","sections":[{"t":"story","text":"Hãy hình dung một bộ búp bê gỗ truyền thống của Nga, thường gọi là búp bê matryoshka: một con búp bê khoác áo hoa sặc sỡ, cao chừng hai bàn tay. Mở con búp bê ấy ra, bên trong lại hiện ra một con búp bê giống hệt về hình dáng và hoa văn, chỉ nhỏ hơn một chút. Mở tiếp con này, lại thấy một con nhỏ hơn nữa nằm bên trong — cứ như vậy, hết lớp này đến lớp khác, cho đến khi gặp một con búp bê đặc ruột, nhỏ nhất, không thể mở ra được nữa. Con búp bê nhỏ nhất ấy chính là điểm dừng của cả bộ: không phải vì có ai ra lệnh dừng lại, mà vì tự bản thân nó không còn gì để mở tiếp.\n\nNhiều bài toán trong lập trình cũng được giải theo đúng tinh thần của bộ búp bê đó: muốn giải một bài toán cỡ lớn, ta ‘mở’ nó ra và thấy bên trong một bài toán CÙNG DẠNG như vậy, chỉ nhỏ hơn — rồi lặp lại đúng cách làm đó cho bài toán nhỏ hơn, cho đến khi gặp một trường hợp nhỏ nhất, đơn giản đến mức giải được ngay, không cần mở thêm nữa. Cách giải một bài toán bằng cách quy bài toán đó về chính nó, ở quy mô nhỏ hơn, gọi là **đệ quy**."},{"t":"h","text":"Đệ quy là gì?"},{"t":"text","text":"**Đệ quy** (recursion) xảy ra khi một hàm, ngay trong quá trình thực hiện, **tự gọi lại chính nó** — nhưng để giải một bài toán nhỏ hơn, cùng dạng với bài toán ban đầu. Nói cách khác, hàm không cố giải toàn bộ bài toán cỡ `n` chỉ trong một bước; nó xử lí một phần nhỏ, rồi giao phần việc còn lại — bài toán cỡ nhỏ hơn — cho chính nó tự giải tiếp, giống hệt việc mở một con búp bê để lộ ra một con nhỏ hơn nằm bên trong.\n\nÝ tưởng cốt lõi của đệ quy có thể tóm gọn trong một câu: muốn giải bài toán cỡ `n`, hãy dựa vào lời giải của CHÍNH bài toán đó nhưng ở cỡ `n - 1`, nhỏ hơn một chút. Bài toán cỡ `n - 1` lại dựa vào bài toán cỡ `n - 2`, cứ thế thu nhỏ dần, cho đến khi gặp một cỡ nhỏ nhất, đơn giản đến mức trả lời được ngay mà không cần thu nhỏ thêm."},{"t":"h","text":"Điều kiện dừng (base case) — phần bắt buộc phải có"},{"t":"text","text":"Nếu một hàm đệ quy cứ tự gọi lại chính nó mãi, không bao giờ dừng, chương trình sẽ không bao giờ chạy xong: máy tính liên tục phải mở thêm một lượt gọi hàm mới bên trong lượt gọi cũ, cho đến khi phần bộ nhớ dành riêng cho việc gọi hàm (gọi là **ngăn xếp**) bị dùng hết, chương trình bị lỗi vì **tràn ngăn xếp**. Vì vậy, MỌI hàm đệ quy đều bắt buộc phải có ít nhất một **điều kiện dừng** (base case): một trường hợp nhỏ nhất, đơn giản nhất, được giải quyết ngay bằng một câu trả lời cụ thể, KHÔNG gọi lại hàm thêm bất kì lần nào nữa.\n\nQuay lại bộ búp bê ở đầu bài: con búp bê nhỏ nhất, đặc ruột, chính là hiện thân của điều kiện dừng — nó không mở ra được nữa, nên hành động ‘mở búp bê’ buộc phải kết thúc tại đó. Một hàm đệ quy thiếu điều kiện dừng cũng giống như một bộ búp bê mà con nào cũng mở ra được, không có con nào là nhỏ nhất cả — cứ mở mãi, không bao giờ xong."},{"t":"example","text":"Xét bài toán tính **giai thừa** của một số tự nhiên `n`, kí hiệu `n!`, vốn được định nghĩa là `n! = n × (n-1) × (n-2) × ... × 2 × 1` (quy ước riêng `0! = 1`). Định nghĩa này vốn đã mang dáng dấp đệ quy: `n! = n × (n-1)!` — giai thừa của `n` dựa vào giai thừa của `n - 1`; còn trường hợp nhỏ nhất `0!` được quy ước bằng 1 ngay, không cần tính tiếp. Đoạn code Python dưới đây thể hiện đúng ý tưởng đó:","code":"def giai_thua(n):\n    if n == 0:\n        return 1\n    else:\n        return n * giai_thua(n - 1)\n\nprint(giai_thua(3))\nprint(giai_thua(5))","output":"6\n120"},{"t":"text","text":"Hàm `giai_thua` có đúng hai trường hợp, khớp với ý tưởng đệ quy vừa nêu. Dòng `if n == 0: return 1` chính là **điều kiện dừng**: khi `n` đã nhỏ đến mức bằng 0, hàm trả lời ngay bằng 1, không gọi lại `giai_thua` thêm lần nào nữa. Còn khi `n` khác 0, dòng `return n * giai_thua(n - 1)` cho hàm tự gọi lại chính nó với đối số nhỏ hơn một đơn vị là `n - 1`, rồi lấy kết quả đó nhân với `n`.\n\nThử đi qua từng bước lệnh gọi `giai_thua(3)` để thấy rõ đệ quy diễn ra thế nào:\n\n`giai_thua(3) = 3 * giai_thua(2)`\n`= 3 * (2 * giai_thua(1))`\n`= 3 * (2 * (1 * giai_thua(0)))`\n\nĐến đây, `giai_thua(0)` chạm điều kiện dừng, trả về 1 ngay lập tức, không gọi thêm nữa. Từ điểm dừng đó, kết quả được nhân ngược trở lại theo đúng chiều vừa mở ra:\n\n`= 3 * (2 * (1 * 1)) = 3 * (2 * 1) = 3 * 2 = 6`\n\nĐúng bằng kết quả mà `print(giai_thua(3))` in ra. Với `giai_thua(5)`, quá trình diễn ra hoàn toàn tương tự nhưng phải thu nhỏ qua nhiều bước hơn (`5 → 4 → 3 → 2 → 1 → 0`), cho kết quả cuối cùng là 120."},{"t":"example","text":"Ý tưởng ‘bài toán cỡ `n` dựa vào bài toán cỡ `n - 1`’ không chỉ áp dụng riêng cho giai thừa. Xét bài toán tính tổng `1 + 2 + ... + n`: tổng đến `n` chính bằng `n` cộng thêm tổng đến `n - 1` — một cách nhìn đệ quy hoàn toàn tương tự, với trường hợp nhỏ nhất là khi `n` bằng 1:","code":"def tong(n):\n    if n == 1:\n        return 1\n    else:\n        return n + tong(n - 1)\n\nprint(tong(4))","output":"10"},{"t":"text","text":"Cấu trúc của `tong` giống hệt `giai_thua`: có một **điều kiện dừng** (`n == 1`, trả về 1 ngay) và một trường hợp còn lại tự gọi lại chính nó với `n - 1`, rồi cộng thêm `n` vào kết quả đó. Lần lượt: `tong(4) = 4 + tong(3) = 4 + (3 + tong(2)) = 4 + 3 + (2 + tong(1)) = 4 + 3 + 2 + 1 = 10`, đúng bằng kết quả in ra.\n\nRất nhiều bài toán khác — đếm ngược từ `n` về 1, tính luỹ thừa, và nhiều bài toán phức tạp hơn sẽ gặp ở các bài sau — đều có thể giải theo đúng khuôn mẫu này: xác định rõ điều kiện dừng, rồi diễn tả bài toán cỡ `n` thông qua bài toán cỡ nhỏ hơn."},{"t":"h","text":"Khi nào nên dùng đệ quy?"},{"t":"list","text":"Trước khi dùng đệ quy để giải một bài toán, nên lưu ý những đặc điểm sau:","items":["**Tự nhiên, ngắn gọn** với những bài toán vốn có thể chia thành các bài toán nhỏ hơn, cùng dạng với chính nó — code đệ quy thường ngắn hơn hẳn so với cách viết khác cho cùng một bài toán.","Sau mỗi lượt tự gọi, bài toán **phải tiến gần hơn** tới điều kiện dừng — chẳng hạn đối số phải giảm dần (`n`, rồi `n - 1`, rồi `n - 2`,...); nếu đối số không thu nhỏ dần, hàm sẽ không bao giờ chạm tới điều kiện dừng.","Mỗi lượt tự gọi còn dang dở sẽ tạm chiếm thêm một phần bộ nhớ (ngăn xếp), cho đến khi chạm điều kiện dừng thì kết quả mới lần lượt được trả ngược lại — vì vậy đệ quy với `n` quá lớn có thể chạy chậm hoặc hết bộ nhớ.","Bất kì bài toán nào giải được bằng đệ quy cũng có thể viết lại bằng vòng lặp (`for`, `while`), và ngược lại — đệ quy chỉ là một CÁCH khác để diễn đạt cùng một ý tưởng lặp lại, không phải công cụ bắt buộc phải dùng."]},{"t":"note","text":"Lỗi phổ biến nhất khi mới viết hàm đệ quy là quên hẳn điều kiện dừng, hoặc có viết điều kiện dừng nhưng đối số truyền vào ở lượt gọi tiếp theo lại không thu nhỏ dần (chẳng hạn gọi nhầm `giai_thua(n)` thay vì `giai_thua(n - 1)`). Khi đó, Python sẽ liên tục tự gọi hàm cho đến khi vượt quá giới hạn độ sâu đệ quy cho phép, rồi báo lỗi `RecursionError`. Vì vậy, mỗi khi viết một hàm đệ quy mới, hãy luôn tự hỏi hai điều: trường hợp nhỏ nhất — điều kiện dừng — là gì, và mỗi lượt gọi tiếp theo có thực sự tiến gần hơn tới trường hợp đó hay không."}],"keypoints":["**Đệ quy** là khi một hàm **tự gọi lại chính nó** để giải một bài toán nhỏ hơn nhưng cùng dạng với bài toán ban đầu — bài toán cỡ `n` được giải dựa trên kết quả của bài toán cỡ `n - 1`.","Mọi hàm đệ quy đều bắt buộc phải có **điều kiện dừng (base case)** — trường hợp nhỏ nhất, giải được ngay không cần gọi tiếp; thiếu điều kiện dừng sẽ khiến hàm gọi mãi không dừng, gây tràn ngăn xếp (`RecursionError`).","Ví dụ kinh điển: tính giai thừa với `giai_thua(n) = n * giai_thua(n - 1)`, điều kiện dừng tại `n = 0`; hay tính tổng `1 + 2 + ... + n` với điều kiện dừng tại `n = 1`.","Đệ quy giúp code ngắn gọn, tự nhiên với các bài toán chia nhỏ được thành bài toán cùng dạng; nhưng mỗi lượt tự gọi phải luôn **tiến gần hơn** về điều kiện dừng."],"quiz":["CB-mc-1901","CB-mc-1902","CB-mc-1903","CB-mc-1904","CB-mc-1905","CB-tf-1901"]},
    {"id":"C11-20","stage":21,"order":20,"topic":"E","grade":11,"minutes":10,"title":"Nhóm nghề dịch vụ và quản trị trong lĩnh vực tin học","intro":"Bài học giới thiệu những nghề nghiệp giữ cho hệ thống tin học vận hành trơn tru mỗi ngày — quản trị mạng và hệ thống, quản trị cơ sở dữ liệu, hỗ trợ kĩ thuật, kiểm thử phần mềm, chuyên viên an toàn thông tin — cùng những kĩ năng cần có và con đường học tập để theo đuổi các nghề này.","sections":[{"t":"story","text":"Hãy hình dung một đêm diễn lớn tại một nhà hát: ánh đèn sân khấu bật sáng, diễn viên bước ra, khán giả vỗ tay không ngớt. Nhưng phía sau tấm màn nhung, còn cả một đội ngũ khác mà khán giả gần như không bao giờ nhìn thấy: người phụ trách âm thanh liên tục căn chỉnh micro để giọng hát không bị rè; người phụ trách ánh sáng đổi màu đèn đúng từng nhịp nhạc; đội hậu đài lặng lẽ kéo phông, dời đạo cụ trong bóng tối; và cả người canh cửa an ninh, đảm bảo không có sự cố nào bên ngoài lọt vào giữa buổi diễn.\n\nKhán giả chỉ chú ý đến diễn viên trên sân khấu, nhưng chỉ cần một trong những người phía sau lơ là — micro rè tiếng, đèn tắt giữa chừng, đạo cụ dời không kịp — cả buổi diễn có thể rối tung ngay lập tức, dù diễn viên có tài giỏi đến đâu.\n\nMột hệ thống tin học — trang mạng bán hàng, ứng dụng ngân hàng, phần mềm quản lí của một công ty — cũng vận hành theo cách tương tự. Người lập trình viên viết ra phần mềm cũng giống như biên kịch và đạo diễn dàn dựng vở diễn; nhưng để vở diễn ấy chạy trơn tru mỗi ngày, không gián đoạn, không rò rỉ thông tin, không sập giữa chừng khi có quá đông người truy cập, cần cả một đội ngũ đứng phía sau — làm những nghề **dịch vụ** và **quản trị** trong lĩnh vực tin học. Bài học này giới thiệu những nghề thầm lặng nhưng không thể thiếu đó."},{"t":"h","text":"1) Không chỉ có nghề lập trình viên"},{"t":"text","text":"Khi nhắc đến ‘làm nghề tin học’, phần lớn mọi người nghĩ ngay đến lập trình viên — người ngồi viết mã nguồn cho một ứng dụng, một trang web hay một trò chơi điện tử. Đó đúng là một nghề quan trọng, nhưng chỉ là một phần của bức tranh chung.\n\nMột phần mềm sau khi viết xong không tự nhiên chạy mãi mãi mà không cần ai chăm sóc. Nó cần chỗ để đặt lên (máy chủ `server`), cần đường truyền để người dùng truy cập vào (mạng máy tính), cần nơi lưu trữ dữ liệu phát sinh mỗi ngày (cơ sở dữ liệu), cần người giúp đỡ khi người dùng gặp khó khăn, cần người dò lỗi trước khi phát hành, và cần người bảo vệ trước những kẻ tấn công mạng. Tất cả những công việc đó gộp lại thành một nhóm nghề riêng, gọi chung là nhóm nghề **dịch vụ và quản trị** — không trực tiếp viết ra phần mềm mới, mà giữ cho những hệ thống đã có tiếp tục hoạt động ổn định, an toàn, đúng như mong đợi."},{"t":"h","text":"2) Điểm mặt các nghề dịch vụ và quản trị"},{"t":"list","text":"Trong nhóm nghề này, năm cái tên thường gặp nhất là:","items":["**Quản trị mạng và hệ thống** (`network and system administrator`): dựng và duy trì mạng máy tính, máy chủ của một cơ quan hay công ty, đảm bảo mọi máy tính, mọi bộ phận luôn kết nối được với nhau và với Internet một cách ổn định.","**Quản trị cơ sở dữ liệu** (`database administrator`, viết tắt `DBA`): trông coi kho dữ liệu — nơi lưu toàn bộ thông tin quan trọng của tổ chức, như thông tin khách hàng, đơn hàng, tài khoản — đảm bảo dữ liệu chính xác, an toàn và không bị mất khi có sự cố.","**Hỗ trợ kĩ thuật** (`IT support`): trực tiếp giúp đỡ người dùng — nhân viên trong công ty hoặc khách hàng — mỗi khi gặp trục trặc với máy tính, phần mềm, như máy không kết nối được máy in, phần mềm báo lỗi hay quên mật khẩu.","**Kiểm thử phần mềm** (`tester`): thử một phần mềm bằng nhiều tình huống khác nhau trước khi phần mềm đó được phát hành, nhằm phát hiện lỗi sớm, trước khi đến tay người dùng.","**Chuyên viên an toàn thông tin**: bảo vệ hệ thống và dữ liệu của tổ chức trước các cuộc tấn công mạng, hành vi truy cập trái phép hay nguy cơ rò rỉ thông tin."]},{"t":"h","text":"3) Một ngày làm việc trông như thế nào"},{"t":"example","text":"Để hình dung rõ hơn, hãy xem một ngày làm việc điển hình của một chuyên viên hỗ trợ kĩ thuật `IT support` tại một công ty:","code":"8:00 — Kiểm tra danh sách các yêu cầu hỗ trợ (ticket) gửi đến từ tối hôm trước\n9:15 — Một nhân viên báo máy tính không in được, đến tận bàn làm việc kiểm tra và khắc phục\n10:30 — Cài đặt phần mềm mới cho một nhân viên vừa được tuyển\n13:30 — Hướng dẫn qua điện thoại cho một chi nhánh ở xa cách đặt lại mật khẩu email\n15:00 — Ghi nhận một lỗi phần mềm lặp đi lặp lại, báo lên bộ phận quản trị hệ thống để kiểm tra sâu hơn\n16:30 — Cập nhật tài liệu hướng dẫn nội bộ, tổng kết các sự cố đã xử lí trong ngày","output":"Phần lớn thời gian trong ngày không dành để viết một dòng mã nguồn nào, mà dành để lắng nghe, xác định đúng vấn đề và xử lí sự cố cho người khác — công việc thay đổi liên tục theo những gì phát sinh trong ngày hôm đó. Quản trị mạng và hệ thống, quản trị cơ sở dữ liệu hay chuyên viên an toàn thông tin cũng có nhịp làm việc tương tự: phần lớn thời gian âm thầm theo dõi hệ thống, và bật chế độ xử lí khẩn khi có sự cố xảy ra."},{"t":"h","text":"4) Kĩ năng cần có và con đường học tập"},{"t":"list","text":"Vì công việc xoay quanh việc hỗ trợ người khác và xử lí sự cố phát sinh, nhóm nghề này đòi hỏi một số kĩ năng riêng, bên cạnh kiến thức kĩ thuật nền tảng:","items":["**Cẩn thận, tỉ mỉ**: một thao tác nhầm khi quản trị mạng hay cơ sở dữ liệu có thể khiến cả hệ thống ngừng hoạt động hoặc làm mất dữ liệu quan trọng của cả tổ chức.","**Giao tiếp tốt**: biết giải thích một vấn đề kĩ thuật bằng ngôn ngữ dễ hiểu cho người không rành công nghệ, đồng thời giữ bình tĩnh khi người khác đang bực bội vì gặp sự cố.","**Khả năng giải quyết sự cố**: nhanh chóng xác định đúng nguyên nhân giữa hàng loạt khả năng — mạng chậm, phần mềm báo lỗi, dữ liệu sai lệch — rồi xử lí đúng hướng thay vì thử ngẫu nhiên.","**Tự học, cập nhật liên tục**: công nghệ, phần mềm và cả các hình thức tấn công mạng đều thay đổi liên tục, đòi hỏi phải tự cập nhật kiến thức thường xuyên để không bị lạc hậu.","**Ngoại ngữ**, nhất là tiếng Anh: phần lớn tài liệu kĩ thuật, thông báo lỗi và diễn đàn trao đổi chuyên môn đều bằng tiếng Anh."]},{"t":"text","text":"Muốn theo đuổi nhóm nghề này, một hướng đi phổ biến là học các chương trình phù hợp ở trường nghề, cao đẳng hoặc đại học, thuộc các ngành như công nghệ thông tin, mạng máy tính, hệ thống thông tin hay an toàn thông tin. Bên cạnh bằng cấp, nhiều nhà tuyển dụng trong nhóm nghề này còn coi trọng **chứng chỉ chuyên môn** — những chứng nhận xác nhận đã thành thạo một kĩ năng cụ thể, như quản trị một hệ thống mạng hay xử lí sự cố an toàn thông tin — đôi khi ngang bằng hoặc hơn cả bằng cấp khi xét tuyển.\n\nDù học ở đâu, thực hành vẫn là phần không thể thiếu: tự dựng một mạng nhỏ tại nhà, tự cài đặt và quản lí một cơ sở dữ liệu đơn giản, hay tham gia các cuộc thi, diễn đàn về an toàn thông tin — tất cả đều giúp tích luỹ kinh nghiệm thực tế trước khi chính thức đi làm."},{"t":"note","text":"Cũng như đội ngũ hậu đài của một đêm diễn, những người làm nghề dịch vụ và quản trị hiếm khi được nhắc tên, và phần lớn người dùng không hề biết đến sự tồn tại của họ. Nhưng chính nhờ họ mà mạng luôn thông suốt, dữ liệu luôn an toàn, và phần mềm luôn sẵn sàng phục vụ mỗi khi cần đến — một vai trò không kém phần quan trọng so với người đã viết ra phần mềm đó."}],"keypoints":["Bên cạnh lập trình viên, lĩnh vực tin học còn có nhóm nghề **dịch vụ và quản trị** — không viết phần mềm mới mà giữ cho hệ thống đã có tiếp tục chạy ổn định, an toàn.","Năm nghề tiêu biểu: **quản trị mạng và hệ thống**, **quản trị cơ sở dữ liệu** (`DBA`), **hỗ trợ kĩ thuật** (`IT support`), **kiểm thử phần mềm** (`tester`), và **chuyên viên an toàn thông tin** — mỗi nghề phụ trách một phần khác nhau của việc giữ hệ thống vận hành.","Kĩ năng cần có: cẩn thận, giao tiếp tốt, khả năng giải quyết sự cố, tự học cập nhật liên tục, và ngoại ngữ (đặc biệt tiếng Anh).","Con đường theo đuổi: học chương trình phù hợp ở trường nghề, cao đẳng hoặc đại học, lấy thêm **chứng chỉ chuyên môn**, và tích luỹ kinh nghiệm qua thực hành thực tế."],"quiz":["CB-mc-2001","CB-mc-2002","CB-mc-2003","CB-mc-2004","CB-mc-2005","CB-tf-2001"]},
    {"id":"C11-21","stage":21,"order":21,"topic":"A","grade":11,"minutes":11,"title":"Thiết lập và chăm sóc máy tính dùng hằng ngày","intro":"Biết máy tính có hệ điều hành là một chuyện, biết **giữ cho chiếc máy của mình chạy êm** lại là chuyện khác. Bài này bàn về những việc rất đời thường mà người dùng nào cũng nên làm: chọn đúng loại tài khoản đăng nhập, cài và gỡ phần mềm cho đúng cách, xử lí ứng dụng bị treo, cập nhật đều đặn và bảo trì máy định kì.","sections":[{"t":"story","text":"Chiếc laptop nhà bạn Ngân mới mua hồi đầu năm lớp 10. Lúc mới về, máy mở lên chỉ mất mươi giây là đã sẵn sàng gõ bài. Sang đến giữa lớp 11, cũng chiếc máy ấy, bấm nút nguồn rồi đi đun xong ấm nước quay lại màn hình vẫn còn đang quay quay. Mở một trang web thôi mà quạt kêu ù ù như máy sấy tóc.\n\nNgân đem máy sang nhà chú họ nhờ xem giúp. Chú không tháo máy ra, cũng không cài lại gì cả. Chú chỉ ngồi bấm vài chỗ, mở ra một danh sách dài dằng dặc những thứ đang chạy ngầm mà Ngân chưa từng biết là có: hai phần mềm tải nhạc cài từ hồi nào, một thanh công cụ lạ tự bám vào trình duyệt sau lần Ngân tải bộ phông chữ miễn phí, và bảy tám chương trình tự bật lên mỗi lần máy khởi động. Ổ đĩa thì còn trống đúng hơn một gi-ga-bai.\n\nChú tắt bớt những thứ không cần, gỡ hẳn mấy phần mềm lạ, dọn chỗ trống trên ổ đĩa rồi bật lại các bản cập nhật mà Ngân bấm ‘Để sau’ suốt ba tháng. Hôm sau máy khởi động lại nhanh gần như hồi mới mua.\n\nĐiều đáng nói là chú không làm gì cao siêu cả. Toàn bộ những thao tác ấy đều nằm sẵn trong máy, ai cũng bấm được, chỉ là phải biết chúng ở đâu và hiểu vì sao phải làm. Bài học này chính là về những việc đó."},{"t":"h","text":"1) Hai loại tài khoản trên cùng một chiếc máy"},{"t":"text","text":"Trên một máy tính, mỗi người dùng đăng nhập bằng một **tài khoản người dùng** riêng, có tên đăng nhập, mật khẩu và khu vực dữ liệu riêng. Nhưng không phải tài khoản nào cũng có quyền hạn như nhau. Người ta phân biệt hai mức: **tài khoản quản trị** (thường gọi là `admin`) và **tài khoản thường** (`standard user`).\n\nTài khoản quản trị được phép làm những việc động chạm đến cả hệ thống: cài đặt hoặc gỡ bỏ phần mềm, thay đổi thiết lập chung của máy, tạo và xoá tài khoản khác, sửa những vùng dữ liệu dùng chung của cả máy. Tài khoản thường thì chỉ được làm việc trong phạm vi của mình — mở ứng dụng đã cài, tạo và sửa tệp trong thư mục cá nhân — còn muốn thay đổi hệ thống thì máy sẽ hỏi mật khẩu quản trị.\n\nVậy tại sao không dùng luôn tài khoản quản trị cho tiện? Lí do nằm ở chỗ: mọi phần mềm bạn chạy đều được thừa hưởng đúng quyền của tài khoản đang đăng nhập. Nếu bạn lỡ mở một tệp đính kèm có mã độc trong khi đang dùng tài khoản quản trị, mã độc đó lập tức có quyền sửa cả hệ thống. Cũng tệp ấy nhưng mở dưới tài khoản thường thì nó bị chặn lại ở ranh giới thư mục cá nhân, thiệt hại nhỏ hơn hẳn. Nguyên tắc chung là **dùng tài khoản thường cho mọi việc hằng ngày**, chỉ nâng lên quyền quản trị đúng lúc cần và đúng việc cần."},{"t":"list","text":"Khi một chiếc máy có nhiều người cùng dùng — máy ở nhà, máy trong phòng thực hành — nên thiết lập tài khoản theo hướng sau:","items":["Mỗi người một tài khoản thường riêng, để tệp của ai nằm trong thư mục của người đó, không lẫn lộn và không xoá nhầm của nhau.","Chỉ giữ đúng một tài khoản quản trị, do người chịu trách nhiệm về máy nắm, và tài khoản đó không dùng để lướt web hay tải phần mềm hằng ngày.","Mật khẩu tài khoản quản trị phải khác hẳn và mạnh hơn mật khẩu tài khoản thường; đừng dán mẩu giấy ghi mật khẩu ngay cạnh màn hình.","Bật chế độ tự khoá màn hình sau vài phút không thao tác, đề phòng lúc rời bàn học mà quên đăng xuất.","Khi cho người lạ mượn máy một lát, hãy để họ dùng tài khoản khách hoặc tài khoản thường, tuyệt đối không đưa tài khoản quản trị."]},{"t":"h","text":"2) Cài đặt và gỡ bỏ phần mềm cho đúng cách"},{"t":"text","text":"Chuyện rắc rối của máy thường bắt đầu ngay từ khâu tải phần mềm về. Cùng một phần mềm nhưng tải từ trang chủ của nhà phát triển hoặc từ **kho ứng dụng chính thức** của hệ điều hành thì bạn nhận đúng bản gốc; còn tải từ một trang chia sẻ lạ đứng đầu kết quả tìm kiếm thì rất có thể bạn nhận bản đã bị ai đó nhét thêm thứ khác vào. Đây chính là con đường mà thanh công cụ lạ trong câu chuyện đầu bài đã đi vào máy bạn Ngân.\n\nKhi trình cài đặt chạy lên, đừng bấm `Next` liên tục cho nhanh. Nhiều bộ cài đi kèm các mục đã tích sẵn kiểu ‘cài thêm phần mềm bạn đồng hành’ hoặc ‘đặt trang tìm kiếm mặc định’. Chỉ cần đọc kĩ từng bước và bỏ tích những mục mình không cần là đã tránh được phần lớn phiền toái về sau. Cũng nên để ý xem phần mềm đòi những quyền gì — một ứng dụng máy tính bỏ túi mà xin quyền truy cập danh bạ, vị trí thì rõ ràng là bất thường.\n\nKhi không dùng nữa, hãy gỡ bằng **chức năng gỡ cài đặt** của hệ điều hành, chứ đừng xoá thư mục cài đặt cho nhanh. Một phần mềm khi cài không chỉ chép tệp vào một thư mục: nó còn ghi thông tin vào cấu hình hệ thống, đăng kí dịch vụ chạy ngầm, tạo mục tự khởi động. Xoá tay thư mục chỉ dọn được phần thấy được, còn phần ghi trong hệ thống vẫn nằm nguyên đó và tiếp tục làm máy chậm, thậm chí sinh lỗi khi khởi động."},{"t":"h","text":"3) Xem và điều khiển các chương trình đang chạy"},{"t":"example","text":"Mỗi phần mềm đang chạy được hệ điều hành coi là một **tiến trình** (`process`), và mỗi tiến trình chiếm một phần năng lực tính toán của `CPU` cùng một phần dung lượng `RAM`. Công cụ có sẵn trong hệ điều hành — trên Windows là `Task Manager` (Trình quản lí tác vụ), gọi nhanh bằng `Ctrl + Shift + Esc` — cho bạn xem toàn bộ danh sách đó theo thời gian thực.\n\nGiả sử máy đang ì ạch, bạn mở công cụ này lên và thấy bảng như dưới đây. Chỉ cần nhìn cột `CPU` và cột `RAM` là biết ngay thủ phạm, còn cột trạng thái cho biết ứng dụng nào đã thật sự bị treo.","code":"TRÌNH QUẢN LÍ TÁC VỤ — Các tiến trình đang chạy\n------------------------------------------------------\nTên tiến trình          CPU     RAM       Trạng thái\nTrình duyệt web         64 %    1,9 GB    Đang chạy\nPhần mềm vẽ hình        23 %    740 MB    Không phản hồi\nỨng dụng nhắn tin        3 %    280 MB    Đang chạy\nPhần mềm diệt vi-rút     1 %    190 MB    Đang chạy\nTiện ích kiểm tra bản vá 0 %     45 MB    Đang chạy\n------------------------------------------------------\nThẻ Khởi động (Startup): 8 chương trình tự bật cùng máy","output":"Phần mềm vẽ hình đang ở trạng thái Không phản hồi — chọn dòng đó rồi bấm Kết thúc tác vụ là đóng riêng nó, các ứng dụng khác vẫn chạy bình thường, không cần tắt cứng cả máy."},{"t":"h","text":"4) Cập nhật hệ điều hành và phần mềm"},{"t":"text","text":"Không có phần mềm nào hoàn hảo ngay từ ngày phát hành. Sau khi sản phẩm đến tay người dùng, nhà phát triển vẫn tiếp tục phát hiện những chỗ chạy sai và những **lỗ hổng bảo mật** — tức là những sơ hở trong mã nguồn cho phép kẻ xấu chen vào làm điều chúng không được phép làm. Mỗi lần vá xong, họ phát hành một **bản cập nhật** (`update`) để sửa lại phần đã hỏng trên máy của tất cả mọi người.\n\nĐiều nhiều người không để ý là: khi một bản vá được phát hành, nội dung lỗ hổng mà nó vá thường cũng được công bố kèm theo. Nghĩa là từ thời điểm đó trở đi, kẻ xấu cũng biết chính xác chỗ nào yếu và tấn công vào đâu. Máy nào đã cập nhật thì được che chắn; máy nào cứ bấm ‘Để sau’ hết lần này đến lần khác thì lại đang phơi ra đúng cái sơ hở vừa được công bố. Trì hoãn cập nhật vì thế không phải là ‘giữ nguyên hiện trạng’ mà thực chất là để rủi ro tăng dần theo thời gian.\n\nCách làm hợp lí là bật chế độ cập nhật tự động cho hệ điều hành và cho các phần mềm quan trọng như trình duyệt, phần mềm diệt vi-rút; đồng thời chọn khung giờ cài đặt vào lúc không dùng máy để khỏi bị gián đoạn giữa buổi học. Trước những bản cập nhật lớn, nên sao lưu các tệp quan trọng và cắm nguồn điện, tránh máy hết pin giữa chừng."},{"t":"h","text":"5) Bảo trì định kì và biết rõ cấu hình máy mình"},{"t":"text","text":"Việc bảo trì đơn giản nhất là **kiểm tra dung lượng ổ đĩa còn trống**. Hệ điều hành cần một khoảng trống nhất định để làm chỗ xoay xở khi chạy — ghi tệp tạm, mở rộng vùng nhớ ảo, tải bản cập nhật về. Khi ổ đĩa gần đầy, máy chậm đi thấy rõ và các bản cập nhật cũng không cài nổi. Nên tập thói quen giữ ổ chứa hệ điều hành còn trống ít nhất khoảng một phần mười dung lượng.\n\nMuốn giải phóng chỗ, đừng vội xoá tài liệu học tập. Hãy dọn trước hai nguồn rác vô hại: **tệp tạm** do các phần mềm sinh ra rồi bỏ quên (hệ điều hành có sẵn công cụ dọn dẹp ổ đĩa để làm việc này) và **thùng rác**, nơi những tệp bạn tưởng đã xoá vẫn đang nằm và vẫn chiếm chỗ cho tới khi bị dọn hẳn. Kèm theo đó là gỡ những phần mềm nhiều tháng rồi không mở lần nào.\n\nCuối cùng, hãy tập nhìn **thông tin cấu hình máy**: loại `CPU`, dung lượng `RAM`, phiên bản hệ điều hành đang chạy là 32 bit hay 64 bit, dung lượng ổ còn lại. Những con số này giúp bạn trả lời một câu hỏi rất thực tế trước khi tải bất cứ phần mềm nào về: máy mình có chạy nổi nó không? Phần mềm nào cũng công bố **cấu hình tối thiểu** ở trang tải; đối chiếu hai bên với nhau sẽ đỡ mất công tải một bộ cài nặng vài `GB` về rồi mới phát hiện máy không đáp ứng nổi."}],"keypoints":["Máy tính phân biệt **tài khoản quản trị** (được thay đổi cả hệ thống) và **tài khoản thường**; nên dùng tài khoản thường cho việc hằng ngày vì mọi phần mềm, kể cả mã độc, đều thừa hưởng quyền của tài khoản đang đăng nhập.","Chỉ tải phần mềm từ **trang chính thức** hoặc kho ứng dụng, đọc kĩ từng bước cài để bỏ các mục đi kèm; khi bỏ dùng phải gỡ bằng **chức năng gỡ cài đặt** của hệ điều hành chứ không xoá thư mục.","**Trình quản lí tác vụ** cho phép xem các tiến trình đang chạy cùng mức chiếm `CPU`, `RAM`; dùng nó để **kết thúc tác vụ** bị treo và tắt bớt chương trình tự khởi động cùng máy.","**Cập nhật** có nhiệm vụ vá lỗi và vá **lỗ hổng bảo mật**, vì vậy càng trì hoãn thì rủi ro càng tăng; bảo trì cơ bản gồm giữ ổ đĩa còn trống, dọn **tệp tạm** cùng thùng rác và đối chiếu **cấu hình máy** với yêu cầu tối thiểu của phần mềm."],"quiz":["CB-mc-2101","CB-mc-2102","CB-mc-2103","CB-mc-2104","CB-mc-2105","CB-tf-2101"]},
    {"id":"C11-22","stage":21,"order":22,"topic":"A","grade":11,"minutes":11,"title":"Cổng kết nối, chuẩn không dây và trình điều khiển thiết bị","intro":"Bài học giúp bạn nhận ra từng loại **cổng kết nối** trên máy tính, phân biệt ba chuẩn không dây `Bluetooth`, `Wi-Fi`, `NFC`, hiểu vai trò của **trình điều khiển** (`driver`), và nắm quy trình kết nối — ngắt kết nối một thiết bị số sao cho an toàn.","sections":[{"t":"story","text":"Chiều thứ Sáu, câu lạc bộ Nhiếp ảnh của trường tổ chức buổi tổng kết chuyến đi thực tế. Ngọc được giao nhiệm vụ trình chiếu bộ ảnh và một đoạn phim ngắn lên màn hình lớn của phòng đa năng. Bạn ấy mang máy tính xách tay tới sớm nửa tiếng, khá tự tin vì bài trình chiếu đã làm xong từ tối hôm trước.\n\nNhưng mọi thứ không suôn sẻ như Ngọc tưởng. Sợi dây thả xuống từ máy chiếu có đầu cắm to bản, trong khi bên hông chiếc máy của Ngọc chỉ có mấy khe nhỏ dẹt — hai bên không khớp nhau chút nào. Đoạn phim thì vẫn còn nằm trong điện thoại, chưa kịp đưa sang máy tính. Chiếc loa mà thầy phụ trách mang tới lại không có dây, bật lên rồi mà tiếng vẫn phát ra từ loa sẵn có của máy.\n\nMay là bạn Hùng chạy xuống phòng thiết bị mượn được một chiếc đầu chuyển nhỏ, rồi hướng dẫn Ngọc bấm giữ nút trên loa vài giây cho đèn nhấp nháy, chờ tên loa hiện lên trên màn hình và chọn nó. Đoạn phim thì Hùng bảo cứ nối điện thoại với máy tính bằng đúng sợi dây sạc, chép thẳng sang. Mười phút sau, buổi tổng kết bắt đầu đúng giờ.\n\nCâu chuyện nhỏ ấy chạm đúng vào những gì ta sẽ học hôm nay: máy tính có những khe cắm nào và mỗi khe làm việc gì, các thiết bị không dây bắt tay với máy ra sao, vì sao đôi khi cắm vào rồi mà máy vẫn chưa chịu nhận, và làm thế nào để tháo một thiết bị ra mà không mất dữ liệu."},{"t":"h","text":"1) Các cổng kết nối có dây và công dụng của từng loại"},{"t":"text","text":"Nhìn vào cạnh bên hoặc mặt sau của một máy tính, ta thấy một dãy khe cắm với hình dạng khác hẳn nhau. Mỗi khe như vậy được gọi là một **cổng kết nối** (tiếng Anh là `port`). Cổng không đơn thuần là cái lỗ để cắm dây: mỗi loại cổng được thiết kế để truyền một kiểu tín hiệu nhất định, với tốc độ nhất định, theo một quy ước điện tử riêng mà cả máy tính lẫn thiết bị đầu kia đều phải tuân theo.\n\nChính vì thế, hình dạng khác nhau của các cổng là có chủ ý. Đó là cách nhà sản xuất chống cắm nhầm: một đầu dây xuất hình ảnh sẽ không thể nhét vừa vào khe dành cho dây mạng, nên người dùng khó mà gây hỏng hóc do lắp sai. Nói cách khác, nhìn hình dạng đầu cắm là đã đoán được nó dùng để làm gì.\n\nKhi mua hoặc mượn một thiết bị mới, việc đầu tiên nên làm là kiểm tra xem máy của mình có cổng phù hợp hay không. Nếu không có — như trường hợp máy của Ngọc trong câu chuyện đầu bài — ta cần một **đầu chuyển** (`adapter`) hoặc một **bộ chia cổng** (`hub`) để biến một cổng sẵn có thành loại cổng đang cần."},{"t":"list","text":"Năm loại cổng có dây bạn sẽ gặp nhiều nhất trên máy tính hiện nay:","items":["`USB-A` — khe chữ nhật dẹt quen thuộc, dùng cho chuột, bàn phím, ổ nhớ USB, máy in; chỉ cắm lọt theo đúng một chiều nên nhiều khi phải lật lại đầu dây.","`USB-C` — khe nhỏ, bo tròn hai đầu, cắm được cả hai chiều; vừa truyền dữ liệu nhanh, vừa sạc pin cho máy và cho điện thoại, trên nhiều máy còn xuất được cả hình ảnh ra màn hình rời.","`HDMI` — cổng chuyên xuất **hình ảnh và âm thanh cùng một lúc** ra màn hình rời, tivi hay máy chiếu, chỉ bằng một sợi dây duy nhất chứ không cần thêm dây tiếng.","Jack `3.5mm` — lỗ tròn nhỏ để cắm tai nghe hoặc loa có dây; đây là cổng truyền **âm thanh**, và trên nhiều máy nó kiêm luôn cả đường tiếng vào từ micrô.","`RJ45` — cổng cắm dây mạng, hình gần vuông có lẫy nhựa; dùng khi cần đường truyền ổn định hơn so với kết nối không dây, chẳng hạn lúc thi trực tuyến hay họp trực tuyến quan trọng."]},{"t":"h","text":"2) Kết nối không dây: Bluetooth, Wi-Fi và NFC"},{"t":"text","text":"Không phải thiết bị nào cũng nối vào máy bằng dây. Ba chuẩn không dây phổ biến nhất hiện nay là **Bluetooth**, **Wi-Fi** và **NFC**; điểm khác nhau căn bản giữa chúng nằm ở hai thứ: đi được xa bao nhiêu và truyền được nhanh bao nhiêu.\n\n**Bluetooth** sinh ra để nối máy với những thiết bị ở ngay bên cạnh: tai nghe, chuột, bàn phím, loa nhỏ, tay cầm chơi game. Phạm vi của nó chỉ khoảng mươi mét trở lại, tốc độ vừa phải — đủ cho âm thanh và các lệnh điều khiển, chứ chép một thư mục ảnh lớn thì rất lâu. Đổi lại, Bluetooth tốn rất ít điện. Điểm cần nhớ là lần đầu dùng, hai bên phải **ghép đôi** (`pairing`): thiết bị được đưa vào chế độ chờ, máy tính dò tìm rồi ghi nhận tên nó; từ lần sau, chỉ cần bật lên là hai bên tự nhận ra nhau.\n\n**Wi-Fi** có phạm vi rộng hơn hẳn — vài chục mét trong nhà — và tốc độ cao gấp nhiều lần Bluetooth, nên ngoài việc đưa máy vào mạng, nó còn dùng để chiếu màn hình không dây hoặc gửi tệp dung lượng lớn giữa các thiết bị trong cùng một mạng. Ở đầu bên kia của thang đo là **NFC**, chỉ hoạt động khi hai thiết bị chạm hoặc gần như chạm vào nhau, trong vòng vài xăng-ti-mét, với tốc độ rất thấp. Đúng vì phạm vi cực ngắn ấy mà NFC được tin dùng cho thẻ ra vào không tiếp xúc, vé xe buýt và thanh toán chạm: kẻ đứng cách vài mét không thể chen vào. Tóm lại, xếp theo cả phạm vi lẫn tốc độ, thứ tự tăng dần là NFC, rồi Bluetooth, rồi Wi-Fi."},{"t":"h","text":"3) Trình điều khiển thiết bị: vì sao cắm vào mà máy chưa nhận"},{"t":"text","text":"Cắm một chiếc máy in mới vào cổng USB, máy tính kêu \"tinh\" một tiếng báo có thiết bị lạ, nhưng bấm In thì chẳng thấy gì xảy ra. Nguyên nhân thường gặp nhất không nằm ở sợi dây hay cái cổng, mà ở chỗ hệ điều hành chưa biết phải ra lệnh cho thiết bị đó như thế nào.\n\nHệ điều hành làm việc theo những câu lệnh chung chung kiểu \"in trang này ra\", trong khi mỗi model máy in của mỗi hãng lại có cách nhận lệnh riêng, rất chi tiết và rất khác nhau. Cầu nối giữa hai bên chính là **trình điều khiển thiết bị**, tiếng Anh gọi là `driver` — một phần mềm nhỏ đóng vai người phiên dịch, chuyển yêu cầu chung của hệ điều hành thành đúng những tín hiệu mà riêng thiết bị đó hiểu được. Không có driver phù hợp, phần cứng vẫn nằm im dù dây nối vẫn tốt nguyên.\n\nVới các thiết bị phổ thông như chuột, bàn phím, ổ nhớ USB, hệ điều hành đã có sẵn driver dùng chung nên vừa cắm là chạy — đó là cơ chế \"cắm là chạy\" (`plug and play`). Nhưng máy in, máy quét, bảng vẽ điện tử hay card đồ hoạ rời thì thường phải cài thêm. Cách làm đúng là vào **trang web chính hãng của nhà sản xuất**, chọn đúng tên model và đúng phiên bản hệ điều hành đang dùng, tải bộ cài về rồi chạy. Muốn kiểm tra thiết bị nào đang thiếu driver, ta mở mục quản lí thiết bị của hệ điều hành (`Device Manager` trên Windows) và tìm những dòng có dấu chấm than màu vàng."},{"t":"note","text":"Tuyệt đối tránh tải driver từ những trang \"kho driver tổng hợp\" hoặc cài các phần mềm hứa hẹn \"tự động cập nhật mọi driver\" tìm được trên mạng. Đây là con đường phát tán **mã độc** rất phổ biến, vì driver chạy với quyền rất cao trong hệ thống — một driver giả mạo có thể kiểm soát gần như toàn bộ máy. Cũng cần nhớ rằng driver mới nhất không phải lúc nào cũng tốt nhất: nếu thiết bị đang chạy ổn định thì không nhất thiết phải cập nhật, chỉ nên cập nhật khi thiết bị gặp lỗi hoặc khi hãng thông báo bản vá quan trọng."},{"t":"h","text":"4) Kết nối, ngắt kết nối an toàn và chuyển dữ liệu với điện thoại"},{"t":"example","text":"Dù là thiết bị có dây hay không dây, quy trình kết nối đều đi qua bốn chặng giống nhau: tạo liên kết vật lí (cắm dây) hoặc mở chế độ ghép đôi, chờ máy nhận ra thiết bị, kiểm tra xem nó đã xuất hiện trong danh sách thiết bị chưa, và cuối cùng là chọn nó làm nguồn phát hoặc nguồn thu. Chặng cuối rất hay bị bỏ quên: máy đã kết nối với loa rồi nhưng tiếng vẫn ra loa cũ, đơn giản vì chưa ai chọn loa mới làm thiết bị phát.\n\nỞ chiều ngược lại, việc tháo thiết bị ra cũng cần đúng cách. Khi ta chép tệp vào ổ nhớ USB, hệ điều hành thường chưa ghi hết ngay mà giữ tạm một phần dữ liệu trong bộ nhớ để ghi gộp cho nhanh. Rút phăng ổ ra ngay lúc đó có thể làm tệp ghi dở, hỏng dữ liệu, thậm chí hỏng cả cấu trúc thư mục của ổ.\n\nDưới đây là hai quy trình mẫu mà bạn nên thuộc lòng.","code":"QUY TRÌNH 1 — Ghép đôi loa Bluetooth với máy tính\n  B1. Bật loa, bấm giữ nút Bluetooth đến khi đèn nhấp nháy (chế độ ghép đôi)\n  B2. Trên máy: mở Cài đặt > Thiết bị > Bluetooth, gạt Bluetooth sang BẬT\n  B3. Chọn \"Thêm thiết bị\", chờ tên loa hiện ra trong danh sách dò được\n  B4. Nháy vào tên loa -> máy báo \"Đã kết nối\"\n  B5. Vào mục Âm thanh, CHỌN loa vừa ghép làm thiết bị phát\n\nQUY TRÌNH 2 — Tháo ổ nhớ USB an toàn\n  B1. Lưu và đóng mọi tệp đang mở nằm trong ổ nhớ\n  B2. Nháy vào biểu tượng ổ USB ở khay hệ thống (góc dưới bên phải)\n  B3. Chọn \"Eject\" / \"Ngắt kết nối\" đúng tên ổ đang dùng\n  B4. Chờ dòng thông báo \"Có thể tháo thiết bị an toàn\"\n  B5. Lúc này mới rút ổ ra khỏi cổng","output":"Loa được chọn đúng làm thiết bị phát âm thanh, và ổ nhớ USB được tháo ra mà dữ liệu vẫn nguyên vẹn."},{"t":"text","text":"Một tình huống kết nối rất hay gặp khác là đưa dữ liệu qua lại giữa điện thoại và máy tính. Việc chuyển ảnh, video hay bài tập theo cả hai chiều có ít nhất bốn con đường, mỗi con đường mạnh ở một hoàn cảnh khác nhau. Nối bằng **cáp** là cách nhanh và chắc chắn nhất: cắm sợi cáp `USB-C` hoặc cáp sạc vào máy, chọn chế độ truyền tệp trên màn hình điện thoại, rồi kéo thả thư mục ảnh như với một ổ nhớ thông thường. Nhược điểm là phải có sẵn đúng loại cáp và phải ngồi cạnh máy.\n\nGửi qua **Bluetooth** thì tiện vì không cần dây gì cả, nhưng tốc độ thấp nên chỉ hợp với vài tấm ảnh hoặc một tệp nhỏ; định chuyển cả một album vài trăm ảnh bằng Bluetooth thì sẽ phải chờ rất lâu. Truyền **qua mạng nội bộ** — dùng thư mục chia sẻ hoặc một ứng dụng gửi tệp trong cùng một mạng Wi-Fi — nhanh hơn Bluetooth rất nhiều và không cần Internet, nhưng đòi hỏi hai thiết bị phải ở chung một mạng và đôi khi phải cấu hình chút ít.\n\nCuối cùng là **dịch vụ lưu trữ trực tuyến**: tải tệp lên từ điện thoại rồi tải xuống ở bất kì máy nào. Cách này mạnh ở chỗ hai thiết bị không cần ở gần nhau, lại có sẵn một bản sao lưu trên mạng; đổi lại, nó phụ thuộc hoàn toàn vào chất lượng đường truyền Internet, tốn dung lượng dữ liệu di động nếu không có Wi-Fi, và bạn phải cân nhắc về quyền riêng tư khi đưa dữ liệu cá nhân lên một dịch vụ của bên thứ ba. Nguyên tắc chọn khá đơn giản: dữ liệu lớn và hai máy ở cạnh nhau thì dùng cáp; vài tệp nhỏ, cần nhanh gọn thì dùng Bluetooth; cần dùng lại ở nhiều nơi hoặc chia sẻ cho người khác thì dùng dịch vụ trực tuyến."}],"keypoints":["Mỗi **cổng kết nối** có nhiệm vụ riêng: `USB-A` và `USB-C` cho chuột, bàn phím, ổ nhớ và sạc; `HDMI` xuất **cả hình ảnh lẫn âm thanh** ra màn hình hoặc máy chiếu; jack `3.5mm` cho âm thanh; `RJ45` cho dây mạng.","**Bluetooth** nối máy với tai nghe, chuột, loa trong phạm vi khoảng mươi mét và lần đầu phải **ghép đôi**; **Wi-Fi** xa hơn và nhanh hơn nhiều; **NFC** chỉ vài xăng-ti-mét, dùng để chạm trao đổi mẩu thông tin nhỏ.","**Trình điều khiển** (`driver`) là phần mềm giúp hệ điều hành hiểu và điều khiển được một thiết bị; cắm thiết bị mới mà máy chưa nhận thường là do thiếu driver, và chỉ nên tải driver từ **trang chính hãng**.","Kết nối xong phải **kiểm tra trong danh sách thiết bị** rồi chọn đúng thiết bị làm nguồn phát/thu; khi dùng xong ổ nhớ USB phải **ngắt kết nối an toàn** trước khi rút để tránh hỏng dữ liệu."],"quiz":["CB-mc-2201","CB-mc-2202","CB-mc-2203","CB-mc-2204","CB-mc-2205","CB-tf-2201"]},
    {"id":"C11-23","stage":21,"order":23,"topic":"B","grade":11,"minutes":11,"title":"Dùng thư điện tử và mạng xã hội một cách chuyên nghiệp","intro":"Ai cũng biết bấm nút gửi thư, nhưng gửi vào ô nào, đính kèm ra sao, đặt tiêu đề thế nào và chia sẻ đến đâu thì lại là chuyện khác. Bài học chỉ ra những **thao tác và thiết lập** giúp bạn dùng hộp thư và trang mạng xã hội vừa gọn gàng, vừa giữ được sự riêng tư.","sections":[{"t":"story","text":"Lớp 11A5 chuẩn bị đi trải nghiệm ở làng nghề gốm, và Minh được cô chủ nhiệm giao việc báo tin cho gia đình các bạn. Minh gõ liền một mạch ba mươi tám địa chỉ của phụ huynh vào ô người nhận, đính kèm tấm ảnh chụp bản kế hoạch cùng đoạn phim giới thiệu làng nghề, rồi bấm gửi và thở phào.\n\nMọi chuyện không êm như Minh nghĩ. Vài phút sau, hệ thống báo lại rằng thư không đi được vì phần đính kèm quá nặng. Minh bỏ đoạn phim ra, gửi lại, lần này thì thư đến nơi — nhưng đến kèm một rắc rối khác: ba mươi tám phụ huynh vốn không quen nhau đều nhìn thấy đầy đủ địa chỉ thư của nhau ngay đầu lá thư. Rồi một bác bấm nút trả lời để hỏi giờ tập trung, mà lỡ tay bấm nhầm sang nút trả lời cho tất cả, thế là ba mươi tám hộp thư cùng kêu một lượt. Sau đó là hàng chục câu trả lời chồng lên nhau, ai cũng bực.\n\nTối hôm ấy, Minh còn đăng lên trang cá nhân tấm ảnh chụp màn hình danh sách lớp kèm dòng chữ ‘đi chơi thôi cả nhà ơi’. Sáng hôm sau bạn xoá đi, nhưng đã có người kịp lưu lại tấm ảnh đó.\n\nBa sự cố trong một ngày, cả ba đều không phải vì Minh không biết dùng máy tính. Chúng xảy ra chỉ vì bạn chưa biết một vài quy tắc và vài thiết lập rất nhỏ — đúng những thứ chúng ta sẽ học trong bài này."},{"t":"h","text":"1) Địa chỉ thư điện tử và ba ô người nhận"},{"t":"text","text":"Mỗi địa chỉ thư điện tử luôn có dạng `tên_người_dùng@tên_miền`, chẳng hạn `thuha.11a5@truongbinhminh.edu.vn`. Phần đứng trước dấu `@` là **tên người dùng** — do bạn tự chọn khi lập hộp thư, phân biệt bạn với những người khác trên cùng hệ thống. Phần đứng sau dấu `@` là **tên miền**, cho biết hộp thư đó do máy chủ của tổ chức nào quản lí. Chính vì vậy, chỉ nhìn phần sau dấu `@` là đã đoán được thư đến từ một trường học, một doanh nghiệp hay một dịch vụ thư miễn phí.\n\nKhi soạn thư, phần mềm luôn cho bạn ba ô để điền địa chỉ người nhận. Ô **To** (Đến) dành cho người mà lá thư nhắm tới trực tiếp — người bạn mong họ đọc và trả lời. Ô **Cc** (đồng gửi) dành cho những người chỉ cần biết chuyện, không nhất thiết phải trả lời; điểm mấu chốt là mọi người trong ô To và Cc đều nhìn thấy đầy đủ danh sách nhau. Ô **Bcc** (gửi kín) cũng gửi thư đi bình thường, nhưng địa chỉ đặt trong ô này bị giấu đi: người nhận thấy thư, còn những người nhận khác thì không hề biết là bạn đã gửi cho họ.\n\nTừ đó suy ra một quy tắc rất đáng nhớ: khi gửi cùng một lá thư cho nhiều người **không quen biết nhau** — như danh sách phụ huynh của Minh, danh sách thí sinh, danh sách khách mời — thì bắt buộc đặt các địa chỉ đó vào ô Bcc. Làm vậy vừa tránh để lộ địa chỉ của người này cho người kia, vừa chặn được cảnh cả trăm người cùng bấm ‘trả lời tất cả’ làm loạn hộp thư của nhau."},{"t":"list","text":"Ba ô người nhận dùng trong những tình huống khác nhau:","items":["To: người trực tiếp phải xử lí việc — ví dụ gửi bài tập cho thầy dạy Tin.","Cc: người cần nắm thông tin để theo dõi — ví dụ đồng gửi cho lớp trưởng biết bạn đã nộp bài.","Bcc: gửi hàng loạt cho những người không quen nhau, hoặc khi muốn một người biết chuyện mà không để người nhận chính nhận ra.","Không bao giờ dán một danh sách dài địa chỉ vào ô To — đó là cách nhanh nhất để làm lộ thông tin của người khác.","Trước khi bấm ‘trả lời tất cả’, hãy tự hỏi: có thật là cả danh sách này cần đọc câu trả lời của mình không?"]},{"t":"h","text":"2) Đính kèm tệp: nén lại hay gửi liên kết?"},{"t":"text","text":"Mỗi dịch vụ thư điện tử đều đặt ra một **giới hạn dung lượng** cho phần đính kèm của một lá thư, thường chỉ vào khoảng vài chục MB. Ngoài ra, bản thân hộp thư của bạn và của người nhận cũng có sức chứa hữu hạn. Vượt quá ngưỡng nào đó, thư sẽ bị hệ thống từ chối và trả về — đúng như chuyện đã xảy ra với đoạn phim làng nghề của Minh.\n\nKhi tệp hơi lớn một chút hoặc khi cần gửi nhiều tệp cùng lúc, cách xử lí quen thuộc là **nén tệp** thành một gói duy nhất có phần mở rộng `.zip`. Nén vừa làm giảm dung lượng (rất hiệu quả với văn bản, bảng tính, mã nguồn; kém hiệu quả với ảnh và phim vì chúng đã được nén sẵn), vừa gói hàng chục tệp lẻ thành một tệp gọn gàng để người nhận chỉ phải tải một lần.\n\nCòn khi tệp thật sự nặng — một đoạn phim quay bằng điện thoại, một tập ảnh của cả buổi lễ — thì nén cũng vô ích. Lúc đó, cách đúng là tải tệp lên một **kho lưu trữ trực tuyến**, đặt quyền xem cho phù hợp, rồi chỉ dán **liên kết** tới tệp đó vào thư. Lá thư nhẹ tênh, gửi đi tức thì, người nhận vẫn lấy được đầy đủ nội dung, và nếu bạn sửa lại tệp thì họ luôn thấy bản mới nhất mà không cần bạn gửi thư lần hai."},{"t":"h","text":"3) Giữ hộp thư gọn gàng và xử lí thư rác"},{"t":"list","text":"Một hộp thư dùng lâu năm sẽ nhanh chóng ngập trong hàng nghìn lá thư nếu bạn không tổ chức nó. Điều may mắn là mọi dịch vụ thư đều có sẵn các công cụ sắp xếp, chỉ cần bạn bật lên và dùng đúng cách:","items":["Nhãn hoặc thư mục: gắn cho mỗi lá thư một nhãn như ‘Học tập’, ‘Tuyển sinh’, ‘Câu lạc bộ’ để về sau lọc ra nhanh; một lá thư có thể mang nhiều nhãn cùng lúc.","Bộ lọc tự động: đặt quy tắc kiểu ‘thư nào gửi từ địa chỉ của thầy chủ nhiệm thì tự gắn nhãn Lớp và chuyển khỏi hộp thư đến’, để thư tự vào đúng chỗ mà bạn không phải làm gì.","Tìm kiếm theo từ khoá: gõ tên người gửi, một cụm từ trong tiêu đề hoặc trong nội dung; kết hợp thêm điều kiện như khoảng thời gian hay ‘có tệp đính kèm’ để thu hẹp kết quả.","Đánh dấu thư rác: bấm nút báo thư rác thay vì chỉ xoá, vì như vậy hệ thống mới học được và tự chặn các thư tương tự về sau.","Huỷ đăng kí nhận thư quảng cáo: với thư quảng cáo hợp pháp, hãy tìm liên kết huỷ đăng kí ở cuối thư — cách này dứt điểm hơn nhiều so với việc ngày nào cũng xoá tay."]},{"t":"h","text":"4) Viết một lá thư trang trọng"},{"t":"example","text":"Thư gửi bạn bè có thể viết thoải mái, nhưng thư gửi thầy cô, gửi ban tổ chức một cuộc thi hay gửi bộ phận tuyển sinh của một trường đại học thì phải trang trọng. Người nhận những lá thư ấy mỗi ngày mở hàng trăm thư; một tiêu đề mơ hồ kiểu ‘Hỏi chút ạ’ rất dễ bị bỏ qua, còn một lá thư không ghi rõ mình là ai thì họ không biết đường trả lời.\n\nMột lá thư trang trọng đạt yêu cầu thường có đủ năm phần: **tiêu đề** ngắn nhưng nêu đúng việc, **lời chào** và xưng hô phù hợp, **phần tự giới thiệu** (tên, lớp, trường), **nội dung** trình bày rõ ràng tách thành từng ý, và cuối cùng là **lời cảm ơn cùng chữ ký** có thông tin liên hệ. Dưới đây là một lá thư mẫu do một bạn lớp 12 gửi bộ phận tuyển sinh.","code":"Tiêu đề: Hỏi về hồ sơ xét tuyển học bạ ngành Công nghệ thông tin 2026\n\nKính gửi Ban Tư vấn tuyển sinh Trường Đại học Kĩ thuật Sông Hồng,\n\nEm tên là Nguyễn Thu Hà, học sinh lớp 12A3 Trường THPT Bình Minh.\nEm đang chuẩn bị hồ sơ xét tuyển bằng học bạ vào ngành Công nghệ\nthông tin của Trường. Em xin phép hỏi hai điều:\n\n(1) Bản sao học bạ nộp kèm có cần công chứng không ạ?\n(2) Hạn cuối nộp hồ sơ trực tuyến là ngày nào ạ?\n\nEm xin chân thành cảm ơn thầy cô và mong sớm nhận được phản hồi.\n\nTrân trọng,\nNguyễn Thu Hà — Lớp 12A3, Trường THPT Bình Minh\nĐiện thoại: 0912 345 xxx","output":"Thư có đủ 5 phần: tiêu đề nêu đúng việc, lời chào, tự giới thiệu, nội dung tách thành từng ý, lời cảm ơn và chữ ký kèm liên hệ."},{"t":"h","text":"5) Quyền riêng tư trên mạng xã hội và dấu vết số"},{"t":"text","text":"Mặc định, nhiều trang mạng xã hội đặt chế độ hiển thị ở mức rộng nhất để bài viết của bạn lan xa nhất có thể — điều đó có lợi cho nền tảng, chưa chắc đã có lợi cho bạn. Vì vậy, việc đầu tiên nên làm sau khi lập tài khoản là mở mục thiết lập **quyền riêng tư** và tự tay chỉnh lại từng mục.\n\nCó bốn thiết lập đáng chỉnh nhất. Thứ nhất là **phạm vi người xem bài đăng**: chọn ‘chỉ bạn bè’ thay vì ‘công khai’, và nhớ rằng mỗi bài đăng mới đều có thể đặt riêng phạm vi khác nhau. Thứ hai là **ai được xem danh sách bạn bè** — để công khai thì người lạ dễ dàng dựng lại toàn bộ quan hệ của bạn. Thứ ba là **ai được xem thông tin cá nhân** như ngày sinh, số điện thoại, trường lớp, nơi ở; càng ít người thấy càng tốt. Thứ tư là **tắt gắn thẻ tự động** hoặc bật chế độ duyệt trước, để không ai gắn tên bạn vào một bức ảnh hay một bài viết mà bạn không hề hay biết.\n\nDù chỉnh kĩ đến đâu, vẫn phải nhớ một điều cốt lõi: mọi thứ đã đưa lên mạng đều để lại **dấu vết số** rất lâu dài. Chỉ cần một người kịp chụp lại màn hình hoặc lưu tấm ảnh về máy, thì việc bạn xoá bài sau đó không còn ý nghĩa gì nữa — bản sao vẫn tồn tại ngoài tầm với của bạn. Tấm ảnh danh sách lớp mà Minh vội xoá sáng hôm sau là một minh chứng. Nhiều năm sau, khi tuyển dụng hay xét học bổng, người ta hoàn toàn có thể tìm lại những gì bạn đăng hôm nay; vì thế, cách bảo vệ chắc chắn nhất luôn là **cân nhắc trước khi đăng**, chứ không phải xoá sau khi đăng."}],"keypoints":["Địa chỉ thư có dạng `tên_người_dùng@tên_miền`; **To** dành cho người phải xử lí, **Cc** cho người cần biết, còn **Bcc** giấu địa chỉ người nhận nên bắt buộc dùng khi gửi hàng loạt cho những người không quen nhau.","Mỗi thư có **giới hạn dung lượng đính kèm**: tệp hơi lớn thì **nén** thành `.zip`, tệp quá nặng thì tải lên **kho lưu trữ trực tuyến** rồi chỉ gửi **liên kết**.","Giữ hộp thư gọn bằng **nhãn/thư mục**, **bộ lọc tự động**, **tìm kiếm theo từ khoá**; với thư quảng cáo nên bấm **huỷ đăng kí** và đánh dấu **thư rác** thay vì chỉ xoá.","Thư trang trọng cần **tiêu đề nêu đúng việc**, xưng hô phù hợp, nội dung rõ ràng và **chữ ký** cuối thư; trên mạng xã hội phải tự chỉnh **quyền riêng tư** vì nội dung đã đăng để lại **dấu vết số** lâu dài dù đã xoá."],"quiz":["CB-mc-2301","CB-mc-2302","CB-mc-2303","CB-mc-2304","CB-mc-2305","CB-tf-2301"]},
    {"id":"C11-24","stage":21,"order":24,"topic":"C","grade":11,"minutes":12,"title":"Kho tài liệu trên đám mây: đồng bộ, phân quyền chia sẻ và cộng tác nhóm","intro":"Bài học đi sâu vào **kĩ năng thực hành** với một kho lưu trữ trực tuyến: sắp xếp tệp và thư mục, hiểu cơ chế **đồng bộ** giữa các thiết bị, chọn đúng **mức quyền** khi chia sẻ liên kết, và cùng nhiều người làm việc trên một tài liệu dùng chung mà không sợ mất dữ liệu.","sections":[{"t":"story","text":"Câu lạc bộ Đọc sách của lớp 11A3 nhận nhiệm vụ làm một bản tin giới thiệu sách cho buổi sinh hoạt dưới cờ. Năm bạn chia nhau mỗi người viết một phần, viết xong thì gửi vào nhóm chat của lớp. Nghe thì rất gọn gàng.\n\nĐến tối Chủ nhật, nhóm chat đã có tới bảy tệp na ná nhau: bản tin mới, bản tin mới sửa, bản tin mới sửa lần cuối, bản tin nộp cô... Bạn nhóm trưởng ngồi ghép tay từng đoạn, ghép nhầm mất phần của một bạn, mà lúc phát hiện ra thì tệp gốc của bạn ấy đã trôi đâu đó giữa hàng trăm tin nhắn. Sáng hôm sau vào thư viện trường định sửa nốt, bạn nhóm trưởng mới nhớ ra bản mới nhất đang nằm trong chiếc USB để quên ở nhà.\n\nCô giáo chủ nhiệm nghe chuyện chỉ cười, rồi bày cho cả nhóm một cách khác hẳn. Thay vì mỗi người giữ một bản riêng rồi gửi qua gửi lại, cả nhóm chỉ giữ đúng một bản duy nhất, đặt trên mạng. Ai cũng mở được bản đó, từ máy tính phòng tin học, từ máy ở nhà hay từ điện thoại trên xe buýt. Bạn này gõ thêm một dòng thì bạn kia nhìn thấy ngay dòng đó xuất hiện trên màn hình của mình.\n\nCô còn dặn thêm hai điều: phải biết ai được phép sửa, ai chỉ được đọc; và nếu lỡ có ai xoá nhầm nguyên một phần thì vẫn có cách lấy lại. Bài học hôm nay sẽ nói đúng về những điều cô đã dặn."},{"t":"h","text":"1) Kho tài liệu trên đám mây và những thao tác phải thạo"},{"t":"text","text":"Một **dịch vụ lưu trữ trực tuyến** cho bạn một khoảng trống trên máy chủ ở xa để cất tệp, và bạn thao tác với khoảng trống đó qua trình duyệt hoặc qua ứng dụng cài trên máy. Cảm giác sử dụng gần giống hệt việc mở một thư mục quen thuộc trên ổ đĩa: vẫn có thư mục, thư mục con, tệp, vẫn kéo thả và đổi tên được. Khác biệt nằm ở chỗ dữ liệu không nằm trong máy của bạn, nên bạn mở được nó từ bất kì thiết bị nào đã đăng nhập đúng tài khoản.\n\nHai thao tác đầu tiên phải thạo là **tải lên** (`upload`) và **tải về** (`download`). Tải lên là đưa một tệp từ máy của mình vào kho; sau khi tải lên xong, tệp tồn tại ở cả hai nơi. Tải về là chép một bản từ kho về máy để dùng khi không có mạng, hoặc để nộp bài qua một kênh khác. Cần nhớ rằng bản tải về là một **bản sao độc lập**: bạn sửa bản đó trên máy thì bản trên đám mây không hề thay đổi theo.\n\nPhần còn lại là chuyện tổ chức cho gọn. Nếu ném hết mọi thứ vào một chỗ, chỉ sau vài tháng bạn sẽ có một đống tệp không thể tìm nổi. Hãy **tạo thư mục** theo môn học hoặc theo dự án, **di chuyển** tệp về đúng thư mục của nó, đặt tên có quy tắc rồi **sắp xếp** danh sách theo tên hoặc theo ngày sửa gần nhất để tệp đang dùng luôn nổi lên trên cùng. Và khi lỡ tay xoá nhầm, đừng hoảng: tệp bị xoá thường chỉ được chuyển vào **thùng rác** và nằm đó một thời gian, đủ để bạn vào khôi phục lại vị trí cũ."},{"t":"list","text":"Sáu thao tác cơ bản cần thành thạo trên một kho lưu trữ trực tuyến:","items":["Tải tệp lên (`upload`): đưa tệp từ máy tính hoặc điện thoại vào kho trên đám mây.","Tải tệp về (`download`): lấy một bản sao về máy để dùng khi không có mạng — sửa bản sao này không làm đổi bản gốc trên đám mây.","Tạo thư mục mới và đặt tên gợi nhớ theo môn học, theo dự án hoặc theo học kì.","Di chuyển tệp giữa các thư mục bằng cách kéo thả hoặc dùng lệnh chuyển tới thư mục khác.","Sắp xếp danh sách theo tên, theo dung lượng hoặc theo thời điểm sửa gần nhất để tìm cho nhanh.","Khôi phục tệp đã xoá nhầm từ thùng rác — nhưng chỉ trong thời hạn dịch vụ còn giữ, xoá vĩnh viễn rồi thì không lấy lại được."]},{"t":"h","text":"2) Đồng bộ — sửa ở một nơi, đổi ở mọi nơi"},{"t":"text","text":"**Đồng bộ** (`sync`) là cơ chế giữ cho bản trên đám mây và bản nằm trong thư mục đặc biệt trên máy của bạn luôn giống hệt nhau. Khi cài ứng dụng của dịch vụ lưu trữ, bạn sẽ có một thư mục được đánh dấu riêng; mọi thay đổi bên trong thư mục đó — thêm tệp, sửa nội dung, đổi tên, xoá — đều được ứng dụng phát hiện và đẩy lên máy chủ. Ngược lại, khi bản trên máy chủ đổi, ứng dụng kéo thay đổi đó về máy. Đồng bộ vì thế là quá trình **hai chiều**, không phải chỉ một chiều từ máy lên mạng.\n\nHệ quả rất tiện: bạn ngồi ở phòng tin học sửa bảng phân công của câu lạc bộ, tối về mở điện thoại ra là đã thấy bảng phân công mới, không phải gửi tệp cho chính mình qua tin nhắn nữa. Điều kiện là các thiết bị đều đăng nhập cùng một tài khoản. Để bạn biết mọi thứ đã xong hay chưa, mỗi tệp thường mang một dấu hiệu trạng thái: **đã đồng bộ** nghĩa là bản trên máy và bản trên máy chủ đã trùng khớp, có thể yên tâm tắt máy; **đang chờ đồng bộ** nghĩa là thay đổi mới còn nằm trong hàng đợi, chưa kịp đẩy lên.\n\nVậy mất mạng thì sao? Bạn vẫn mở và sửa tệp trong thư mục đồng bộ bình thường, vì bản đó nằm ngay trên ổ đĩa. Thay đổi được ghi lại và xếp vào hàng đợi, đến khi có mạng trở lại ứng dụng sẽ tự đẩy lên, bạn không cần làm gì thêm. Điều cần cẩn thận là trong khoảng thời gian mất mạng ấy, người khác mở bản trên đám mây sẽ chỉ thấy nội dung cũ; và nếu hai người cùng sửa một tệp trong lúc đứt liên lạc, dịch vụ sẽ báo **xung đột phiên bản** và giữ lại cả hai bản để con người tự quyết định chọn bản nào."},{"t":"h","text":"3) Chia sẻ bằng liên kết: ba mức quyền và hai phạm vi người nhận"},{"t":"text","text":"Muốn người khác dùng chung tệp của mình, bạn không cần gửi tệp đi đâu cả. Bạn chỉ cần **chia sẻ liên kết** — một địa chỉ trỏ thẳng tới tệp đang nằm trên đám mây. Người nhận bấm vào liên kết là mở đúng bản gốc ấy, nên không bao giờ có chuyện mỗi người cầm một bản khác nhau như trong câu chuyện đầu bài.\n\nĐiều quan trọng nhất khi chia sẻ không phải là gửi cho ai, mà là gửi kèm **mức quyền** nào. Ba mức thường gặp, xếp từ chặt đến lỏng, là: **chỉ được xem** (`viewer`) — mở đọc và tải về, không đụng được vào nội dung; **được nhận xét** (`commenter`) — ngoài đọc còn ghi được ý kiến vào lề tài liệu, nhưng nội dung gốc vẫn nguyên vẹn; và **được chỉnh sửa** (`editor`) — sửa, thêm, xoá trực tiếp như chính chủ. Nguyên tắc chọn rất đơn giản: cấp mức **thấp nhất mà người đó vẫn làm được việc**. Cô giáo cần góp ý bản nháp thì cấp quyền nhận xét là đủ; các bạn cùng viết bài mới cần quyền chỉnh sửa; cả lớp chỉ cần đọc thì để mức chỉ xem.\n\nBên cạnh mức quyền còn một lựa chọn nữa dễ bị bỏ qua: **phạm vi người nhận**. Chia sẻ cho **danh sách người cụ thể** nghĩa là bạn nhập đúng địa chỉ email của từng người; chỉ những tài khoản đó đăng nhập mới mở được, và bạn có thể đặt mức quyền khác nhau cho từng người. Chia sẻ **công khai cho bất kì ai có liên kết** thì ngược lại: hệ thống không kiểm tra người mở là ai nữa, ai cầm được đường liên kết cũng vào được. Liên kết mà lọt vào một hội nhóm đông người hoặc bị chụp màn hình đăng lại, dữ liệu coi như công khai với người lạ — đặc biệt nguy hiểm nếu tệp chứa số điện thoại, địa chỉ, ảnh cá nhân của cả lớp. Vì vậy, chỉ dùng chế độ công khai cho nội dung thật sự không nhạy cảm, và khi việc đã xong thì vào lại phần thiết lập để **thu hồi quyền**: xoá tên người trong danh sách, hoặc chuyển liên kết về chế độ hạn chế để mọi đường liên kết đã phát tán trước đó lập tức hết hiệu lực."},{"t":"example","text":"Nhóm của bạn Minh đang làm báo cáo hoạt động câu lạc bộ sách. Minh cần ba người cùng tham gia ở ba vai trò khác nhau: bạn An viết nội dung, bạn Bích đọc soát và góp ý câu chữ, còn cô Hạnh chỉ đọc bản cuối để duyệt chứ không ghi gì vào tệp. Ngoài ra, bản báo cáo sau khi xong sẽ được cho cả lớp xem qua liên kết.\n\nBảng thiết lập chia sẻ dưới đây minh hoạ cách Minh cấu hình: ba người được mời đích danh bằng địa chỉ email với ba mức quyền khác nhau, còn liên kết công khai chỉ để ở mức thấp nhất. Hãy để ý dòng cuối — đó chính là công tắc thu hồi: chuyển từ 'Bất kì ai có liên kết' về 'Hạn chế' là toàn bộ liên kết đã phát tán trước đó ngừng hoạt động ngay.","code":"TỆP: BaoCao_CLB_Sach_2026.docx        Chủ sở hữu: Minh\n────────────────────────────────────────────────────\nCHIA SẺ VỚI NGƯỜI CỤ THỂ (theo địa chỉ email)\n  an.nguyen@lop11a3.edu.vn      →  Được chỉnh sửa\n  bich.tran@lop11a3.edu.vn      →  Được nhận xét\n  co.hanh@truong.edu.vn         →  Chỉ được xem\n────────────────────────────────────────────────────\nCHIA SẺ BẰNG LIÊN KẾT\n  Phạm vi : Bất kì ai có liên kết\n  Mức quyền: Chỉ được xem\n────────────────────────────────────────────────────\n[ Đổi phạm vi liên kết sang \"Hạn chế\" = thu hồi ]\n[ Nhấn dấu x cạnh một email    = gỡ quyền người đó ]","output":"Ba người được mời có ba mức quyền khác nhau trên cùng một tệp, còn người ngoài chỉ mở được ở mức chỉ xem và có thể bị chặn ngay khi đổi phạm vi liên kết về Hạn chế."},{"t":"h","text":"4) Cộng tác nhiều người trên cùng một tài liệu"},{"t":"text","text":"Khi tài liệu đã nằm trên đám mây và mọi người đã có quyền chỉnh sửa, cả nhóm có thể **cùng làm việc đồng thời** trên đúng một bản. Không ai phải chờ ai đóng tệp. Mỗi người đang mở sẽ hiện ra một dấu hiệu riêng — thường là một con trỏ màu khác nhau kèm tên — nên bạn nhìn là biết ngay ai đang đứng ở đoạn nào, tránh được cảnh hai người viết đè lên cùng một câu. Chữ vừa gõ xuất hiện gần như tức thời trên màn hình của những người còn lại, và hệ thống tự lưu liên tục, không cần bấm lưu thủ công.\n\nKhi cần trao đổi về nội dung, đừng sửa thẳng vào bài viết của bạn mình mà hãy dùng **nhận xét** (`comment`). Bôi đen đoạn cần bàn, chèn một nhận xét, người viết đoạn đó sẽ nhận được thông báo và trả lời ngay bên dưới; góp ý nào đã xử lí xong thì đánh dấu giải quyết cho khuất đi. Cách này giữ được toàn bộ cuộc thảo luận nằm ngay cạnh chỗ cần sửa, tốt hơn hẳn việc nhắn tin mô tả 'đoạn gần cuối trang hai' rồi cả nhóm cùng đoán.\n\nCuối cùng là tấm lưới an toàn quan trọng nhất: **lịch sử phiên bản**. Dịch vụ tự động ghi lại các mốc thay đổi của tài liệu — ai sửa, sửa lúc nào, sửa những gì. Nếu sáng ra cả nhóm phát hiện phần kết luận biến mất mà không ai nhận là mình xoá, bạn chỉ cần mở lịch sử phiên bản, xem lại bản ở thời điểm trước khi mất, rồi khôi phục đúng bản đó. Nhờ vậy, sự cố 'có người sửa hỏng bài' trong làm việc nhóm trực tuyến hầu như luôn cứu được, miễn là bạn biết chỗ để tìm."},{"t":"note","text":"Ba lỗi hay gặp nhất khi làm việc nhóm trên tài liệu dùng chung. Một là **để chế độ công khai kèm quyền chỉnh sửa** cho tệp có dữ liệu cá nhân — chỉ cần liên kết lọt ra ngoài là người lạ vừa đọc được vừa xoá được, nên hãy giữ thói quen kiểm tra lại phạm vi và mức quyền trước khi bấm sao chép liên kết. Hai là **nhầm bản tải về với bản trên đám mây**: sửa hăng say trên bản `download` trong thư mục Tải xuống rồi thắc mắc vì sao cả nhóm không thấy gì. Ba là **tắt máy khi tệp còn đang chờ đồng bộ**, khiến công sức vừa làm chưa kịp lên máy chủ; hãy đợi biểu tượng chuyển sang trạng thái đã đồng bộ rồi mới yên tâm đóng máy."}],"keypoints":["Trên kho lưu trữ trực tuyến cần thạo sáu thao tác: **tải lên**, **tải về**, tạo và sắp xếp thư mục, di chuyển tệp và **khôi phục từ thùng rác** khi xoá nhầm.","**Đồng bộ** là quá trình hai chiều giữa thiết bị và đám mây; mất mạng vẫn sửa được, thay đổi nằm ở trạng thái **đang chờ đồng bộ** và sẽ tự đẩy lên khi có mạng trở lại.","Khi chia sẻ phải chọn đúng **mức quyền** — **chỉ được xem**, **được nhận xét** hay **được chỉnh sửa** — theo nguyên tắc cấp mức thấp nhất mà người đó vẫn làm được việc.","Chia sẻ **theo danh sách email** an toàn hơn hẳn chia sẻ **công khai cho bất kì ai có liên kết**; khi cộng tác, dùng **nhận xét** để trao đổi và **lịch sử phiên bản** để khôi phục bản cũ."],"quiz":["CB-mc-2401","CB-mc-2402","CB-mc-2403","CB-mc-2404","CB-mc-2405","CB-tf-2401"]},
    {"id":"C11-25","stage":21,"order":25,"topic":"D","grade":11,"minutes":12,"title":"Nhận diện chiêu lừa trực tuyến và giữ an toàn cho danh tính số","intro":"Kẻ lừa đảo trên mạng hiếm khi phá khoá thiết bị của bạn — chúng thuyết phục bạn tự mở cửa cho chúng. Bài học này chỉ ra các kịch bản lừa hay gặp, cách **soi một liên kết** trước khi bấm, cách khoá chặt tài khoản bằng **mật khẩu riêng** cùng **xác thực hai bước**, và quy trình phải làm ngay khi đã lỡ sập bẫy.","sections":[{"t":"story","text":"Tối thứ Bảy, Trâm đang ngồi làm nốt bài tập thì điện thoại rung. Tin nhắn đến từ tài khoản của Hân — cô bạn ngồi cùng bàn suốt hai năm nay. Hân viết rằng mẹ đang nằm viện, ví thì để quên ở nhà, nhờ Trâm chuyển tạm hai trăm nghìn, mai đi học sẽ trả ngay. Giọng văn hơi lạ, không có mấy biểu tượng mặt cười mà Hân vẫn hay dùng, nhưng đang lúc gấp thì ai để ý mấy chuyện nhỏ như vậy.\n\nTrâm định bấm chuyển thì chợt nhớ ra một chi tiết: Hân đang đi trại hè trên núi, tối nay gần như chắc chắn không có sóng. Trâm gọi thử một cuộc, không ai bắt máy. Cô nhắn lại một câu mà chỉ hai đứa mới biết: hôm thi giữa kì mày mượn tao cây bút màu gì. Đầu bên kia im lặng một lúc lâu, rồi trả lời vòng vo, rồi quay sang giục chuyển tiền gấp. Đến lúc đó thì Trâm hiểu ra: người đang nhắn không phải Hân.\n\nSáng hôm sau, Hân kể lại đầu đuôi. Hai hôm trước, Hân nhận được một tin nhắn báo tài khoản sắp bị khoá, kèm một đường dẫn để xác nhận. Hân bấm vào, thấy hiện lên một trang trông y hệt trang đăng nhập quen thuộc, liền gõ tên và mật khẩu. Vài giây sau, một mã số được gửi về máy, Hân cũng gõ nốt vào ô trên trang đó cho xong. Thế là đủ: người lạ vào được tài khoản, đổi mật khẩu, rồi lần lượt nhắn tin xin tiền tất cả bạn bè trong danh sách.\n\nChuyện của Hân không hiếm chút nào. Điều đáng nói là ở mỗi khúc quanh — lúc nhận tin nhắn lạ, lúc bấm vào đường dẫn, lúc gõ mã số — đều có một chỗ để dừng lại và kiểm tra chỉ mất mươi giây. Bài học này chỉ cho bạn đúng những chỗ dừng ấy."},{"t":"h","text":"1) Điểm mặt những chiêu lừa quen thuộc"},{"t":"text","text":"Điều đầu tiên cần hiểu là **lừa đảo trực tuyến** thường không phải một cuộc tấn công kĩ thuật cao vào máy móc. Kẻ gian không cần bẻ khoá điện thoại của bạn nếu chúng khiến bạn tự tay gõ mật khẩu vào trang của chúng. Mọi kịch bản, dù khoác vỏ bọc nào, cũng chỉ xoay quanh ba chất liệu tâm lí: **lòng tin** (mượn danh một tổ chức hoặc một người bạn quen), **nỗi sợ** (tài khoản sắp bị khoá, hồ sơ sắp bị huỷ) và **lòng tham** (trúng thưởng, việc nhẹ lương cao).\n\nNhóm kịch bản mượn danh tổ chức là phổ biến nhất: một tin nhắn xưng là ngân hàng báo tài khoản có giao dịch bất thường, một tin xưng là nhà trường báo hồ sơ học bổng còn thiếu giấy tờ, kèm theo một liên kết để bạn bấm vào bổ sung ngay. Nhóm thứ hai đánh vào lòng tham: thông báo bạn trúng một chiếc điện thoại trong chương trình tri ân, hoặc tin tuyển cộng tác viên bán hàng trực tuyến chỉ ngồi nhà bấm điện thoại mà lương cao, nhưng phải ứng tiền cho đơn hàng đầu tiên. Nhóm thứ ba chính là chuyện của Hân: tài khoản của một người quen bị chiếm rồi dùng để nhắn mượn tiền cả danh bạ, vì lời nhờ vả từ người thân quen bao giờ cũng dễ tin hơn từ người lạ.\n\nMột biến thể ngày càng hay gặp là **mã QR** và **liên kết rút gọn**. Cả hai đều có chung một đặc điểm nguy hiểm: nhìn vào chúng, mắt người không đọc được đích đến thật sự. Một mã QR dán đè lên mã cũ ở quán nước, một liên kết rút gọn thả vào nhóm chat của lớp kèm dòng chữ tài liệu ôn thi đây — bạn chỉ biết mình đang đi đâu sau khi trang đã mở ra. Điểm chung của tất cả các chiêu trên là **sự hối thúc**: trong 24 giờ, chỉ còn 3 suất cuối, làm ngay kẻo mất. Hối thúc chính là để bạn không kịp dừng lại kiểm tra, nên hễ thấy ai đó giục gấp là đúng lúc phải chậm lại."},{"t":"h","text":"2) Soi kĩ một liên kết trước khi bấm"},{"t":"text","text":"Một địa chỉ web bao giờ cũng có dạng giao thức, rồi đến **tên miền**, rồi mới đến phần đường dẫn phía sau. Quy tắc đọc quan trọng nhất là: hãy nhìn đúng đoạn nằm giữa dấu `//` và dấu gạch chéo đầu tiên, vì đó mới là nơi cho biết trang thuộc về ai; mọi thứ viết sau dấu gạch chéo đầu tiên đều do chủ trang tự đặt và không nói lên điều gì. Trong đoạn đó, chủ sở hữu thật nằm ở **cuối chuỗi**, ngay trước phần đuôi như `.vn`, `.com`, `.xyz` hay `.edu.vn`. Tất cả các nhãn đứng trước nó chỉ là tên miền phụ, và kẻ lừa đảo được quyền đặt chúng thành bất cứ chữ gì chúng muốn.\n\nHiểu quy tắc đó rồi thì hai chiêu giả mạo hay gặp nhất sẽ lộ ngay. Chiêu thứ nhất là nhét tên thật vào phần đầu, ví dụ một địa chỉ bắt đầu bằng tên trường bạn nhưng lại kết thúc bằng một tên miền lạ hoắc — trang ấy thuộc về cái tên lạ hoắc kia chứ không phải của trường. Chiêu thứ hai là **viết sai lệch một chữ** so với địa chỉ thật: đổi một chữ cái sang chữ nhìn na ná, thêm một dấu gạch nối vào giữa, hay đổi phần đuôi `.vn` thành một đuôi khác. Đọc lướt thì y hệt, đọc kĩ từng kí tự mới thấy khác.\n\nCòn hai thói quen nữa nên rèn. Trên máy tính, hãy **di chuột** lên liên kết mà chưa bấm: địa chỉ thật sẽ hiện ở góc dưới màn hình, và rất nhiều lần nó khác hẳn dòng chữ đang hiển thị; trên điện thoại thì nhấn giữ liên kết để xem trước. Nhưng cách chắc chắn nhất, đơn giản nhất và luôn dùng được là: **đừng bấm liên kết trong tin nhắn**, hãy tự gõ địa chỉ chính thức vào trình duyệt, hoặc mở thẳng ứng dụng chính thức của ngân hàng, của trường. Bạn mất thêm mười giây, nhưng bạn chắc chắn mình đang đứng đúng cửa."},{"t":"example","text":"Hãy thử áp dụng quy tắc đọc tên miền cho ba địa chỉ dưới đây. Giả sử trang chính thức của trường là `thpthonngoc.edu.vn` và của ngân hàng là `nganhangabc.com.vn`. Với mỗi địa chỉ, ta chỉ lấy đoạn nằm trước dấu gạch chéo đầu tiên, rồi đọc phần cuối của đoạn đó.","code":"(1) https://thpthonngoc.hocbong2026.xyz/nop-ho-so\n    đoạn trước dấu / đầu tiên : thpthonngoc.hocbong2026.xyz\n    chủ sở hữu thật (phần cuối): hocbong2026.xyz\n    => tên trường chỉ là tên miền phụ -> GIẢ MẠO\n\n(2) https://nganhangabc.com.vn.xac-thuc-otp.top/login\n    đoạn trước dấu / đầu tiên : nganhangabc.com.vn.xac-thuc-otp.top\n    chủ sở hữu thật (phần cuối): xac-thuc-otp.top\n    => cả cụm com.vn cũng chỉ là tên miền phụ -> GIẢ MẠO\n\n(3) https://thpthonngoc.edu.vn/tin-tuc/hoc-bong\n    đoạn trước dấu / đầu tiên : thpthonngoc.edu.vn\n    chủ sở hữu thật (phần cuối): thpthonngoc.edu.vn\n    => đúng tên miền chính thức -> HỢP LỆ","output":"Chỉ địa chỉ (3) thật sự thuộc về trường; hai địa chỉ đầu chỉ mượn tên trường và tên ngân hàng đặt ở phần đầu cho giống."},{"t":"note","text":"Bẫy rất hay gặp: nhiều bạn tin rằng cứ thấy `https` và biểu tượng **ổ khoá** ở đầu địa chỉ thì trang đó an toàn. Không phải vậy. Ổ khoá chỉ bảo đảm **đường truyền được mã hoá**, tức là người ngoài không đọc lén được nội dung bạn gửi đi — nó hoàn toàn không bảo đảm **người nhận** ở đầu bên kia là tổ chức thật. Kẻ lừa đảo cũng xin được chứng chỉ cho trang của chúng một cách dễ dàng và miễn phí, nên một trang giả mạo vẫn có đủ ổ khoá xanh như thường. Ngược lại, một trang xin thông tin đăng nhập mà **không** có `https` thì chắc chắn phải tránh xa."},{"t":"h","text":"3) Ba lớp khoá cho tài khoản và nguyên tắc vàng về mã OTP"},{"t":"text","text":"Lớp khoá thứ nhất là **mật khẩu mạnh**. Mạnh ở đây trước hết là dài — nên từ 12 kí tự trở lên — và có trộn chữ hoa, chữ thường, chữ số cùng kí hiệu. Quan trọng không kém, mật khẩu không được lấy từ những thông tin mà người khác tra ra trong năm phút: ngày sinh, tên mình, tên người thân, số điện thoại, tên đội bóng yêu thích. Một mẹo vừa mạnh vừa dễ nhớ là ghép bốn từ chẳng liên quan gì đến nhau rồi chèn thêm vài kí tự riêng, ví dụ kiểu ghép từ về cái bàn, con mèo, cơn mưa và chiếc xe đạp — dài, khó dò mà vẫn thuộc được.\n\nLớp khoá thứ hai, và là điều nhiều người bỏ qua nhất, là mỗi dịch vụ phải dùng một **mật khẩu khác nhau**. Lí do rất thực tế: các trang web bị lộ dữ liệu người dùng là chuyện xảy ra thường xuyên, và việc đầu tiên kẻ tấn công làm sau khi có được một danh sách tên đăng nhập kèm mật khẩu là đem đúng từng cặp đó thử tự động vào hàng loạt dịch vụ khác. Nếu bạn dùng chung một mật khẩu cho hộp thư, mạng xã hội và tài khoản học trực tuyến, thì một chỗ bị lộ đồng nghĩa với mất cả ba. Nhớ không xuể thì hãy dùng **trình quản lí mật khẩu**, chỉ cần thuộc duy nhất một mật khẩu chính.\n\nLớp khoá thứ ba là **xác thực hai bước** — sau khi gõ đúng mật khẩu, hệ thống còn đòi thêm một mã dùng một lần sinh ra từ ứng dụng sinh mã hoặc gửi về điện thoại. Nhờ lớp này, kẻ gian dù có mật khẩu của bạn vẫn đứng ngoài cửa. Và đây là **nguyên tắc vàng** không có ngoại lệ: **mã OTP** (`One-Time Password`) là mã dùng một lần chỉ dành riêng cho bạn, tuyệt đối không đọc qua điện thoại, không chụp màn hình gửi đi, không gõ vào bất kì trang nào ngoài trang chính thức mà bạn tự mở. Không một nhân viên ngân hàng, công an, thầy cô hay người thân nào có lí do chính đáng để hỏi mã ấy — nên hễ ai hỏi mã OTP thì chính người đó đang lừa bạn. Hân mất tài khoản đúng ở bước này."},{"t":"h","text":"4) Ranh giới với người lạ và cách gỡ khi đã lỡ"},{"t":"text","text":"Với người quen qua mạng mà chưa từng gặp ngoài đời, hãy tự đặt cho mình một ranh giới cố định về thông tin. Không cung cấp địa chỉ nhà, tên trường và lớp, lịch học thêm, giờ tan học hay giờ bố mẹ đi vắng; cũng đừng đăng những tấm ảnh vô tình để lộ phù hiệu áo đồng phục, biển số xe hay cổng nhà. Từng mẩu tưởng như vô hại, nhưng ghép năm bảy mẩu lại thì một người lạ hoàn toàn có thể biết bạn ở đâu, vào lúc mấy giờ, và khi nào chỉ có một mình.\n\nHãy đặc biệt cảnh giác với kiểu người **thân thiết quá nhanh**: mới quen vài hôm đã khen ngợi hết lời, tặng quà, nhận là chỉ mình họ mới hiểu bạn, rồi than phiền rằng bạn không tin tưởng họ khi bạn từ chối điều gì đó. Đó là một quy trình dụ dỗ có bài bản, và bước tiếp theo thường là xin ảnh riêng tư hoặc rủ gặp riêng. Nguyên tắc cần thuộc: **không gửi ảnh riêng tư** cho bất kì ai trên mạng, vì ảnh đã gửi đi là không lấy lại được và rất dễ trở thành công cụ đe doạ; **không hẹn gặp một mình**, nếu thật sự cần gặp thì phải là ban ngày, nơi đông người, và luôn có người lớn biết bạn đang ở đâu.\n\nDù cẩn thận đến mấy, vẫn có lúc ta lỡ tay bấm nhầm hoặc gõ mật khẩu vào trang giả. Lúc ấy điều tệ nhất là im lặng và giấu đi vì sợ bị mắng, bởi vài chục phút đầu tiên quyết định thiệt hại lớn hay nhỏ. Hãy làm lần lượt theo đúng thứ tự dưới đây."},{"t":"list","text":"Quy trình xử lí khi đã lỡ bấm liên kết lạ hoặc tài khoản bị chiếm:","items":["Ngắt kết nối mạng của thiết bị vừa bấm nhầm — tắt Wi-Fi và dữ liệu di động — để chặn việc dữ liệu tiếp tục bị gửi ra ngoài.","Dùng một thiết bị khác đã an toàn để đổi mật khẩu, và đổi cho hộp thư điện tử trước tiên, vì hộp thư là chìa khoá khôi phục của mọi tài khoản còn lại.","Vào mục quản lí phiên đăng nhập của dịch vụ, đăng xuất khỏi tất cả thiết bị đang mở, rồi bật ngay xác thực hai bước nếu trước đó chưa bật.","Chụp lại màn hình tin nhắn, đường dẫn lạ và số tài khoản nhận tiền để làm bằng chứng, trước khi phía bên kia kịp xoá đi.","Báo ngay cho cha mẹ hoặc thầy cô, đồng thời báo cho nhà cung cấp dịch vụ qua chức năng báo cáo tài khoản bị chiếm; nếu có liên quan đến tiền thì báo ngân hàng và cơ quan công an càng sớm càng tốt.","Nhắn cho bạn bè trong danh bạ biết tài khoản của mình vừa bị chiếm, để không ai tin theo những tin nhắn mượn tiền gửi đi từ tài khoản đó."]}],"keypoints":["Hầu hết **lừa đảo trực tuyến** không tấn công máy móc mà đánh vào tâm lí: mượn danh tổ chức hoặc người quen, hứa hẹn lợi ích lớn, và luôn **hối thúc** để nạn nhân không kịp kiểm tra.","Trước khi bấm phải đọc **tên miền** ở cuối đoạn đứng trước dấu gạch chéo đầu tiên; `https` cùng biểu tượng ổ khoá **không** chứng minh trang là thật, nên an toàn nhất là **tự gõ địa chỉ chính thức**.","Mỗi dịch vụ dùng một **mật khẩu mạnh và khác nhau**, luôn bật **xác thực hai bước**, và tuyệt đối không đọc hay gửi **mã OTP** cho bất kì ai, kể cả người tự xưng là nhân viên ngân hàng hay công an.","Khi đã lỡ: **ngắt mạng**, đổi mật khẩu từ thiết bị khác, **đăng xuất mọi phiên**, lưu bằng chứng, báo người lớn cùng nhà cung cấp dịch vụ và cảnh báo bạn bè trong danh bạ."],"quiz":["CB-mc-2501","CB-mc-2502","CB-mc-2503","CB-mc-2504","CB-mc-2505","CB-tf-2501"]},
    {"id":"C11-26","stage":21,"order":26,"topic":"C","grade":11,"minutes":12,"title":"Tách một quyển sổ ghi tay thành các bảng dữ liệu liên kết","intro":"Biết thế nào là bảng, bản ghi, trường và khoá mới chỉ là một nửa câu chuyện. Nửa còn lại — cũng là phần hay bị hỏi trong đề thi — là **tự thiết kế** được bộ bảng cho một bài toán quản lí có thật. Bài này đi trọn một ví dụ: từ quyển sổ mượn – trả sách của thư viện trường đến ba bảng dữ liệu nối với nhau bằng khoá.","sections":[{"t":"story","text":"Đầu năm học, thư viện trường của Minh tuyển cộng tác viên, và Minh xung phong nhận việc ghi sổ. Cô phụ trách thư viện đưa cho Minh một quyển sổ kẻ ô to đùng, dặn rằng cứ mỗi lần có bạn nào tới mượn sách thì ghi một dòng: ngày hôm đó, họ tên bạn mượn, lớp của bạn ấy, tên cuốn sách, tên tác giả và ngày hẹn phải trả. Nghe qua thì đơn giản, và trong hai tuần đầu mọi thứ trôi chảy.\n\nRắc rối bắt đầu từ tháng thứ hai. Bạn Lan lớp 11A2 chuyển sang lớp 11A5. Minh phải lật lại toàn bộ quyển sổ, tìm cho ra mười mấy dòng có tên Lan để sửa lớp. Sửa được mười ba dòng thì Minh mỏi mắt, bỏ sót mất một dòng ở trang trước. Từ hôm đó, cùng một quyển sổ, cùng một người, mà trang này ghi Lan học 11A5, trang kia lại ghi 11A2 — chẳng ai biết chỗ nào mới đúng.\n\nChưa hết. Có hôm Minh ghi ‘Nguyễn Thị Lan’, hôm khác vội quá ghi ‘Ng. T. Lan’, hôm sau nữa lại có một bạn Lan khác ở lớp 10 tới mượn. Đến cuối học kì, khi cô hỏi lớp nào mượn nhiều sách nhất, ai đang giữ sách quá hạn và cuốn nào được các bạn ưa chuộng nhất, Minh chỉ biết ngồi lật từng trang đếm tay suốt một buổi chiều mà vẫn không dám chắc con số của mình là đúng.\n\nĐiều đáng nói là Minh không hề lười, cũng không ghi thiếu chữ nào. Thứ sai ở đây không phải người ghi, mà là cách quyển sổ được kẻ ra ngay từ đầu."},{"t":"h","text":"1) Bài toán quản lí và những thông tin cần lưu"},{"t":"text","text":"Trước khi kẻ bất kì cái bảng nào, người thiết kế phải trả lời cho xong một câu hỏi: hệ thống này sinh ra để phục vụ những công việc nào? Với thư viện trường, các công việc đó khá rõ. Thủ thư cần biết một cuốn sách hiện còn trên giá hay đã có người mượn, cần biết bạn nào đang giữ sách quá hạn để nhắc, cần biết cuốn nào được mượn nhiều nhất để đề xuất mua thêm bản, và cuối kì cần thống kê mỗi lớp đã mượn bao nhiêu lượt để chấm điểm thi đua.\n\nMỗi câu hỏi quản lí như vậy chính là một ‘bài kiểm tra’ cho thiết kế. Nếu dữ liệu ta lưu không đủ để trả lời một câu trong số đó, thiết kế coi như thiếu; ngược lại, nếu ta lưu những thứ chẳng câu hỏi nào cần tới, thiết kế bị thừa. Chẳng hạn, muốn biết ai quá hạn thì bắt buộc phải lưu ngày mượn và hạn phải trả — chỉ lưu mỗi ngày mượn thôi là không đủ, vì thư viện có thể cho mượn 7 ngày với truyện và 14 ngày với sách tham khảo.\n\nLàm rõ danh sách công việc trước, rồi mới liệt kê thông tin cần lưu sau — đó là thứ tự đúng. Cứ cắm đầu kẻ bảng trước rồi mới nghĩ xem dùng để làm gì thì gần như chắc chắn sẽ phải làm lại từ đầu."},{"t":"list","text":"Từ những câu hỏi trên, ta rút ra danh sách thông tin mà hệ thống buộc phải lưu:","items":["Về mỗi bạn được mượn sách: một mã số riêng để phân biệt, họ tên đầy đủ, lớp đang học, số điện thoại liên hệ khi cần nhắc trả sách.","Về mỗi đầu sách trong kho: một mã số riêng, nhan đề, tác giả, nhà xuất bản, năm xuất bản, số bản mà thư viện đang có.","Về mỗi lượt mượn: bạn nào mượn, mượn cuốn nào, mượn ngày nào, hạn phải trả là ngày nào.","Về kết quả của lượt mượn đó: ngày trả thực tế (còn để trống chừng nào sách chưa được mang trả), và ghi chú nếu sách bị rách hay mất.","Về người tiếp nhận: tên cộng tác viên hoặc thủ thư đã ghi nhận lượt mượn, để truy lại khi có sai sót."]},{"t":"h","text":"2) Cái bẫy mang tên ‘một bảng cho tất cả’"},{"t":"example","text":"Phản xạ đầu tiên của hầu hết người mới học — và cũng là điều Minh đã làm với quyển sổ — là nhét toàn bộ danh sách trên vào duy nhất một cái bảng thật rộng, mỗi lượt mượn một dòng. Hãy nhìn kĩ bảng dưới đây, chú ý ba dòng có tên bạn Lan.","code":"SO_MUON  — một bảng duy nhất cho mọi thứ\n\nSTT | HoTenDocGia    | Lop  | NhanDeSach          | TacGia        | NgayMuon   | HanTra\n----+----------------+------+---------------------+---------------+------------+-----------\n 1  | Nguyễn Thị Lan | 11A5 | Sổ tay Hình học 11  | Phạm Văn Đức  | 2025-09-08 | 2025-09-22\n 2  | Trần Quốc Bảo  | 11A1 | Vật lí quanh ta     | Lê Minh Châu  | 2025-09-09 | 2025-09-23\n 3  | Nguyễn Thị Lan | 11A5 | Vật lí quanh ta     | Lê Minh Châu  | 2025-09-15 | 2025-09-29\n 4  | Ng. T. Lan     | 11A2 | Chuyện kể ven sông  | Đỗ Thu Hà     | 2025-10-02 | 2025-10-09\n 5  | Trần Quốc Bảo  | 11A1 | Sổ tay Hình học 11  | Phạm Văn Đức  | 2025-10-03 | 2025-10-17","output":"Tên và lớp của Lan bị chép lại 3 lần, tên và tác giả cuốn ‘Vật lí quanh ta’ bị chép 2 lần; riêng dòng 4 đã sai lớp và sai cả cách viết tên."},{"t":"text","text":"Cái bảng đó hỏng ở ba chỗ, và cả ba đều bắt nguồn từ một nguyên nhân duy nhất: cùng một thông tin bị ghi ở nhiều nơi. Chỗ hỏng thứ nhất là **dư thừa dữ liệu**. Bạn nào mượn nhiều thì tên và lớp của bạn ấy bị chép lại đúng bằng số lượt mượn; cuốn sách nào được ưa chuộng thì nhan đề và tác giả cũng bị chép lại y như vậy. Với một thư viện trường vài nghìn lượt mượn mỗi năm, phần lớn dung lượng bảng chỉ để chứa những dòng chữ lặp đi lặp lại chẳng mang thêm tin tức gì.\n\nChỗ hỏng thứ hai nguy hiểm hơn nhiều: **dữ liệu mâu thuẫn** khi cập nhật. Lan chuyển lớp thì đúng ra chỉ có một sự kiện xảy ra, nhưng vì lớp của Lan nằm rải rác ở mười mấy ô nên ta phải sửa mười mấy lần. Chỉ cần sót một ô như dòng 4 ở trên, bảng lập tức tự nói ngược với chính nó: Lan vừa học 11A5 vừa học 11A2. Máy tính không có cách nào tự biết ô nào đúng, nên mọi thống kê theo lớp từ đó trở đi đều sai.\n\nChỗ hỏng thứ ba là bảng không có chỗ nào để cất thông tin về một đối tượng khi đối tượng đó chưa dính tới lượt mượn nào. Thư viện vừa nhập về một cuốn sách mới, chưa ai mượn — muốn ghi cuốn đó vào bảng thì phải tạo một dòng trống hoác không có người mượn, không có ngày mượn. Ngược lại, xoá đi lượt mượn cuối cùng của một cuốn sách hiếm cũng đồng nghĩa với việc thông tin về chính cuốn sách ấy biến mất khỏi hệ thống."},{"t":"h","text":"3) Tách thành ba bảng và nối chúng bằng khoá"},{"t":"text","text":"Cách chữa nằm gọn trong một nguyên tắc: **mỗi thông tin chỉ được lưu ở đúng một nơi**, và mọi chỗ khác cần dùng tới thì tham chiếu về nơi đó chứ không chép lại. Muốn làm được thế, ta nhìn vào bài toán và nhận ra ở đây có ba loại đối tượng khác hẳn nhau về bản chất: con người đi mượn, cuốn sách được mượn, và sự kiện mượn – trả nối hai thứ kia lại. Ba loại đối tượng thì ba bảng: ĐỘC GIẢ, SÁCH và LƯỢT MƯỢN.\n\nMỗi bảng cần một **khoá chính** — trường mà giá trị không bao giờ trùng nhau giữa các dòng, dùng để chỉ đích danh một dòng. Ở bảng ĐỘC GIẢ ta đặt trường mã độc giả dạng `DG007`; ở bảng SÁCH là mã sách dạng `S014`. Vì sao không lấy luôn họ tên làm khoá chính cho gọn? Vì họ tên không bảo đảm được tính duy nhất: cả trường có thể có ba bạn cùng tên Nguyễn Thị Lan. Họ tên còn dễ bị viết hoa viết thường khác nhau, viết tắt, gõ sót dấu — đúng như dòng 4 trong bảng trên. Một mã số do hệ thống cấp thì ngắn, cố định suốt đời, không bao giờ trùng và cũng không ai gõ nhầm thành mã của người khác.\n\nCòn bảng LƯỢT MƯỢN thì sao? Nó không chép tên bạn Lan và cũng không chép nhan đề sách, mà chỉ giữ hai trường mã: mã độc giả và mã sách. Hai trường này là **khoá ngoại** — chúng không phải khoá chính của bảng LƯỢT MƯỢN, mà là ‘sợi dây’ trỏ ngược về khoá chính của hai bảng kia. Nhờ vậy, lớp của Lan chỉ tồn tại ở đúng một ô duy nhất trong bảng ĐỘC GIẢ; Lan chuyển lớp thì sửa một ô là xong, và toàn bộ hàng chục lượt mượn của bạn ấy tự động được hiểu theo lớp mới mà không phải đụng tới dòng nào."},{"t":"example","text":"Dưới đây là ba bảng sau khi tách, kèm sơ đồ liên kết giữa chúng. Cho gọn, mỗi bảng chỉ vẽ các trường chính; những trường phụ đã nêu ở mục 1 như ghi chú tình trạng sách hay tên người tiếp nhận vẫn nằm trong bảng LƯỢT MƯỢN. Ký hiệu 1 ────< đọc là ‘một dòng ở bảng bên trái có thể ứng với nhiều dòng ở bảng bên phải’: một độc giả có nhiều lượt mượn, một cuốn sách cũng có nhiều lượt được mượn.","code":"DOC_GIA        (khoá chính: MaDG)\nMaDG  | HoTen          | Lop  | DienThoai\n------+----------------+------+-----------\nDG007 | Nguyễn Thị Lan | 11A5 | 09xx111222\nDG012 | Trần Quốc Bảo  | 11A1 | 09xx333444\n\nSACH           (khoá chính: MaSach)\nMaSach | NhanDe             | TacGia       | NamXB | SoBan\n-------+--------------------+--------------+-------+------\nS014   | Sổ tay Hình học 11 | Phạm Văn Đức | 2023  | 4\nS021   | Vật lí quanh ta    | Lê Minh Châu | 2024  | 2\n\nLUOT_MUON      (khoá chính: MaLuot;  khoá ngoại: MaDG, MaSach)\nMaLuot | MaDG  | MaSach | NgayMuon   | HanTra     | NgayTraThucTe\n-------+-------+--------+------------+------------+---------------\nL1001  | DG007 | S014   | 2025-09-08 | 2025-09-22 | 2025-09-20\nL1002  | DG012 | S021   | 2025-09-09 | 2025-09-23 | (trống)\nL1003  | DG007 | S021   | 2025-09-15 | 2025-09-29 | (trống)\n\nSơ đồ liên kết:\n  DOC_GIA.MaDG    1 ────<  LUOT_MUON.MaDG\n  SACH.MaSach     1 ────<  LUOT_MUON.MaSach","output":"Lớp của Lan chỉ nằm ở đúng một ô (DG007, bảng DOC_GIA); tên tác giả cuốn S021 cũng chỉ nằm ở một ô — muốn sửa chỉ phải sửa một chỗ."},{"t":"h","text":"4) Kiểu dữ liệu, trường bắt buộc và phép thử thiết kế"},{"t":"text","text":"Kẻ xong ba bảng vẫn chưa phải là xong. Với từng trường, ta còn phải chọn **kiểu dữ liệu** và **miền giá trị** hợp lí, bởi kiểu dữ liệu chính là hàng rào đầu tiên chặn dữ liệu rác lọt vào. Các trường mã như `MaDG`, `MaSach`, `MaLuot` là văn bản độ dài cố định vì chúng có cả chữ lẫn số và không bao giờ đem đi cộng trừ. `HoTen`, `Lop`, `NhanDe`, `TacGia` là văn bản. `NamXB` và `SoBan` là số nguyên, kèm miền giá trị: năm xuất bản phải nằm trong khoảng hợp lí và số bản không được âm. Riêng `NgayMuon`, `HanTra`, `NgayTraThucTe` bắt buộc phải để kiểu ngày tháng chứ không phải văn bản — có như vậy máy mới so sánh được ngày và trừ được hai ngày cho nhau để tính số ngày quá hạn. Một lưu ý nhỏ mà nhiều bạn quên: `DienThoai` nên để kiểu văn bản, vì nếu lưu kiểu số thì con số 0 ở đầu sẽ bị mất.\n\nTiếp theo là câu hỏi trường nào **bắt buộc không được để trống**. Mọi khoá chính đương nhiên không được trống, vì trống thì không còn phân biệt được các dòng. Hai khoá ngoại `MaDG` và `MaSach` cũng không được trống, vì một lượt mượn mà không biết ai mượn hoặc mượn cuốn gì thì hoàn toàn vô nghĩa; hơn nữa giá trị điền vào còn phải thực sự tồn tại ở bảng được trỏ tới, chứ không thể là một mã bịa ra. Ngược lại, `NgayTraThucTe` lại là trường được phép để trống, và chính cái trống đó mang thông tin: nó có nghĩa là cuốn sách vẫn đang nằm trong tay độc giả.\n\nCuối cùng, hãy tự chấm bài thiết kế của mình bằng cách thử trả lời từng câu hỏi quản lí đã nêu ở mục 1. Ai đang giữ sách quá hạn? Lọc bảng LƯỢT MƯỢN lấy các dòng có `NgayTraThucTe` còn trống và `HanTra` đã qua so với hôm nay, rồi theo `MaDG` sang bảng ĐỘC GIẢ lấy họ tên và số điện thoại — trả lời được. Cuốn nào được mượn nhiều nhất? Đếm số dòng của bảng LƯỢT MƯỢN theo từng `MaSach` rồi lấy mã có số đếm lớn nhất, sang bảng SÁCH tra nhan đề — trả lời được. Mỗi lớp mượn bao nhiêu lượt? Ghép LƯỢT MƯỢN với ĐỘC GIẢ qua `MaDG` để biết mỗi lượt thuộc lớp nào, rồi đếm theo lớp — cũng trả lời được, mà không cần thêm cột `Lop` nào vào bảng LƯỢT MƯỢN. Ba câu đều thông suốt, nghĩa là thiết kế đã đủ dùng. Nếu có câu nào bí, đó là dấu hiệu ta còn thiếu một trường hoặc thiếu hẳn một bảng."}],"keypoints":["Thiết kế cơ sở dữ liệu bắt đầu từ **các câu hỏi quản lí cần trả lời**, rồi mới liệt kê thông tin phải lưu — không kẻ bảng trước rồi mới nghĩ sau.","Dồn mọi thứ vào **một bảng duy nhất** gây **dư thừa dữ liệu** và khiến bảng **tự mâu thuẫn** khi cập nhật mà sót một dòng.","Nguyên tắc tách bảng: mỗi loại đối tượng một bảng, và **mỗi thông tin chỉ được lưu ở đúng một nơi**; các bảng nối nhau bằng **khoá chính** và **khoá ngoại** chứ không chép lại dữ liệu.","Nên dùng **mã số** làm khoá chính thay cho họ tên, chọn đúng **kiểu dữ liệu** cho từng trường (nhất là kiểu ngày tháng), và tự kiểm tra thiết kế bằng cách thử trả lời lại các câu hỏi khai thác."],"quiz":["CB-mc-2601","CB-mc-2602","CB-mc-2603","CB-mc-2604","CB-mc-2605","CB-tf-2601"]},
    {"id":"C11-27","stage":21,"order":27,"topic":"C","grade":11,"minutes":13,"title":"Tạo bảng, đặt ràng buộc và thống kê dữ liệu bằng SQL","intro":"Bài học chỉ cách dùng `CREATE TABLE` để dựng khung một bảng dữ liệu, cách gài sẵn các **ràng buộc** để hệ quản trị tự từ chối dữ liệu sai, và cách dùng các **hàm tổng hợp** cùng `GROUP BY`, `HAVING` để máy tính thống kê thay cho việc đếm tay.","sections":[{"t":"story","text":"Tháng mười, trường của Long tổ chức giải bóng đá học sinh. Ban tổ chức dán ở bảng tin một tờ giấy khổ lớn: đội nào muốn dự thì tự ghi vào bốn ô — tên đội, lớp, tên đội trưởng và một số điện thoại để ban tổ chức gọi khi có thay đổi lịch thi đấu.\n\nĐến hạn chốt danh sách, tờ giấy kín chữ nhưng rắc rối thì đủ kiểu. Có đội đặt tên thật kêu rồi bỏ trống hẳn ô số điện thoại, đến hôm trời mưa phải dời trận thì chẳng biết báo cho ai. Hai đội ở hai lớp khác nhau lại cùng chọn tên \"Sấm Sét\", loa gọi lên sân mà cả hai bên cùng đứng dậy. Lại có một dòng ghi lớp 11A9, trong khi cả trường chỉ có đến lớp 11A8 — hoá ra bạn ấy viết vội, nhầm mất một chữ số.\n\nSang năm sau, thầy tổng phụ trách làm khác. Thay cho tờ giấy, thầy đặt ở phòng Đoàn một máy tính mở sẵn biểu mẫu đăng kí. Bỏ trống số điện thoại thì máy không cho gửi. Gõ một tên đội đã có người đặt thì máy báo ngay tại chỗ để đổi sang tên khác. Còn lớp thì không phải gõ tay mà chọn trong danh sách các lớp có thật của trường, nên không thể xuất hiện lớp 11A9 nào nữa. Cái sai bị chặn ngay ở cửa, thay vì nằm im trong danh sách chờ đến ngày thi đấu mới lộ ra.\n\nChưa hết. Cuối đợt đăng kí, thầy còn cần biết mỗi khối có bao nhiêu đội, khối nào từ năm đội trở lên thì tách ra một bảng đấu riêng. Với tờ giấy ngoài bảng tin thì phải ngồi đếm tay, đếm hai lượt ra hai con số. Với chiếc máy tính kia, thầy chỉ gõ một câu hỏi là có ngay bảng kết quả. Dặn máy trước những gì nó phải kiểm tra, rồi hỏi máy đúng cách để lấy con số thống kê — đó chính là hai việc ta sẽ học trong bài này."},{"t":"h","text":"1) Dựng khung cho bảng bằng lệnh CREATE TABLE"},{"t":"text","text":"Ở những bài trước, ta luôn giả sử bảng đã có sẵn rồi mới đi thêm, sửa, xoá hay truy vấn dữ liệu trong đó. Nhưng bảng ấy từ đâu ra? Người thiết kế cơ sở dữ liệu phải tạo nó trước bằng lệnh `CREATE TABLE`. Có thể hình dung lệnh này giống như việc kẻ sẵn một tờ bảng biểu: đặt tên cho tờ bảng, rồi kẻ ra từng cột và ghi rõ mỗi cột sẽ chứa loại thông tin gì.\n\nCú pháp chung là `CREATE TABLE <tên bảng> (<tên cột 1> <kiểu dữ liệu>, <tên cột 2> <kiểu dữ liệu>, ...);`. Điều bắt buộc là mỗi cột phải được khai báo **kiểu dữ liệu**, tức là loại giá trị mà cột đó được phép chứa. Bốn kiểu hay gặp nhất là `INTEGER` cho số nguyên (số lượt mượn, số ngày), `REAL` cho số thực có phần thập phân (điểm trung bình, chiều cao), `TEXT` cho chuỗi kí tự (họ tên, tên sách, mã học sinh) và `DATE` cho ngày tháng. Khai báo kiểu không phải là thủ tục hình thức: nhờ nó mà hệ quản trị biết cách sắp xếp, so sánh và tính toán trên cột, đồng thời phát hiện được ngay khi ai đó định nhét một chuỗi chữ vào cột lẽ ra chỉ chứa số.\n\nĐối lập với `CREATE TABLE` là lệnh `DROP TABLE <tên bảng>;`. Bạn phải hết sức phân biệt nó với `DELETE` đã học: `DELETE FROM LuotMuon;` xoá sạch các dòng dữ liệu nhưng cái bảng rỗng vẫn còn đó, vẫn đủ cột, hôm sau vẫn thêm dữ liệu mới vào được; còn `DROP TABLE LuotMuon;` thì xoá luôn cả bảng — cả cấu trúc cột lẫn toàn bộ dữ liệu bên trong — sau lệnh đó, trong cơ sở dữ liệu không còn tồn tại cái tên `LuotMuon` nữa. Gõ nhầm `DROP` thay vì `DELETE` là một tai nạn rất khó cứu."},{"t":"h","text":"2) Ràng buộc: hàng rào chặn dữ liệu sai ngay từ cửa"},{"t":"text","text":"Quay lại tờ giấy đăng kí dán ngoài bảng tin. Vấn đề không nằm ở chỗ ban tổ chức lười kiểm tra, mà ở chỗ tờ giấy không có khả năng tự từ chối: bút cứ viết thì giấy cứ nhận, dòng bỏ trống số điện thoại vẫn nằm yên ở đó cho tới ngày thi đấu mới bị phát hiện. Một bảng trong cơ sở dữ liệu thì khác: ta có thể viết sẵn \"luật chơi\" cho từng cột ngay trong lệnh `CREATE TABLE`, và từ lúc đó trở đi hệ quản trị sẽ tự động kiểm tra mọi dòng dữ liệu được thêm vào hoặc sửa đổi, dòng nào phạm luật thì từ chối thẳng và báo lỗi. Đó chính là chiếc biểu mẫu trên máy tính của thầy tổng phụ trách, chỉ khác là luật được đặt ở tận lớp dữ liệu bên dưới.\n\nNhững \"luật chơi\" ấy gọi là **ràng buộc**. Trong bài về an toàn và toàn vẹn dữ liệu, ta đã bàn về ràng buộc toàn vẹn ở mức ý tưởng — dữ liệu phải hợp lí, phải nhất quán, không được mâu thuẫn. Bây giờ là lúc viết ý tưởng đó ra thành cú pháp SQL cụ thể, mỗi ràng buộc chỉ là một hoặc vài từ khoá đặt ngay sau tên cột. Điều đáng nói là ràng buộc chỉ cần khai báo một lần duy nhất lúc tạo bảng, nhưng có hiệu lực mãi mãi về sau, với mọi người dùng, mọi phần mềm truy cập vào bảng đó — an toàn hơn hẳn việc trông chờ vào trí nhớ của người nhập liệu."},{"t":"list","text":"Bốn ràng buộc hay dùng nhất khi tạo bảng và ý nghĩa của từng loại:","items":["`PRIMARY KEY` — khai báo cột làm khoá chính: giá trị không được trùng nhau giữa các dòng và cũng không được để trống, nhờ đó mỗi dòng luôn có một \"chứng minh thư\" phân biệt với mọi dòng còn lại.","`NOT NULL` — cột bắt buộc phải có giá trị, không cho phép bỏ trống; đúng thứ mà tờ đăng kí giấy ở đầu bài thiếu, nên ô số điện thoại mới trống trơn mà chẳng ai hay.","`UNIQUE` — các giá trị trong cột không được trùng nhau, nhưng vẫn cho phép để trống; hợp với những cột như số điện thoại, địa chỉ thư điện tử, hay tên đội bóng — mỗi tên chỉ một đội được dùng.","`FOREIGN KEY (<cột>) REFERENCES <bảng khác>(<cột khoá chính>)` — khai báo khoá ngoại: giá trị điền vào cột này bắt buộc phải là một giá trị đã có thật ở bảng được tham chiếu, giống hệt việc chỉ cho chọn lớp trong danh sách các lớp có thật nên không thể xuất hiện lớp 11A9."]},{"t":"example","text":"Ở bài trước, ta đã ngồi thiết kế trên giấy bộ bảng cho việc mượn – trả sách của thư viện trường. Giờ là lúc viết bản thiết kế ấy ra thành SQL thật, với hai bảng: `DocGia` lưu thông tin thành viên, `LuotMuon` lưu từng lượt mượn sách. Cột `MaDG` trong `LuotMuon` chính là khoá ngoại trỏ về khoá chính `MaDG` của bảng `DocGia`.\n\nSau khi tạo bảng, hai lệnh thêm dữ liệu ở cuối được cố tình viết để thấy ràng buộc làm việc: một lệnh hợp lệ và một lệnh vi phạm khoá ngoại.","code":"CREATE TABLE DocGia (\n    MaDG    TEXT PRIMARY KEY,\n    HoTen   TEXT NOT NULL,\n    Lop     TEXT NOT NULL,\n    DienThoai TEXT UNIQUE\n);\n\nCREATE TABLE LuotMuon (\n    MaLuot     INTEGER PRIMARY KEY,\n    MaDG       TEXT NOT NULL,\n    TenSach    TEXT NOT NULL,\n    NgayMuon   DATE NOT NULL,\n    SoNgayMuon INTEGER,\n    FOREIGN KEY (MaDG) REFERENCES DocGia(MaDG)\n);\n\nINSERT INTO DocGia VALUES ('DG01', 'Trần Bảo Long', '11A2', '0912000111');\n\nINSERT INTO LuotMuon VALUES (1, 'DG09', 'Bản đồ sao trời', '2025-09-12', 7);","output":"Hai bảng được tạo và dòng độc giả DG01 thêm thành công, riêng lệnh cuối bị từ chối với thông báo lỗi khoá ngoại vì mã DG09 chưa hề có trong bảng DocGia."},{"t":"h","text":"3) Thống kê dữ liệu: hàm tổng hợp, GROUP BY và ghép bảng"},{"t":"text","text":"Câu hỏi cuối cùng của thầy tổng phụ trách ở đầu bài — mỗi khối có bao nhiêu đội — thuộc một loại khác hẳn mọi thứ ta đã học. Nó không đòi liệt kê từng dòng, mà đòi một con số duy nhất rút ra từ cả một cột. Với bộ bảng thư viện cũng vậy: \"cả tháng có bao nhiêu lượt mượn\", \"trung bình mỗi lượt giữ sách mấy ngày\" đều là những câu hỏi cùng loại. SQL có sẵn năm **hàm tổng hợp** thông dụng làm đúng việc đó: `COUNT` đếm số dòng, `SUM` cộng dồn tất cả giá trị, `AVG` tính trung bình cộng, `MAX` lấy giá trị lớn nhất và `MIN` lấy giá trị nhỏ nhất. Cách viết rất gọn, chỉ cần đặt tên cột vào trong ngoặc, chẳng hạn `SELECT AVG(SoNgayMuon) FROM LuotMuon;`. Riêng `COUNT(*)` là cách viết quen thuộc để đếm toàn bộ số dòng của kết quả, không quan tâm cột nào.\n\nNhưng câu hỏi \"bạn nào mượn từ ba cuốn trở lên\" thì một con số tổng chưa đủ: ta cần một con số riêng cho từng bạn. Đây là lúc dùng mệnh đề `GROUP BY`. Nó gom những dòng có cùng giá trị ở cột chỉ định thành một **nhóm**, rồi các hàm tổng hợp sẽ được tính riêng rẽ trên từng nhóm thay vì trên cả bảng. Viết `GROUP BY MaDG` nghĩa là: tất cả lượt mượn của cùng một mã độc giả gom lại thành một cụm, và `COUNT(*)` sẽ cho biết mỗi cụm có bao nhiêu dòng. Cũng theo cách đó, `SELECT Lop, COUNT(*) FROM DocGia GROUP BY Lop;` cho biết mỗi lớp có bao nhiêu bạn đăng kí thẻ đọc, còn `GROUP BY TenSach` trên bảng `LuotMuon` cho biết mỗi đầu sách được các bạn tìm đến bao nhiêu lần. Lưu ý là cột đem ra gộp nhóm phải nằm ngay trong bảng đang truy vấn; muốn gộp theo lớp mà lại đếm số lượt mượn thì phải ghép hai bảng lại với nhau đã — chuyện đó nói ngay ở phần sau.\n\nCòn muốn giữ lại đúng những nhóm thoả một điều kiện nào đó — chỉ những bạn mượn từ ba cuốn trở lên — ta dùng `HAVING`. Đây chính là chỗ dễ nhầm nhất của cả bài, nên hãy khắc sâu: `WHERE` lọc **từng dòng** và lọc **trước** khi gộp nhóm, còn `HAVING` lọc **từng nhóm** và lọc **sau** khi đã gộp và đã tính xong hàm tổng hợp. Vì lẽ đó, điều kiện chứa hàm tổng hợp như `COUNT(*) >= 3` bắt buộc phải đặt trong `HAVING`, không thể đặt trong `WHERE` — lúc `WHERE` làm việc thì các nhóm còn chưa hình thành, lấy đâu ra số đếm để so sánh. Hai mệnh đề này không thay thế nhau mà thường phối hợp với nhau trong cùng một truy vấn: `WHERE` gạn thô trước, `HAVING` chọn tinh sau."},{"t":"example","text":"Giả sử bảng `LuotMuon` đang có bảy dòng, lần lượt ứng với các cặp (mã độc giả, số ngày mượn) là (DG01, 7), (DG01, 5), (DG02, 10), (DG03, 6), (DG01, 3), (DG02, 14), (DG03, 4).\n\nBa truy vấn dưới đây lần lượt cho: một dòng thống kê chung cho cả bảng, rồi số lượt của từng độc giả, và cuối cùng là chỉ những độc giả đạt từ ba lượt mượn trở lên.","code":"SELECT COUNT(*), SUM(SoNgayMuon), AVG(SoNgayMuon),\n       MAX(SoNgayMuon), MIN(SoNgayMuon)\nFROM LuotMuon;\n\nSELECT MaDG, COUNT(*)\nFROM LuotMuon\nGROUP BY MaDG;\n\nSELECT MaDG, COUNT(*)\nFROM LuotMuon\nGROUP BY MaDG\nHAVING COUNT(*) >= 3;","output":"Truy vấn 1 cho một dòng 7 | 49 | 7.0 | 14 | 3; truy vấn 2 cho ba dòng DG01-3, DG02-2, DG03-2; truy vấn 3 chỉ còn một dòng DG01-3."},{"t":"example","text":"Kết quả trên vẫn còn khó đọc vì chỉ hiện mã `DG01`, `DG02` chứ không hiện tên. Lí do là tên độc giả nằm ở bảng `DocGia`, còn lượt mượn nằm ở bảng `LuotMuon`. Muốn có cả hai, ta phải **nối hai bảng** lại qua đúng cặp khoá chính – khoá ngoại: mỗi dòng của `LuotMuon` sẽ được ghép với dòng của `DocGia` có cùng giá trị `MaDG`. Trong SQL, việc này viết bằng `JOIN <bảng kia> ON <điều kiện ghép>`, và điều kiện ghép chính là `DocGia.MaDG = LuotMuon.MaDG`. Khi có hai bảng cùng lúc, tên cột nên viết đầy đủ dạng `<tên bảng>.<tên cột>` để không lẫn.\n\nGiả sử `DocGia` có ba thành viên: DG01 là Trần Bảo Long lớp 11A2, DG02 là Nguyễn Hà My lớp 11A6, DG03 là Phạm Quốc Huy lớp 11A1. Hai truy vấn dưới đây khác nhau đúng một dòng `WHERE`, và chính chỗ khác nhau đó cho thấy `WHERE` đã cắt bớt các dòng trước khi việc gộp nhóm diễn ra.","code":"SELECT DocGia.HoTen, COUNT(*)\nFROM DocGia JOIN LuotMuon ON DocGia.MaDG = LuotMuon.MaDG\nGROUP BY DocGia.HoTen;\n\nSELECT DocGia.HoTen, COUNT(*)\nFROM DocGia JOIN LuotMuon ON DocGia.MaDG = LuotMuon.MaDG\nWHERE LuotMuon.SoNgayMuon >= 5\nGROUP BY DocGia.HoTen;","output":"Truy vấn đầu cho Nguyễn Hà My 2, Phạm Quốc Huy 2, Trần Bảo Long 3; truy vấn sau chỉ đếm các lượt giữ sách từ 5 ngày trở lên nên cho Nguyễn Hà My 2, Phạm Quốc Huy 1, Trần Bảo Long 2."},{"t":"note","text":"Ba cái bẫy hay gặp trong đề thi. Thứ nhất, đừng lẫn `DROP TABLE` với `DELETE`: một bên xoá cả bảng lẫn cấu trúc, một bên chỉ xoá các dòng dữ liệu. Thứ hai, đừng đặt điều kiện chứa hàm tổng hợp vào `WHERE` — hễ thấy `COUNT`, `SUM`, `AVG`, `MAX`, `MIN` xuất hiện trong điều kiện lọc thì gần như chắc chắn nó phải nằm ở `HAVING`, còn điều kiện về giá trị của từng dòng riêng lẻ thì để ở `WHERE`. Thứ ba, khi nối hai bảng mà quên viết điều kiện ghép qua cặp khoá chính – khoá ngoại, hệ quản trị sẽ ghép mọi dòng của bảng này với mọi dòng của bảng kia, cho ra một kết quả phình to và vô nghĩa — số lượt mượn đếm được sẽ lớn hơn thực tế rất nhiều lần."}],"keypoints":["Lệnh **`CREATE TABLE`** dựng khung một bảng mới: đặt tên bảng và khai báo từng cột kèm **kiểu dữ liệu** (`INTEGER`, `REAL`, `TEXT`, `DATE`); còn `DROP TABLE` xoá cả cấu trúc lẫn dữ liệu, khác hẳn `DELETE` chỉ xoá các dòng.","Các **ràng buộc** `PRIMARY KEY` (không trùng, không rỗng), `NOT NULL` (bắt buộc có giá trị), `UNIQUE` (không trùng) và `FOREIGN KEY` (phải tồn tại ở bảng được tham chiếu) được khai báo ngay lúc tạo bảng, giúp hệ quản trị **tự động từ chối dữ liệu sai** ngay khi thêm hoặc sửa.","Năm **hàm tổng hợp** `COUNT`, `SUM`, `AVG`, `MAX`, `MIN` rút cả một cột về một con số; kết hợp **`GROUP BY`** để gộp các dòng cùng giá trị thành nhóm rồi thống kê riêng cho từng nhóm.","**`WHERE` lọc từng dòng TRƯỚC khi gộp nhóm, còn `HAVING` lọc từng nhóm SAU khi gộp**; muốn lấy dữ liệu từ hai bảng thì dùng `JOIN ... ON` nối qua đúng cặp **khoá chính – khoá ngoại**."],"quiz":["CB-mc-2701","CB-mc-2702","CB-mc-2703","CB-mc-2704","CB-mc-2705","CB-tf-2701"]},
    {"id":"C11-28","stage":21,"order":28,"topic":"F","grade":11,"minutes":13,"title":"Mảng hai chiều: hàng, cột và hai vòng lặp lồng nhau","intro":"Nhiều dữ liệu quanh ta không nằm trên một dãy thẳng mà nằm trong một **bảng có hàng và có cột**. Bài học này chỉ cách đưa một bảng như vậy vào chương trình Python bằng **mảng hai chiều**, cách gọi đúng từng ô bằng `a[i][j]`, và cách dùng hai vòng lặp lồng nhau để tính toán trên cả bảng.","sections":[{"t":"story","text":"Cuối mỗi tuần, cô phụ trách căng tin trường bạn lại dán lên bảng tin một tờ giấy kẻ ô kín đặc. Cột ngoài cùng bên trái ghi tên các tổ trực, hàng trên cùng ghi các thứ trong tuần từ thứ Hai đến thứ Sáu. Mỗi ô bên trong là số suất cơm mà tổ đó đã đặt trong ngày tương ứng.\n\nĐiều thú vị là chỉ với một tờ giấy như vậy, cô trả lời được rất nhiều câu hỏi khác nhau. Muốn biết tổ 2 đặt tất cả bao nhiêu suất trong cả tuần, cô cộng các số nằm trên cùng một hàng của tổ 2. Muốn biết riêng thứ Tư toàn trường đặt bao nhiêu suất, cô lại cộng các số nằm trên cùng một cột thứ Tư. Vẫn tờ giấy ấy, nhưng cộng theo hàng thì ra kết quả của từng tổ, còn cộng theo cột thì ra kết quả của từng ngày.\n\nCũng có hôm cô cần dò tìm ô ghi số lớn nhất để biết tổ nào ăn đông nhất vào ngày nào mà chuẩn bị trước, hoặc đếm xem có bao nhiêu ô vượt quá mười lăm suất để đặt thêm nguyên liệu. Tất cả những việc đó đều xoay quanh đúng một tấm bảng có hàng và có cột.\n\nBài học hôm nay sẽ chỉ cho bạn cách đưa nguyên vẹn tấm bảng ấy vào chương trình máy tính, và cách viết vài dòng lệnh ngắn để máy làm giúp mình toàn bộ những phép cộng, phép so sánh và phép đếm nói trên."},{"t":"h","text":"1) Từ dãy số một chiều đến bảng số liệu hai chiều"},{"t":"text","text":"Cho tới lúc này, mỗi khi cần lưu nhiều giá trị cùng loại ta đều dùng một danh sách duy nhất — một dãy nằm thẳng hàng, mỗi giá trị ứng với một vị trí. Cách đó rất gọn khi dữ liệu chỉ có một chiều, chẳng hạn điểm môn Toán của cả lớp hay số suất cơm của riêng tổ 1 trong năm ngày.\n\nNhưng rất nhiều dữ liệu thực tế lại có hai chiều cùng lúc: bảng suất cơm ở đầu bài vừa được chia theo tổ (chiều dọc) vừa được chia theo ngày (chiều ngang); bảng điểm của lớp vừa chia theo học sinh vừa chia theo môn học. Muốn nói tới một con số cụ thể, ta phải nêu đủ hai thông tin: nó ở hàng nào và ở cột nào.\n\nPython không có một kiểu dữ liệu riêng mang tên ‘bảng’, nhưng có một cách rất tự nhiên để tạo ra bảng: coi mỗi hàng của bảng là một danh sách, rồi xếp tất cả các danh sách hàng đó vào trong một danh sách lớn. Kết quả là một **danh sách mà mỗi phần tử của nó lại là một danh sách** — đó chính là **mảng hai chiều**. Cùng một ý tưởng ấy dùng được cho bảng điểm nhiều môn của cả lớp, cho ma trận trong toán học, hay cho bàn cờ vua tám hàng tám cột."},{"t":"h","text":"2) Gọi đúng một ô bằng a[i][j]"},{"t":"example","text":"Giả sử ta cần lưu điểm kiểm tra của 4 bạn trong tổ, mỗi bạn có điểm của 3 môn. Bảng sẽ có 4 hàng (mỗi hàng là một bạn) và 3 cột (mỗi cột là một môn). Trong Python, ta viết mỗi hàng trên một dòng cho dễ nhìn, giữa các hàng có dấu phẩy.\n\nĐể lấy ra một ô, ta viết `a[i][j]` và đọc từ trái sang phải: `a[i]` lấy ra cả hàng thứ `i`, rồi `[j]` lấy tiếp phần tử thứ `j` của hàng đó. Vì vậy `i` luôn là **chỉ số hàng** còn `j` luôn là **chỉ số cột**, và cả hai đều **bắt đầu từ 0** giống hệt quy ước của danh sách một chiều. Kèm theo đó là hai công thức rất hay dùng: `len(a)` cho **số hàng**, còn `len(a[0])` cho **số cột** (số phần tử của hàng đầu tiên).","code":"diem = [\n    [8, 7, 9],\n    [6, 9, 5],\n    [7, 8, 8],\n    [9, 6, 10]\n]\n\nprint('Số hàng:', len(diem))\nprint('Số cột:', len(diem[0]))\nprint('Điểm bạn thứ 2, môn thứ 3:', diem[1][2])\nprint('Cả hàng của bạn thứ 4:', diem[3])","output":"Số hàng: 4\nSố cột: 3\nĐiểm bạn thứ 2, môn thứ 3: 5\nCả hàng của bạn thứ 4: [9, 6, 10]"},{"t":"h","text":"3) Duyệt cả bảng bằng hai vòng lặp lồng nhau"},{"t":"text","text":"Với một dãy một chiều, chỉ cần một vòng lặp là đi hết được mọi phần tử. Với một bảng thì khác: muốn chạm tới mọi ô, ta phải đi theo hai chiều, nên cần **hai vòng lặp `for` lồng nhau**. Vòng ngoài cho `i` chạy qua từng hàng; ứng với mỗi giá trị của `i`, vòng trong lại cho `j` chạy hết các cột của hàng đó rồi mới quay ra để vòng ngoài tăng `i` lên một.\n\nHãy hình dung đúng như khi bạn đọc một trang vở: mắt lướt hết dòng thứ nhất từ trái sang phải, xuống dòng, lại lướt hết dòng thứ hai, cứ thế cho tới dòng cuối. Vòng ngoài chính là việc ‘xuống dòng’, còn vòng trong là việc ‘lướt hết một dòng’. Vì lí do đó, một bảng `n` hàng `m` cột sẽ được duyệt qua đúng `n * m` lượt.\n\nKhi in ra màn hình, nếu dùng `print` bình thường thì mỗi ô sẽ nhảy xuống một dòng và bảng trông rất rối. Cách quen dùng là thêm `end=' '` để các ô trên cùng một hàng nằm sát nhau, rồi đặt một lệnh `print()` rỗng ở cuối vòng ngoài để xuống dòng khi đã hết một hàng. Cũng trong đoạn mã dưới đây, bạn sẽ thấy cách **tạo sẵn một bảng `n` hàng `m` cột toàn số 0** — rất cần khi ta chưa có dữ liệu mà phải nhập vào sau."},{"t":"example","text":"Đoạn chương trình sau in bảng số suất cơm của 3 tổ trong 5 ngày dưới dạng bảng cho dễ nhìn, sau đó tạo thêm một bảng trống 2 hàng 3 cột với mọi ô bằng 0.\n\nHãy chú ý câu lệnh `bang.append([0] * m)`: mỗi lần lặp nó tạo ra một danh sách mới gồm `m` số 0 rồi nối vào bảng, nên sau `n` lần ta có đúng `n` hàng. Nếu dữ liệu được nhập từ bàn phím theo từng dòng, ta thay chỗ số 0 đó bằng lệnh đọc và tách một dòng nhập thành `m` số.","code":"suat = [\n    [12, 10, 11, 9, 13],\n    [8, 9, 9, 10, 7],\n    [14, 12, 13, 12, 15]\n]\n\nfor i in range(len(suat)):\n    for j in range(len(suat[i])):\n        print(suat[i][j], end=' ')\n    print()\n\nn = 2\nm = 3\nbang = []\nfor i in range(n):\n    bang.append([0] * m)\nprint(bang)","output":"12 10 11 9 13\n8 9 9 10 7\n14 12 13 12 15\n[[0, 0, 0], [0, 0, 0]]"},{"t":"h","text":"4) Bốn bài toán quen thuộc trên bảng số liệu"},{"t":"list","text":"Bốn yêu cầu sau xuất hiện đi xuất hiện lại trong các đề bài về bảng số liệu; điều đáng nói là chúng chỉ khác nhau ở hai chỗ: đặt biến tích luỹ ở đâu và cho vòng lặp nào chạy bên ngoài.","items":["Tổng và trung bình của TỪNG HÀNG: vòng ngoài chạy theo hàng `i`, biến tổng được đặt lại bằng 0 ngay đầu mỗi hàng, vòng trong cộng dồn theo cột `j`; muốn trung bình thì chia tổng cho số cột.","Tổng của TỪNG CỘT: vẫn hai vòng lặp ấy nhưng đổi vai trò — vòng ngoài chạy theo cột `j`, vòng trong chạy theo hàng `i`, và biến tổng được đặt lại bằng 0 ở đầu mỗi cột.","Giá trị lớn nhất trên TOÀN BẢNG cùng vị trí của nó: lấy tạm ô `a[0][0]` làm chuẩn, đồng thời nhớ thêm hai biến ghi hàng và cột; mỗi khi gặp ô lớn hơn thì cập nhật cả ba biến một lượt.","Đếm số ô thoả một điều kiện: duyệt hết bảng bằng hai vòng lặp, gặp ô nào thoả thì cho biến đếm tăng thêm 1."]},{"t":"example","text":"Đoạn chương trình dưới đây làm cả bốn việc trên với chính bảng điểm 4 bạn × 3 môn ở mục 2. Bạn hãy để ý kĩ hai khối đầu tiên: chúng gần như giống hệt nhau, chỉ hoán đổi thứ tự `i` và `j`, vậy mà một khối cho kết quả theo từng bạn còn khối kia cho kết quả theo từng môn.\n\nCũng lưu ý vị trí của dòng `tong = 0`. Nó nằm bên trong vòng ngoài chứ không nằm trước cả hai vòng — nhờ vậy mỗi hàng (hoặc mỗi cột) được tính lại từ số 0. Nếu vô ý đặt nó ra ngoài, chương trình sẽ cộng dồn tất cả và cho ra một con số duy nhất của cả bảng.","code":"diem = [\n    [8, 7, 9],\n    [6, 9, 5],\n    [7, 8, 8],\n    [9, 6, 10]\n]\nn = len(diem)\nm = len(diem[0])\n\nfor i in range(n):\n    tong = 0\n    for j in range(m):\n        tong += diem[i][j]\n    print('Bạn', i + 1, '- tổng:', tong, '- trung bình:', round(tong / m, 2))\n\nfor j in range(m):\n    tong = 0\n    for i in range(n):\n        tong += diem[i][j]\n    print('Môn', j + 1, '- tổng:', tong)\n\nmaxv = diem[0][0]\nhang = 0\ncot = 0\nfor i in range(n):\n    for j in range(m):\n        if diem[i][j] > maxv:\n            maxv = diem[i][j]\n            hang = i\n            cot = j\nprint('Lớn nhất:', maxv, 'tại hàng', hang, 'cột', cot)\n\ndem = 0\nfor i in range(n):\n    for j in range(m):\n        if diem[i][j] >= 8:\n            dem += 1\nprint('Số ô đạt từ 8 trở lên:', dem)","output":"Bạn 1 - tổng: 24 - trung bình: 8.0\nBạn 2 - tổng: 20 - trung bình: 6.67\nBạn 3 - tổng: 23 - trung bình: 7.67\nBạn 4 - tổng: 25 - trung bình: 8.33\nMôn 1 - tổng: 30\nMôn 2 - tổng: 30\nMôn 3 - tổng: 32\nLớn nhất: 10 tại hàng 3 cột 2\nSố ô đạt từ 8 trở lên: 7"},{"t":"note","text":"Hai lỗi khiến học sinh mất điểm nhiều nhất khi làm bài về mảng hai chiều đều liên quan tới chỉ số. Thứ nhất là **nhầm chỉ số hàng với chỉ số cột**: `a[2][1]` là ô ở hàng 2 cột 1, hoàn toàn khác với `a[1][2]` là ô ở hàng 1 cột 2; hai biểu thức này chỉ tình cờ bằng nhau ở vài bảng đặc biệt chứ không phải luôn luôn. Mẹo nhớ là đọc `a[i][j]` theo thứ tự ‘hàng trước, cột sau’, đúng như cách ta đọc địa chỉ một ô trong bảng tính.\n\nThứ hai là lỗi `IndexError` khi các hàng của bảng **không dài bằng nhau**. Python cho phép hàng này có 5 phần tử còn hàng kia chỉ có 3, nên nếu ta lấy `m = len(a[0])` rồi cho `j` chạy tới `m - 1` ở mọi hàng thì tới hàng ngắn hơn chương trình sẽ báo lỗi vượt quá chỉ số. Cách viết an toàn là dùng `range(len(a[i]))` cho vòng trong để mỗi hàng được duyệt đúng theo độ dài thật của nó."}],"keypoints":["**Mảng hai chiều** trong Python là một **danh sách mà mỗi phần tử lại là một danh sách**, dùng để biểu diễn dữ liệu dạng bảng như bảng điểm nhiều môn, ma trận hay bàn cờ.","Ô của bảng được gọi bằng `a[i][j]` với `i` là **chỉ số hàng**, `j` là **chỉ số cột**, cả hai đều đếm từ 0; `len(a)` cho **số hàng** còn `len(a[0])` cho **số cột**.","Muốn chạm tới mọi ô phải dùng **hai vòng lặp `for` lồng nhau**: vòng ngoài chạy theo hàng, vòng trong chạy theo cột — giống như đọc hết một dòng rồi mới xuống dòng tiếp theo.","Tính tổng theo hàng, tổng theo cột, tìm **giá trị lớn nhất cùng vị trí** hay **đếm ô thoả điều kiện** đều dùng chung khuôn mẫu, chỉ khác ở **thứ tự hai vòng lặp** và chỗ đặt lại biến tích luỹ bằng 0."],"quiz":["CB-mc-2801","CB-mc-2802","CB-mc-2803","CB-mc-2804","CB-mc-2805","CB-tf-2801"]},
    {"id":"C11-29","stage":21,"order":29,"topic":"F","grade":11,"minutes":13,"title":"Hai cách sắp xếp khác: chọn dần và chèn dần","intro":"Ngoài cách đổi chỗ hai phần tử liền kề mà em đã học, còn hai lối sắp xếp rất tự nhiên khác: mỗi lượt **chọn** ra phần tử nhỏ nhất, hoặc lần lượt **chèn** từng phần tử vào đúng chỗ. Bài này mô phỏng, cài đặt và so sánh cả hai, rồi giới thiệu hai công cụ sắp xếp có sẵn của Python là `sort()` và `sorted()`.","sections":[{"t":"story","text":"Chiều thứ Sáu, Minh và Lan được cô thủ thư nhờ dọn lại chồng phiếu mượn sách của cả tuần. Mỗi phiếu có một con số in ở góc, và chồng phiếu thì lộn xộn hoàn toàn vì bạn nào mượn xong cũng chỉ thả đại lên bàn. Cô dặn: xếp lại cho số nhỏ nằm trên cùng, số lớn nằm dưới cùng, để tuần sau còn tra cho nhanh.\n\nMinh làm theo kiểu của cậu ấy. Cậu lướt mắt qua toàn bộ chồng phiếu, tìm ra tờ có số bé nhất, rút nó ra và đặt riêng sang một bên. Rồi cậu lại lướt qua chỗ phiếu còn lại, tìm tờ bé nhất trong đó, rút ra đặt tiếp xuống dưới tờ vừa rồi. Cứ thế, chồng bên trái ngày một dày lên và luôn luôn ngay ngắn, chồng bên phải thì vơi dần. Mỗi lần Minh chỉ nhấc tay đúng một lần, nhưng bù lại mắt cậu phải quét hết chỗ phiếu còn lại.\n\nLan thì làm khác hẳn. Cô ấy cầm chồng phiếu trên tay như cầm một cỗ bài, rút từng tờ một theo đúng thứ tự đang có, rồi luồn tờ vừa rút vào đúng khe của nó trong xấp phiếu đã ngay ngắn cầm ở tay trái — muốn luồn được thì phải đẩy mấy tờ có số lớn hơn nhích sang một chút. Tay cô ấy động đậy liên tục, nhưng mỗi tờ chỉ cần so với vài tờ gần đó là biết chỗ.\n\nCuối buổi, hai chồng phiếu đều thẳng thớm như nhau, và cô thủ thư chẳng phân biệt nổi cái nào do ai xếp. Nhưng hai bạn vừa vô tình diễn lại đúng hai thuật toán kinh điển của môn Tin học — và điểm khác nhau giữa hai cách làm ấy chính là nội dung bài học hôm nay."},{"t":"h","text":"1) Sắp xếp chọn: mỗi lượt chọn ra phần tử nhỏ nhất"},{"t":"text","text":"Cách làm của Minh trong câu chuyện trên chính là **sắp xếp chọn** (`selection sort`). Ta hình dung dãy luôn bị chia làm hai phần: phần đầu là **đoạn đã sắp xếp** (lúc bắt đầu thì rỗng), phần còn lại là **đoạn chưa sắp xếp**. Ở mỗi lượt, thuật toán quét toàn bộ đoạn chưa sắp xếp để tìm ra phần tử nhỏ nhất, rồi đổi chỗ nó với phần tử đang đứng ở đầu đoạn đó.\n\nĐiều quan trọng cần nhớ là sau khi kết thúc lượt thứ k, k phần tử đầu dãy đã nằm đúng vị trí **cuối cùng** của chúng — không bao giờ phải động đến nữa. Vì thế mỗi lượt sau lại xét một đoạn ngắn hơn lượt trước một phần tử. Với dãy n phần tử, ta chỉ cần n − 1 lượt là xong, bởi khi n − 1 phần tử đầu đã đúng chỗ thì phần tử cuối cùng bắt buộc cũng đã đúng chỗ.\n\nKhi cài đặt bằng Python, ta dùng **hai vòng lặp lồng nhau**: vòng ngoài cho biến `i` chạy qua vị trí đầu của đoạn chưa sắp xếp, vòng trong cho biến `j` quét phần còn lại. Một mẹo rất đáng chú ý: trong vòng trong ta **không đổi chỗ ngay** mỗi khi gặp số nhỏ hơn, mà chỉ ghi nhớ **vị trí** của phần tử nhỏ nhất vào một biến (ở đây đặt tên là `vt_min`). Chỉ đến khi vòng trong kết thúc, ta mới thực hiện đúng **một** phép đổi chỗ duy nhất. Nhờ vậy cả lượt chỉ tốn một lần hoán đổi thay vì rất nhiều lần."},{"t":"example","text":"Ta mô phỏng sắp xếp chọn trên dãy điểm kiểm tra của một tổ: 7, 3, 9, 4, 6.\n\nLượt 1 xét cả dãy, số nhỏ nhất là 3 ở vị trí 1, đổi chỗ với 7 ở vị trí 0. Lượt 2 chỉ xét từ vị trí 1 trở đi (7, 9, 4, 6), nhỏ nhất là 4, đổi chỗ với 7. Lượt 3 xét (9, 7, 6), nhỏ nhất là 6, đổi chỗ với 9. Lượt 4 xét (7, 9), phần tử nhỏ nhất đã đứng sẵn ở đầu đoạn nên `vt_min` trùng với `i` và ta bỏ qua, không đổi chỗ.\n\nChương trình dưới đây in ra trạng thái dãy sau mỗi lượt để em đối chiếu với phần mô phỏng bằng tay.","code":"def sap_xep_chon(a):\n    n = len(a)\n    for i in range(n - 1):\n        vt_min = i\n        for j in range(i + 1, n):\n            if a[j] < a[vt_min]:\n                vt_min = j\n        if vt_min != i:\n            a[i], a[vt_min] = a[vt_min], a[i]\n        print('Sau lượt', i + 1, ':', a)\n\ndiem = [7, 3, 9, 4, 6]\nsap_xep_chon(diem)\nprint('Kết quả  :', diem)","output":"Sau lượt 1 : [3, 7, 9, 4, 6]\nSau lượt 2 : [3, 4, 9, 7, 6]\nSau lượt 3 : [3, 4, 6, 7, 9]\nSau lượt 4 : [3, 4, 6, 7, 9]\nKết quả  : [3, 4, 6, 7, 9]"},{"t":"h","text":"2) Sắp xếp chèn: xếp như người ta xếp bài trên tay"},{"t":"text","text":"Cách của Lan là **sắp xếp chèn** (`insertion sort`). Dãy vẫn được chia làm hai phần như trên, nhưng lần này thuật toán không đi tìm phần tử nhỏ nhất. Nó chỉ lấy đúng phần tử **đầu tiên** của đoạn chưa sắp xếp — gọi là `x` — rồi đi tìm đúng khe cho `x` trong đoạn đã sắp xếp phía trước.\n\nCách tìm khe rất khéo: ta lùi ngược từ phần tử liền trước `x` về đầu dãy, gặp phần tử nào lớn hơn `x` thì **dịch nó sang phải một ô**, cứ dịch cho đến khi gặp một phần tử nhỏ hơn hoặc bằng `x` (hoặc đi hết dãy). Chỗ trống vừa được dọn ra chính là khe của `x`. Đây đúng là động tác đẩy mấy quân bài lớn hơn sang bên để luồn quân bài mới vào giữa.\n\nTrong Python, vòng lặp lùi này được viết bằng `while j >= 0 and a[j] > x`. Em cần chú ý thứ tự hai điều kiện: phải kiểm tra `j >= 0` **trước**, vì nếu `x` nhỏ hơn mọi phần tử phía trước thì `j` sẽ tụt xuống −1, và nếu vội truy cập `a[-1]` thì Python sẽ lấy nhầm phần tử cuối dãy khiến chương trình sai lặng lẽ mà không báo lỗi. Sau khi vòng `while` dừng, câu lệnh `a[j + 1] = x` đặt `x` vào đúng khe vừa dọn."},{"t":"example","text":"Vẫn dãy 7, 3, 9, 4, 6 nhưng lần này sắp xếp bằng cách chèn. Phần tử 7 coi như đã sắp sẵn (một phần tử thì luôn đúng thứ tự).\n\nChèn 3: 7 lớn hơn 3 nên 7 dịch sang phải, 3 vào đầu dãy. Chèn 9: 7 không lớn hơn 9 nên vòng `while` dừng ngay, 9 đứng nguyên tại chỗ — lượt này không dịch phần tử nào. Chèn 4: 9 rồi 7 lần lượt dịch sang phải, 4 luồn vào sau số 3. Chèn 6: 9 rồi 7 dịch sang phải, 6 luồn vào sau số 4.\n\nHãy so các trạng thái dãy in ra dưới đây với những trạng thái đã in ở mục 1 — cùng một dãy đầu vào, cùng một kết quả cuối, nhưng đường đi ở giữa hoàn toàn khác nhau.","code":"def sap_xep_chen(a):\n    for i in range(1, len(a)):\n        x = a[i]\n        j = i - 1\n        while j >= 0 and a[j] > x:\n            a[j + 1] = a[j]\n            j = j - 1\n        a[j + 1] = x\n        print('Sau khi chèn', x, ':', a)\n\ndiem = [7, 3, 9, 4, 6]\nsap_xep_chen(diem)\nprint('Kết quả       :', diem)","output":"Sau khi chèn 3 : [3, 7, 9, 4, 6]\nSau khi chèn 9 : [3, 7, 9, 4, 6]\nSau khi chèn 4 : [3, 4, 7, 9, 6]\nSau khi chèn 6 : [3, 4, 6, 7, 9]\nKết quả       : [3, 4, 6, 7, 9]"},{"t":"h","text":"3) Ba thuật toán sắp xếp đơn giản khác nhau ở chỗ nào?"},{"t":"list","text":"Cùng với sắp xếp nổi bọt đã học, giờ em có ba thuật toán sắp xếp đơn giản. Cả ba đều dùng hai vòng lặp lồng nhau và đều có độ phức tạp **O(n²)** — nghĩa là dữ liệu tăng gấp 10 thì thời gian chạy tăng khoảng 100 lần, nên không bao giờ nên dùng chúng cho hàng triệu bản ghi. Tuy vậy, ở những chi tiết nhỏ chúng lại khác nhau rõ rệt, và đề thi rất hay hỏi đúng vào những chi tiết ấy:","items":["**Sắp xếp nổi bọt** liên tục đổi chỗ hai phần tử đứng cạnh nhau, nên số phép đổi chỗ nhiều nhất trong ba thuật toán.","**Sắp xếp chọn** tốn nhiều phép so sánh (lượt nào cũng phải quét hết đoạn còn lại) nhưng thực hiện **ít phép đổi chỗ nhất**: nhiều nhất n − 1 lần cho cả quá trình. Đây là lựa chọn hợp lí khi mỗi lần hoán đổi rất tốn kém.","**Sắp xếp chèn** chạy **rất nhanh khi dãy đã gần như được sắp sẵn**: khi đó mỗi phần tử mới thường đã lớn hơn phần tử liền trước, vòng `while` dừng ngay sau một phép so sánh và gần như không phải dịch chuyển gì.","Ngược lại, sắp xếp chọn **không hề nhanh lên** khi dãy đã gần sắp sẵn — nó vẫn quét đủ số lần như thường, vì muốn biết đâu là số nhỏ nhất thì bắt buộc phải nhìn hết.","Cả ba đều là thuật toán **sắp xếp tại chỗ**: chúng biến đổi trực tiếp trên dãy ban đầu, không cần tạo thêm một dãy mới có cùng kích thước."]},{"t":"h","text":"4) Trong thực tế: Python đã có sẵn sort() và sorted()"},{"t":"example","text":"Học ba thuật toán trên là để hiểu máy tính sắp xếp thế nào, còn khi lập trình thật thì hầu như không ai tự viết lại. Python cung cấp sẵn hai công cụ, và điểm khác nhau giữa chúng là câu hỏi rất hay gặp:\n\n`a.sort()` là một phương thức của danh sách, nó **sắp xếp ngay trên chính `a`** (sắp xếp tại chỗ) và **không trả về danh sách nào cả** — giá trị trả về là `None`. Còn `sorted(a)` là một hàm, nó **giữ nguyên `a`** và **trả về một danh sách mới** đã được sắp xếp. Cả hai đều nhận tham số `reverse=True` để sắp giảm dần.","code":"diem = [7, 3, 9, 4, 6]\n\nmoi = sorted(diem)\nprint('Danh sách gốc  :', diem)\nprint('Danh sách mới  :', moi)\n\ndiem.sort()\nprint('Sau diem.sort():', diem)\n\ndiem.sort(reverse=True)\nprint('Giảm dần       :', diem)\n\nprint('sort() trả về  :', [1, 2].sort())","output":"Danh sách gốc  : [7, 3, 9, 4, 6]\nDanh sách mới  : [3, 4, 6, 7, 9]\nSau diem.sort(): [3, 4, 6, 7, 9]\nGiảm dần       : [9, 7, 6, 4, 3]\nsort() trả về  : None"},{"t":"note","text":"Ba cái bẫy hay gặp nhất ở phần này. Thứ nhất, viết `a = a.sort()` — lệnh này sắp xếp `a` xong rồi gán `None` đè lên chính nó, làm mất sạch dữ liệu; muốn giữ dãy gốc thì phải dùng `b = sorted(a)`. Thứ hai, trong sắp xếp chọn nhiều bạn đổi chỗ ngay mỗi lần gặp số nhỏ hơn; chương trình vẫn cho kết quả đúng nhưng đã đánh mất đúng cái ưu điểm của thuật toán là **ít đổi chỗ nhất**. Thứ ba, đừng nhầm ‘chọn’ với ‘chèn’ vì hai chữ gần giống nhau: **chọn** thì đi tìm phần tử nhỏ nhất rồi đổi chỗ, **chèn** thì lấy ngay phần tử kế tiếp rồi dịch các phần tử lớn hơn sang phải để luồn nó vào."}],"keypoints":["**Sắp xếp chọn** mỗi lượt quét đoạn chưa sắp xếp để tìm phần tử **nhỏ nhất** rồi đổi chỗ nó về đầu đoạn; sau lượt thứ k, k phần tử đầu đã đúng vị trí vĩnh viễn.","Khi cài đặt sắp xếp chọn, vòng trong chỉ **ghi nhớ vị trí** phần tử nhỏ nhất vào một biến, đến cuối lượt mới thực hiện **một** phép đổi chỗ duy nhất.","**Sắp xếp chèn** lấy lần lượt từng phần tử của đoạn chưa sắp xếp, **dịch các phần tử lớn hơn sang phải** rồi luồn nó vào đúng khe — giống cách xếp bài trên tay.","Cả ba thuật toán sắp xếp đơn giản đều là **O(n²)**, nhưng **sắp xếp chọn ít đổi chỗ nhất** còn **sắp xếp chèn rất nhanh khi dãy gần sắp sẵn**; thực tế nên dùng `a.sort()` (tại chỗ) hoặc `sorted(a)` (tạo danh sách mới), kèm `reverse=True` để giảm dần."],"quiz":["CB-mc-2901","CB-mc-2902","CB-mc-2903","CB-mc-2904","CB-mc-2905","CB-tf-2901"]},
    {"id":"C11-30","stage":21,"order":30,"topic":"F","grade":11,"minutes":12,"title":"Tổ chức chương trình lớn thành các mô đun độc lập","intro":"Khi chương trình lớn dần, chia nhỏ thành hàm thôi vẫn chưa đủ. Bài học này bàn về mức tổ chức cao hơn: tách mã nguồn ra thành nhiều **mô đun** — nhiều tệp `.py` riêng biệt — sao cho mỗi mô đun tự lo được phần việc của mình và ghép lại vẫn chạy trơn tru.","sections":[{"t":"story","text":"Cuối học kì, lớp 11A3 nhận mở một gian hàng bánh mì que trong hội chợ ẩm thực của trường. Ba mươi tám bạn, một buổi sáng, mục tiêu bán hết ba trăm chiếc bánh. Ngày đầu bàn kế hoạch, cả lớp cùng nói một lúc: người bàn chuyện mua nguyên liệu, người bàn giá bán, người bàn trang trí gian hàng — cuối buổi chẳng ai biết mình phải làm gì.\n\nBạn lớp trưởng bèn kẻ một bảng lên bảng đen và chia thành ba tổ. Tổ Hậu cần lo đi chợ, mua đủ nguyên liệu và giao về khu bếp trước bảy giờ sáng. Tổ Bếp nhận nguyên liệu, chế biến, rồi giao ra quầy đúng ba trăm chiếc bánh đã đóng gói. Tổ Bán hàng nhận bánh, bày quầy, thu tiền và ghi sổ. Mỗi tổ chỉ cần biết mình nhận gì từ tổ trước và phải giao gì cho tổ sau, còn bên trong tổ làm thế nào thì tự lo.\n\nCách chia này lập tức có hiệu quả. Ba tổ làm song song ngay từ tối hôm trước mà không phải chờ nhau. Đến gần ngày hội, tổ Bếp đổi hẳn công thức nước sốt cho hợp khẩu vị hơn, nhưng vì vẫn giao đúng ba trăm chiếc bánh, đóng gói y như đã hẹn, nên tổ Bán hàng không hề bị ảnh hưởng — họ thậm chí không cần biết công thức đã đổi.\n\nHãy thử tưởng tượng kịch bản ngược lại: không chia tổ, ai rảnh thì làm, ai cũng thò tay vào mọi khâu. Chỉ cần một bạn đổi loại bánh mì đang mua là cả khâu chế biến lẫn khâu tính giá đều rối tung, và không ai biết hỏi ai. Câu chuyện rất đời thường này lại chính là bài toán mà người viết chương trình lớn phải giải mỗi ngày."},{"t":"h","text":"1) Chia thành hàm và chia thành mô đun khác nhau ở chỗ nào?"},{"t":"text","text":"Ở các bài trước, ta đã biết rằng một bài toán lớn không nên viết dồn thành một khối lệnh dài mà nên tách ra thành nhiều hàm, mỗi hàm lo đúng một việc. Cách làm đó rất tốt, nhưng nó vẫn diễn ra **bên trong một tệp duy nhất**. Đến khi chương trình lớn lên tới bốn, năm chục hàm, tệp mã nguồn dài hàng nghìn dòng, việc cuộn lên cuộn xuống tìm một hàm cũng đã đủ mệt, chưa nói tới chuyện hai bạn cùng sửa một tệp thì đè lên bài của nhau.\n\nLúc này ta cần một mức tổ chức cao hơn: **mô đun**. Một mô đun là một nhóm hàm cùng phục vụ một mảng công việc, được đặt riêng ra trong một tệp `.py` của nó. Chẳng hạn tất cả các hàm liên quan tới việc đọc và ghi dữ liệu được gom vào tệp `dulieu.py`; tất cả các hàm tính toán, thống kê được gom vào tệp `thongke.py`. Mỗi tệp như vậy chính là một mô đun.\n\nSự khác nhau vì thế rất dễ nhớ: **chia thành hàm là chia công việc bên trong một tệp, còn chia thành mô đun là tách hẳn ra nhiều tệp khác nhau**. Nếu ví chương trình như một cái tủ đựng đồ, thì chia hàm giống như xếp đồ gọn gàng thành từng chồng trong một ngăn, còn chia mô đun là làm hẳn nhiều ngăn kéo, mỗi ngăn một loại đồ, dán nhãn bên ngoài để ai cũng biết mở ngăn nào."},{"t":"h","text":"2) Ba nguyên tắc để chia mô đun cho tốt"},{"t":"text","text":"Nguyên tắc thứ nhất: **mỗi mô đun chỉ đảm nhận một nhiệm vụ rõ ràng**. Bạn phải gọi tên được nhiệm vụ đó bằng đúng một câu ngắn, kiểu như “mô đun này lo việc đọc dữ liệu từ tệp và kiểm tra dữ liệu hợp lệ”. Nếu phải nói tới ba, bốn câu mới mô tả hết những gì mô đun đang làm, gần như chắc chắn nó đang ôm quá nhiều việc và nên được tách tiếp.\n\nNguyên tắc thứ hai: **các mô đun ít phụ thuộc lẫn nhau**. Mô đun tính toán không cần biết dữ liệu được lấy từ bàn phím hay từ tệp; mô đun hiển thị không cần biết con số nó đang in ra được tính bằng thuật toán nào. Càng ít phụ thuộc, mỗi mô đun càng dễ đem đi dùng lại ở chương trình khác, và càng dễ thay thế khi cần.\n\nNguyên tắc thứ ba: **giao diện sử dụng của mô đun phải gọn**. Ở đây “giao diện” không phải là cửa sổ đồ hoạ, mà là phần thông tin mà người dùng mô đun cần biết để gọi được nó: tên hàm, các tham số phải đưa vào, và kết quả sẽ nhận về. Một mô đun đạt yêu cầu là mô đun mà bạn dùng được ngay chỉ với ba thông tin đó, hoàn toàn không phải mở tệp ra đọc từng dòng lệnh bên trong — giống hệt việc tổ Bán hàng chỉ cần biết “sẽ nhận ba trăm chiếc bánh đã đóng gói” chứ không cần biết công thức nước sốt."},{"t":"list","text":"Bốn câu hỏi giúp bạn tự kiểm tra một mô đun đã được chia tốt hay chưa:","items":["Mô đun này làm việc gì? Nếu phải trả lời bằng nhiều câu mới hết, nó đang ôm quá nhiều việc.","Mô đun này cần gọi tới bao nhiêu mô đun khác? Con số càng nhỏ càng tốt.","Người khác muốn dùng nó thì phải biết những gì? Chỉ nên là tên hàm, tham số cần đưa vào và kết quả trả về.","Nếu sửa phần bên trong mô đun mà vẫn giữ nguyên tên hàm và tham số, các phần còn lại của chương trình có phải sửa theo không? Câu trả lời đúng phải là: không."]},{"t":"h","text":"3) Ví dụ cụ thể: chương trình quản lí điểm của lớp"},{"t":"text","text":"Hãy hình dung nhóm bạn được giao viết một chương trình quản lí điểm cho lớp mình: nhập họ tên và điểm của từng bạn, tính điểm trung bình, đếm số bạn đạt, rồi in ra một bảng kết quả gọn gàng. Nếu viết tất cả vào một tệp thì cũng xong, nhưng ta thử tổ chức lại theo mô đun xem sao.\n\nBa mảng công việc lộ ra khá rõ. Mảng thứ nhất là lo dữ liệu: nhập vào hoặc đọc từ tệp, kiểm tra điểm có nằm trong khoảng hợp lệ không — đặt vào tệp `dulieu.py`. Mảng thứ hai là tính toán và thống kê: điểm trung bình, số bạn đạt, điểm cao nhất — đặt vào tệp `thongke.py`. Mảng thứ ba là hiển thị: in bảng, in dòng tóm tắt, căn chỉnh cho dễ nhìn — đặt vào tệp `hienthi.py`.\n\nCòn lại là tệp chương trình chính, chẳng hạn `chinh.py`. Điều thú vị là chương trình chính bây giờ rất ngắn: nó **không tự làm gì cả**, mà chỉ gọi lần lượt các mô đun theo đúng trình tự công việc — lấy dữ liệu, đưa cho mô đun thống kê tính, rồi đưa kết quả cho mô đun hiển thị in ra. Đọc tệp chính giống như đọc lại đúng bảng phân công ba tổ của lớp 11A3."},{"t":"example","text":"Dưới đây là một phiên bản rút gọn của chương trình đó, gồm ba tệp đặt chung trong một thư mục. Hai tệp đầu là hai mô đun, tệp thứ ba là chương trình chính; câu lệnh `import` cho phép tệp chính gọi được các hàm nằm trong hai tệp kia.\n\nHãy để ý: trong `chinh.py` không hề có một phép tính hay một lệnh `print` chi tiết nào — mọi việc đều được giao cho mô đun. Ta chạy bằng lệnh `python chinh.py`.","code":"# ===== tệp thongke.py =====\ndef diem_trung_binh(ds):\n    return sum(ds) / len(ds)\n\ndef dem_dat(ds, nguong=5):\n    d = 0\n    for x in ds:\n        if x >= nguong:\n            d += 1\n    return d\n\n\n# ===== tệp hienthi.py =====\ndef in_bang(ten, diem):\n    for i in range(len(ten)):\n        print(ten[i], '-', diem[i])\n\ndef in_tom_tat(tb, so_dat, tong):\n    print('Diem trung binh:', round(tb, 2))\n    print('So ban dat:', so_dat, '/', tong)\n\n\n# ===== tệp chinh.py =====\nimport thongke\nimport hienthi\n\nten = ['An', 'Binh', 'Chi', 'Dung']\ndiem = [8.5, 4.0, 6.5, 9.0]\n\nhienthi.in_bang(ten, diem)\ntb = thongke.diem_trung_binh(diem)\nsd = thongke.dem_dat(diem)\nhienthi.in_tom_tat(tb, sd, len(diem))","output":"Bốn dòng bảng điểm An - 8.5, Binh - 4.0, Chi - 6.5, Dung - 9.0; rồi hai dòng tóm tắt Diem trung binh: 7.0 và So ban dat: 3 / 4."},{"t":"h","text":"4) Tổ chức theo mô đun thì được lợi gì?"},{"t":"text","text":"Lợi ích đầu tiên là **làm việc song song**. Nhóm ba bạn có thể nhận mỗi người một mô đun và viết cùng lúc ngay từ hôm nhận đề, miễn là đã thống nhất trước với nhau tên hàm, tham số và kết quả trả về. Không ai phải ngồi chờ ai viết xong mới bắt đầu, và cũng không có cảnh ba người cùng sửa một tệp rồi đè mất bài của nhau.\n\nLợi ích thứ hai là **sửa an toàn**. Chừng nào giao diện được giữ nguyên, bạn có thể thay hẳn cách làm bên trong một mô đun mà phần còn lại của chương trình vẫn chạy y như cũ. Chẳng hạn bạn phụ trách `thongke.py` phát hiện cách đếm cũ hơi chậm và viết lại gọn hơn; miễn là hàm vẫn tên `dem_dat`, vẫn nhận vào một danh sách điểm và vẫn trả về một số nguyên, thì `chinh.py` và `hienthi.py` không phải sửa một dòng nào.\n\nLợi ích thứ ba là **kiểm thử được từng phần**. Bạn có thể viết vài dòng thử riêng mô đun thống kê với danh sách rỗng, danh sách một phần tử, danh sách toàn điểm dưới 5... để chắc chắn nó đúng, rồi mới đem ghép. Khi cả ba mô đun đều đã được thử riêng, việc ghép lại thường rất nhẹ nhàng; còn nếu vẫn có lỗi thì phạm vi nghi ngờ đã hẹp đi rất nhiều, thường nằm ở chỗ ghép nối chứ không phải bên trong mô đun."},{"t":"note","text":"Cần cảnh giác với ba dấu hiệu cho thấy chương trình đang bị **chia mô đun kém**. Thứ nhất, các mô đun **gọi chéo nhau chằng chịt**: mô đun hiển thị lại gọi ngược sang mô đun dữ liệu, mô đun dữ liệu lại gọi sang mô đun thống kê — lúc này ranh giới giữa các tổ đã bị xoá, tách tệp cũng chẳng còn ý nghĩa. Thứ hai, có **một mô đun ôm quá nhiều việc**, dài gấp mấy lần các mô đun còn lại và động vào việc gì cũng phải mở nó ra. Thứ ba, và đáng ngại nhất: **sửa một chỗ lại làm hỏng nhiều chỗ khác** — dấu hiệu chắc chắn rằng các mô đun đang phụ thuộc vào phần bên trong của nhau chứ không chỉ phụ thuộc vào giao diện. Nhớ rằng chia thành nhiều tệp mới chỉ là hình thức; chia đúng ranh giới công việc mới là thực chất."}],"keypoints":["**Mô đun** là một nhóm hàm cùng phục vụ một mảng công việc, được đặt riêng trong một tệp `.py`; chia thành **hàm** là chia bên trong một tệp, còn chia thành **mô đun** là tách ra nhiều tệp khác nhau.","Ba nguyên tắc chia mô đun tốt: mỗi mô đun chỉ lo **một nhiệm vụ rõ ràng**, các mô đun **ít phụ thuộc lẫn nhau**, và **giao diện sử dụng gọn** — chỉ cần biết tên hàm, tham số và kết quả trả về là dùng được.","Chương trình quản lí điểm có thể tách thành mô đun **dữ liệu**, mô đun **thống kê** và mô đun **hiển thị**; **chương trình chính** chỉ gọi lần lượt các mô đun đó theo đúng trình tự.","Tổ chức theo mô đun cho phép **nhiều người làm song song**, **sửa bên trong mà không hỏng phần còn lại** (miễn giữ nguyên giao diện) và **kiểm thử riêng từng mô đun** trước khi ghép."],"quiz":["CB-mc-3001","CB-mc-3002","CB-mc-3003","CB-mc-3004","CB-mc-3005","CB-tf-3001"]},
    {"id":"C11-31","stage":21,"order":31,"topic":"F","grade":11,"minutes":12,"title":"Tủ đồ nghề của lập trình viên: nạp và tự tạo thư viện Python","intro":"Bài học chỉ ra cách nạp và sử dụng các thư viện có sẵn của Python bằng `import`, cách tự đóng gói những hàm mình hay dùng thành một thư viện riêng, và vai trò của khối `if __name__ == '__main__':` trong tệp thư viện.","sections":[{"t":"story","text":"Câu lạc bộ Kĩ thuật của trường có một tủ đồ nghề đặt ở góc phòng thực hành. Trong tủ là những thứ đã được làm sẵn, thử đi thử lại nhiều lần và ai cũng dùng được: bộ tua vít đủ cỡ, cuộn dây điện đã đo sẵn, mấy cái giá đỡ in 3D, vài mạch cảm biến đã hàn xong và dán nhãn cẩn thận. Mỗi nhãn ghi rõ ba dòng: món này dùng để làm gì, cắm vào đâu, và cho ra tín hiệu kiểu gì.\n\nMỗi khi có nhóm nhận một dự án mới — làm đèn tự động cho hành lang, làm hệ thống tưới cây cho vườn trường — các bạn không ngồi hàn lại mạch cảm biến từ đầu. Các bạn mở tủ, lấy đúng món cần dùng, đọc nhãn rồi lắp vào. Nhờ vậy một dự án tưởng chừng mất cả tháng lại xong trong hai buổi chiều.\n\nCó lần một bạn phát hiện cái giá đỡ hay bị lỏng ốc. Bạn ấy sửa lại đúng một lần, ngay trên món đồ trong tủ. Kể từ đó mọi nhóm mượn giá đỡ đều nhận được bản đã sửa, không ai phải sửa lại lần thứ hai.\n\nCái tủ đồ nghề ấy khác hẳn với hộp linh kiện riêng của từng nhóm — hộp riêng chỉ hợp với đúng một dự án và thường bị bỏ đi khi dự án kết thúc. Trong lập trình cũng có một cái tủ đồ nghề như thế, và bài này sẽ chỉ cho bạn cách mở tủ của người khác lẫn cách tự đóng cho mình một cái tủ."},{"t":"h","text":"1) Thư viện là gì, khác mô đun ở chỗ nào?"},{"t":"text","text":"**Thư viện** là một tập hợp các hàm đã được viết sẵn, đã kiểm thử kĩ và được đóng gói lại để dùng lại cho **nhiều chương trình khác nhau**. Người dùng thư viện chỉ cần biết ba điều: hàm đó làm gì, phải đưa vào những tham số nào và nó trả về kết quả gì — hoàn toàn không cần đọc dòng lệnh bên trong. Đúng như cái nhãn dán trên món đồ trong tủ ở câu chuyện mở bài.\n\nBạn đã quen với việc tách chương trình lớn thành các **mô đun**. Điểm khác nhau nằm ở phạm vi phục vụ: một mô đun thường sinh ra để gánh một phần việc của **đúng một chương trình cụ thể** — chẳng hạn mô đun đọc dữ liệu điểm cho phần mềm quản lí điểm của lớp 11A2. Còn thư viện thì được viết với ý định ngay từ đầu là **dùng chung**: hôm nay phục vụ phần mềm quản lí điểm, tháng sau phục vụ chương trình tính tiền quỹ lớp, sang năm phục vụ dự án khác nữa mà không phải sửa gì.\n\nVì vậy tiêu chuẩn của một thư viện tốt cao hơn mô đun một bậc: hàm phải tổng quát (không gắn chặt vào số liệu của một lớp cụ thể), phải chạy đúng cả với dữ liệu bất thường, và phải có mô tả rõ ràng để người khác đọc nhãn là dùng được."},{"t":"h","text":"2) Ba cách nạp một thư viện có sẵn"},{"t":"text","text":"Python đi kèm sẵn một bộ **thư viện chuẩn** rất phong phú, nhưng chúng không tự động có mặt trong chương trình của bạn. Muốn dùng, bạn phải **nạp** (import) thư viện đó vào. Có ba cách viết, khác nhau ở chỗ sau khi nạp thì gọi hàm như thế nào.\n\nCách thứ nhất là `import math`: nạp nguyên cả thư viện, và từ đó mọi hàm bên trong phải gọi kèm tên thư viện — `math.sqrt(x)`, `math.floor(x)`. Cách này dài dòng hơn một chút nhưng đọc vào là biết ngay hàm đến từ đâu, nên rất được ưa dùng. Cách thứ hai là `from math import sqrt`: chỉ lấy đúng hàm `sqrt` và đặt thẳng nó vào chương trình, nhờ vậy gọi ngắn gọn `sqrt(x)` mà **không** kèm tiền tố `math.` nữa. Đổi lại, nếu chương trình của bạn cũng có một hàm tên `sqrt` thì hai cái tên sẽ đè lên nhau.\n\nCách thứ ba là `import numpy as np`: vẫn nạp cả thư viện nhưng đặt cho nó một **tên gọi tắt**. Từ đó `np` chính là `numpy`, gọi hàm bằng `np.array(...)`. Cách này rất tiện với những thư viện có tên dài phải gõ đi gõ lại hàng chục lần trong một chương trình."},{"t":"example","text":"Đoạn chương trình sau dùng cả ba cách nạp trong cùng một tệp, để bạn thấy rõ sự khác nhau khi gọi hàm. Bài toán rất đời thường: tính chu vi bồn hoa tròn ở sân trường, tính đường chéo một sân chơi hình chữ nhật 9 m x 12 m và xem ngày thi rơi vào thứ mấy.","code":"import math\nfrom math import sqrt\nimport datetime as dt\n\n# Cách 1: nạp cả thư viện, gọi hàm qua tên thư viện\nchu_vi = 2 * math.pi * 3.5\nprint('Chu vi bồn hoa:', round(chu_vi, 2))\n\n# Cách 2: nạp thẳng hàm sqrt, gọi trực tiếp không cần tiền tố\nprint('Đường chéo sân:', sqrt(9**2 + 12**2))\n\n# Cách 3: đặt tên gọi tắt dt cho thư viện datetime\nngay_thi = dt.date(2025, 6, 26)\nprint('Ngày thi rơi vào thứ:', ngay_thi.isoweekday())","output":"Chu vi bồn hoa: 21.99 / Đường chéo sân: 15.0 / Ngày thi rơi vào thứ: 4 (tức thứ Năm, vì `isoweekday()` đánh số thứ Hai là 1)"},{"t":"list","text":"Một vài thư viện chuẩn của Python mà học sinh hay gặp nhất:","items":["`math` — các hàm và hằng số toán học: `math.sqrt()`, `math.floor()`, `math.pi`.","`random` — sinh số ngẫu nhiên, bốc thăm, xáo trộn danh sách: `random.randint()`, `random.choice()`.","`datetime` — làm việc với ngày tháng: tạo ngày, tính khoảng cách giữa hai mốc thời gian.","Ngoài thư viện chuẩn còn có thư viện của cộng đồng (như `numpy` cho tính toán trên mảng số), phải cài thêm mới dùng được."]},{"t":"h","text":"3) Tự đóng gói thư viện riêng và khối chạy thử"},{"t":"text","text":"Sau vài tháng học lập trình, chắc chắn bạn nhận ra mình viết đi viết lại vài hàm giống hệt nhau: tính điểm trung bình, quy điểm ra xếp loại, chuẩn hoá lại họ tên viết hoa viết thường lộn xộn. Đây chính là lúc nên gom chúng vào tủ đồ nghề của riêng mình.\n\nCách làm đơn giản đến bất ngờ: tạo một tệp Python mới, chẳng hạn `tienich.py`, rồi chép các hàm dùng chung vào đó — chỉ phần định nghĩa hàm, không cần gì thêm. Thế là bạn đã có một thư viện. Trong chương trình chính, bạn viết `import tienich` (lưu ý: **không** viết đuôi `.py`), sau đó gọi hàm theo mẫu `tienich.ten_ham(...)` y hệt cách gọi `math.sqrt(...)`.\n\nĐiều kiện bắt buộc là hai tệp phải nằm **cùng một thư mục**, vì khi gặp lệnh `import tienich`, Python sẽ tìm tệp `tienich.py` ngay tại thư mục chứa chương trình đang chạy. Đặt lạc sang thư mục khác là chương trình báo lỗi không tìm thấy mô đun."},{"t":"example","text":"Dưới đây là hai tệp đặt cạnh nhau trong cùng một thư mục. Tệp `tienich.py` đóng vai trò thư viện, mỗi hàm đều có phần mô tả đặt trong cặp ba dấu nháy (gọi là docstring) và có sẵn một khối chạy thử ở cuối. Tệp `bangdiem.py` là chương trình chính, chỉ việc nạp thư viện rồi gọi hàm.","code":"# ===== Tệp tienich.py =====\ndef diem_trung_binh(ds_diem):\n    '''Tính điểm trung bình của một danh sách điểm.\n    ds_diem: danh sách các số.\n    Trả về: số thực đã làm tròn 2 chữ số, bằng 0 nếu danh sách rỗng.'''\n    if len(ds_diem) == 0:\n        return 0\n    return round(sum(ds_diem) / len(ds_diem), 2)\n\n\ndef xep_loai(diem):\n    '''Nhận vào một điểm trung bình, trả về xâu xếp loại tương ứng.'''\n    if diem >= 8:\n        return 'Giỏi'\n    if diem >= 6.5:\n        return 'Khá'\n    return 'Trung bình'\n\n\nif __name__ == '__main__':\n    print('Chạy thử thư viện:', diem_trung_binh([8, 9, 7]))\n\n\n# ===== Tệp bangdiem.py, đặt cùng thư mục =====\nimport tienich\n\ndiem_to_1 = [7.5, 8.0, 9.0, 6.5]\ntb = tienich.diem_trung_binh(diem_to_1)\nprint('Điểm trung bình tổ 1:', tb)\nprint('Xếp loại:', tienich.xep_loai(tb))","output":"Chạy bangdiem.py in ra: Điểm trung bình tổ 1: 7.75 / Xếp loại: Khá — dòng 'Chạy thử thư viện' không hề xuất hiện"},{"t":"text","text":"Hãy để ý phần mô tả đặt ngay dưới dòng `def`, nằm giữa cặp ba dấu nháy — người ta gọi đó là **docstring**. Nó trả lời đúng ba câu hỏi mà người muốn dùng lại hàm cần biết: hàm làm việc gì, phải đưa vào tham số nào, trả về kết quả ra sao. Nhờ docstring, bạn cùng nhóm chỉ cần liếc qua là dùng được `diem_trung_binh`, kể cả khi họ chưa từng đọc một dòng lệnh nào bên trong nó. Đây là điểm phân biệt một thư viện dùng được với một đống hàm để lộn xộn.\n\nĐiều thú vị hơn nằm ở dòng `if __name__ == '__main__':`. Python luôn tự tạo cho mỗi tệp một biến `__name__`. Khi bạn cho chạy trực tiếp tệp `tienich.py`, biến này mang giá trị `'__main__'`, điều kiện đúng, nên dòng chạy thử được thực hiện — rất tiện để bạn tự kiểm tra thư viện mình vừa sửa. Nhưng khi tệp đó bị **nạp vào** chương trình khác bằng `import tienich`, `__name__` lại mang giá trị `'tienich'`, điều kiện sai, nên phần chạy thử bị bỏ qua hoàn toàn.\n\nĐó là lí do trong kết quả ở trên, chạy `bangdiem.py` không hề thấy dòng chữ 'Chạy thử thư viện'. Nếu thiếu khối `if __name__` này và bạn để câu lệnh `print` chạy thử trần trụi ở cuối tệp thư viện, thì mọi chương trình nạp thư viện đều bị dính thêm dòng in vô duyên đó — một lỗi rất hay gặp khi mới tập viết thư viện."},{"t":"note","text":"Ba cái bẫy thường gặp cần nhớ. Thứ nhất, đừng đặt tên tệp thư viện trùng tên một thư viện chuẩn — tệp `math.py` do bạn tạo sẽ được Python ưu tiên tìm thấy trước, khiến `math.sqrt()` báo lỗi một cách khó hiểu. Thứ hai, `import tienich` là nạp **tên mô đun**, tuyệt đối không viết `import tienich.py`. Thứ ba, hãy nhớ lợi ích lớn nhất của thư viện: **viết một lần, dùng nhiều lần**, chương trình chính nhờ đó ngắn gọn dễ đọc, và khi phát hiện lỗi bạn chỉ sửa đúng một chỗ trong thư viện thì mọi chương trình đang dùng nó đều được sửa theo — hệt như cái giá đỡ được siết lại ốc đúng một lần trong tủ đồ nghề."}],"keypoints":["**Thư viện** là tập hợp các hàm viết sẵn, đã kiểm thử, dùng lại được cho **nhiều chương trình khác nhau**, khác với **mô đun** thường chỉ phục vụ một chương trình cụ thể.","Ba cách nạp: `import math` gọi bằng `math.sqrt(x)`; `from math import sqrt` gọi trực tiếp `sqrt(x)`; `import numpy as np` đặt **tên gọi tắt** cho thư viện.","Tự tạo thư viện bằng cách gom các hàm dùng chung vào tệp `tienich.py`, đặt **cùng thư mục** với chương trình chính, rồi `import tienich` và gọi `tienich.ten_ham(...)`; mỗi hàm nên có **docstring** mô tả nhiệm vụ, tham số và giá trị trả về.","Khối `if __name__ == '__main__':` chứa phần **chạy thử** của tệp thư viện; phần này chỉ chạy khi mở trực tiếp tệp đó, và **bị bỏ qua** khi tệp được `import` vào chương trình khác."],"quiz":["CB-mc-3101","CB-mc-3102","CB-mc-3103","CB-mc-3104","CB-mc-3105","CB-tf-3101"]}
  );
})();
